window.INITIAL_TRAINING_DB = {"meta":{"appName":"Cẩm Nang Tư Vấn Mầm Non Chuyển Giao — NovaStars","adminPin":"Nvs123456","defaultPassThreshold":80,"version":1,"rosterVersion":3,"updatedAt":"2026-11-26T08:46:39.402Z","coreModulesVersion":2},"users":[{"id":"sale-haunt","name":"Nguyễn Thị Hậu","pin":"1111","role":"sale","title":"Chuyên viên Tư vấn (Sale)"},{"id":"up-huongdt","name":"Đinh Thị Hương","pin":"3333","role":"uploader","title":"Phụ trách Nội dung & Đào tạo"},{"id":"up-hienntm","name":"Nguyễn Thị Minh Hiền","pin":"7777","role":"uploader","title":"Phụ trách Nội dung & Đào tạo"}],"modules":[{"id":"mod-01-tong-quan","code":"HP01","category":"Nền tảng & Định vị Sản phẩm","title":"So sánh Tổng quan Chương trình Bộ GD&ĐT và Kĩ năng sống Novastars (72 tiết)","subtitle":"Bối cảnh bán hàng: Tư vấn cho Chủ trường và Hiệu trưởng trường Mầm non tư thục mua chương trình đưa vào dạy chính khóa cho trẻ 3 đến 6 tuổi","durationMinutes":20,"passThreshold":80,"status":"published","authorName":"Phạm Mỹ Linh","updatedAt":"2026-11-26T08:46:39.402Z","sourceFile":{"name":"So_sanh_Novastars_va_Chuong_trinh_Bo_GDDT_Chinh_khoa.xlsx","url":"data/files/So_sanh_Novastars_va_Chuong_trinh_Bo_GDDT_Chinh_khoa.xlsx","type":"xlsx","sheetName":"1_Tong_quan_Chinh_khoa"},"summaryPoints":["Định vị: Chương trình chuyên sâu riêng về Kĩ năng sống (2 tiết/tuần × 36 tuần = 72 tiết/năm cho 3 khối Bé, Nhỡ, Lớn) làm chương trình mũi nhọn trong giờ chính khóa.","Cấu trúc bài học: Thiết kế theo cụm 2–3 tiết nối tiếp nhau (Tiết 1 hiểu quy tắc → Tiết 2 thực hành làm thật → Tiết 3 đứng lên thuyết trình chia sẻ) thay vì 1 tiết rời rạc.","Phương pháp tổ chức: Trẻ là người hoạt động chính qua 4–5 chặng liên tiếp trong 30 phút (mỗi hoạt động 5–7 phút), giáo án cùng mẫu chuẩn của Bộ và có sẵn sơ đồ vị trí 2 cô giáo.","Công nghệ & Học liệu: Phần mềm chạy trực tuyến hoặc tải về dạy offline không cần mạng, đồng bộ bộ nhân vật hoạt hình Kem – Su – Sao Nova suốt 216 tiết của 3 khối.","Đầu ra truyền thông tuyển sinh: Video học sinh 3–5 tuổi tự tin thuyết trình trước máy quay và bài tập về nhà chia sẻ lại cho bố mẹ."],"structuredType":"comparison_6_criteria","structuredData":[{"stt":"1","title":"Vị trí của chương trình trong nhà trường","bo_gddt":"Là khung chương trình bắt buộc của Nhà nước, dạy đều cả 5 mặt: Thể chất, Nhận thức, Ngôn ngữ, Tình cảm – Kỹ năng xã hội và Thẩm mỹ.","novastars":"Là chương trình chuyên sâu riêng về Kĩ năng sống, dạy đều đặn 2 tiết/tuần × 36 tuần = 72 tiết/năm cho 3 khối: Mẫu giáo bé, Mẫu giáo nhỡ, Mẫu giáo lớn.","giong_nhau":"Đều hướng tới giúp trẻ ngoan ngoãn, khỏe mạnh, biết cư xử lễ phép và chuẩn bị sẵn sàng vào lớp 1.","khac_biet_an_tien":"Làm sâu và nổi bật hẳn mảng Kĩ năng sống – An toàn – Tự lập – Tự tin thuyết trình vốn trong chương trình Bộ chỉ được dạy lồng ghép rải rác.","sale_pitch":"Trường mua bản quyền Novastars để làm chương trình mũi nhọn về Kĩ năng sống trong giờ chính khóa. Vừa đúng định hướng của Bộ, vừa tạo điểm nhấn khác biệt rõ rệt cho trường."},{"stt":"2","title":"Cách sắp xếp bài học trong năm","bo_gddt":"Mỗi đề tài thường chỉ dạy gói gọn trong 1 tiết học độc lập: cô cho hát, kể chuyện hoặc xem tranh, hỏi đáp đúng – sai rồi chơi 1 đến 2 trò chơi trên bảng là kết thúc.","novastars":"Không dạy rời rạc từng tiết mà thiết kế theo cụm 2 đến 3 tiết nối tiếp nhau cho 1 kỹ năng: Tiết 1 hiểu quy tắc → Tiết 2 thực hành làm thật → Tiết 3 đứng lên thuyết trình chia sẻ.","giong_nhau":"Đều có các chủ đề rất quen thuộc với trẻ mầm non: chào hỏi, gia đình, ăn uống, giao thông, bảo vệ môi trường, cảm xúc, chuẩn bị vào lớp 1.","khac_biet_an_tien":"Mỗi kỹ năng đều được chia nhỏ tới từng cử chỉ cụ thể để trẻ làm theo được ngay như chào hỏi phải đủ mắt nhìn – miệng cười – tay vẫy hoặc khoanh; ngồi học đo đúng bằng thước 30cm.","sale_pitch":"Trẻ mầm non học 1 tiết rời rạc sẽ rất nhanh quên. Novastars đã nghiên cứu chia thành chuỗi nhiều tiết liên tiếp từ dễ đến khó suốt 3 năm học để biến kiến thức thành thói quen thật."},{"stt":"3","title":"Cách cô giáo tổ chức tiết học trên lớp","bo_gddt":"Cô giáo là người nói chính: cô mở tranh hoặc video, đặt câu hỏi cho trẻ trả lời đúng hay sai, cô làm mẫu rồi cho vài trẻ lên đóng vai hoặc chia 2 đội chạy lên gắn tranh lô tô.","novastars":"Trẻ là người hoạt động chính qua 4 đến 5 chặng liên tiếp trong 30 phút: Xem phim nhân vật → Chơi phản xạ toàn thân → Thực hành làm việc nhóm và kiểm tra bài cho bạn → Tự đứng thuyết trình.","giong_nhau":"Mẫu giáo án của Novastars trình bày giống hệt mẫu giáo án chuẩn của trường mầm non nên cô giáo nhìn vào là biết dạy ngay.","khac_biet_an_tien":"Có những phương pháp rất thông minh mà giáo án thường không có: cho trẻ 3 tuổi nhìn tranh tự tô để thuyết trình theo câu mẫu; trò chơi rèn tập trung não bộ trước khi tập ngồi viết; mẹo dùng 2 bàn tay phân biệt chữ b và d.","sale_pitch":"Khi mua chương trình, giáo viên của trường không phải vất vả tự nghĩ trò chơi hay cách dẫn dắt. Mọi câu hỏi, câu nói mẫu, cách chia nhóm đã được viết sẵn từng bước, cô rất nhàn mà tiết học lại cuốn hút."},{"stt":"4","title":"Phần mềm và phim hoạt hình đi kèm","bo_gddt":"Không có phần mềm chung. Mỗi cô tự lên mạng tìm nhạc, cắt ghép video và tự làm slide nên lớp cô khéo thì hay, lớp cô mới thì sơ sài.","novastars":"Có sẵn phần mềm Kĩ năng sống Novastars chạy trực tuyến hoặc tải về máy dạy không cần mạng, với bộ nhân vật hoạt hình Kem – Su – Sao Nova đi cùng trẻ suốt từ lớp 3 tuổi đến 5 tuổi.","giong_nhau":"Đều dùng hình ảnh, âm nhạc và video trên màn hình tivi hoặc máy chiếu sẵn có tại phòng học của trường.","khac_biet_an_tien":"Phim hoạt hình và trò chơi trên màn hình được thiết kế ăn khớp 100% với hoạt động dưới lớp của cô và trẻ: nhân vật Su hỏi gì, trẻ dưới lớp giơ thẻ, ném bóng hoặc nghiêng người trả lời đúng lượt đó.","sale_pitch":"Một trường mầm non hay một cô giáo không thể tự vẽ phim hoạt hình và lập trình hàng trăm trò chơi tương tác cho 216 tiết học. Mua Novastars giúp tất cả các lớp trong trường đều có học liệu đồng bộ và dạy đều tay như nhau."},{"stt":"5","title":"Thời lượng và sự phù hợp với số lượng cô trong lớp","bo_gddt":"Tiết học thông thường kéo dài 15 đến 20 phút ở lớp Bé, 20 đến 25 phút ở lớp Nhỡ, 25 đến 30 phút ở lớp Lớn.","novastars":"Thiết kế khung 30 phút mỗi tiết nhưng chia nhỏ thành 4 đến 5 hoạt động ngắn, mỗi hoạt động chỉ 5 đến 7 phút, thay đổi liên tục giữa xem phim, đứng nhảy, thảo luận, chơi vận động.","giong_nhau":"Hoàn toàn vừa vặn với số lượng 2 cô giáo mỗi lớp và không gian phòng học, sân trường sẵn có của các trường tư thục.","khac_biet_an_tien":"Trong từng giáo án đều vẽ sẵn sơ đồ cực kỳ rõ ràng: cô chính đứng đâu, cô phụ đứng đâu, bàn ghế xếp thế nào, đặt điện thoại quay phim ở góc nào để đảm bảo an toàn và trật tự.","sale_pitch":"Chủ trường không lo tốn thêm nhân sự hay quá sức trẻ. Trẻ không phải ngồi im nghe giảng 30 phút mà được vận động đổi trạng thái liên tục nên rất hào hứng."},{"stt":"6","title":"Kết quả nhìn thấy được để trường giới thiệu với phụ huynh","bo_gddt":"Cuối tuần phát phiếu bé ngoan hoặc gửi tranh tô màu về nhà; phụ huynh khó nhìn thấy con mình đã học được kỹ năng sống gì cụ thể.","novastars":"Mỗi bài đều có mục tiêu rõ ràng từ 70% đến 100% trẻ làm được, có hoạt động cho trẻ đứng thuyết trình trước máy quay và có bài tập nhỏ để tối về con thuyết trình lại cho bố mẹ nghe.","giong_nhau":"Đều mong muốn phụ huynh hài lòng, tin tưởng vào chất lượng chăm sóc và giáo dục của nhà trường.","khac_biet_an_tien":"Tạo ra sản phẩm truyền thông cực tốt cho trường: video con 3 tuổi dõng dạc giới thiệu 4 quy tắc đi xe an toàn, con 4 tuổi về nhà dạy lại bố mẹ 4 nguyên tắc phòng bỏng, con 5 tuổi thuyết trình báo tường 20/11.","sale_pitch":"Đây là lợi thế tuyển sinh và giữ chân phụ huynh cho trường tư thục: phụ huynh nhìn thấy con tự tin, hiểu chuyện qua từng tuần thì sẽ gắn bó lâu dài và giới thiệu thêm học sinh mới cho trường."}],"contentHtml":"","questions":[{"id":"hp01-std-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Quy mô thời lượng chuẩn của chương trình Kĩ năng sống Novastars khi đưa vào dạy chính khóa tại trường mầm non được thiết kế như thế nào?","options":["Triển khai 1 tiết/tuần trong 36 tuần (36 tiết/năm/khối), áp dụng đồng bộ cho cả 3 khối Bé, Nhỡ, Lớn với tổng 108 tiết học liệu chung.","Triển khai 2 tiết/tuần trong 36 tuần (72 tiết/năm/khối), áp dụng đồng bộ cho cả 3 khối Bé, Nhỡ, Lớn với tổng 216 tiết có học liệu riêng.","Triển khai 2 tiết/tuần trong 25 tuần (50 tiết/năm/khối), tập trung chủ yếu cho 2 khối Nhỡ và Lớn với tổng 100 tiết kỹ năng tự lập.","Triển khai lồng ghép 3 tiết/tuần vào giờ hoạt động góc của Bộ GD&ĐT (108 tiết/năm/khối) và chỉ áp dụng bắt buộc tại khối Mẫu giáo Lớn."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Tiêu chí 1 quy định 2 tiết/tuần × 36 tuần = 72 tiết/năm mỗi khối, đủ 3 khối Bé–Nhỡ–Lớn thành 216 tiết. | Phân biệt bẫy sai: Các phương án nhiễu giữ đúng bối cảnh chính khóa nhưng đánh tráo tần suất (1 tiết/tuần), số tuần (25 tuần) hoặc tổng số tiết (108 tiết)."},{"id":"hp01-std-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Vì sao trong Tiêu chí 2, Novastars không sắp xếp mỗi đề tài gói gọn trong 1 tiết độc lập mà tổ chức thành cụm 2 đến 3 tiết nối tiếp nhau?","options":["Vì trẻ cần 1 tiết dạy lý thuyết dài 45 phút rồi mới chuyển sang 1 tiết ôn tập tổng hợp cuối học kỳ nhằm tối ưu lịch học của trường.","Vì mỗi tiết chỉ nên giảng một khái niệm thật nhanh, phần còn lại giao về nhà cho phụ huynh tự kèm trẻ thực hành theo phiếu bài tập giấy.","Vì giáo án của Bộ GD&ĐT không có các chủ đề quen thuộc như chào hỏi, giao thông, ăn uống nên Novastars phải tách nhiều tiết để bù kiến thức nền.","Vì trẻ mầm non học 1 tiết rời rạc rất nhanh quên, cần chuỗi tiết nối tiếp từ hiểu quy tắc → thực hành làm thật → đứng thuyết trình để thành thói quen."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Tiêu chí 2 chỉ rõ trẻ học 1 tiết dễ quên, nên phải đi theo chuỗi Hiểu quy tắc → Thực hành → Thuyết trình qua 2–3 tiết. | Phân biệt bẫy sai: Novastars vẫn có chung chủ đề quen thuộc với khung Bộ và không dùng bài tập giấy về nhà hay tiết giảng 45 phút."},{"id":"hp01-std-3","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong một tiết học 30 phút của Novastars (Tiêu chí 3 & 5), tiến trình trên lớp được chia thành mấy chặng hoạt động và mỗi chặng kéo dài bao lâu?","options":["Chia thành 2 hoạt động lớn (15 phút/chặng): cô giảng kỹ nội dung bằng slide mở rộng, sau đó cho từng cặp trẻ lên đóng vai kiểm tra cuối giờ.","Chia thành 4 đến 5 hoạt động ngắn (5–7 phút/chặng), đổi trạng thái liên tục giữa xem phim, chơi phản xạ, thực hành nhóm và thuyết trình.","Chia thành 3 chặng cố định (10 phút/chặng): khởi động hát tập thể, cô làm mẫu hoàn toàn trên bục giảng và phát phiếu tô màu cá nhân tại bàn.","Chia thành 6 chặng nhanh (3–4 phút/chặng) chỉ áp dụng riêng cho khối Lớn 5–6 tuổi, còn khối Bé chỉ học 15 phút xem phim nhân vật rồi nghỉ."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Tiêu chí 3 & 5 quy định 30 phút chia 4–5 chặng (5–7 phút/chặng), liên tục đổi trạng thái giúp trẻ là trung tâm. | Phân biệt bẫy sai: Cả 3 khối đều dùng khung 30 phút chia 4–5 chặng, không rút xuống 15 phút hay để cô giảng 15 phút một chiều."},{"id":"hp01-std-4","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Khi Chủ trường băn khoăn: \"Trường chị ở khu vực mạng Wi-Fi hay chập chờn, mua phần mềm tương tác sợ lên lớp bị đơ làm hỏng tiết học\", Sale xử lý thế nào?","options":["Khẳng định phần mềm Novastars vừa chạy trực tuyến vừa tải được về máy để dạy offline không cần mạng, vẫn giữ nguyên nhân vật và game tương tác.","Đề xuất nhà trường tạm cắt bỏ các tiết dùng phần mềm trong học kỳ I, chỉ dạy những bài thủ công truyền thống đợi nâng cấp đường truyền sau.","Tư vấn nhà trường đầu tư thêm bộ phát Wi-Fi riêng cho từng phòng học vì phần mềm bắt buộc phải kết nối máy chủ liên tục mới mở được video.","Ghi nhận khó khăn của Chủ trường, sau đó gửi file PDF báo giá qua Zalo và đề nghị trường tự khảo sát lại hạ tầng mạng trước khi chốt lịch."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Tiêu chí 4 xác nhận phần mềm Novastars cho phép tải về máy để dạy hoàn toàn offline khi không có Internet. | Phân biệt bẫy sai: Tránh bẫy thừa nhận phụ thuộc mạng, cắt giảm bài học cốt lõi hoặc phản ứng thụ động chỉ gửi báo giá chờ trường."},{"id":"hp01-std-5","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Bộ nhân vật hoạt hình đồng hành xuyên suốt trong phần mềm Novastars từ khối 3 tuổi đến khối 5 tuổi gồm những nhân vật nào?","options":["Gồm 2 nhân vật là Mèo Con và Chú Cuội xuất hiện ở phần mở đầu video, sau đó giáo viên tự đóng vai dẫn tiếp các trò chơi vận động.","Gồm 3 nhân vật thay đổi theo từng khối lớp là Thỏ Trắng (khối Bé), Gấu Nâu (khối Nhỡ) và Ong Vàng (khối Lớn) nhằm tránh nhàm chán.","Gồm 3 nhân vật xuyên suốt là Kem, Su và Sao Nova dẫn dắt tình huống, đặt câu hỏi tương tác để trẻ dưới lớp phản hồi đúng lượt.","Gồm 4 nhân vật tiểu học là Nam, Lan, Kem và Rô-bốt chỉ xuất hiện từ nửa cuối Học kì II của khối Mẫu giáo Lớn khi ôn vào lớp 1."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Tiêu chí 4 nêu rõ bộ nhân vật xuyên suốt 3 năm học là Kem – Su – Sao Nova, ăn khớp với tương tác dưới lớp. | Phân biệt bẫy sai: Không thay đổi bộ nhân vật riêng theo từng tuổi và không dùng nhân vật minh họa rời rạc kiểu Mèo Con, Thỏ Trắng."},{"id":"hp01-std-6","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng hỏi: \"Trường đã dạy theo khung 5 mặt của Bộ GD&ĐT rồi, đưa thêm Novastars vào giờ chính khóa có bị trùng lặp hay trái quy định không?\"","options":["Giải thích Novastars là chương trình chuyên sâu Kĩ năng sống giúp làm rõ nét mảng vốn chỉ lồng ghép rải rác ở Bộ, biến thành mũi nhọn chính khóa.","Giải thích Novastars sẽ thay thế hoàn toàn mảng Tình cảm – Xã hội trong chương trình Bộ để giáo viên không phải soạn lại phần đó trong tuần.","Đề xuất xếp toàn bộ 72 tiết Novastars sang giờ đón trả trẻ buổi chiều muộn như câu lạc bộ tự chọn để hoàn toàn tách khỏi khung Bộ GD&ĐT.","Cam kết Bộ GD&ĐT quy định mọi trường tư thục bắt buộc mua thêm giáo trình Novastars như điều kiện công nhận chuẩn kiểm định chất lượng."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Tiêu chí 1 nhấn mạnh Novastars bám đúng định hướng Bộ nhưng đào sâu mảng KNS vốn chỉ được lồng ghép rải rác. | Phân biệt bẫy sai: Không nói sai sự thật (thay thế khung Bộ hay Bộ bắt buộc mua) và không tự hạ xuống ngoại khóa chiều muộn."},{"id":"hp01-std-7","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Khi Chủ trường hỏi: \"Trẻ học xong có kết quả cụ thể nào để phụ huynh nhìn thấy ngay thay vì cuối tuần chỉ phát phiếu bé ngoan?\", Sale nên nêu dẫn chứng nào?","options":["Nêu việc cuối mỗi tháng nhà trường tổ chức một buổi họp phụ huynh toàn trường để giáo viên chủ nhiệm đọc báo cáo nhận xét từng kỹ năng.","Nêu việc nhà trường phát thêm sổ theo dõi tô màu 20 trang mỗi tháng để phụ huynh tự chấm điểm mức độ ngoan ngoãn của con tại nhà.","Nêu chỉ tiêu 100% trẻ hoàn thành bài kiểm tra trắc nghiệm trên giấy vào cuối mỗi học kỳ để giáo viên gửi bảng điểm xếp hạng về cho phụ huynh.","Nêu chuỗi đầu ra truyền thông rõ ràng: bé 3 tuổi quay video 4 quy tắc đi xe, bé 4 tuổi dạy bố mẹ phòng bỏng, bé 5 tuổi thuyết trình báo tường 20/11."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Tiêu chí 6 cung cấp đúng 3 sản phẩm thực tế theo từng độ tuổi (video B45 3t, dạy bố mẹ phòng bỏng 4t, báo tường 20/11 5t). | Phân biệt bẫy sai: Không bịa ra bài thi trắc nghiệm giấy cho trẻ mầm non hay sổ tô màu 20 trang thay cho video/sản phẩm thật."},{"id":"hp01-std-8","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Chi tiết thiết kế nào trong giáo án Novastars giúp Chủ trường yên tâm triển khai ngay với đúng 2 cô giáo mỗi lớp mà không lo rối đội hình?","options":["Mỗi tiết học chỉ cho tối đa 10 trẻ ở lại trong lớp chơi phần mềm, nhóm còn lại sang phòng đa năng cùng cô trợ giảng chờ đến lượt thay ca.","Từng giáo án vẽ sẵn sơ đồ vị trí cô chính, cô phụ, cách kê bàn ghế và góc đặt điện thoại quay phim, kèm sẵn lời dẫn và bước chia nhóm.","Tất cả hoạt động nhóm đều được chuyển sang hình thức ngồi yên tại bàn cá nhân để 2 cô giáo chỉ cần đứng quan sát từ bục giảng phía trên.","Nhà trường được cung cấp thêm 1 nhân viên kỹ thuật của Novastars trực tiếp đứng lớp hỗ trợ bấm máy chiếu và điều phối trẻ suốt năm học."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Tiêu chí 3 & 5 chỉ rõ giáo án chuẩn hóa cả sơ đồ vị trí 2 cô, sắp xếp bàn ghế, góc quay phim và lời dẫn từng bước. | Phân biệt bẫy sai: Không tách đôi lớp sang phòng khác, không triệt tiêu vận động nhóm và không kèm nhân sự kỹ thuật cắm chốt tại lớp."},{"id":"hp01-std-9","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Theo Tiêu chí 2 & 3 trong Bảng Tổng quan, những phương pháp sư phạm đặc trưng nào của Novastars giúp trẻ nhỏ nhớ sâu và làm đúng kỹ năng hơn?","options":["Chia lớp thành 2 đội chạy tiếp sức gắn thẻ lô tô mặt cười – mặt mếu lên bảng từ rồi cô giáo chấm điểm cộng trừ cho từng tổ vào cuối tuần.","Dùng bài thơ vần 8 câu để cả lớp đọc đồng thanh đầu giờ, kết hợp treo bảng nội quy chữ in hoa cỡ lớn ở bốn góc tường cho trẻ nhìn theo.","Cho trẻ xem lại toàn bộ bản ghi hình tiết học của lớp khác trước khi thực hành, sau đó yêu cầu mỗi bé chép lại 1 lần bảng quy tắc ra vở.","Dùng tranh tự tô làm điểm tựa thuyết trình cho trẻ 3 tuổi, trò chơi rèn tập trung não bộ trước khi ngồi viết, và mẹo 2 bàn tay phân biệt chữ b và d."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Tiêu chí 3 liệt kê đúng 3 kỹ thuật đặc trưng: tranh tự tô để thuyết trình 3t, game tập trung não bộ và mẹo 2 tay b–d. | Phân biệt bẫy sai: Gắn thẻ mặt cười/mếu hay đọc thơ đồng thanh là lối dạy truyền thống trường hay làm, không phải USP của Novastars."},{"id":"hp01-std-10","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Chủ trường lo ngại: \"Cô lớn tuổi ở trường vững chuyên môn nhưng ngại công nghệ, còn cô mới ra trường lại thiếu kinh nghiệm, liệu dạy có bị lệch chất lượng?\"","options":["Trấn an rằng trường có thể giao toàn bộ 72 tiết phần mềm cho 2 cô trẻ nhất trường chạy xoay vòng dạy thay ở tất cả các lớp trong khối.","Đề xuất nhà trường yêu cầu giáo viên tự biên tập lại giáo án và quay video bổ trợ trước mỗi học kỳ cho phù hợp với thói quen riêng của từng lớp.","Khẳng định giáo án viết theo đúng chuẩn mẫu mầm non quen thuộc kèm từng câu dẫn, kết hợp phần mềm và video giúp cả cô mới lẫn cô lâu năm dạy đều tay.","Giải thích rằng phần mềm tự động vận hành suốt 30 phút nên cô giáo chỉ cần bật máy chiếu cho trẻ làm theo nhân vật mà không cần can thiệp nhiều."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Tiêu chí 3 & 4 chứng minh mẫu giáo án giống chuẩn mầm non + lời dẫn + phần mềm sẵn có giúp mọi lớp dạy đồng bộ. | Phân biệt bẫy sai: Không đẩy cô lên vai trò bật máy chiếu thụ động, không giao hết cho cô trẻ chạy show hay bắt cô tự soạn lại video."},{"id":"hp01-std-11","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Mức độ đạt mục tiêu đầu ra được thiết kế trong từng tiết học Novastars và giá trị cốt lõi đối với công tác tuyển sinh là gì?","options":["Mỗi bài đặt chuẩn đầu ra rõ ràng từ 70% đến 100% trẻ thực hiện được kèm video thực tế giúp phụ huynh tin tưởng, gắn bó và giới thiệu học sinh mới.","Mỗi bài đặt chuẩn tối thiểu 50% trẻ nhớ được tên bài học trên lớp và nhận đủ 10 phiếu bé ngoan cuối tháng để làm hồ sơ thi đua với phòng giáo dục.","Chỉ đặt mục tiêu đạt 80% ở các bài tổng kết cuối học kỳ, các bài thường trong tuần không cần đo tỷ lệ trẻ làm được để giảm áp lực cho giáo viên.","Đặt chuẩn đầu ra đồng nhất là 100% trẻ phải tự quay video thuyết trình dài 5 phút tại nhà với sự chấm điểm trực tiếp của tổ trưởng chuyên môn."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Tiêu chí 6 nêu mức đạt từng bài là 70%–100% trẻ làm được kèm bài thuyết trình/bài tập nhỏ về nhà tạo uy tín tuyển sinh. | Phân biệt bẫy sai: Không có mức chuẩn 50% hay video dài 5 phút, và từng tiết đều có mục tiêu đo được chứ không đợi cuối học kỳ."},{"id":"hp01-std-12","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Điểm khác biệt cốt lõi nhất giữa việc \"trường tự dạy qua hình ảnh trên tivi\" và \"phần mềm Kĩ năng sống Novastars\" nằm ở đâu?","options":["Ở số lượng bài hát thiếu nhi tiếng Anh tích hợp sẵn nhiều gấp đôi giúp tiết Kĩ năng sống kiêm luôn vai trò tiết làm quen ngoại ngữ mỗi tuần.","Ở độ phân giải video trên phần mềm Novastars cao hơn video tải từ mạng nên trẻ nhìn rõ hình vẽ hơn khi chiếu lên tivi cỡ lớn trong lớp.","Ở màn hình tương tác Novastars đồng bộ nhịp câu hỏi của Sao Nova/Su với hành động giơ thẻ, ném bóng, nghiêng người của cả lớp dưới phòng.","Ở tính năng tự động điểm danh khuôn mặt học sinh mỗi đầu tiết học giúp giáo viên giảm bớt thao tác nhập sổ theo dõi sĩ số buổi sáng."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Tiêu chí 4 nhấn mạnh sự ăn khớp 100% giữa lời hỏi của nhân vật trên màn hình với thao tác giơ thẻ, ném bóng, nghiêng người dưới lớp. | Phân biệt bẫy sai: Điểm ăn tiền là tính tương tác sư phạm hai chiều giữa phần mềm và lớp học, không phải độ phân giải hay tính năng điểm danh."}],"authorId":"admin"},{"id":"mod-02-nen-tang-sp","code":"HP02","title":"6 Lý Do Thuyết Phục Chủ Trường: Vì sao Cô giáo dễ dạy nhưng không thể tự soạn được như Novastars?","status":"published","category":"Nghiệp vụ Tư vấn & Xử lý Từ chối","subtitle":"Dùng cho Sale khi Hiệu trưởng hỏi: 'Mấy bài kỹ năng này các cô trường chị tự soạn giáo án dạy cũng được, sao phải mua chương trình?'","questions":[{"id":"hp02-std-1","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng nói: \"Kỹ năng chào hỏi dễ thế thì cô giáo tự kể chuyện rồi đóng vai trong lớp là xong, việc gì phải dùng giáo án Novastars?\" — Sale phân tích thế nào?","options":["Khuyên Hiệu trưởng mời phụ huynh của tất cả các bé đến ngồi dự giờ trực tiếp ngay trong tiết đầu tiên để tạo môi trường có người lạ cho trẻ tập chào.","Đề nghị trường giữ nguyên cách đóng vai tại bục giảng nhưng kéo dài thêm 15 phút hát múa mở đầu để các bé dạn dĩ hơn trước khi về chỗ ngồi.","Phân tích tâm lý trẻ 3–4 tuổi ngồi trong lớp trả lời rất to nhưng ra sân gặp khách thật lại rụt rè; Novastars tách B05 học câu và B06 đi chào người thật.","Thừa nhận chào hỏi là kỹ năng đơn giản nên trường có thể tự dạy theo cách cũ, còn bản quyền Novastars chỉ cần mua để dạy các bài phòng tránh tai nạn."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Lý do 1 chỉ rõ tách B05 (trong lớp) → B06 (ra sân gặp người thật) cùng 3 cử chỉ mắt–tay–miệng khắc phục nỗi sợ người lạ. | Phân biệt bẫy sai: Không nhượng bộ cắt phần nền tảng của khối Bé, cũng không bắt phụ huynh dự giờ thay cho kỹ thuật xếp hàng đi sân trường."},{"id":"hp02-std-2","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong bài B06 khối Bé, kỹ thuật sư phạm tinh tế nào giúp ngay cả những bé 3 tuổi nhút nhát nhất cũng dám cất tiếng chào người gặp trên sân trường?","options":["Cô chính đi đầu hàng chủ động mở lời chào mẫu thật tươi trước rồi nhắc cả lớp đồng thanh chào to theo, không ép từng bé đơn lẻ chào trước.","Cô chia các bé thành từng cặp tự tách đoàn đi gõ cửa các phòng ban, bé nào chào to sẽ được phát phiếu khen trước toàn trường vào cuối tuần.","Cô phụ đứng ở cuối hàng chỉ định luân phiên 3 bé mạnh dạn nhất lớp bước lên chào thay diện mạo cả lớp trước khách để đảm bảo trật tự hàng lối.","Cô phát sẵn loa cầm tay cho bé đứng đầu hàng tự giới thiệu tên lớp rồi các bạn phía sau chỉ cần khoanh tay cúi đầu mỉm cười mà không cần nói."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Lý do 1 & B06: Cô chính dẫn đầu, chủ động chào mẫu phá băng trước rồi cả lớp đồng thanh chào theo giúp trẻ hết sợ. | Phân biệt bẫy sai: Không tách lẻ trẻ hay để vài bé nói thay; hiệu ứng cô làm gương + đồng thanh là chi tiết đắt giá nhất."},{"id":"hp02-std-3","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Công thức 4 bước trong bài B45 khối Bé (An toàn giao thông) được sắp xếp theo đúng trình tự nào để bé 3 tuổi đứng thuyết trình trôi chảy trước máy quay?","options":["Xem video đèn xanh đèn đỏ → Chơi chạy dừng theo hiệu lệnh còi → Chọn 2 bạn lớp trưởng đứng trước giá vẽ nói thay cho toàn bộ lớp để quay tư liệu.","Cô đọc mẫu trọn bài thuyết trình 5 lần → Cho từng bé đơn lẻ đứng lên bục giảng thuộc lòng không nhìn tranh → Phát bảng vẽ tự do cuối giờ.","Hỏi lý do để nhớ 4 quy tắc → Tô và dán 4 tranh lên giá vẽ làm điểm tựa → Dạy câu mẫu 3 phần & nói đồng thanh → Nhóm 4–6 bé đứng cạnh giá vẽ quay video.","Tô màu 4 bức tranh giao thông tại bàn → Cất toàn bộ tranh vào ba lô mang về nhà → Cô giáo quay video phỏng vấn cá nhân từng bé ở góc lớp."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Lý do 2 ghi chuẩn 4 bước B45: hiểu lý do → tranh tự tô trên giá vẽ làm điểm tựa → câu mẫu 3 phần đồng thanh → nhóm 4–6 bé quay video. | Phân biệt bẫy sai: Bắt trẻ 3 tuổi nói đơn lẻ không nhìn tranh hoặc không qua bước đồng thanh sẽ khiến trẻ khớp và im lặng."},{"id":"hp02-std-4","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Tại sao ở bài B45 khối Bé, giáo án lại bố trí nhóm 4 đến 6 bé cùng đứng hai bên bảng giá vẽ thay vì gọi từng bé đứng thuyết trình một mình?","options":["Vì thời lượng 30 phút không đủ để quay lần lượt từng bé một nên buộc phải gộp nhóm để kịp phát hết phần thưởng sticker trước giờ ăn trưa.","Vì trẻ 3 tuổi có vốn từ ít và dễ run; đứng cùng nhóm bạn hai bên giá vẽ có tranh tự tô làm điểm tựa giúp bé hết ngại và nhớ đủ cả 4 ý.","Vì mỗi bảng giá vẽ chỉ có kích thước đủ để 4 đến 6 bé cùng cầm giữ chân bảng cho khỏi đổ khi giáo viên đặt điện thoại quay ở khoảng cách gần.","Vì cô phụ cần giữ trật tự 20 bé còn lại ở cuối lớp nên chỉ gọi những bé ngồi gần bàn giáo viên nhất lên đứng thành hàng ngang trước giá vẽ."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Lý do 2: Nhóm 4–6 bé đứng cùng nhau bên giá vẽ tranh tự tô tạo tâm lý an toàn và điểm tựa trí nhớ cho trẻ 3 tuổi. | Phân biệt bẫy sai: Không phải vì thiếu thời gian hay giữ giá vẽ mà là chủ đích tâm lý học lứa tuổi mầm non."},{"id":"hp02-std-5","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Ở bài B56 khối Lớn (Tư thế ngồi học), trò chơi \"Thỏ con tinh nghịch\" với luật \"Chỉ làm theo lời Su nói, không làm theo tay cô làm\" có tác dụng sư phạm gì?","options":["Thay thế hoàn toàn phần hướng dẫn tư thế ngồi và cầm bút để trẻ tự hình thành phản xạ đúng thông qua 8 lượt chơi vận động trước màn hình.","Giúp trẻ 5 tuổi thuộc nhanh tên 4 động tác múa khởi động cổ tay để giảm mỏi khớp ngón tay trước khi bước vào luyện viết nét cong kín trên vở.","Giúp giáo viên phân loại ngay đầu giờ nhóm trẻ nào hay mất tập trung để xếp ngồi bàn đầu riêng và miễn tham gia phần thực hành thước đo 30cm.","Kích hoạt sự tập trung chú ý cao độ của não bộ để trẻ 5 tuổi làm chủ cơ thể trước khi bước vào 4 bước đo khoảng cách mắt 30cm và 3 bước cầm bút."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Lý do 3: Trẻ 5t hiếu động nhắc miệng dễ quên sau 2 phút; game 8 lượt đánh thức tập trung não bộ trước khi rèn kỹ thuật ngồi & đo 30cm. | Phân biệt bẫy sai: Trò chơi là bước khởi động kích hoạt tập trung não bộ dẫn vào luyện tư thế, không thay thế việc tập ngồi đo thước 30cm."},{"id":"hp02-std-6","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Mẹo trực quan bằng đôi bàn tay trên phần mềm ở bài B57 khối Lớn giúp trẻ không còn viết nhầm chữ \"b\" và chữ \"d\" được quy ước chính xác như thế nào?","options":["Giơ nắm tay nút Thích (ngón cái dựng đứng): bàn tay PHẢI tạo thành hình chữ b, bàn tay TRÁI tạo thành hình chữ d ngược chiều để trẻ nhớ.","Giơ nắm tay nút Thích (ngón cái dựng đứng): bàn tay TRÁI tạo thành hình chữ b, bàn tay PHẢI tạo thành hình chữ d để trẻ soi ngay khi viết.","Úp hai lòng bàn tay áp sát vào nhau trước ngực để ngón trỏ tạo nét sổ thẳng ở giữa, phân biệt chữ b nằm trên còn chữ d nằm phía dưới.","Dùng hai ngón trỏ và giữa của tay phải ghép thành vòng tròn chữ o, sau đó dùng tay trái giơ thẳng bên cạnh làm dấu hiệu chữ đ có gạch."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Lý do 4 & B57: Giơ nút Thích — TAY TRÁI tạo đúng chữ b, TAY PHẢI tạo đúng chữ d. | Phân biệt bẫy sai: Bẫy kinh điển là đảo ngược tay trái thành chữ d, tay phải thành chữ b — cần kiểm tra kỹ phản xạ 2 tay thật."},{"id":"hp02-std-7","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Điểm khác biệt sâu sắc trong bài B13 (Cảm xúc của bé — khối Nhỡ) so với cách dạy cảm xúc truyền thống tại trường mầm non nằm ở khía cạnh nào?","options":["Tôn trọng trẻ tự chọn màu theo cảm nhận cho Huy hiệu 4 mặt để lật báo cảm xúc với cô suốt cả năm, thay vì ép màu cứng nhắc hay chỉ soi gương.","Quy định chuẩn màu đỏ là tức giận, màu xanh là buồn, màu vàng là vui để toàn bộ 100% trẻ trong lớp tô giống nhau thành bộ giáo cụ đồng bộ.","Yêu cầu trẻ 4 tuổi luôn phải giơ mặt vui vẻ trước lớp, nếu có cảm xúc buồn hay sợ hãi thì tự úp mặt xuống bàn nghỉ 5 phút trước khi học tiếp.","Tổ chức cho hai đội thi gắn tranh mặt cười – mặt mếu lên bảng từ trong 3 phút, đội gắn đúng nhiều mặt hơn sẽ được giáo viên khen thưởng trước lớp."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Lý do 5: B13 không ép màu sắc cảm xúc cố định và biến sản phẩm thành Huy hiệu lật mặt giao tiếp thật với cô suốt năm học. | Phân biệt bẫy sai: Ép màu cứng nhắc hay chỉ dạy cười – tránh buồn là cách tiếp cận phi tâm lý mà B13 khắc phục hoàn toàn."},{"id":"hp02-std-8","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Trong bài B09 khối Nhỡ (Ăn uống đủ chất dinh dưỡng), điểm tổ chức nào giúp trẻ tự nhận ra thói quen kén ăn của mình và nhớ bài sâu gấp đôi?","options":["Lớp chia thành 2 đội chạy tiếp sức lên bảng gắn thẻ thực phẩm vào 4 ngôi nhà, sau đó cô giáo đứng trên bục đếm số thẻ đúng và công bố đội thắng.","Giáo viên chuẩn bị sẵn một thực đơn mẫu chuẩn 4 nhóm chất trên màn hình để cả lớp tô màu giống hệt nhau rồi dán lên bảng tổng kết chung.","Mỗi bé tự làm bảng 5 món mình thích vào 4 nhóm chất rồi 2 bạn ngồi cạnh tự kiểm tra chéo cho nhau để nhắc bạn dán bù nhóm rau hoặc thịt bị thiếu.","Phụ huynh gửi ảnh bữa cơm tối của con lên nhóm lớp trước buổi học để giáo viên trình chiếu và trực tiếp chấm điểm thực đơn của từng gia đình."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Lý do 5 & B09: Trẻ tự chọn 5 món yêu thích nên dễ lộ thiếu nhóm, rồi cặp đôi kiểm tra chéo nhắc nhau bổ sung. | Phân biệt bẫy sai: Chạy tiếp sức để cô chấm là cách dạy truyền thống; B09 chuyển quyền tự kiểm tra và nhắc nhở sang chính cặp bạn."},{"id":"hp02-std-9","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Với bài B39 khối Nhỡ (Phòng tránh nguy cơ bỏng, nóng), ngoài việc nhắc tránh vật nóng, Novastars nâng cấp nội dung sinh hoạt thực tế & sơ cứu gì cho trẻ?","options":["Biết nhờ người lớn kiểm tra nước tắm, làm nguội thức ăn nóng, ngồi xa máy sưởi và tự xả nước mát vào vết bỏng ngay rồi mới báo người lớn.","Học thuộc khẩu hiệu \"Nóng là không chạm\", khi lỡ bị bỏng nhẹ thì dùng kem đánh răng hoặc nước mắm thoa nhanh lên vết thương chờ bố mẹ về.","Chỉ cần nhận diện 4 hình ảnh ấm siêu tốc, phích nước, bếp ga và bàn là trên tranh minh họa rồi gạch chéo đỏ lên những vật gây bỏng đó.","Tự tay dùng khăn khô lau sạch tay khi bị dính nước sôi và ngồi im chờ cô giáo mang hộp thuốc y tế đến băng kín vết bỏng bằng gạc vô trùng."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Lý do 6 & B39: Dạy kỹ năng nhờ người lớn thử nước/làm nguội đồ ăn và bước sơ cứu y tế chuẩn là xả/ngâm nước mát ngay. | Phân biệt bẫy sai: Tuyệt đối không dạy giữ khô hay dùng mẹo dân gian sai y khoa; phần mềm B39 nhấn mạnh xả nước mát ngay."},{"id":"hp02-std-10","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Chuỗi hoạt động 30 phút trong bài B39 khối Nhỡ chứng minh sức mạnh đóng gói sẵn của phần mềm Novastars qua trình tự 4 chặng nào?","options":["Thảo luận nhóm về bỏng lạnh và bỏng hóa chất → Tập băng bó vết thương giả định bằng băng gạc thật → Làm bài thu hoạch cuối giờ tại bàn.","Nghe cô kể chuyện về bạn nhỏ nghịch bếp → Tô màu tranh phích nước nóng → Chơi trò chơi chuyền bóng tại chỗ → Thu tranh dán lên góc lớp.","Xem phim hoạt hình Mẹ Su suốt 20 phút → Cả lớp đọc đồng thanh 4 câu khẩu hiệu phòng bỏng → Cô giáo phát phiếu đánh dấu đồ vật nguy hiểm.","Giơ thẻ Xanh/Đỏ với 16 đồ vật → Chạy thả bóng vào 4 rổ → Xem phim Mẹ Su dạy phòng & sơ cứu bỏng → Đứng thuyết trình xử lý 4 tình huống của Su."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Lý do 6 ghi chuẩn 4 chặng B39: 16 lượt thẻ Xanh/Đỏ → ném bóng 4 rổ → phim Mẹ Su → thuyết trình 4 tình huống của Su. | Phân biệt bẫy sai: Các phương án khác mô tả lối dạy thủ công hoặc bịa nội dung băng gạc/bỏng hóa chất không có trong giáo án B39."},{"id":"hp02-std-11","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng nhận xét: \"Dịp 20/11 năm nào lớp 5 tuổi trường chị cũng cho bé tô thiệp tặng cô, bài B70 của Novastars có gì mới để phụ huynh ấn tượng hơn?\"","options":["Giải thích B70 cho mỗi bé tự vẽ 3 tấm thiệp khổ lớn mang về tặng cả cô giáo cũ lớp Bé, lớp Nhỡ và cô lớp Lớn kèm bài hát đồng ca.","Giải thích B70 chuyển từ mỗi bé tô 1 thiệp riêng sang cả lớp chia 4 nhóm ghép thành 1 tờ Báo tường khổ lớn A1 giống Tiểu học rồi thuyết trình nối tiếp.","Giải thích B70 mời phụ huynh trực tiếp vào lớp ngồi cắt dán hoa giấy cùng con suốt 30 phút để tăng sự gắn kết giữa gia đình và nhà trường.","Giải thích B70 sử dụng hoàn toàn thiệp điện tử thiết kế trên phần mềm để các bé bấm chọn nhãn dán chúc mừng gửi qua ứng dụng của trường."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Lý do 6 & B70: Chia 4 nhóm chuyên môn ghép 1 tờ Báo tường A1 (trái tim vân tay, hoa nổi, chân dung cô, chữ CON–CÔ) + thuyết trình nhóm. | Phân biệt bẫy sai: Tô thiệp rời từng cá nhân hay dùng thiệp điện tử đều không tạo được dự án tập thể kiểu Tiểu học như Báo tường A1."},{"id":"hp02-std-12","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Sau khi trình bày các bài mẫu ở Học phần 2, Sale dùng luận điểm tổng kết đắt giá nào để chốt giá trị bản quyền với Chủ trường?","options":["Trường được đảm bảo mọi học sinh 5 tuổi sau khi hoàn thành chương trình đều viết thành thạo đoạn văn ngắn và làm toán cộng trừ trước khi vào lớp 1.","Trường chỉ cần mua phần mềm để giáo viên tham khảo ý tưởng 1 tháng đầu, sau đó các cô hoàn toàn có thể tự cắt bỏ và chỉnh lại thành giáo án ngắn 10 phút.","Trường sẽ cắt giảm được một nửa số lượng giáo viên đứng lớp hiện tại vì toàn bộ trò chơi và thuyết trình đã có hệ thống phần mềm tự động điều khiển.","Trường nhận trọn hệ thống bài giảng chuẩn tâm lý lứa tuổi, 16 lượt game, chuỗi phim Mẹ Su–Kem–Sao Nova và mẫu học liệu mà cô đơn lẻ không tự làm nổi."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Câu chốt Lý do 6 nhấn mạnh sự đóng gói đồng bộ từ chuyên gia (phim Mẹ Su, 16 lượt game, mẫu A1, chuẩn tâm lý) giúp trường sở hữu hệ thống chuyên sâu. | Phân biệt bẫy sai: Tuyệt đối tránh các cam kết sai lệch về giảm giáo viên hay dạy trước kiến thức toán/chính tả lớp 1."}],"updatedAt":"2026-11-26T08:46:39.402Z","authorName":"Phạm Mỹ Linh","sourceFile":{"url":"data/files/So_sanh_Novastars_va_Chuong_trinh_Bo_GDDT_Chinh_khoa.xlsx","name":"So_sanh_Novastars_va_Chuong_trinh_Bo_GDDT_Chinh_khoa.xlsx","type":"xlsx","sheetName":"2_Chung_minh_Nen_tang_SP"},"contentHtml":"","passThreshold":80,"summaryPoints":["Lý do 1 (Bài B05–B06 khối Bé): Biến 'biết nói trong lớp' thành 'dám làm ngoài đời thật' qua chuỗi 2 tiết và kỹ thuật cô chủ động chào mẫu phá băng khi dẫn trẻ đi quanh trường.","Lý do 2 (Bài B45 khối Bé): Công thức 4 bước giúp bé 3 tuổi vốn từ còn ít vẫn đứng thuyết trình trọn bài trước máy quay nhờ điểm tựa 4 bức tranh tự tô trên giá vẽ.","Lý do 3 (Bài B56 khối Lớn): Chơi 'Thỏ con tinh nghịch' 8 lượt kích hoạt sự tập trung não bộ trước khi dùng thước 30cm đo khoảng cách mắt tới vở và tập 3 bước cầm bút.","Lý do 4 (Bài B57 khối Lớn): Mẹo giơ hai bàn tay bấm nút Thích (Tay trái = chữ b, Tay phải = chữ d) giải quyết dứt điểm lỗi nhầm chữ b và d của trẻ 5–6 tuổi.","Lý do 5 (Bài B09 & B13 khối Nhỡ): Biến sản phẩm thủ công thành công cụ dùng thật (Huy hiệu cảm xúc 4 mặt lật được suốt năm; Bảng phân loại món ăn để 2 bạn ngồi cạnh tự kiểm tra chéo cho nhau).","Lý do 6 (Bài B39 khối Nhỡ & B70 khối Lớn): Dạy kỹ năng an toàn tới tận bước sơ cứu xả nước mát khi bị bỏng (16 lượt thẻ màu + phim Mẹ Su) và làm dự án Báo tường khổ lớn A1 như học sinh Tiểu học."],"structuredData":[{"stt":"1","title":"Biến biết nói trong lớp thành dám làm ngoài đời thật","sale_pitch":"Với 2 cô sẵn có trong lớp, cầm giáo án Novastars là các cô dẫn trẻ đi thực hành rất nhẹ nhàng. Nhưng nếu tự soạn, các cô thường chỉ đóng vai trong phòng học chứ không thiết kế thành chuỗi 2 tiết nối tiếp và kỹ thuật cô chào mẫu phá băng trước như vậy.","tam_ly_tre":"Trẻ 3 đến 4 tuổi ngồi trong lớp cô hỏi Gặp người lớn phải làm gì thì trả lời rất to là Khoanh tay chào ạ. Nhưng vừa bước ra sân gặp khách lạ hay bác bảo vệ là cúi mặt trốn sau lưng mẹ, vì trẻ chưa được tập chào người thật ngoài không gian lớp học.","cach_novastars":"• Bài B05 và B06 khối Bé: Tách hẳn thành 2 tiết. Tiết B05 học câu chào trong lớp; sang tiết B06 chỉ tập trung rèn 3 cử chỉ gồm Mắt nhìn thẳng – Tay vẫy bạn hoặc khoanh tay với người lớn – Miệng cười tươi, rồi 2 cô dẫn cả lớp xếp hàng đi quanh sân trường gặp người thật để chào. Cô chủ động chào mẫu trước cho trẻ hết ngại rồi cả lớp chào to theo.","cach_truong_thuong_day":"Cô giáo soạn 1 tiết học gồm: hát mở đầu → kể chuyện về lễ phép → gọi vài bé lên bục giảng đóng vai chào cô, chào bạn rồi chơi trò chơi chọn mặt cười, mặt mếu trong phòng học."},{"stt":"2","title":"Công thức 4 bước giúp bé 3 tuổi đứng thuyết trình trước máy quay","sale_pitch":"Cô giáo của trường áp dụng cực kỳ dễ vì câu nói mẫu và cách bố trí giá vẽ, góc quay phim đã có sẵn trong giáo án. Nhờ vậy ngay từ lớp 3 tuổi trường đã có video học sinh đứng thuyết trình dõng dạc để gửi cho phụ huynh.","tam_ly_tre":"Trẻ 3 tuổi vốn từ còn ít và hay quên. Nếu chỉ bảo Con lên nói quy tắc giao thông cho các bạn nghe đi thì bé sẽ đứng im hoặc chỉ nói cụt lủn 1 đến 2 chữ khi cô nhắc.","cach_novastars":"• Bài B45 khối Bé: Dùng công thức 4 bước giúp bé tự nói trọn bài: Bước 1 hỏi lý do để trẻ tự nhớ 4 quy tắc đi xe → Bước 2 cho trẻ tô màu tranh quy tắc rồi dán 4 tranh đó lên giá vẽ giữa lớp để trẻ nhìn vào không bị quên ý → Bước 3 dạy câu nói mẫu 3 phần và cả lớp đứng tập nói đồng thanh → Bước 4 cho nhóm 4 đến 6 bé lên đứng cạnh giá vẽ thuyết trình để cô quay video.","cach_truong_thuong_day":"Trong tiết An toàn giao thông, các cô thường cho xem tranh đèn xanh – đèn đỏ, hỏi trẻ hành vi nào đúng hay sai, rồi cho trẻ chơi chạy hoặc dừng theo tín hiệu đèn cô giơ trên tay."},{"stt":"3","title":"Trò chơi rèn sự tập trung não bộ trước khi rèn nền nếp lớp 1","sale_pitch":"Trò chơi này cô giáo tổ chức tại lớp rất vui và không tốn đồ dùng gì phức tạp, nhưng cách sắp xếp chơi rèn phản xạ tập trung trước rồi dùng thước 30cm đo tư thế thật sau là do đội ngũ chuyên gia nghiên cứu tâm lý trẻ 5 tuổi thiết kế sẵn.","tam_ly_tre":"Trẻ 5 tuổi rất hiếu động, tay chân hay làm theo thói quen bộc phát. Nếu chỉ nhắc miệng Ngồi thẳng lưng lên, cầm bút đúng vào thì chỉ được 2 phút là trẻ lại cúi gập người xuống bàn.","cach_novastars":"• Bài B56 khối Lớn: Tách riêng thành 1 tiết rèn tư thế chuẩn bị vào lớp 1. Trước khi tập ngồi, cho trẻ chơi trò Thỏ con tinh nghịch 8 lượt với luật: Chỉ làm theo lời nhân vật Su nói, không làm theo động tác cô làm đánh lừa để kích hoạt sự tập trung cao độ của não bộ. Sau đó mới dạy 4 bước ngồi dùng thước 30cm đo đúng khoảng cách mắt tới vở và 3 bước cầm bút.","cach_truong_thuong_day":"Các cô thường ghép việc nhắc tư thế ngồi và cách cầm bút vào 5 phút đầu của giờ Tập tô chữ, sau đó phát vở cho trẻ tô và cô đi từng bàn nhắc nhở."},{"stt":"4","title":"Mẹo dùng chính đôi bàn tay trẻ để không bao giờ nhầm chữ b và d","sale_pitch":"Chỉ một mẹo nhỏ dùng hai bàn tay gắn với video trên phần mềm nhưng giải quyết dứt điểm nỗi đau lớn nhất khi dạy chữ lớp 5 tuổi. Cô giáo trường dạy rất nhàn mà phụ huynh thấy con phân biệt chữ b và d nhanh vượt trội.","tam_ly_tre":"Trẻ 5 đến 6 tuổi khi mới học chữ cực kỳ hay nhầm chữ b với chữ d vì hai chữ này ngược chiều trái – phải với nhau.","cach_novastars":"• Bài B57 khối Lớn: Trước hết cho trẻ xem phim để thấy thích học chữ vì biết chữ giúp tự đọc truyện tranh, viết thư cho ông bà. Sau đó dạy trẻ mẹo cực hay trên phần mềm: Giơ nắm tay bấm nút Thích – TAY TRÁI tạo thành đúng hình chữ b, TAY PHẢI tạo thành đúng hình chữ d, rồi cho trẻ nhìn từ trên bảng và viết nhanh chữ b hoặc d ra giấy giơ lên.","cach_truong_thuong_day":"Trong tiết Làm quen chữ cái b, d, đ, các cô thường giơ thẻ chữ và giải thích bằng lời: Chữ b có nét sổ thẳng bên trái, nét cong tròn bên phải; chữ d có nét cong tròn bên trái, nét sổ thẳng bên phải. Trẻ nghe lúc đó nhưng khi viết vẫn bị lẫn."},{"stt":"5","title":"Biến đồ thủ công và bài tập thành công cụ trẻ dùng thật, tự kiểm tra cho nhau","sale_pitch":"Cách tổ chức này giúp lớp học của cô sinh động hơn hẳn: trẻ biết quan tâm kiểm tra giúp bạn và biết dùng huy hiệu báo cảm xúc với cô suốt cả năm học, chứ không phải làm đồ thủ công xong rồi cất đi.","tam_ly_tre":"Trẻ 4 đến 5 tuổi khi buồn, sợ hay tức giận thường khóc hoặc ăn vạ vì chưa biết diễn tả bằng lời. Khi học kiến thức mới như ăn uống đủ chất, nếu chỉ cô giáo kiểm tra thì trẻ rất thụ động.","cach_novastars":"• Bài B13 khối Nhỡ: Cho mỗi trẻ tự chọn màu sắc theo cảm nhận riêng để làm Huy hiệu cảm xúc 4 mặt. Khi nào trẻ buồn, sợ hay giận mà chưa nói được thì chỉ cần lật mặt huy hiệu đó lên để cô và bạn hiểu, hỗ trợ kịp thời.\n• Bài B09 khối Nhỡ: Mỗi trẻ tự làm bảng phân loại 5 món ăn mình thích vào 4 nhóm chất, rồi 2 bạn ngồi cạnh tự kiểm tra bài cho nhau xem bạn mình thiếu nhóm rau hay thịt để nhắc bạn dán thêm.","cach_truong_thuong_day":"• Bài Cảm xúc: Cô cho xem tranh mặt vui hoặc buồn, soi gương làm mặt cười, mặt mếu.\n• Bài 4 nhóm thực phẩm: Cô giảng trên slide rồi chia 2 đội chạy lên gắn tranh đồ ăn vào 4 ngôi nhà, cuối cùng cô giáo là người đếm và nhận xét đúng hay sai."},{"stt":"6","title":"Dạy kỹ năng an toàn tới tận bước sơ cứu và làm dự án tập thể như học sinh Tiểu học","sale_pitch":"Toàn bộ chuỗi phim tình huống của Mẹ Su, 16 lượt game thẻ màu và bộ mẫu làm báo tường A1 đều đã được Novastars đóng gói sẵn trong phần mềm và học liệu. Trường mua bản quyền là có ngay hệ thống bài giảng chuyên sâu mà không cô giáo đơn lẻ nào tự sản xuất hết được.","tam_ly_tre":"Với tai nạn bỏng hay các dịp lễ 20/11, nếu chỉ dạy trẻ Không được sờ vào đồ nóng hay Mỗi bé tô 1 bông hoa tặng cô thì mới dừng ở mức bề nổi.","cach_novastars":"• Bài B39 khối Nhỡ: Dạy trên phần mềm từ nhận diện 16 đồ vật bằng thẻ Xanh và Đỏ → ném bóng vào 4 rổ an toàn → xem phim Mẹ Su dạy cách nhờ người lớn kiểm tra nước tắm, đồ ăn nóng và biết tự xả nước mát vào tay ngay khi bị bỏng → đứng thuyết trình cách xử lý 4 tình huống của Su và tối về giảng lại cho bố mẹ.\n• Bài B70 khối Lớn: Chia lớp làm 4 nhóm chuyên môn cùng ghép thành 1 tờ Báo tường khổ lớn A1 giống anh chị Tiểu học rồi thay nhau thuyết trình.","cach_truong_thuong_day":"• Bài Phòng tránh bỏng: Cô cho xem tranh phích nước, bếp ga và dặn Nóng là không chạm, phải kêu cứu người lớn.\n• Bài 20/11: Cô trò chuyện về cô giáo rồi phát thiệp hoặc tranh cho từng trẻ ngồi tô màu."}],"structuredType":"pedagogy_6_reasons","durationMinutes":25},{"id":"mod-03-10-bai-mau","code":"HP03","title":"Phân tích và so sánh  10 Bài Học  của chương trình KNS Novastars với chương trình KNS truyền thống","status":"published","category":"Dẫn chứng Bài học Mẫu","subtitle":"Dùng để Sale dẫn chứng cụ thể khi trường nói: 'Những bài như chào hỏi, giao thông, ăn uống, chữ cái... các cô trường chị vẫn đang dạy rồi!'","questions":[{"id":"hp03-exam-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong số 10 bài học mẫu ở Học phần 3, nhóm bài nào được thiết kế tích hợp trực tiếp \"Phần mềm Novastars\" để tổ chức trò chơi tương tác trên màn hình?","options":["Gồm 5 bài học tích hợp phần mềm tương tác trực tiếp là B69 (Bé), B39 (Nhỡ), B24 (Lớn), B56 (Lớn) và B57 (Lớn) xuyên suốt cả ba khối tuổi.","Gồm tất cả 10 bài học mẫu từ B06 đến B70 đều bắt buộc mở phần mềm trò chơi có nhân vật Sao Nova tương tác trong toàn bộ 30 phút tiết học.","Chỉ có 3 bài ở khối Mẫu giáo Lớn (B24, B56, B57) mới có phần mềm Novastars, còn khối Bé và khối Nhỡ hoàn toàn dùng video YouTube để dạy.","Gồm 4 bài duy nhất ở các chủ đề về An toàn và Sắp xếp là B45, B09, B13 và B70 để tổ chức thi ném bóng và chấm thẻ Xanh/Đỏ trực tuyến."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Kiểm tra nhãn công nghệ của 10 bài mẫu HP03: B69, B39, B24, B56, B57 dùng Phần mềm Novastars; B06, B45, B13 dùng Video YouTube; B09, B70 tự tổ chức/nhạc. | Phân biệt bẫy sai: Các bài B06, B45, B09, B13, B70 không dùng phần mềm tương tác mà dùng video YouTube hoặc đạo cụ tự tổ chức tinh gọn."},{"id":"hp03-exam-2","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Nhóm những bài mẫu nào trong 10 bài HP03 có yêu cầu tổ chức hoạt động thuyết trình (quay video/nói trước lớp) cho học sinh?","options":["Cả 10 bài từ B06 đến B70 đều kết thúc bằng hoạt động gọi từng nhóm 5 trẻ lên bục giảng thuyết trình quy tắc trước ống kính điện thoại của cô phụ.","Chỉ duy nhất 2 bài B45 (khối Bé) và B70 (khối Lớn) có phần đứng trước giá vẽ thuyết trình quay video gửi phụ huynh, các bài khác chỉ chơi vận động.","Gồm 6 bài có hoạt động thuyết trình: B45 (Bé), B09 (Nhỡ), B13 (Nhỡ), B39 (Nhỡ), B57 (Lớn) và B70 (Lớn); 4 bài còn lại không đặt nặng thuyết trình.","Gồm 4 bài duy nhất thuộc khối Mẫu giáo Nhỡ và Lớn là B09, B24, B56 và B57 nhằm chuẩn bị kỹ năng nói mạch lạc cho bậc Tiểu học."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Trong 10 bài HP03, thẻ 'Thuyết trình: Có' gắn ở 6 bài: B45, B09, B13, B39, B57, B70; 4 bài 'Không': B06, B69, B24, B56. | Phân biệt bẫy sai: B06, B69, B24 và B56 tập trung 100% vào thực hành đi chào/phân loại/gấp đồ/đo tư thế chứ không ép ghép thuyết trình."},{"id":"hp03-exam-3","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Đặt cạnh nhau 3 bài thuyết trình xuyên suốt 3 lứa tuổi là B45 (3 tuổi), B39 (4 tuổi) và B70 (5 tuổi), lộ trình nâng độ khó thuyết trình của Novastars đi theo hướng nào?","options":["Từ 4–6 bé 3 tuổi nhìn tranh tự tô nói 3 câu mẫu (B45) → bé 4 tuổi tập đủ 5 cử chỉ khuyên Su xử lý 4 tình huống (B39) → nhóm 5 tuổi nói nối tiếp báo tường A1 (B70).","Từ bé 3 tuổi thuyết trình tự do không tranh (B45) → bé 4 tuổi đọc thuộc thơ 4 câu trên màn hình (B39) → bé 5 tuổi viết kịch bản giấy tự thuyết trình đơn lẻ (B70).","Giữ nguyên duy nhất một mẫu câu 3 phần cố định từ lớp 3 tuổi lên đến lớp 5 tuổi để học sinh các khối không phải làm quen lại cấu trúc trình bày mới.","Tăng dần thời lượng đứng nói của mỗi học sinh từ 1 phút (B45) lên 3 phút (B39) và 5 phút cá nhân độc lập (B70) ngay tại giá vẽ trung tâm phòng học."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Trình tự nâng dần năng lực: B45 (đứng nhóm nhìn tranh tự tô, câu mẫu 3 câu) → B39 (5 cử chỉ + tư duy xử lý 4 tình huống) → B70 (phối hợp thuyết trình nhóm nối tiếp). | Phân biệt bẫy sai: Novastars không ép trẻ mầm non tự viết kịch bản hay đứng nói đơn độc 5 phút; mỗi độ tuổi có điểm tựa sư phạm khác nhau."},{"id":"hp03-exam-4","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Nhìn xuyên suốt cặp bài B06 (chào hỏi quanh sân trường) và B09 (kiểm tra chéo bảng dinh dưỡng), Novastars sử dụng \"môi trường xã hội quanh trẻ\" khác lối dạy cũ như thế nào?","options":["Cả B06 và B09 đều tận dụng màn hình tivi chiếu tình huống giả lập 100% để thay thế hoàn toàn nhu cầu tương tác với con người thật xung quanh trẻ.","Cả B06 và B09 đều yêu cầu giáo viên phụ trách lớp mời phụ huynh vào đóng vai khách lạ và vai đầu bếp nhằm tăng tính chân thực cho bối cảnh đóng vai.","Cả hai bài đều chuyển hoạt động kiểm tra từ cá nhân sang thi đấu giữa 2 đội chạy tiếp sức trên bảng từ nhằm tạo không khí ganh đua điểm số trong giờ học.","Thay vì cô giáo đóng hết vai chấm đúng–sai trong phòng kín, B06 đưa trẻ ra gặp người thật ngoài sân còn B09 để chính bạn ngồi cạnh phát hiện lỗi thiếu chất giúp nhau."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): B06 biến người thật trong sân trường thành bối cảnh rèn phản xạ; B09 biến bạn ngồi cạnh thành người đồng kiểm tra chéo (peer feedback). | Phân biệt bẫy sai: Không dùng kịch đóng vai giả định hay thi tiếp sức chạy lên bảng gắn lô tô như giáo án truyền thống."},{"id":"hp03-exam-5","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Các tiết học mẫu nào trong HP03 thể hiện rõ tính chất \"là tiết nối tiếp số 2 hoặc số 3\" trong một cụm kỹ năng liên hoàn chứ không dạy đơn lẻ 1 tiết?","options":["Chỉ có duy nhất hai bài ở khối Mẫu giáo Lớn là B24 và B70 được tách thành cụm nhiều tiết, toàn bộ các bài ở khối Bé và Nhỡ đều là tiết độc lập.","Nhiều bài nằm trong chuỗi liên hoàn như B06 (sau B05), B45 (sau B44), B09 (sau B08), B13 (sau B12), B24 (sau B22–B23) và B70 (sau B68–B69).","Chỉ có cặp bài B56 và B57 tạo thành một cụm 2 tiết liền nhau về chữ cái và tập viết, các chuyên đề kỹ năng còn lại chỉ giảng trong 1 tiết duy nhất.","Mười bài mẫu được thiết kế thành 1 chuỗi 10 tiết liên tiếp dạy gói gọn trong tháng 11 hằng năm nhằm phục vụ kế hoạch thi giáo viên dạy giỏi cấp trường."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Trong 10 bài HP03: B05→B06, B44→B45, B08→B09, B12→B13, B22–B23→B24, B68–B69→B70 đều là mắt xích trong cụm 2–3 tiết. | Phân biệt bẫy sai: 10 bài mẫu rải đều qua cả 3 khối suốt 72 tiết năm học, không phải chuỗi dạy trong tháng 11 hay chỉ ghép ở lớp Lớn."},{"id":"hp03-exam-6","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Trong các bài dùng phần mềm ở HP03, Novastars thiết kế những dạng game vận động tập thể nào để 100% trẻ trong lớp đều được cử động thay vì ngồi xem màn hình?","options":["Gồm trò chơi đứng tại chỗ giơ tay biểu quyết A hoặc B với bộ câu hỏi trắc nghiệm chữ viết chiếu trên slide cho nhóm 5 trẻ ngồi bàn đầu tiên.","Gồm thi đấu bấm nút trên máy tính bảng cá nhân phát tới từng bàn để phần mềm tự động chấm điểm tốc độ trả lời nhanh nhất của mỗi trẻ.","Gồm trò chơi nhảy lò cò theo ô số trên sàn và thi kéo co giữa hai tổ ở hành lang lớp học trong suốt 15 phút cuối của mỗi tiết học tương tác.","Gồm nghiêng người tại chỗ (B69 – 6 lượt, B24 – 8 lượt), giơ thẻ màu Xanh/Đỏ (B39 – 16 lượt) và chạy nhóm thả bóng/chạm thẻ (B69, B39, B24, B57)."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): 4 bài phần mềm (B69, B39, B24, B57) kết hợp thuần thục nghiêng người tại chỗ, giơ thẻ màu đồng loạt và chạy xếp hàng thả bóng/chạm thẻ. | Phân biệt bẫy sai: Trường mầm non không phát máy tính bảng cá nhân hay làm trắc nghiệm chữ cho trẻ; mọi game đều vận động toàn thân theo tập thể."},{"id":"hp03-exam-7","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Chủ trường hỏi: \"Phần mềm tốt thật đấy, nhưng nếu hôm nào trường mất điện hoặc máy chiếu lớp hỏng đột xuất thì cả tiết học hôm đó coi như bỏ à?\"","options":["Đề xuất nhà trường đầu tư thêm bộ máy tính xách tay dự phòng và loa kéo di động để tự tổ chức phát lại toàn bộ 16 lượt game đồ họa trên sân trường.","Thừa nhận nếu mất điện thì bắt buộc phải cho cả lớp nghỉ tiết Kĩ năng sống tuần đó để chuyển sang dạy bù vào cuối tháng sau vì 100% bài không thể dạy chay.","Phân tích kho 10 bài mẫu cho thấy nhiều bài cực hay vẫn dạy trọn vẹn bằng video nhạc hoặc không cần phần mềm (như B06, B09, B13, B70) và trường có thể hoán đổi linh hoạt.","Khuyên giáo viên chỉ cần đọc to nội dung các lượt câu hỏi từ giáo án giấy cho trẻ ngồi tại chỗ tưởng tượng và giơ tay trả lời miệng thay thế hoàn toàn phần mềm."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Trong 10 bài mẫu có B06, B45, B09, B13, B70 hoàn toàn linh hoạt dùng nhạc/video/đạo cụ in sẵn, đảm bảo giáo viên vẫn xử lý chủ động nếu gặp sự cố điện. | Phân biệt bẫy sai: Không phóng đại rằng mất điện vẫn chạy được đồ họa tương tác và cũng không nói 100% bài đều liệt hoàn toàn nếu thiếu máy chiếu."},{"id":"hp03-exam-8","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Trong cặp bài chuẩn bị vào lớp 1 (B56 & B57 khối Lớn), Novastars đã lồng ghép văn hóa tự quản của học sinh Tiểu học ngay trong giờ Kĩ năng sống qua chi tiết nào?","options":["Ngay từ Hoạt động 1 bầu Lớp trưởng – Lớp phó để hô cả lớp đứng nghiêm chào đầu/cuối giờ và giữ trật tự, cuối tiết B56 thưởng 3 sao cho Lớp trưởng, 2 sao Lớp phó.","Cho trẻ đeo khăn quàng đỏ giả định và mang cặp sách nặng 2kg ngồi học liên tục 45 phút không giải lao để làm quen đúng thời lượng tiết học Tiểu học.","Yêu cầu mỗi bé lớp Lớn tự mang sổ liên lạc cá nhân để Lớp trưởng đi kiểm tra chữ ký phụ huynh và chấm điểm kỷ luật cho từng bạn vào đầu giờ.","Phát bảng con và phấn viết để cả lớp luyện chép chính tả 10 câu thơ ngắn trong khi giáo viên đóng vai thầy hiệu trưởng trường Tiểu học đi dự giờ."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Cả B56 và B57 đều bắt đầu bằng nghi thức chào Tiểu học và bầu Lớp trưởng – Lớp phó tự quản (B56 thưởng 3 sao Lớp trưởng, 2 sao Lớp phó). | Phân biệt bẫy sai: Không ép trẻ ngồi 45 phút hay mang cặp 2kg/chép chính tả 10 câu thơ — tâm thế Tiểu học đến từ nghi thức và hứng thú tự quản."},{"id":"hp03-exam-9","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"So sánh cặp bài \"rèn trẻ giữ an toàn thực tế\" B45 (3 tuổi) và B39 (4 tuổi), kỹ thuật giao bài về nhà/kết nối gia đình ở bài B39 nâng lên mức nào?","options":["Cả B45 và B39 đều yêu cầu phụ huynh tự quay clip thực hành trên xe ô tô hoặc trong bếp gia đình gửi về nhóm lớp để cô giáo nghiệm thu đánh giá cuối học kỳ.","Ở B45 trẻ không làm sản phẩm nào, còn sang B39 trẻ mang tờ phiếu trắc nghiệm 10 câu về để phụ huynh đọc cho con khoanh đáp án rồi nộp lại cô chấm sáng hôm sau.","Ở B45 trẻ quay video tại lớp gửi bố mẹ xem, còn sang B39 giao hẳn nhiệm vụ tối về nhà trẻ trực tiếp đứng thuyết trình giảng lại 4 nguyên tắc phòng bỏng cho bố mẹ nghe.","Ở B39 bỏ hoàn toàn phần kết nối về nhà để tránh làm phiền phụ huynh buổi tối, chỉ lưu bảng điểm trò chơi thả bóng trên phần mềm làm báo cáo cuối tháng."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B45 quay video trẻ tại lớp bên giá vẽ gửi phụ huynh; B39 nâng tầm biến trẻ 4 tuổi thành 'thầy giáo nhí' tối về thuyết trình giảng lại cho bố mẹ (tương tự B69). | Phân biệt bẫy sai: Không có phiếu trắc nghiệm 10 câu gửi phụ huynh chấm hay clip bếp gia đình bắt buộc."},{"id":"hp03-exam-10","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Giáo viên trường nhận xét: \"Đọc giáo án mẫu bài B09, B13, B56 thấy ghi rất kỹ từ câu nói mẫu đến vị trí bàn, sợ các cô bị gò bó mất sáng tạo\" — Sale nên phản biện ra sao?","options":["Khuyên Hiệu trưởng cho phép giáo viên tự do lược bỏ 50% số hoạt động trong giáo án mẫu nếu thấy dài, chỉ cần giữ lại tên bài học cho đúng phân phối chương trình.","Giải thích chi tiết đó là khung chuẩn (để cô mới không lúng túng và giữ an toàn khi phát kéo ở B09, thử 5 bé ở B56); cô giàu kinh nghiệm vẫn linh hoạt sáng tạo lời dẫn tự nhiên.","Khẳng định phần mềm quản lý giáo án khóa cứng từng giây, nếu giáo viên nói khác một chữ so với câu thoại mẫu sẽ không đồng bộ được với lượt chuyển cảnh tiếp theo.","Đề xuất trường chỉ dùng giáo án chi tiết của Novastars cho giáo viên thực tập mới ra trường, còn giáo viên lâu năm cứ tiếp tục soạn bài theo giáo án tay trước đây."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Giáo án chuẩn hóa chi tiết (sơ đồ bàn, mẹo phát kéo B09, tốp 5 bé B56, lời thoại mẫu) là bệ đỡ đảm bảo đồng đều và an toàn toàn trường, không trói buộc sáng tạo. | Phân biệt bẫy sai: Không có chuyện phần mềm khóa giọng cô từng giây, và cũng không khuyên tách giáo viên lâu năm dạy giáo trình riêng làm mất đồng bộ."},{"id":"hp03-exam-11","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Điểm chung về nghệ thuật \"cụ thể hóa khái niệm trừu tượng\" được Novastars áp dụng thành công trong các bài B69 (3t), B13 (4t), B56 (5t) và B57 (5t) là gì?","options":["Sử dụng kính hiển vi đồ chơi và mô hình giải phẫu cơ thể người cỡ lớn ở tất cả các bài trên để trẻ 3–5 tuổi quan sát trực tiếp cấu tạo bên trong.","Dùng các đoạn thuyết minh giảng giải dài 10 phút kèm bảng số liệu thống kê thực tế để trẻ mầm non ghi nhớ chính xác định nghĩa khoa học ngay từ lớp 3 tuổi.","Chuyển toàn bộ các khái niệm trừu tượng thành bài vè đồng dao 4 chữ để cả lớp học vẹt thuộc lòng theo nhịp phách tre trước khi chuyển sang tiết tập tô.","Biến khái niệm khó thành vật/cử chỉ chạm thấy được: B69 hóa phân hủy thành thẻ Xanh/Cam, B13 thành Huy hiệu 4 mặt, B56 dùng thước 30cm, B57 dùng 2 bàn tay chữ b–d."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Cả 4 bài đều neo kiến thức trừu tượng vào công cụ cụ thể hóa trực quan (thẻ màu, huy hiệu lật mặt, cây thước 30cm, 2 bàn tay bấm nút Thích). | Phân biệt bẫy sai: Mầm non tiếp thu qua trực quan – hành động cụ thể chứ không qua bài giảng định nghĩa 10 phút hay kính hiển vi."},{"id":"hp03-exam-12","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Trong bài B56 khối Lớn, tại sao Hoạt động 4 & 5 lại tổ chức gọi từng tốp 5 trẻ lên 5 bộ bàn ghế mẫu trước lớp thay vì kiểm tra đồng loạt cả lớp cùng ngồi tại bàn nhóm?","options":["Vì nhà trường không có đủ thước nhựa 30cm và bút chì cho 25 học sinh cùng lúc nên giáo án thiết kế xoay vòng dùng chung 5 bộ đồ dùng trên bục giảng.","Để hai cô quan sát sát sao từng góc nhìn thước 30cm và vị trí 3 ngón cầm bút của từng em trong tốp 5 bạn, sửa chuẩn tận tay điều mà dạy đại trà cả lớp bỏ sót.","Vì theo quy định kiểm định Tiểu học, mỗi phòng học mầm non chỉ được kê tối đa 5 bộ bàn ghế đơn chuẩn lớp 1 để tiết kiệm diện tích vui chơi.","Để 20 trẻ ngồi bên dưới tự do nói chuyện nghỉ ngơi trong khi giáo viên chỉ cần tập trung hướng dẫn cho 5 bạn ngồi bàn đầu tiên đủ thời lượng quay tư liệu."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Gọi từng tốp 5 bé lên 5 bàn mẫu giúp cô kèm cặp chính xác từng ngón tay cầm bút (cách ngòi 2–3cm) và khoảng cách thước 30cm cho từng em. | Phân biệt bẫy sai: Không phải vì thiếu thước hay cho lớp dưới nói chuyện; cả lớp quan sát và lần lượt lên thực hành chuẩn xác 100%."},{"id":"hp03-exam-13","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Chi tiết âm thanh/nhạc nền được cài đặt khéo léo trong từng bài mẫu (B06, B45, B09, B13) khác nhau thế nào để dẫn dắt cảm xúc và nhịp độ lớp học?","options":["B06 & B45 dùng video vui nhộn (Con chim vành khuyên, Wheels on the bus); B09 dùng nhạc sôi động tăng tốc độ vận động; B13 mở nhạc không lời êm dịu khi tô cắt.","Tất cả 10 bài học đều phát duy nhất một bản nhạc không lời êm dịu xuyên suốt 30 phút để giữ cho trẻ mầm non luôn ở trạng thái tĩnh lặng tập trung cao.","Chỉ sử dụng tiếng trống lắc tay và phách tre truyền thống của cô giáo để giữ nhịp, tuyệt đối không dùng nhạc từ YouTube hay video tiếng Anh trong tiết học.","Các bài học đều mở nhạc sôi động với âm lượng lớn suốt phần làm thủ công để kích thích nhóm trẻ nhút nhát nói to hơn khi đứng cắt dán sản phẩm tại bàn."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B06 (Con chim vành khuyên), B45 (Wheels on the bus), B09 (nhạc khởi động tốc độ tăng dần + nhạc 3p tô màu), B13 (If you are happy → nhạc không lời êm dịu). | Phân biệt bẫy sai: Âm nhạc được chọn theo đúng tâm trạng hoạt động: khởi động thì sôi động, lắng tâm tô cắt cảm xúc (B13) thì dùng nhạc không lời êm dịu."},{"id":"hp03-exam-14","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Chủ trường hỏi: \"Khối Lớn 5 tuổi nhà chị năm nay có 32 bé hơi đông, các bài vận động và xếp nhóm ở B24, B57, B70 có bị chật hay vỡ đội hình không?\"","options":["Đề nghị giáo viên bỏ bớt các hoạt động chạy thả bóng ở B57 và thi gấp theo đội ở B24 đối với lớp trên 30 trẻ, chỉ giữ lại phần ngồi xem phim trên màn hình.","Khuyên trường nên tách bắt buộc những lớp trên 25 trẻ thành 2 ca học Kĩ năng sống khác ngày nhau để đảm bảo đúng quy chuẩn 15 trẻ mỗi tiết học.","Giải thích mọi trò chơi chạy/thả bóng đều chia tốp 5–7 bé lên luân phiên xếp hàng trước vạch (như B24, B39, B57), còn B70 chia 4 nhóm bàn nên lớp 30+ bé vẫn gọn gàng.","Tư vấn nhà trường phải thuê thêm phòng hội trường lớn hoặc chuyển toàn bộ các tiết học khối Lớn ra sân ngoài trời bất kể thời tiết nắng mưa."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Các giáo án B24, B39, B57 luôn gọi từng tốp 5–7 trẻ lên hàng, còn B70 chia đều 4 nhóm bàn theo 4 mảnh ghép A1 — tối ưu cho sĩ số lớp tư thục đông. | Phân biệt bẫy sai: Không cắt bỏ vận động cũng không bắt trường chia đôi lớp hay bỏ phòng học."},{"id":"hp03-exam-15","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Trong Hoạt động 4 bài B57 khối Lớn (Đoán tên sách hay), chi tiết cho trẻ nghe gợi ý đoán 5 đầu sách nổi tiếng có mục đích sư phạm gì trước khi dạy chữ b, d?","options":["Giúp trẻ 5 tuổi thấy rõ lợi ích thiết thực của việc biết chữ là tự đọc được bao nhiêu truyện hay (Doraemon, Thần đồng Đất Việt, Rùa và thỏ...), từ đó tự hứng thú học chữ.","Giúp giáo viên kiểm tra khả năng đánh vần trôi chảy tiêu đề của 5 quyển truyện dày ngay tại lớp nhằm xếp loại mức độ sẵn sàng đọc sớm của học sinh.","Thay thế hoàn toàn hoạt động kể chuyện buổi chiều của trường bằng việc tóm tắt hết cốt truyện của cả 5 bộ sách truyện tranh trong một tiết học 30 phút.","Phát hiện xem gia đình phụ huynh nào có mua nhiều truyện tranh ở nhà nhất để giáo viên tham khảo bổ sung thêm đầu sách vào tủ thư viện góc lớp."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): B57 dùng phim Su–Kem + 5 bìa sách quen thuộc (Thần đồng Đất Việt, Cậu bé chăn cừu, Doraemon, Rùa và thỏ, Trầu cau) để truyền động lực thích học chữ. | Phân biệt bẫy sai: Trẻ 5 tuổi nhìn hình bìa đoán theo gợi ý nhân vật, không phải thi đánh vần tiêu đề dài hay kể hết 5 bộ truyện."},{"id":"hp03-exam-16","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Khi so sánh cặp bài \"rèn nếp ăn uống – dọn dẹp\" B09 (Nhỡ) và B24 (Lớn), sự dịch chuyển từ \"kiểm tra bạn\" sang \"tự chủ hệ thống\" thể hiện qua bước nào?","options":["Từ việc cắt dán bằng kéo ở B09 rút gọn xuống chỉ còn chơi trò chơi chọn ảnh trên màn hình ở B24 nhằm giảm bớt khối lượng thao tác bằng tay cho học sinh 5 tuổi.","Từ việc cô giáo bưng thức ăn sẵn vào bàn cho trẻ ở B09 chuyển sang việc trẻ 5 tuổi tự đi chợ và nấu một bữa ăn đơn giản trong góc nội trợ ở tiết B24.","Từ việc tự chọn món ăn tùy thích ở B09 nâng lên thành việc bắt buộc 100% trẻ khối Lớn phải mặc đồng phục giống hệt nhau để giảm thao tác sắp xếp tủ đồ.","Từ tự lập bảng 5 món & kiểm tra chéo cho bạn (B09), lên 5 tuổi trẻ tự quy hoạch cả tủ quần áo theo 3 nguyên tắc và phản xạ đổi vai gấp áo–quần liên tục theo lệnh Kem (B24)."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Sự phát triển xuyên khối: B09 tự lập bảng 4 nhóm & kiểm tra cặp đôi → B24 tư duy quy hoạch tủ đồ (phân loại, ưu tiên, ngăn phụ kiện) & phối hợp đổi vai nhanh. | Phân biệt bẫy sai: B24 vẫn có thực hành gấp quần áo thật theo đội (không bỏ thao tác tay), và không có việc đi chợ nấu ăn hay mặc đồng phục."},{"id":"hp03-exam-17","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng hỏi: \"Ở bài B69 khối Bé hay B39 khối Nhỡ đều có phần mềm nhân vật giải thích, vậy cô giáo có bị biến thành 'người bấm máy' mà mất vai trò sư phạm không?\"","options":["Thừa nhận phần mềm tự động đảm nhiệm khoảng 85% vai trò giảng dạy trên lớp nhằm giúp giáo viên mầm non đỡ phải chuẩn bị nội dung câu hỏi gợi mở trước buổi học.","Chứng minh ngược lại: phần mềm chỉ chiếu tình huống/rác nhảy 12–16 lượt, chính cô giáo là người hô nhịp, đặt 2–6 câu hỏi chốt ý, sửa 5 cử chỉ thuyết trình và quản lý an toàn.","Giải thích rằng chỉ trong 5 phút cuối giờ giáo viên mới cần bước lên bục giảng dặn dò, còn 25 phút đầu cả cô và trò cùng ngồi hàng ghế khán giả theo dõi màn hình.","Khuyên Hiệu trưởng có thể bố trí 1 nhân viên hành chính ngồi điều khiển máy tính cho cả khối, không nhất thiết phải có giáo viên chuyên môn đứng lớp suốt tiết học."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Phần mềm là trợ thủ trực quan (12–16 lượt game, phim nhân vật), còn cô giáo luôn dẫn nhịp hỏi đáp (2 câu ở B69, 6 câu ở B39), uốn nắn cử chỉ và kết nối gia đình. | Phân biệt bẫy sai: Tuyệt đối không biến cô thành người bấm máy thụ động hay cho rằng phần mềm thay được giáo viên mầm non."},{"id":"hp03-exam-18","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Ở bài B57 khối Lớn, tại sao sau khi tập mẹo giơ tay nút Thích cho chữ b và d, Hoạt động 5 lại đưa thêm 5 cặp từ thực tế như \"con bê – con dê\", \"quả bóng – dưa hấu\" ra giấy A5?","options":["Để giáo viên chấm điểm chính tả hằng tuần rồi xếp hạng thứ tự từ cao xuống thấp nhằm báo cáo kết quả học tập môn Tiếng Việt cho phụ huynh.","Để kiểm tra tốc độ viết chữ nối liền hai âm tiết của trẻ 5 tuổi chuẩn bị thi vào lớp chọn của các trường Tiểu học chất lượng cao trong khu vực.","Để thay thế hoàn toàn vở tập tô chữ in sẵn, yêu cầu trẻ tự chép lại trọn vẹn cả 10 từ vựng đó vào vở ô li ngay trong 5 phút cuối cùng của tiết học.","Để chuyển ngay mẹo bàn tay thành kỹ năng nhận diện và viết đúng thực chất: trẻ nhìn từ có ngữ cảnh, tự soi tay viết b hoặc d ra giấy A5 giơ lên cho cô kiểm tra từng em."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Cặp từ quen thuộc (con bê–con dê, bóng–dưa hấu, bánh bao–cái diều) giúp trẻ thử dùng mẹo 2 tay ứng dụng viết ngay b/d vào A5 cho cô kiểm tra tức thì. | Phân biệt bẫy sai: Không yêu cầu chép cả từ vựng hay thi vào lớp chọn; trẻ chỉ cần viết đúng chữ b hoặc d."},{"id":"hp03-exam-19","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Chi tiết \"giao nhiệm vụ về nhà cho trẻ tương tác với bố mẹ\" xuất hiện rõ nét nhất ở những bài mẫu nào trong nhóm 10 bài HP03?","options":["Cả 10 bài học đều đính kèm một phiếu bài tập in 2 mặt giao về nhà bắt buộc phụ huynh ký xác nhận sau khi trẻ làm xong trước ngày học tuần kế tiếp.","Chỉ duy nhất bài B70 (Báo tường 20/11) có bài tập giao về nhà yêu cầu bố mẹ cùng con gấp thêm 5 bông hoa nổi mang lên lớp nộp vào sáng hôm sau.","Xuất hiện rõ ở B69 (kể tên rác dễ/khó phân hủy), B09 (quan sát mâm cơm gia đình đủ 4 nhóm chất chưa) và B39 (thuyết trình lại 4 nguyên tắc phòng bỏng cho bố mẹ).","Không có bài nào trong 10 bài mẫu giao nhiệm vụ về nhà vì chương trình Novastars chủ trương hoàn tất 100% nội dung trong phạm vi 30 phút tại trường."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B69 (kể bố mẹ rác dễ/khó phân hủy), B09 (kiểm tra mâm cơm nhà đủ 4 nhóm), B39 (thuyết trình 4 nguyên tắc phòng bỏng cho bố mẹ) đều có nhịp cầu về nhà. | Phân biệt bẫy sai: Là bài tập trải nghiệm/thuyết trình nhẹ nhàng gắn kết gia đình chứ không phải phiếu bài tập giấy có chữ ký bắt buộc."},{"id":"hp03-exam-20","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Sau khi nghe hết 10 bài mẫu HP03, Chủ trường hỏi câu chốt: \"Nếu chọn ra 2 bài tiêu biểu nhất để dạy Demo cho phụ huynh thấy trọn vẹn cả Công nghệ lẫn Chiều sâu tâm lý, nên chọn bài nào?\"","options":["Đề xuất B39 khối Nhỡ hoặc B56/B57 khối Lớn (khoe phần mềm 16 lượt game, phim nhân vật, mẹo b–d/thước 30cm) kết hợp B13 hoặc B70 (tâm lý tinh tế, sản phẩm A1/huy hiệu).","Đề xuất chọn cùng lúc cả B05 và B06 chỉ dạy riêng nội dung chào hỏi trong phòng học suốt 60 phút để phụ huynh tập trung đánh giá độ lễ phép của trẻ.","Đề xuất chỉ chiếu 15 phút đoạn phim hoạt hình mẫu của nhân vật Sao Nova trong phòng họp thay vì dạy thật trên lớp cùng học sinh để tránh rủi ro trẻ mất trật tự.","Đề xuất bỏ qua các bài có thực hành nhóm hoặc cắt dán như B09, B70 vì chỉ những bài ngồi xem tivi 100% mới thể hiện rõ tính hiện đại của công nghệ Novastars."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Cặp Demo hoàn hảo kết hợp 1 bài phần mềm đặc sắc (B39/B56/B57) + 1 bài chiều sâu tâm lý/sản phẩm nhóm (B13/B70/B45) phô diễn trọn vẹn 2 trụ cột USP. | Phân biệt bẫy sai: Không chiếu video họp phụ huynh thay dạy thật và không chỉ chọn tiết ngồi xem màn hình thuần túy."}],"updatedAt":"2026-11-26T08:46:39.402Z","authorName":"Phạm Mỹ Linh","sourceFile":{"url":"data/files/Phan_tich_10_Bai_Mau_Novastars.xlsx","name":"Phan_tich_10_Bai_Mau_Novastars.xlsx","type":"xlsx","sheetName":"3_Phan_tich_10_Bai_Mau"},"contentHtml":"","contentText":"[Bài mẫu 1 - Mẫu giáo bé: B06 - Bé thực hành lời chào với những người xung quanh]\n- Đề tài trường vẫn dạy (Dạy trẻ kỹ năng chào hỏi lễ phép): • Bước 1 – Mở đầu: Cô cho cả lớp hát bài Lời chào buổi sáng hoặc Con chim vành khuyên rồi trò chuyện dẫn vào bài.\n• Bước 2 – Dạy bài mới: Cô kể chuyện hoặc mở video Mèo con lễ phép, hỏi trẻ bạn nào ngoan, gặp ông bà và cô giáo phải chào thế nào. Sau đó cô làm mẫu khoanh tay chào và gọi một số trẻ lên bục giảng đóng vai chào theo tình huống giả định ngay trong lớp.\n• Bước 3 – Trò chơi: Chơi chọn mặt cười, mặt mếu cho hành vi lễ phép hoặc chưa lễ phép.\n- Nội dung Novastars: • Là tiết thứ 2 nối tiếp ngay sau bài B05: ở tiết B05 trẻ đã học nhận biết lời chào trong lớp, sang tiết B06 dành trọn 100% thời gian để trẻ đi thực hành chào người thật.\n• Dạy trẻ phân biệt rõ 2 câu chào theo đúng người gặp:\n  + Gặp người lớn: Con chào cô ạ!\n  + Gặp bạn bè: Tớ chào các bạn!\n• Rèn cho trẻ làm đúng 3 cử chỉ cùng lúc khi chào: Mắt nhìn thẳng vào người mình chào; Tay giơ vẫy nếu là bạn hoặc Khoanh tay nếu là người lớn; Miệng cười tươi.\n• Mục tiêu rõ ràng: 70% trẻ nói được lời chào kèm đúng cả 3 cử chỉ mắt – tay – miệng.\n- Cách triển khai: • Hoạt động 1: Cả lớp nghe và hát theo video Con chim vành khuyên để tạo không khí vui vẻ.\n• Hoạt động 2 – Ôn và tập động tác tại chỗ: Cô hỏi lại trẻ cách chào bạn và chào người lớn khác nhau thế nào từ câu nói đến mắt, tay, miệng. Cả lớp cùng đứng dậy tại chỗ tập nói to câu chào kết hợp mắt nhìn – miệng cười – tay vẫy hoặc khoanh tay.\n• Hoạt động 3 – Đi thực hành chào người thật quanh trường: Cô cho cả lớp xếp thành 1 hàng dọc gồm Cô giáo chính đi đầu hàng dẫn dắt – Trẻ đi ở giữa – Cô phụ đi cuối hàng bao quát, cùng đi dạo một vòng quanh sân trường. Giáo án hướng dẫn mẹo rất hay: Khi bắt gặp bất kỳ ai trong trường, CÔ GIÁO CHỦ ĐỘNG CHÀO TRƯỚC để làm gương cho trẻ hết rụt rè, rồi nhắc cả lớp đồng thanh chào thật to, rõ ràng.\n• Tổng kết: Cô khen ngợi và thưởng sticker cho trẻ.\n- Điểm ăn tiền thuyết phục Chủ trường: • Khác biệt lớn nhất: Ở giáo án thông thường, cô gom cả kể chuyện lẫn đóng vai vào 1 tiết ngồi trong phòng học. Trẻ 3 tuổi ngồi trong lớp cô hỏi thì trả lời rất giỏi, nhưng vừa bước ra ngoài gặp người lạ là ngượng ngùng trốn sau lưng mẹ vì chưa được tập chào trong hoàn cảnh thật. Novastars nghiên cứu tâm lý này nên tách hẳn thành 2 tiết: B05 học trong lớp, B06 đưa trẻ ra sân trường tập chào người thật.\n• Mẹo sư phạm tinh tế giúp trẻ hết sợ: Giáo án hướng dẫn rõ khi gặp người khác, cô giáo chủ động chào trước rồi nhắc trẻ đồng thanh chào to. Nhờ cô mở lời trước và có cả lớp chào cùng, những bé nhút nhát nhất cũng dám mở miệng chào theo, cộng thêm việc rèn tỉ mỉ cả ánh mắt và nụ cười chứ không chỉ khoanh tay đọc vẹt.\n• Điểm chốt với Chủ trường: Hoạt động này vừa khít với 2 cô giáo sẵn có của mỗi lớp nên trường áp dụng ngay cực kỳ dễ dàng, không tốn thêm nhân sự hay đạo cụ nào; nhưng nếu không có lộ trình 2 tiết nối tiếp và kịch bản chi tiết của Novastars thì các cô thường chỉ cho đóng vai trong lớp là xong.\n\n[Bài mẫu 2 - Mẫu giáo bé: B45 - Bé giới thiệu về cách tham gia giao thông an toàn]\n- Đề tài trường vẫn dạy (Bé với an toàn giao thông): • Bước 1 – Mở đầu: Hát vận động bài Em đi qua ngã tư đường phố.\n• Bước 2 – Dạy bài mới: Cô cho trẻ xem tranh hoặc video về đèn xanh – đèn đỏ, đi bộ trên vỉa hè phải có người lớn dắt, ngồi xe máy đội mũ bảo hiểm. Cô hỏi trẻ tranh nào đúng, tranh nào sai rồi cô tổng kết bài học.\n• Bước 3 – Trò chơi: Trò chơi Tín hiệu giao thông khi cô giơ đèn xanh trẻ chạy, đèn đỏ trẻ dừng và chia 2 đội chạy lên gắn tranh đúng hoặc sai lên bảng.\n- Nội dung Novastars: • Là tiết thứ 2 nối tiếp bài B44: ở tiết B44 dạy trẻ hiểu quy tắc, sang tiết B45 rèn trẻ đứng lên sân khấu giới thiệu lại quy tắc đó cho mọi người.\n• Nội dung sát đúng thực tế của trẻ 3 tuổi khi đi xe buýt, xe ô tô cùng trường và gia đình, gói gọn trong 4 quy tắc trẻ tự làm được: Xếp hàng – Giữ trật tự – Lắng nghe hướng dẫn – Ngồi yên tại chỗ.\n• Mục tiêu đầu ra vượt trội: 80% trẻ 3 tuổi tự tin nói to, rõ ràng để giới thiệu lại 4 quy tắc an toàn trước cả lớp.\n- Cách triển khai: • Hoạt động 1: Trẻ đứng 2 hàng so le nhảy sôi động theo video Wheels on the bus.\n• Hoạt động 2 – Hỏi lý do để trẻ tự nhớ bài: Cô không đọc lại bài cũ mà đặt câu hỏi gợi mở: Để không bị ngã khi xe đang chạy thì mình ngồi thế nào → Ngồi yên trên ghế; Để không xô đẩy nhau khi lên xe → Xếp hàng; Để nghe rõ cô dặn → Giữ trật tự, lắng nghe.\n• Hoạt động 3 – Tô tranh làm điểm tựa trí nhớ: Trẻ về bàn nhóm tô màu tranh quy tắc, mỗi bé 1 tranh. Sau đó cô chọn dán đủ 4 bức tranh quy tắc trẻ vừa tô lên bảng giá vẽ đặt chính giữa phía trên lớp.\n• Hoạt động 4 – Tập thuyết trình theo câu mẫu và Quay video: Cô làm mẫu bài giới thiệu gồm 3 câu ngắn gọn vừa sức trẻ 3 tuổi: Xin chào các bạn, tớ tên là... năm nay tớ 3 tuổi. Để đảm bảo an toàn tớ sẽ thực hiện các quy tắc: xếp hàng, lắng nghe, giữ trật tự, ngồi yên trên ghế. Cảm ơn các bạn đã lắng nghe → Cả lớp đứng tại chỗ tập nói đồng thanh cùng cô → Cô mời từng nhóm 4 đến 6 bé lên đứng hai bên bảng giá vẽ để thuyết trình trước máy quay phim.\n- Điểm ăn tiền thuyết phục Chủ trường: • Khác biệt về kết quả đầu ra: Cách dạy thông thường chỉ dừng ở việc Cô hỏi – Trẻ đáp đúng hay sai và chạy theo đèn hiệu của cô. Còn Novastars nâng trẻ 3 tuổi lên mức cao hơn hẳn: Trẻ tự đứng trước lớp nói trọn vẹn một bài giới thiệu 4 quy tắc an toàn.\n• Vì sao trẻ mới 3 tuổi lại thuyết trình được? Nhờ công thức 4 bước được Novastars tính toán rất kỹ: Bước 1 hỏi lý do vì sao phải ngồi yên, xếp hàng để trẻ hiểu thay vì học vẹt → Bước 2 dán chính 4 bức tranh trẻ vừa tô lên giá vẽ ngay giữa sân khấu để khi lên nói, trẻ nhìn vào tranh là nhớ ngay 4 quy tắc không sợ quên → Bước 3 cung cấp khung câu mẫu 3 phần ngắn gọn và cho cả lớp đứng nói đồng thanh trước cho hết ngại → Bước 4 bố trí cho 4 đến 6 bé lên đứng cùng nhau hai bên giá vẽ giúp trẻ 3 tuổi có bạn đứng cạnh nên rất bạo dạn trước máy quay.\n• Điểm chốt với Chủ trường: Cô giáo của trường có sẵn câu nói mẫu, tranh in và sơ đồ chỗ đứng, chỗ đặt máy quay trong giáo án nên dạy rất nhàn; kết thúc tiết học trường có ngay những đoạn video các bé 3 tuổi đứng thuyết trình cực kỳ đáng yêu để gửi cho phụ huynh.\n\n[Bài mẫu 3 - Mẫu giáo bé: B69 - Bé học cách phân loại rác bảo vệ môi trường]\n- Đề tài trường vẫn dạy (Dạy trẻ bỏ rác đúng nơi quy định): • Bước 1 – Mở đầu: Hát bài Không xả rác hoặc cô đóng kịch Chú Cuội đi chơi dẫm phải vỏ chuối bị ngã.\n• Bước 2 – Dạy bài mới: Xem video bạn nhỏ ăn kẹo vứt vỏ ra sàn lớp; cô hỏi hành vi đó đúng hay sai, cô dặn trẻ ăn quà xong phải bỏ rác vào thùng.\n• Bước 3 – Trò chơi: Giơ thẻ mặt cười, mặt mếu cho hành vi đúng hoặc sai và cho trẻ thi nhặt giấy vụn trên sàn lớp bỏ vào 1 thùng rác chung.\n- Nội dung Novastars: • Không chỉ dạy bỏ rác vào thùng là ngoan, mà dạy trẻ ngay từ 3 tuổi biết phân loại 2 nhóm rác:\n  + Rác dễ phân hủy như vỏ cam, vỏ chuối, bông hoa, lá cây, thức ăn thừa → bỏ vào thùng màu Xanh lá.\n  + Rác khó phân hủy như vỏ bim bim, vỏ hộp sữa, túi bóng, lon nước, hộp nhựa → bỏ vào thùng màu Cam.\n• Trẻ biết nhìn nhãn dán trên thùng rác để bỏ đúng loại rác vào đúng thùng.\n- Cách triển khai: • Hoạt động 1 – Trò chơi nghiêng người theo màn hình: Mở phim dẫn dắt trên phần mềm → trẻ hô to Sẵn sàng → qua 6 lượt rác xuất hiện trên màn hình gồm vỏ chuối, hộp sữa, cành hoa, vỏ bim bim, túi rách, cành lá, cả lớp nghiêng người sang bên thùng Xanh hoặc thùng Cam để chọn thùng vứt rác.\n• Hoạt động 2 – Xem phim hoạt hình Sao Nova: Nhân vật Sao Nova trên phần mềm giải thích bằng hình ảnh sinh động thế nào là rác dễ phân hủy, rác khó phân hủy; cô hỏi lại trẻ 2 câu hỏi kiểm tra.\n• Hoạt động 3 – Trò chơi chạy lên chạm thẻ màu: Chia từng nhóm 6 đến 8 trẻ xếp hàng ngang trước vạch; qua 6 lượt rác mới trên màn hình phần mềm, khi cô hô Bắt đầu, trẻ đi nhanh lên bàn chạm tay vào thẻ màu Xanh lá hoặc thẻ màu Cam tương ứng với thùng rác cần bỏ.\n• Tổng kết: Dặn trẻ tối về kể cho bố mẹ nghe tên các loại rác dễ phân hủy và khó phân hủy.\n- Điểm ăn tiền thuyết phục Chủ trường: • Nâng tầm nội dung bài học: Giáo án các trường thường chỉ dạy trẻ 3 tuổi không xả rác bừa bãi. Novastars dạy trẻ 3 tuổi tư duy văn minh hiện đại hơn hẳn: biết phân loại rác hữu cơ dễ phân hủy vào thùng Xanh và rác nhựa, vỏ hộp khó phân hủy vào thùng Cam.\n• Phương pháp học bằng vận động kết hợp phần mềm trò chơi 12 lượt: Thay vì ngồi nghe cô giảng khái niệm phân hủy khô khan, trẻ được nhân vật hoạt hình Sao Nova giải thích trực quan và được vận động 2 vòng liên tiếp gồm Vòng 1 nghiêng người tại chỗ 6 lượt và Vòng 2 chạy lên bàn chạm thẻ màu 6 lượt theo hình ảnh rác nhảy ra trên màn hình.\n• Điểm chốt với Chủ trường: Giáo viên trường không thể tự làm ra phim hoạt hình Sao Nova hay tự lập trình 12 lượt trò chơi phân loại rác trên tivi; nhưng khi trường mua phần mềm Novastars, cô chỉ cần bật máy chiếu và đặt 2 tấm thẻ màu lên bàn là cả lớp có một tiết học công nghệ cực kỳ sôi nổi.\n\n[Bài mẫu 4 - Mẫu giáo nhỡ: B09 - Bé ôn tập cách ăn uống đủ chất dinh dưỡng]\n- Đề tài trường vẫn dạy (Khám phá 4 nhóm thực phẩm / Thực phẩm bé cần): • Bước 1 – Mở đầu: Hát bài Mời bạn ăn, hỏi trẻ sáng nay con ăn món gì.\n• Bước 2 – Dạy bài mới: Cô chiếu slide giới thiệu lần lượt 4 nhóm chất gồm Bột đường, Đạm, Béo, Vitamin và muối khoáng, giảng cho trẻ nghe từng nhóm có tác dụng gì.\n• Bước 3 – Trò chơi: Chia lớp làm 2 đến 4 đội xếp hàng bật qua vòng lên chọn tranh lô tô thực phẩm gắn vào 4 ngôi nhà trên bảng, cuối giờ cô giáo là người kiểm tra và đếm xem đội nào gắn đúng nhiều hơn.\n- Nội dung Novastars: • Là tiết thứ 2 nối tiếp bài B08: ở tiết B08 đã làm quen 4 nhóm chất, sang tiết B09 trẻ tự tay lập bảng món ăn của mình và kiểm tra chéo cho bạn.\n• Kiến thức: 80% trẻ kể tên được 4 nhóm thức ăn gần gũi hàng ngày: thịt, rau, hoa quả, ngũ cốc.\n• Kĩ năng: 100% trẻ tự phân loại được các món ăn mình thích vào đúng 4 nhóm và biết kiểm tra bảng của bạn ngồi cạnh xem bạn thiếu nhóm chất nào.\n- Cách triển khai: • Hoạt động 1 – Nhảy khởi động theo hiệu lệnh tay cô: Cô cầm 1 đồ vật to trên tay di chuyển trái, phải, lên, xuống, xoay tròn trên nền nhạc sôi động; trẻ nhìn đồ vật để nghiêng người, nhảy lên, ngồi xuống theo tốc độ tăng dần.\n• Hoạt động 2: Cô hỏi trẻ nhắc lại nhanh 4 nhóm thức ăn cần thiết đã học ở tiết trước.\n• Hoạt động 3 – Tự làm Bảng phân loại thức ăn cá nhân: Xếp trẻ ngồi theo sơ đồ 3 bàn, mỗi bàn 6 trẻ. Mỗi trẻ nhận 1 Bảng phân loại thức ăn, tự chọn tô màu 5 món ăn mình thích rồi cắt dán vào đúng 4 ô nhóm thức ăn. Giáo án hướng dẫn mẹo giữ an toàn rất chi tiết: Cô cho trẻ tô màu 3 phút trong 1 bản nhạc trước, tô xong cô mới phát kéo để trẻ cắt dán.\n• Hoạt động 4 – Hai bạn ngồi cạnh tự kiểm tra bài cho nhau: Từng cặp 2 trẻ ngồi cạnh nhìn bảng của nhau xem bảng của bạn có bị trống nhóm thức ăn nào không, ví dụ bạn chỉ chọn toàn thịt mà thiếu rau. Nếu thiếu thì nhắc bạn lấy hình món ăn nhóm đó dán bổ sung cho đủ 4 nhóm chất.\n• Hoạt động 5: Treo bảng sản phẩm của trẻ lên triển lãm và dặn trẻ về nhà quan sát mâm cơm gia đình xem đã đủ 4 nhóm thức ăn chưa.\n- Điểm ăn tiền thuyết phục Chủ trường: • Khác biệt thông minh nhất nằm ở bước Hai trẻ tự kiểm tra bài cho nhau: Trong cách dạy truyền thống chạy tiếp sức gắn lô tô lên bảng, chỉ vài bạn nhanh nhẹn chạy lên gắn và cô giáo là người chấm đúng hay sai. Còn ở bài B09 của Novastars, 100% trẻ đều tự làm bảng món ăn riêng; vì trẻ chỉ chọn 5 món mình thích nên rất dễ lộ ra việc trẻ kén ăn như chỉ chọn thịt và quả mà bỏ qua rau. Khi hai bạn ngồi cạnh tự kiểm tra bảng cho nhau và nhắc bạn bảng của cậu thiếu nhóm rau kìa, trẻ nhớ sâu gấp đôi và tự hiểu vì sao không được ăn thiên lệch.\n• Mẹo quản lý lớp học cực kỳ thực tế cho cô giáo: Giáo án tính toán sẵn đến từng chi tiết nhỏ như cho trẻ tô màu 3 phút xong mới phát kéo cắt và vẽ sẵn sơ đồ 3 bàn – chỗ cô chính – chỗ cô phụ – góc chụp ảnh, giúp cô giáo quản lý lớp 4 tuổi dùng kéo rất an toàn, không bị lộn xộn.\n• Điểm chốt với Chủ trường: Cùng là bài dinh dưỡng nhưng cách tổ chức của Novastars biến trẻ thành người chủ động kiểm tra dinh dưỡng cho mình và cho bạn, lại có sẵn mẫu Bảng phân loại in đẹp để cuối buổi trẻ mang về khoe bố mẹ.\n\n[Bài mẫu 5 - Mẫu giáo nhỡ: B13 - Cảm xúc của bé]\n- Đề tài trường vẫn dạy (Nhận biết các cảm xúc Vui, Buồn, Tức giận, Sợ hãi): • Bước 1 – Mở đầu: Hát bài Khuôn mặt cười, trò chuyện về nét mặt vui tươi khi đến lớp.\n• Bước 2 – Dạy bài mới: Xem tranh hoặc video các khuôn mặt Vui, Buồn, Giận, Sợ; cô hỏi khi nào con vui, khi nào con buồn; cho trẻ cầm gương soi và bắt chước làm mặt cười, mặt mếu theo cô.\n• Bước 3 – Trò chơi: Cô đọc tình huống cho trẻ giơ thẻ mặt cảm xúc tương ứng hoặc chia nhóm ghép mắt, miệng vào khuôn mặt giấy.\n- Nội dung Novastars: • Nằm trong chuỗi bài về Cảm xúc của khối Nhỡ, nối tiếp bài B12 nhận biết cảm xúc sợ hãi.\n• Kiến thức: 80% trẻ gọi đúng tên 4 cảm xúc: vui, buồn, sợ hãi, tức giận.\n• Kĩ năng: 100% trẻ được rèn khéo léo đôi tay tô, cắt, dán kết hợp tự chọn màu sắc cảm xúc theo cảm nhận riêng của mình để làm chiếc Huy hiệu cảm xúc dùng giao tiếp trong lớp.\n- Cách triển khai: • Hoạt động 1: Cả lớp đứng nhảy khởi động theo video bài hát If you are happy.\n• Hoạt động 2 – Trò chuyện Màu sắc cảm xúc: Trẻ gọi tên 4 cảm xúc trên tranh đen trắng. Cô đặt câu hỏi rất mở: Theo các con, cảm xúc vui vẻ sẽ có màu gì, rồi hỏi lần lượt cả 4 cảm xúc vui, buồn, sợ hãi, tức giận. Cô ghi nhận tất cả ý kiến của trẻ và khẳng định: Mỗi bạn có một cảm nhận riêng nên mỗi cảm xúc có thể mang nhiều màu sắc khác nhau.\n• Hoạt động 3 – Làm Huy hiệu cảm xúc của riêng bé: Mở nhạc không lời êm dịu; mỗi trẻ nhận bộ tranh 4 gương mặt cảm xúc đen trắng, tự tô màu theo đúng màu sắc mình vừa liên tưởng, dùng kéo cắt rời và dán băng dính tạo thành chiếc Huy hiệu cảm xúc 4 mặt, cô ghi tên lên sản phẩm cho từng bé.\n• Tổng kết – Đưa vào sử dụng thật hằng ngày: Cô dặn trẻ mỗi khi trong lòng có cảm xúc mạnh như buồn, sợ hãi hay tức giận mà chưa nói ra lời được, con hãy nói với cô hoặc lật đúng mặt cảm xúc đó trên chiếc huy hiệu để cô và các bạn hiểu, kịp thời giúp đỡ con.\n- Điểm ăn tiền thuyết phục Chủ trường: • Khác biệt sâu sắc về cách thấu hiểu tâm lý trẻ: Giáo án thông thường chỉ dạy trẻ nhìn nét mặt bên ngoài qua việc soi gương làm mặt cười, mặt mếu và hay dặn trẻ phải vui vẻ, không được khóc hay cáu giận. Còn Novastars tôn trọng cảm nhận riêng của từng đứa trẻ, không ép buộc màu đỏ phải là giận hay màu xanh là buồn – trẻ thích tô cảm xúc của mình màu gì đều được công nhận.\n• Tạo ra công cụ giúp trẻ giải tỏa tâm lý suốt cả năm: Trẻ 4 tuổi khi đang tủi thân, sợ hãi hay tức giận thường khóc lóc hoặc im lặng vì chưa đủ vốn từ để giải thích. Chiếc Huy hiệu cảm xúc có thể lật mặt giúp trẻ chỉ cần lật mặt buồn hoặc sợ lên là cô giáo biết ngay để đến ôm và hỏi han.\n• Điểm chốt với Chủ trường: Tiết học này cô giáo tổ chức rất nhẹ nhàng trên nền nhạc không lời, đồ dùng chỉ cần mẫu tranh in sẵn của Novastars, bút màu, kéo, băng dính; nhưng câu chuyện chiếc huy hiệu để con lật mặt báo cảm xúc với cô khi kể cho phụ huynh nghe thì phụ huynh nào cũng cảm động vì sự tinh tế của nhà trường.\n\n[Bài mẫu 6 - Mẫu giáo nhỡ: B39 - Kĩ năng phòng, tránh nguy cơ bỏng, nóng]\n- Đề tài trường vẫn dạy (Kỹ năng phòng tránh tai nạn bỏng cho trẻ): • Bước 1 – Mở đầu: Xem đoạn video ngắn về một bạn nhỏ nghịch bếp bị bỏng.\n• Bước 2 – Dạy bài mới: Xem tranh các đồ vật nóng trong nhà như phích nước, nồi canh, bàn là, bếp ga, bô xe máy; cô giải thích bị bỏng sẽ phồng rộp rất đau và dạy trẻ câu khẩu hiệu Nóng là không chạm – Không vào bếp khi người lớn đang nấu – Kêu cứu khi gặp nguy hiểm.\n• Bước 3 – Trò chơi: Chia 2 đội chạy lên bảng gạch chéo vào tranh đồ vật gây bỏng.\n- Nội dung Novastars: • Nằm trong chuỗi bài An toàn thực tế của khối Nhỡ cùng với phòng điện giật, đuối nước, vật sắc nhọn, Thanh tra an toàn.\n• Kiến thức: Trẻ nhớ được 4 nguyên tắc an toàn phòng tránh nguy cơ bỏng, nóng.\n• Kĩ năng: Không chỉ biết tránh xa vật nóng mà trẻ còn biết cách xử lý chủ động trong sinh hoạt hàng ngày khi ăn súp nóng, tắm bồn, bật máy sưởi và biết cách sơ cứu đúng ngay khi lỡ bị bỏng.\n- Cách triển khai: • Hoạt động 1 – Phản xạ giơ thẻ Xanh và Đỏ với 16 đồ vật trên phần mềm: Trẻ cầm thẻ Xanh cho đồ vật an toàn và thẻ Đỏ cho đồ vật gây bỏng; màn hình phần mềm chiếu lần lượt 16 đồ vật trong nhà gồm tách trà, lọ hoa, vòi nước, bồn tắm, máy sưởi, bàn là, lò vi sóng, chảo rán, ấm đun nước, bát chè, bếp hồng ngoại, thú bông..., trẻ phán đoán và giơ thẻ thật nhanh.\n• Hoạt động 2 – Trò chơi vận động thả bóng vào 4 rổ: Từng nhóm 5 đến 7 trẻ xếp hàng dọc nhìn 4 ô hình trên màn hình, qua 5 lượt chơi chạy lên thả bóng vào đúng chiếc rổ tương ứng với đồ vật an toàn.\n• Hoạt động 3 – Xem phim Mẹ Su dạy nguyên tắc an toàn và sơ cứu bỏng: Trẻ xem phim nhân vật Mẹ Su hướng dẫn và trả lời 6 câu hỏi để rút ra nguyên tắc thực tế: Muốn ăn hoặc uống đồ nóng, tắm bồn hay bật máy sưởi thì phải nhờ người lớn kiểm tra nhiệt độ, làm nguội hoặc bật giúp và ngồi cách xa; nếu lỡ bị bỏng tay thì phải làm mát vết bỏng ngay bằng nước lạnh rồi báo cho người lớn.\n• Hoạt động 4 – Tập phong thái và đứng thuyết trình xử lý 4 tình huống của Su: Cả lớp đứng tập 5 cử chỉ thuyết trình gồm Mắt nhìn thẳng – Miệng cười – Giọng to rõ – Tay vẫy chào, giơ số tuổi, chỉ vào tranh – Dáng đứng thẳng và câu mẫu → 5 đến 7 trẻ đại diện lên nhìn màn hình thuyết trình cách khuyên bạn Su trong 4 tình huống: ấm siêu tốc đang sôi, bàn ăn có bát bốc khói, muốn bật máy sưởi, tay Su vừa bị bỏng nước nóng.\n• Tổng kết: Giao nhiệm vụ tối về nhà trẻ đứng thuyết trình giới thiệu lại 4 nguyên tắc phòng bỏng cho bố mẹ nghe.\n- Điểm ăn tiền thuyết phục Chủ trường: • Khác biệt thực tế về nội dung an toàn: Giáo án thông thường chỉ dặn trẻ Nóng là không chạm. Nhưng hàng ngày trẻ vẫn phải ăn cháo, súp nóng, tắm nước nóng, dùng máy sưởi mùa đông. Novastars dạy trẻ cách hành xử khôn ngoan trong đời sống: biết nhờ người lớn làm nguội thức ăn, kiểm tra nước tắm trước khi bước vào, ngồi xa quạt sưởi và dạy trẻ bước sơ cứu y tế cực kỳ quan trọng là xả hoặc ngâm ngay tay bị bỏng vào nước mát rồi báo người lớn thay vì chỉ đứng khóc.\n• Sự vượt trội của phần mềm tương tác: Trong 30 phút, phần mềm Novastars cuốn trẻ đi qua 4 chặng liên tiếp từ 16 lượt giơ thẻ màu → 5 lượt chạy ném bóng → xem phim Mẹ Su → xem 4 phim tình huống của Su để đứng lên thuyết trình khuyên bạn. Không một cô giáo nào tự làm slide lẻ tẻ mà có được chuỗi phim hoạt hình nhân vật và trò chơi đồng bộ như vậy.\n• Điểm chốt với Chủ trường: Tối hôm đó trẻ về nhà đứng khoanh tay thuyết trình cho bố mẹ nghe 4 nguyên tắc phòng và sơ cứu bỏng – phụ huynh sẽ thấy ngay giá trị đồng tiền học phí bỏ ra tại trường.\n\n[Bài mẫu 7 - Mẫu giáo lớn: B24 - Bé tự sắp xếp tủ quần áo]\n- Đề tài trường vẫn dạy (Kỹ năng tự phục vụ: Dạy trẻ gấp quần áo): • Bước 1 – Mở đầu: Hát bài Múa cho mẹ xem, trò chuyện về việc giúp bố mẹ làm việc nhà.\n• Bước 2 – Dạy bài mới: Cô trải cái áo, cái quần lên bàn, chỉ cho trẻ đâu là cổ áo, tay áo, thân áo rồi cô làm mẫu từng bước gấp đôi tay áo, gấp thân áo, vuốt phẳng.\n• Bước 3 – Thực hành: Mỗi trẻ lấy 1 đến 2 bộ quần áo trong rổ tự tập gấp tại chỗ, cô đi sửa cho từng bạn rồi khen bạn nào gấp vuông vắn.\n- Nội dung Novastars: • Là tiết thứ 3 nâng cao trong chuỗi 3 tiết liên tiếp của khối Lớn: Tiết B22 Phân loại quần áo → Tiết B23 Học cách gấp quần áo → Tiết B24 Học tư duy sắp xếp cả tủ quần áo.\n• Kiến thức: Trẻ nhớ được 3 nguyên tắc thông minh khi sắp xếp tủ quần áo:\n  + Nguyên tắc 1: Phân loại quần, áo rõ ràng.\n  + Nguyên tắc 2: Xếp theo thứ tự ưu tiên – đồ nào hay mặc thường xuyên thì để ở vị trí dễ lấy nhất.\n  + Nguyên tắc 3: Cất riêng những đồ nhỏ như tất, găng tay, mũ, khăn, đồ lót vào 1 ngăn riêng để không bị thất lạc.\n• Kĩ năng: Biết phân loại đồ theo mùa, theo ngăn tủ và phối hợp nhóm gấp quần áo nhanh, gọn.\n- Cách triển khai: • Hoạt động 1 – Trò chơi Giúp Kem tìm đồ trên phần mềm: Nhóm 5 đến 7 trẻ nhìn màn hình xem bạn Kem đang cần tìm món đồ nào qua 5 lượt gồm áo phông bóng rổ, quần đùi, mũ lưỡi trai, tất xanh, găng tay để chạy về xếp hàng trước thẻ màu tương ứng.\n• Hoạt động 2 – Khám phá 3 nguyên tắc xếp tủ thông minh: Xem phim trên phần mềm và trả lời câu hỏi gợi mở Quần áo hay mặc hàng ngày nên để ở chỗ nào trong tủ → Chỗ dễ nhìn, dễ lấy nhất, rồi cùng chốt lại 3 nguyên tắc xếp tủ.\n• Hoạt động 3 – Trò chơi nghiêng người chọn ngăn tủ: Màn hình phần mềm hiện ra 8 lượt quần áo và phụ kiện gồm áo phông, quần dài, áo dài tay, quần cộc, găng tay, khăn len, tất, mũ lưỡi trai cùng hình 2 ngăn tủ; cả lớp nghiêng người sang trái hoặc sang phải để cất món đồ đó vào đúng Ngăn đồ mùa hè, Ngăn đồ mùa đông hoặc Ngăn đựng phụ kiện nhỏ.\n• Hoạt động 4 – Thử thách chia đội gấp quần áo theo lệnh của Kem: Chia 2 nhóm đứng ở 2 bàn có rổ quần áo thật; qua 5 lượt hiệu lệnh của nhân vật Kem trên màn hình, Nhóm 1 và Nhóm 2 đổi vai cho nhau, lượt thì Nhóm 1 gấp áo – Nhóm 2 gấp quần, lượt sau đảo lại rồi xếp gọn vào rổ.\n- Điểm ăn tiền thuyết phục Chủ trường: • Khác biệt lớn về đẳng cấp nội dung: Giáo án trường mầm non thông thường chỉ dừng ở việc dạy trẻ thao tác tay gấp cái áo, gấp cái quần. Còn Novastars đã dạy xong cách gấp ở tiết B23 rồi, nên sang tiết B24 dạy trẻ 5 tuổi tư duy sắp xếp khoa học giống như cách người lớn quy hoạch tủ đồ: phân loại theo mùa – đồ hay dùng để ngoài dễ lấy – đồ nhỏ như tất, mũ, khăn phải gom vào ngăn phụ kiện riêng.\n• Cách tổ chức kết hợp cả game màn hình lẫn quần áo thật: Trẻ vừa được chơi 8 lượt nghiêng người cất đồ vào ngăn tủ ảo trên phần mềm, vừa được thi gấp quần áo thật trên bàn theo hiệu lệnh đổi vai liên tục của nhân vật Kem.\n• Điểm chốt với Chủ trường: Nhờ chuỗi 3 tiết liên hoàn B22 – B23 – B24 và phần mềm dẫn dắt, trẻ 5 tuổi về nhà không chỉ biết gấp chiếc áo mà còn biết tự sắp xếp ngăn tủ của riêng mình gọn gàng – bố mẹ nhìn thấy sự trưởng thành rõ rệt của con trước khi vào lớp 1.\n\n[Bài mẫu 8 - Mẫu giáo lớn: B56 - Bé rèn luyện tư thế ngồi học và kĩ năng cầm bút đúng cách]\n- Đề tài trường vẫn dạy (Hướng dẫn trẻ tư thế ngồi học và cách cầm bút): • Các trường thường không có tiết Kĩ năng sống riêng cho đề tài này mà chỉ nhắc lồng ghép 3 đến 5 phút đầu giờ Tập tô:\n• Cô treo tranh mẫu Tư thế ngồi học đúng, nhắc trẻ ngồi thẳng lưng, ngực không tì vào bàn, mắt cách vở 25 đến 30cm, cầm bút bằng 3 ngón tay. Sau đó cả lớp đọc bài thơ ngắn rồi mở vở tập tô ngồi tô chữ, cô đi quanh lớp chỉnh lưng và tay cho trẻ.\n- Nội dung Novastars: • Là tiết học chuyên biệt nằm trong chuỗi 25 tiết Hành trang vào Tiểu học của học kì II lớp Lớn, từ bài B47 đến B71.\n• Kiến thức: Trẻ hiểu rõ vì sao phải ngồi đúng, cầm bút đúng: nếu cúi sát mắt sẽ nhìn mờ và hại mắt, nếu gập lưng sẽ bị đau lưng như bạn Su và bạn Kem trong phim.\n• Kĩ năng được chia thành từng bước rõ ràng, dễ làm theo:\n  + 4 bước ngồi học chuẩn: Bước 1 Ngồi vào ghế, chỉnh ghế ngay ngắn → Bước 2 Hai chân để thẳng, bàn chân chạm đất → Bước 3 Ngồi thẳng lưng → Bước 4 Dùng cây thước 30cm đo đúng khoảng cách từ mắt đến vở.\n  + 3 bước cầm bút chuẩn: Bước 1 Giơ 3 ngón tay cầm bút là cái, trỏ, giữa, 2 ngón còn lại nắm vào lòng bàn tay → Bước 2 Ngón cái và ngón trỏ giữ bút, ngón giữa đỡ bút ở vị trí cách ngòi bút 2 đến 3cm → Bước 3 Hướng đuôi bút về phía vai.\n- Cách triển khai: • Hoạt động 1 – Tập nghi thức lớp học Tiểu học: Xem video mở đầu, cô bầu chọn Lớp trưởng – Lớp phó và cho lớp trưởng hô cả lớp đứng nghiêm chào cô giống hệt tiết học ở trường Tiểu học.\n• Hoạt động 2 – Trò chơi rèn sự tập trung Thỏ con tinh nghịch: Trẻ học 4 động tác tay gồm Con thỏ – Ăn cỏ – Uống nước – Vào hang rồi chơi 8 lượt với luật đặc biệt từ nhân vật Su: Chỉ làm theo lời Su nói, KHÔNG làm theo động tác cô làm; 2 lượt đầu cô hô và làm giống nhau, 6 lượt sau cô cố tình hô một đằng nhưng tay làm một nẻo để rèn trẻ tập trung lắng nghe, không bắt chước máy móc.\n• Hoạt động 3 – Xem phim hoạt hình Su và Kem ngồi sai tư thế: Trẻ xem phim thấy bạn Su dí sát mắt vào sách nên mắt nhìn mờ, bạn Kem cúi thấp nên bị đau lưng → trẻ rút ra bài học và hô to câu thần chú tư thế.\n• Hoạt động 4 và 5 – Đo khoảng cách bằng thước 30cm và Luyện cầm bút theo tốp 5 trẻ: Xem video hướng dẫn từng bước → Cô mời lần lượt từng tốp 5 trẻ lên ngồi vào 5 bộ bàn ghế mẫu trước lớp để thực hành đủ 4 bước ngồi, dùng thước 30cm đặt đo thử từ mắt xuống vở và 3 bước cầm bút cho cô kiểm tra kỹ từng bé.\n• Tổng kết: Thưởng 3 sao cho Lớp trưởng, 2 sao cho Lớp phó vì đã giúp cô giữ trật tự lớp và lớp trưởng hô chào cuối giờ.\n- Điểm ăn tiền thuyết phục Chủ trường: • Bí quyết khiến tiết học này cực kỳ hiệu quả: Vì sao ở trường mầm non cô nhắc ngồi thẳng lưng lên nhưng chỉ 1 đến 2 phút sau trẻ lại cúi gập xuống? Vì trẻ 5 tuổi chưa bật được chế độ tập trung chú ý và làm chủ cơ thể. Novastars đưa trò chơi Thỏ con tinh nghịch vào ngay đầu giờ để đánh thức não bộ trẻ tập trung cao độ qua 8 lượt nghe lệnh mà không bị động tác của cô đánh lừa, rồi mới dạy kỹ thuật ngồi và cầm bút.\n• Cụ thể hóa những thứ trừu tượng: Thay vì nói miệng mắt cách vở 30cm khiến trẻ 5 tuổi không thể tưởng tượng 30cm dài bằng nào, giáo án Novastars cho trẻ dùng chính cây thước 30cm đặt đo thử để cảm nhận khoảng cách chuẩn; đồng thời tập luôn văn hóa Lớp trưởng – Lớp phó tự quản giống lớp 1.\n• Điểm chốt với Chủ trường: Cô giáo trường dạy tiết này rất nhàn vì chỉ cần kê 5 bàn ghế mẫu lên đầu lớp, thước 30cm, bút chì và bật phần mềm, nhưng phụ huynh khi biết con được chuẩn bị vào lớp 1 bài bản từ trò chơi rèn tập trung đến cách đo khoảng cách mắt 30cm thì sẽ cực kỳ yên tâm.\n\n[Bài mẫu 9 - Mẫu giáo lớn: B57 - Bé vui học cùng các chữ cái]\n- Đề tài trường vẫn dạy (Làm quen chữ cái b, d, đ): • Bước 1 – Mở đầu: Hát bài hát chủ đề, xem tranh con bò, con dê, rút các chữ cái đã học.\n• Bước 2 – Dạy bài mới: Cô giơ thẻ chữ b và chữ d cho cả lớp, tổ, cá nhân đọc to; sau đó cô phân tích cấu tạo nét chữ: Chữ b có 1 nét sổ thẳng bên trái và 1 nét cong tròn bên phải; chữ d có 1 nét cong tròn bên trái và 1 nét sổ thẳng bên phải, rồi hỏi trẻ 2 chữ giống và khác nhau ở đâu.\n• Bước 3 – Trò chơi: Tìm chữ theo tiếng sắc xô, bật qua vòng lên bảng gắn chữ b, d hoặc tô chữ chấm mờ.\n- Nội dung Novastars: • Nằm trong chuỗi bài Hành trang vào Tiểu học, bổ trợ trực tiếp cho việc học chữ của trẻ 5 đến 6 tuổi.\n• Kiến thức: Giúp trẻ hiểu và yêu thích việc học chữ vì thấy rõ lợi ích thiết thực: biết chữ để tự đọc tên mình, tự đọc truyện tranh yêu thích, viết thư cho ông bà và bạn bè ở xa.\n• Kĩ năng: Nhận diện nhanh các chữ cái a, b, o, t, x, h, m; đặc biệt nắm được mẹo dùng hai bàn tay để phân biệt chính xác cặp chữ cái trẻ hay viết ngược nhất là chữ b và chữ d.\n- Cách triển khai: • Hoạt động 1: Nghi thức chào đầu giờ Tiểu học và bầu chọn Lớp trưởng, Lớp phó.\n• Hoạt động 2 – Trò chơi vận động Nghe chữ, thả bóng: Từng nhóm 5 trẻ đứng trước vạch nghe nhân vật Su đọc chữ cái qua 5 lượt gồm a–o, t–a, m–t, b–h, o–x rồi chạy lên thả quả bóng vào đúng chiếc rổ có gắn chữ cái đó.\n• Hoạt động 3 – Xem phim Su và Kem để khơi gợi niềm yêu thích học chữ: Xem phim hai bạn Su, Kem nói về điều thú vị khi biết chữ → Cô hỏi từng trẻ: Khi biết chữ, con thích làm điều gì nhất, vì sao để trẻ hào hứng chia sẻ ước mơ của mình.\n• Hoạt động 4 – Trò chơi Đoán tên sách hay trên màn hình: Trẻ nghe gợi ý của Su hoặc Kem và nhìn hình 3 cuốn sách trên màn hình để giơ tay đoán đúng 5 đầu sách nổi tiếng gồm Thần đồng Đất Việt, Cậu bé chăn cừu, Doraemon, Rùa và thỏ, Trầu cau.\n• Hoạt động 5 – Mẹo dùng 2 bàn tay phân biệt chữ b và d, kết hợp Tập viết nhanh: Xem video hướng dẫn mẹo cực dễ nhớ: Giơ bàn tay bấm nút Thích với ngón cái dựng đứng, 4 ngón nắm tròn – Giơ nút Thích bằng TAY TRÁI sẽ tạo thành đúng hình chữ b; Giơ nút Thích bằng TAY PHẢI sẽ tạo thành đúng hình chữ d → Cô chỉ chữ b, d trên bảng cho trẻ giơ tay trái hoặc tay phải tương ứng và đọc to → Phát giấy A5 và bút màu, qua 5 lượt cô viết cặp từ lên bảng như con bê – con dê, quả bóng – dưa hấu, bánh bao – cái diều..., trẻ nhìn từ rồi tự viết chữ b hoặc d ra giấy giơ lên cho cô kiểm tra.\n- Điểm ăn tiền thuyết phục Chủ trường: • Giải quyết nỗi đau lớn nhất khi dạy chữ cho trẻ 5 đến 6 tuổi: Hầu hết trẻ 5 tuổi đều bị nhầm giữa chữ b và chữ d nếu cô chỉ giảng lý thuyết nét sổ thẳng bên trái, nét cong bên phải vì trẻ rất dễ quên bên nào là trái, bên nào là phải của con chữ. Novastars dùng mẹo Giơ nút Thích bằng hai bàn tay: tay trái là chữ b, tay phải là chữ d – đôi bàn tay luôn gắn trên người trẻ nên lúc nào quên trẻ chỉ cần giơ 2 tay lên nhìn là biết ngay chữ nào là b, chữ nào là d!\n• Truyền cảm hứng làm trẻ thích học chữ trước khi vào lớp 1: Thay vì bắt trẻ ngồi đọc thẻ chữ khô khan, tiết học cho trẻ khám phá bìa truyện Doraemon, Thần đồng Đất Việt, Rùa và thỏ để trẻ tự thấy học chữ giúp mình tự đọc được bao nhiêu truyện hay.\n• Điểm chốt với Chủ trường: Bài này kết hợp với giờ Làm quen chữ viết của trường thì hiệu quả tăng gấp bội. Cô giáo có sẵn phần mềm 5 lượt thả bóng, 5 lượt đoán sách và video dạy mẹo nút Thích tay trái, tay phải nên tiết học cực kỳ cuốn hút.\n\n[Bài mẫu 10 - Mẫu giáo lớn: B70 - Bé thể hiện sự tôn trọng và yêu thương thầy, cô giáo]\n- Đề tài trường vẫn dạy (Chủ đề Ngày Nhà giáo Việt Nam 20/11): • Bước 1 – Mở đầu: Hát vận động bài Cô giáo miền xuôi hoặc Bông hồng tặng cô.\n• Bước 2 – Dạy bài mới: Xem hình ảnh hoặc video về ngày 20/11, cô hỏi trẻ hàng ngày cô chăm sóc và dạy con những gì, con làm gì để cô vui lòng.\n• Bước 3 – Trải nghiệm: Chia trẻ về các nhóm để mỗi bé trang trí 1 tấm bưu thiếp nhỏ, cắm hoa hoặc tô màu tranh tặng cô; cuối giờ đại diện trẻ lên tặng hoa và chúc cô giáo.\n- Nội dung Novastars: • Là tiết tổng kết của cụm 3 tiết liên tiếp ở cuối năm lớp Lớn: B68 Tôn trọng thầy cô → B69 Yêu thương thầy cô → B70 Thể hiện sự tôn trọng và yêu thương thầy cô, ngay trước tiết B71 Sẵn sàng trở thành học sinh Tiểu học.\n• Kiến thức: Trẻ biết truyền thống Làm báo tường tập thể để tri ân thầy cô giáo của các anh chị học sinh Tiểu học.\n• Kĩ năng: Biết phối hợp làm việc nhóm theo sự phân công gồm cắt, dán, tô màu, gấp hoa, chấm vân tay để cùng tạo nên 1 tờ báo tường khổ lớn A1 và rèn kỹ năng đứng thuyết trình theo nhóm trước cả lớp.\n- Cách triển khai: • Hoạt động 1 – Cả lớp chia 4 nhóm cùng làm 1 tờ Báo tường khổ lớn A1: Cô ôn lại những cách thể hiện tình yêu thương với thầy cô → Cô giới thiệu: Ở trường Tiểu học, hằng năm vào dịp 20/11 các anh chị học sinh đều cùng nhau làm báo tường để tri ân thầy cô. Hôm nay cả lớp mình cùng làm 1 bức báo tường thật to tặng cô nhé! → Cô chia lớp thành 4 nhóm bàn, mỗi nhóm phụ trách 1 phần việc riêng để ghép lên tờ giấy A1 trên giá vẽ:\n  + Nhóm 1: Cắt hình trái tim lớn và dùng hộp mực đỏ chấm dấu vân tay của các bạn trong nhóm phủ kín hình trái tim.\n  + Nhóm 2: Tô màu lên bó hoa, gấp nổi theo đường nét đứt và dán lên báo tường.\n  + Nhóm 3: Vẽ thêm các chi tiết và tô màu bức chân dung cô giáo rồi dán lên giữa báo tường.\n  + Nhóm 4: Cắt và tô màu bộ chữ tiêu đề CON, CÔ cùng các hình bông hoa, trái tim nhỏ để dán trang trí hoàn thiện tờ báo tường Con yêu cô.\n• Hoạt động 2 – Tập thuyết trình nhóm nối tiếp và Quay video: Xếp đội hình vòng cung trước giá vẽ treo tờ báo tường và đặt máy quay phim → Cô hướng dẫn 3 yêu cầu khi đứng thuyết trình gồm Dáng đứng thẳng – Miệng cười tươi – Nói to rõ ràng và đọc mẫu bài giới thiệu hoàn chỉnh của học sinh 6 tuổi → Cho từng nhóm đứng tại chỗ tập phân công nhau, mỗi bạn trong nhóm nói tiếp nối một phần của bài giới thiệu → Mời 1 đến 2 nhóm lên đứng cạnh bức báo tường thuyết trình trước lớp để cô quay phim.\n- Điểm ăn tiền thuyết phục Chủ trường: • Khác biệt lớn về cách rèn làm việc nhóm: Ở tiết học truyền thống, dù chia trẻ ngồi theo nhóm nhưng mỗi bé vẫn tự tô 1 tấm thiệp nhỏ của riêng mình, ai làm xong của người nấy. Còn ở bài B70 của Novastars, cả lớp cùng hợp sức làm chung 1 tờ Báo tường khổ lớn A1 giống hệt văn hóa trường Tiểu học: nhóm làm trái tim vân tay, nhóm làm hoa nổi, nhóm vẽ chân dung cô, nhóm làm dòng chữ tiêu đề Con yêu cô. Trẻ hiểu rằng mỗi nhóm là một mảnh ghép không thể thiếu để tạo nên tác phẩm lớn của cả lớp.\n• Rèn kỹ năng thuyết trình tập thể: Không chỉ 1 bạn lớp trưởng lên nói, mà cả nhóm cùng bước lên sân khấu, mỗi bạn tự tin nói tiếp nối nhau một đoạn trong bài giới thiệu bức báo tường trước ống kính máy quay.\n• Điểm chốt với Chủ trường: Toàn bộ bộ mẫu in sẵn để ghép vừa khít tờ báo tường A1 gồm chữ CON, CÔ, khung trái tim chấm vân tay, bó hoa có sẵn nét đứt để gấp, tranh chân dung cô đã có sẵn trong thư viện học liệu của Novastars. Cô giáo chuẩn bị rất nhanh mà cuối năm lớp 5 tuổi lại có một bức báo tường tuyệt đẹp treo ở sảnh trường cùng video các con thuyết trình tri ân cô giáo đầy xúc động gửi phụ huynh.\n","passThreshold":80,"summaryPoints":["Khối Mẫu giáo Bé (3–4 tuổi): B06 Thực hành lời chào với người thật quanh trường; B45 Giới thiệu 4 quy tắc giao thông an toàn theo công thức 4 bước; B69 Phân loại rác dễ phân hủy (thùng Xanh) & khó phân hủy (thùng Cam) qua 12 lượt game cùng Sao Nova.","Khối Mẫu giáo Nhỡ (4–5 tuổi): B09 Ôn tập ăn uống đủ chất & 2 bạn ngồi cạnh kiểm tra chéo Bảng phân loại thức ăn; B13 Cảm xúc của bé & làm Huy hiệu cảm xúc 4 mặt theo màu sắc riêng; B39 Phòng tránh và sơ cứu bỏng nóng cùng phim Mẹ Su.","Khối Mẫu giáo Lớn (5–6 tuổi): B24 Tự sắp xếp tủ quần áo theo 3 nguyên tắc thông minh; B56 Rèn tư thế ngồi học (thước 30cm) & cầm bút 3 bước sau trò chơi Thỏ con tinh nghịch; B57 Vui học chữ cái & mẹo nút Thích 2 bàn tay phân biệt b–d; B70 Làm báo tường khổ lớn A1 tri ân thầy cô."],"structuredData":[{"stt":"1","khoi":"Mẫu giáo bé","bai_hoc":"B06 - Bé thực hành lời chào với những người xung quanh","cong_nghe":"Video YouTube","diem_an_tien":"• Khác biệt lớn nhất: Ở giáo án thông thường, cô gom cả kể chuyện lẫn đóng vai vào 1 tiết ngồi trong phòng học. Trẻ 3 tuổi ngồi trong lớp cô hỏi thì trả lời rất giỏi, nhưng vừa bước ra ngoài gặp người lạ là ngượng ngùng trốn sau lưng mẹ vì chưa được tập chào trong hoàn cảnh thật. Novastars nghiên cứu tâm lý này nên tách hẳn thành 2 tiết: B05 học trong lớp, B06 đưa trẻ ra sân trường tập chào người thật.\n• Mẹo sư phạm tinh tế giúp trẻ hết sợ: Giáo án hướng dẫn rõ khi gặp người khác, cô giáo chủ động chào trước rồi nhắc trẻ đồng thanh chào to. Nhờ cô mở lời trước và có cả lớp chào cùng, những bé nhút nhát nhất cũng dám mở miệng chào theo, cộng thêm việc rèn tỉ mỉ cả ánh mắt và nụ cười chứ không chỉ khoanh tay đọc vẹt.\n• Điểm chốt với Chủ trường: Hoạt động này vừa khít với 2 cô giáo sẵn có của mỗi lớp nên trường áp dụng ngay cực kỳ dễ dàng, không tốn thêm nhân sự hay đạo cụ nào; nhưng nếu không có lộ trình 2 tiết nối tiếp và kịch bản chi tiết của Novastars thì các cô thường chỉ cho đóng vai trong lớp là xong.","cach_trien_khai":"• Hoạt động 1: Cả lớp nghe và hát theo video Con chim vành khuyên để tạo không khí vui vẻ.\n• Hoạt động 2 – Ôn và tập động tác tại chỗ: Cô hỏi lại trẻ cách chào bạn và chào người lớn khác nhau thế nào từ câu nói đến mắt, tay, miệng. Cả lớp cùng đứng dậy tại chỗ tập nói to câu chào kết hợp mắt nhìn – miệng cười – tay vẫy hoặc khoanh tay.\n• Hoạt động 3 – Đi thực hành chào người thật quanh trường: Cô cho cả lớp xếp thành 1 hàng dọc gồm Cô giáo chính đi đầu hàng dẫn dắt – Trẻ đi ở giữa – Cô phụ đi cuối hàng bao quát, cùng đi dạo một vòng quanh sân trường. Giáo án hướng dẫn mẹo rất hay: Khi bắt gặp bất kỳ ai trong trường, CÔ GIÁO CHỦ ĐỘNG CHÀO TRƯỚC để làm gương cho trẻ hết rụt rè, rồi nhắc cả lớp đồng thanh chào thật to, rõ ràng.\n• Tổng kết: Cô khen ngợi và thưởng sticker cho trẻ.","co_thuyet_trinh":"Không","de_tai_quen_thuoc":"Dạy trẻ kỹ năng chào hỏi lễ phép","noi_dung_novastars":"• Là tiết thứ 2 nối tiếp ngay sau bài B05: ở tiết B05 trẻ đã học nhận biết lời chào trong lớp, sang tiết B06 dành trọn 100% thời gian để trẻ đi thực hành chào người thật.\n• Dạy trẻ phân biệt rõ 2 câu chào theo đúng người gặp:\n  + Gặp người lớn: Con chào cô ạ!\n  + Gặp bạn bè: Tớ chào các bạn!\n• Rèn cho trẻ làm đúng 3 cử chỉ cùng lúc khi chào: Mắt nhìn thẳng vào người mình chào; Tay giơ vẫy nếu là bạn hoặc Khoanh tay nếu là người lớn; Miệng cười tươi.\n• Mục tiêu rõ ràng: 70% trẻ nói được lời chào kèm đúng cả 3 cử chỉ mắt – tay – miệng.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Cô cho cả lớp hát bài Lời chào buổi sáng hoặc Con chim vành khuyên rồi trò chuyện dẫn vào bài.\n• Bước 2 – Dạy bài mới: Cô kể chuyện hoặc mở video Mèo con lễ phép, hỏi trẻ bạn nào ngoan, gặp ông bà và cô giáo phải chào thế nào. Sau đó cô làm mẫu khoanh tay chào và gọi một số trẻ lên bục giảng đóng vai chào theo tình huống giả định ngay trong lớp.\n• Bước 3 – Trò chơi: Chơi chọn mặt cười, mặt mếu cho hành vi lễ phép hoặc chưa lễ phép."},{"stt":"2","khoi":"Mẫu giáo bé","bai_hoc":"B45 - Bé giới thiệu về cách tham gia giao thông an toàn","cong_nghe":"Video YouTube","diem_an_tien":"• Khác biệt về kết quả đầu ra: Cách dạy thông thường chỉ dừng ở việc Cô hỏi – Trẻ đáp đúng hay sai và chạy theo đèn hiệu của cô. Còn Novastars nâng trẻ 3 tuổi lên mức cao hơn hẳn: Trẻ tự đứng trước lớp nói trọn vẹn một bài giới thiệu 4 quy tắc an toàn.\n• Vì sao trẻ mới 3 tuổi lại thuyết trình được? Nhờ công thức 4 bước được Novastars tính toán rất kỹ: Bước 1 hỏi lý do vì sao phải ngồi yên, xếp hàng để trẻ hiểu thay vì học vẹt → Bước 2 dán chính 4 bức tranh trẻ vừa tô lên giá vẽ ngay giữa sân khấu để khi lên nói, trẻ nhìn vào tranh là nhớ ngay 4 quy tắc không sợ quên → Bước 3 cung cấp khung câu mẫu 3 phần ngắn gọn và cho cả lớp đứng nói đồng thanh trước cho hết ngại → Bước 4 bố trí cho 4 đến 6 bé lên đứng cùng nhau hai bên giá vẽ giúp trẻ 3 tuổi có bạn đứng cạnh nên rất bạo dạn trước máy quay.\n• Điểm chốt với Chủ trường: Cô giáo của trường có sẵn câu nói mẫu, tranh in và sơ đồ chỗ đứng, chỗ đặt máy quay trong giáo án nên dạy rất nhàn; kết thúc tiết học trường có ngay những đoạn video các bé 3 tuổi đứng thuyết trình cực kỳ đáng yêu để gửi cho phụ huynh.","cach_trien_khai":"• Hoạt động 1: Trẻ đứng 2 hàng so le nhảy sôi động theo video Wheels on the bus.\n• Hoạt động 2 – Hỏi lý do để trẻ tự nhớ bài: Cô không đọc lại bài cũ mà đặt câu hỏi gợi mở: Để không bị ngã khi xe đang chạy thì mình ngồi thế nào → Ngồi yên trên ghế; Để không xô đẩy nhau khi lên xe → Xếp hàng; Để nghe rõ cô dặn → Giữ trật tự, lắng nghe.\n• Hoạt động 3 – Tô tranh làm điểm tựa trí nhớ: Trẻ về bàn nhóm tô màu tranh quy tắc, mỗi bé 1 tranh. Sau đó cô chọn dán đủ 4 bức tranh quy tắc trẻ vừa tô lên bảng giá vẽ đặt chính giữa phía trên lớp.\n• Hoạt động 4 – Tập thuyết trình theo câu mẫu và Quay video: Cô làm mẫu bài giới thiệu gồm 3 câu ngắn gọn vừa sức trẻ 3 tuổi: Xin chào các bạn, tớ tên là... năm nay tớ 3 tuổi. Để đảm bảo an toàn tớ sẽ thực hiện các quy tắc: xếp hàng, lắng nghe, giữ trật tự, ngồi yên trên ghế. Cảm ơn các bạn đã lắng nghe → Cả lớp đứng tại chỗ tập nói đồng thanh cùng cô → Cô mời từng nhóm 4 đến 6 bé lên đứng hai bên bảng giá vẽ để thuyết trình trước máy quay phim.","co_thuyet_trinh":"Có","de_tai_quen_thuoc":"Bé với an toàn giao thông","noi_dung_novastars":"• Là tiết thứ 2 nối tiếp bài B44: ở tiết B44 dạy trẻ hiểu quy tắc, sang tiết B45 rèn trẻ đứng lên sân khấu giới thiệu lại quy tắc đó cho mọi người.\n• Nội dung sát đúng thực tế của trẻ 3 tuổi khi đi xe buýt, xe ô tô cùng trường và gia đình, gói gọn trong 4 quy tắc trẻ tự làm được: Xếp hàng – Giữ trật tự – Lắng nghe hướng dẫn – Ngồi yên tại chỗ.\n• Mục tiêu đầu ra vượt trội: 80% trẻ 3 tuổi tự tin nói to, rõ ràng để giới thiệu lại 4 quy tắc an toàn trước cả lớp.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Hát vận động bài Em đi qua ngã tư đường phố.\n• Bước 2 – Dạy bài mới: Cô cho trẻ xem tranh hoặc video về đèn xanh – đèn đỏ, đi bộ trên vỉa hè phải có người lớn dắt, ngồi xe máy đội mũ bảo hiểm. Cô hỏi trẻ tranh nào đúng, tranh nào sai rồi cô tổng kết bài học.\n• Bước 3 – Trò chơi: Trò chơi Tín hiệu giao thông khi cô giơ đèn xanh trẻ chạy, đèn đỏ trẻ dừng và chia 2 đội chạy lên gắn tranh đúng hoặc sai lên bảng."},{"stt":"3","khoi":"Mẫu giáo bé","bai_hoc":"B69 - Bé học cách phân loại rác bảo vệ môi trường","cong_nghe":"Phần mềm Novastars","diem_an_tien":"• Nâng tầm nội dung bài học: Giáo án các trường thường chỉ dạy trẻ 3 tuổi không xả rác bừa bãi. Novastars dạy trẻ 3 tuổi tư duy văn minh hiện đại hơn hẳn: biết phân loại rác hữu cơ dễ phân hủy vào thùng Xanh và rác nhựa, vỏ hộp khó phân hủy vào thùng Cam.\n• Phương pháp học bằng vận động kết hợp phần mềm trò chơi 12 lượt: Thay vì ngồi nghe cô giảng khái niệm phân hủy khô khan, trẻ được nhân vật hoạt hình Sao Nova giải thích trực quan và được vận động 2 vòng liên tiếp gồm Vòng 1 nghiêng người tại chỗ 6 lượt và Vòng 2 chạy lên bàn chạm thẻ màu 6 lượt theo hình ảnh rác nhảy ra trên màn hình.\n• Điểm chốt với Chủ trường: Giáo viên trường không thể tự làm ra phim hoạt hình Sao Nova hay tự lập trình 12 lượt trò chơi phân loại rác trên tivi; nhưng khi trường mua phần mềm Novastars, cô chỉ cần bật máy chiếu và đặt 2 tấm thẻ màu lên bàn là cả lớp có một tiết học công nghệ cực kỳ sôi nổi.","cach_trien_khai":"• Hoạt động 1 – Trò chơi nghiêng người theo màn hình: Mở phim dẫn dắt trên phần mềm → trẻ hô to Sẵn sàng → qua 6 lượt rác xuất hiện trên màn hình gồm vỏ chuối, hộp sữa, cành hoa, vỏ bim bim, túi rách, cành lá, cả lớp nghiêng người sang bên thùng Xanh hoặc thùng Cam để chọn thùng vứt rác.\n• Hoạt động 2 – Xem phim hoạt hình Sao Nova: Nhân vật Sao Nova trên phần mềm giải thích bằng hình ảnh sinh động thế nào là rác dễ phân hủy, rác khó phân hủy; cô hỏi lại trẻ 2 câu hỏi kiểm tra.\n• Hoạt động 3 – Trò chơi chạy lên chạm thẻ màu: Chia từng nhóm 6 đến 8 trẻ xếp hàng ngang trước vạch; qua 6 lượt rác mới trên màn hình phần mềm, khi cô hô Bắt đầu, trẻ đi nhanh lên bàn chạm tay vào thẻ màu Xanh lá hoặc thẻ màu Cam tương ứng với thùng rác cần bỏ.\n• Tổng kết: Dặn trẻ tối về kể cho bố mẹ nghe tên các loại rác dễ phân hủy và khó phân hủy.","co_thuyet_trinh":"Không","de_tai_quen_thuoc":"Dạy trẻ bỏ rác đúng nơi quy định","noi_dung_novastars":"• Không chỉ dạy bỏ rác vào thùng là ngoan, mà dạy trẻ ngay từ 3 tuổi biết phân loại 2 nhóm rác:\n  + Rác dễ phân hủy như vỏ cam, vỏ chuối, bông hoa, lá cây, thức ăn thừa → bỏ vào thùng màu Xanh lá.\n  + Rác khó phân hủy như vỏ bim bim, vỏ hộp sữa, túi bóng, lon nước, hộp nhựa → bỏ vào thùng màu Cam.\n• Trẻ biết nhìn nhãn dán trên thùng rác để bỏ đúng loại rác vào đúng thùng.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Hát bài Không xả rác hoặc cô đóng kịch Chú Cuội đi chơi dẫm phải vỏ chuối bị ngã.\n• Bước 2 – Dạy bài mới: Xem video bạn nhỏ ăn kẹo vứt vỏ ra sàn lớp; cô hỏi hành vi đó đúng hay sai, cô dặn trẻ ăn quà xong phải bỏ rác vào thùng.\n• Bước 3 – Trò chơi: Giơ thẻ mặt cười, mặt mếu cho hành vi đúng hoặc sai và cho trẻ thi nhặt giấy vụn trên sàn lớp bỏ vào 1 thùng rác chung."},{"stt":"4","khoi":"Mẫu giáo nhỡ","bai_hoc":"B09 - Bé ôn tập cách ăn uống đủ chất dinh dưỡng","cong_nghe":"Nhạc / Tự tổ chức","diem_an_tien":"• Khác biệt thông minh nhất nằm ở bước Hai trẻ tự kiểm tra bài cho nhau: Trong cách dạy truyền thống chạy tiếp sức gắn lô tô lên bảng, chỉ vài bạn nhanh nhẹn chạy lên gắn và cô giáo là người chấm đúng hay sai. Còn ở bài B09 của Novastars, 100% trẻ đều tự làm bảng món ăn riêng; vì trẻ chỉ chọn 5 món mình thích nên rất dễ lộ ra việc trẻ kén ăn như chỉ chọn thịt và quả mà bỏ qua rau. Khi hai bạn ngồi cạnh tự kiểm tra bảng cho nhau và nhắc bạn bảng của cậu thiếu nhóm rau kìa, trẻ nhớ sâu gấp đôi và tự hiểu vì sao không được ăn thiên lệch.\n• Mẹo quản lý lớp học cực kỳ thực tế cho cô giáo: Giáo án tính toán sẵn đến từng chi tiết nhỏ như cho trẻ tô màu 3 phút xong mới phát kéo cắt và vẽ sẵn sơ đồ 3 bàn – chỗ cô chính – chỗ cô phụ – góc chụp ảnh, giúp cô giáo quản lý lớp 4 tuổi dùng kéo rất an toàn, không bị lộn xộn.\n• Điểm chốt với Chủ trường: Cùng là bài dinh dưỡng nhưng cách tổ chức của Novastars biến trẻ thành người chủ động kiểm tra dinh dưỡng cho mình và cho bạn, lại có sẵn mẫu Bảng phân loại in đẹp để cuối buổi trẻ mang về khoe bố mẹ.","cach_trien_khai":"• Hoạt động 1 – Nhảy khởi động theo hiệu lệnh tay cô: Cô cầm 1 đồ vật to trên tay di chuyển trái, phải, lên, xuống, xoay tròn trên nền nhạc sôi động; trẻ nhìn đồ vật để nghiêng người, nhảy lên, ngồi xuống theo tốc độ tăng dần.\n• Hoạt động 2: Cô hỏi trẻ nhắc lại nhanh 4 nhóm thức ăn cần thiết đã học ở tiết trước.\n• Hoạt động 3 – Tự làm Bảng phân loại thức ăn cá nhân: Xếp trẻ ngồi theo sơ đồ 3 bàn, mỗi bàn 6 trẻ. Mỗi trẻ nhận 1 Bảng phân loại thức ăn, tự chọn tô màu 5 món ăn mình thích rồi cắt dán vào đúng 4 ô nhóm thức ăn. Giáo án hướng dẫn mẹo giữ an toàn rất chi tiết: Cô cho trẻ tô màu 3 phút trong 1 bản nhạc trước, tô xong cô mới phát kéo để trẻ cắt dán.\n• Hoạt động 4 – Hai bạn ngồi cạnh tự kiểm tra bài cho nhau: Từng cặp 2 trẻ ngồi cạnh nhìn bảng của nhau xem bảng của bạn có bị trống nhóm thức ăn nào không, ví dụ bạn chỉ chọn toàn thịt mà thiếu rau. Nếu thiếu thì nhắc bạn lấy hình món ăn nhóm đó dán bổ sung cho đủ 4 nhóm chất.\n• Hoạt động 5: Treo bảng sản phẩm của trẻ lên triển lãm và dặn trẻ về nhà quan sát mâm cơm gia đình xem đã đủ 4 nhóm thức ăn chưa.","co_thuyet_trinh":"Có","de_tai_quen_thuoc":"Khám phá 4 nhóm thực phẩm / Thực phẩm bé cần","noi_dung_novastars":"• Là tiết thứ 2 nối tiếp bài B08: ở tiết B08 đã làm quen 4 nhóm chất, sang tiết B09 trẻ tự tay lập bảng món ăn của mình và kiểm tra chéo cho bạn.\n• Kiến thức: 80% trẻ kể tên được 4 nhóm thức ăn gần gũi hàng ngày: thịt, rau, hoa quả, ngũ cốc.\n• Kĩ năng: 100% trẻ tự phân loại được các món ăn mình thích vào đúng 4 nhóm và biết kiểm tra bảng của bạn ngồi cạnh xem bạn thiếu nhóm chất nào.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Hát bài Mời bạn ăn, hỏi trẻ sáng nay con ăn món gì.\n• Bước 2 – Dạy bài mới: Cô chiếu slide giới thiệu lần lượt 4 nhóm chất gồm Bột đường, Đạm, Béo, Vitamin và muối khoáng, giảng cho trẻ nghe từng nhóm có tác dụng gì.\n• Bước 3 – Trò chơi: Chia lớp làm 2 đến 4 đội xếp hàng bật qua vòng lên chọn tranh lô tô thực phẩm gắn vào 4 ngôi nhà trên bảng, cuối giờ cô giáo là người kiểm tra và đếm xem đội nào gắn đúng nhiều hơn."},{"stt":"5","khoi":"Mẫu giáo nhỡ","bai_hoc":"B13 - Cảm xúc của bé","cong_nghe":"Video YouTube","diem_an_tien":"• Khác biệt sâu sắc về cách thấu hiểu tâm lý trẻ: Giáo án thông thường chỉ dạy trẻ nhìn nét mặt bên ngoài qua việc soi gương làm mặt cười, mặt mếu và hay dặn trẻ phải vui vẻ, không được khóc hay cáu giận. Còn Novastars tôn trọng cảm nhận riêng của từng đứa trẻ, không ép buộc màu đỏ phải là giận hay màu xanh là buồn – trẻ thích tô cảm xúc của mình màu gì đều được công nhận.\n• Tạo ra công cụ giúp trẻ giải tỏa tâm lý suốt cả năm: Trẻ 4 tuổi khi đang tủi thân, sợ hãi hay tức giận thường khóc lóc hoặc im lặng vì chưa đủ vốn từ để giải thích. Chiếc Huy hiệu cảm xúc có thể lật mặt giúp trẻ chỉ cần lật mặt buồn hoặc sợ lên là cô giáo biết ngay để đến ôm và hỏi han.\n• Điểm chốt với Chủ trường: Tiết học này cô giáo tổ chức rất nhẹ nhàng trên nền nhạc không lời, đồ dùng chỉ cần mẫu tranh in sẵn của Novastars, bút màu, kéo, băng dính; nhưng câu chuyện chiếc huy hiệu để con lật mặt báo cảm xúc với cô khi kể cho phụ huynh nghe thì phụ huynh nào cũng cảm động vì sự tinh tế của nhà trường.","cach_trien_khai":"• Hoạt động 1: Cả lớp đứng nhảy khởi động theo video bài hát If you are happy.\n• Hoạt động 2 – Trò chuyện Màu sắc cảm xúc: Trẻ gọi tên 4 cảm xúc trên tranh đen trắng. Cô đặt câu hỏi rất mở: Theo các con, cảm xúc vui vẻ sẽ có màu gì, rồi hỏi lần lượt cả 4 cảm xúc vui, buồn, sợ hãi, tức giận. Cô ghi nhận tất cả ý kiến của trẻ và khẳng định: Mỗi bạn có một cảm nhận riêng nên mỗi cảm xúc có thể mang nhiều màu sắc khác nhau.\n• Hoạt động 3 – Làm Huy hiệu cảm xúc của riêng bé: Mở nhạc không lời êm dịu; mỗi trẻ nhận bộ tranh 4 gương mặt cảm xúc đen trắng, tự tô màu theo đúng màu sắc mình vừa liên tưởng, dùng kéo cắt rời và dán băng dính tạo thành chiếc Huy hiệu cảm xúc 4 mặt, cô ghi tên lên sản phẩm cho từng bé.\n• Tổng kết – Đưa vào sử dụng thật hằng ngày: Cô dặn trẻ mỗi khi trong lòng có cảm xúc mạnh như buồn, sợ hãi hay tức giận mà chưa nói ra lời được, con hãy nói với cô hoặc lật đúng mặt cảm xúc đó trên chiếc huy hiệu để cô và các bạn hiểu, kịp thời giúp đỡ con.","co_thuyet_trinh":"Có","de_tai_quen_thuoc":"Nhận biết các cảm xúc Vui, Buồn, Tức giận, Sợ hãi","noi_dung_novastars":"• Nằm trong chuỗi bài về Cảm xúc của khối Nhỡ, nối tiếp bài B12 nhận biết cảm xúc sợ hãi.\n• Kiến thức: 80% trẻ gọi đúng tên 4 cảm xúc: vui, buồn, sợ hãi, tức giận.\n• Kĩ năng: 100% trẻ được rèn khéo léo đôi tay tô, cắt, dán kết hợp tự chọn màu sắc cảm xúc theo cảm nhận riêng của mình để làm chiếc Huy hiệu cảm xúc dùng giao tiếp trong lớp.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Hát bài Khuôn mặt cười, trò chuyện về nét mặt vui tươi khi đến lớp.\n• Bước 2 – Dạy bài mới: Xem tranh hoặc video các khuôn mặt Vui, Buồn, Giận, Sợ; cô hỏi khi nào con vui, khi nào con buồn; cho trẻ cầm gương soi và bắt chước làm mặt cười, mặt mếu theo cô.\n• Bước 3 – Trò chơi: Cô đọc tình huống cho trẻ giơ thẻ mặt cảm xúc tương ứng hoặc chia nhóm ghép mắt, miệng vào khuôn mặt giấy."},{"stt":"6","khoi":"Mẫu giáo nhỡ","bai_hoc":"B39 - Kĩ năng phòng, tránh nguy cơ bỏng, nóng","cong_nghe":"Phần mềm Novastars","diem_an_tien":"• Khác biệt thực tế về nội dung an toàn: Giáo án thông thường chỉ dặn trẻ Nóng là không chạm. Nhưng hàng ngày trẻ vẫn phải ăn cháo, súp nóng, tắm nước nóng, dùng máy sưởi mùa đông. Novastars dạy trẻ cách hành xử khôn ngoan trong đời sống: biết nhờ người lớn làm nguội thức ăn, kiểm tra nước tắm trước khi bước vào, ngồi xa quạt sưởi và dạy trẻ bước sơ cứu y tế cực kỳ quan trọng là xả hoặc ngâm ngay tay bị bỏng vào nước mát rồi báo người lớn thay vì chỉ đứng khóc.\n• Sự vượt trội của phần mềm tương tác: Trong 30 phút, phần mềm Novastars cuốn trẻ đi qua 4 chặng liên tiếp từ 16 lượt giơ thẻ màu → 5 lượt chạy ném bóng → xem phim Mẹ Su → xem 4 phim tình huống của Su để đứng lên thuyết trình khuyên bạn. Không một cô giáo nào tự làm slide lẻ tẻ mà có được chuỗi phim hoạt hình nhân vật và trò chơi đồng bộ như vậy.\n• Điểm chốt với Chủ trường: Tối hôm đó trẻ về nhà đứng khoanh tay thuyết trình cho bố mẹ nghe 4 nguyên tắc phòng và sơ cứu bỏng – phụ huynh sẽ thấy ngay giá trị đồng tiền học phí bỏ ra tại trường.","cach_trien_khai":"• Hoạt động 1 – Phản xạ giơ thẻ Xanh và Đỏ với 16 đồ vật trên phần mềm: Trẻ cầm thẻ Xanh cho đồ vật an toàn và thẻ Đỏ cho đồ vật gây bỏng; màn hình phần mềm chiếu lần lượt 16 đồ vật trong nhà gồm tách trà, lọ hoa, vòi nước, bồn tắm, máy sưởi, bàn là, lò vi sóng, chảo rán, ấm đun nước, bát chè, bếp hồng ngoại, thú bông..., trẻ phán đoán và giơ thẻ thật nhanh.\n• Hoạt động 2 – Trò chơi vận động thả bóng vào 4 rổ: Từng nhóm 5 đến 7 trẻ xếp hàng dọc nhìn 4 ô hình trên màn hình, qua 5 lượt chơi chạy lên thả bóng vào đúng chiếc rổ tương ứng với đồ vật an toàn.\n• Hoạt động 3 – Xem phim Mẹ Su dạy nguyên tắc an toàn và sơ cứu bỏng: Trẻ xem phim nhân vật Mẹ Su hướng dẫn và trả lời 6 câu hỏi để rút ra nguyên tắc thực tế: Muốn ăn hoặc uống đồ nóng, tắm bồn hay bật máy sưởi thì phải nhờ người lớn kiểm tra nhiệt độ, làm nguội hoặc bật giúp và ngồi cách xa; nếu lỡ bị bỏng tay thì phải làm mát vết bỏng ngay bằng nước lạnh rồi báo cho người lớn.\n• Hoạt động 4 – Tập phong thái và đứng thuyết trình xử lý 4 tình huống của Su: Cả lớp đứng tập 5 cử chỉ thuyết trình gồm Mắt nhìn thẳng – Miệng cười – Giọng to rõ – Tay vẫy chào, giơ số tuổi, chỉ vào tranh – Dáng đứng thẳng và câu mẫu → 5 đến 7 trẻ đại diện lên nhìn màn hình thuyết trình cách khuyên bạn Su trong 4 tình huống: ấm siêu tốc đang sôi, bàn ăn có bát bốc khói, muốn bật máy sưởi, tay Su vừa bị bỏng nước nóng.\n• Tổng kết: Giao nhiệm vụ tối về nhà trẻ đứng thuyết trình giới thiệu lại 4 nguyên tắc phòng bỏng cho bố mẹ nghe.","co_thuyet_trinh":"Có","de_tai_quen_thuoc":"Kỹ năng phòng tránh tai nạn bỏng cho trẻ","noi_dung_novastars":"• Nằm trong chuỗi bài An toàn thực tế của khối Nhỡ cùng với phòng điện giật, đuối nước, vật sắc nhọn, Thanh tra an toàn.\n• Kiến thức: Trẻ nhớ được 4 nguyên tắc an toàn phòng tránh nguy cơ bỏng, nóng.\n• Kĩ năng: Không chỉ biết tránh xa vật nóng mà trẻ còn biết cách xử lý chủ động trong sinh hoạt hàng ngày khi ăn súp nóng, tắm bồn, bật máy sưởi và biết cách sơ cứu đúng ngay khi lỡ bị bỏng.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Xem đoạn video ngắn về một bạn nhỏ nghịch bếp bị bỏng.\n• Bước 2 – Dạy bài mới: Xem tranh các đồ vật nóng trong nhà như phích nước, nồi canh, bàn là, bếp ga, bô xe máy; cô giải thích bị bỏng sẽ phồng rộp rất đau và dạy trẻ câu khẩu hiệu Nóng là không chạm – Không vào bếp khi người lớn đang nấu – Kêu cứu khi gặp nguy hiểm.\n• Bước 3 – Trò chơi: Chia 2 đội chạy lên bảng gạch chéo vào tranh đồ vật gây bỏng."},{"stt":"7","khoi":"Mẫu giáo lớn","bai_hoc":"B24 - Bé tự sắp xếp tủ quần áo","cong_nghe":"Phần mềm Novastars","diem_an_tien":"• Khác biệt lớn về đẳng cấp nội dung: Giáo án trường mầm non thông thường chỉ dừng ở việc dạy trẻ thao tác tay gấp cái áo, gấp cái quần. Còn Novastars đã dạy xong cách gấp ở tiết B23 rồi, nên sang tiết B24 dạy trẻ 5 tuổi tư duy sắp xếp khoa học giống như cách người lớn quy hoạch tủ đồ: phân loại theo mùa – đồ hay dùng để ngoài dễ lấy – đồ nhỏ như tất, mũ, khăn phải gom vào ngăn phụ kiện riêng.\n• Cách tổ chức kết hợp cả game màn hình lẫn quần áo thật: Trẻ vừa được chơi 8 lượt nghiêng người cất đồ vào ngăn tủ ảo trên phần mềm, vừa được thi gấp quần áo thật trên bàn theo hiệu lệnh đổi vai liên tục của nhân vật Kem.\n• Điểm chốt với Chủ trường: Nhờ chuỗi 3 tiết liên hoàn B22 – B23 – B24 và phần mềm dẫn dắt, trẻ 5 tuổi về nhà không chỉ biết gấp chiếc áo mà còn biết tự sắp xếp ngăn tủ của riêng mình gọn gàng – bố mẹ nhìn thấy sự trưởng thành rõ rệt của con trước khi vào lớp 1.","cach_trien_khai":"• Hoạt động 1 – Trò chơi Giúp Kem tìm đồ trên phần mềm: Nhóm 5 đến 7 trẻ nhìn màn hình xem bạn Kem đang cần tìm món đồ nào qua 5 lượt gồm áo phông bóng rổ, quần đùi, mũ lưỡi trai, tất xanh, găng tay để chạy về xếp hàng trước thẻ màu tương ứng.\n• Hoạt động 2 – Khám phá 3 nguyên tắc xếp tủ thông minh: Xem phim trên phần mềm và trả lời câu hỏi gợi mở Quần áo hay mặc hàng ngày nên để ở chỗ nào trong tủ → Chỗ dễ nhìn, dễ lấy nhất, rồi cùng chốt lại 3 nguyên tắc xếp tủ.\n• Hoạt động 3 – Trò chơi nghiêng người chọn ngăn tủ: Màn hình phần mềm hiện ra 8 lượt quần áo và phụ kiện gồm áo phông, quần dài, áo dài tay, quần cộc, găng tay, khăn len, tất, mũ lưỡi trai cùng hình 2 ngăn tủ; cả lớp nghiêng người sang trái hoặc sang phải để cất món đồ đó vào đúng Ngăn đồ mùa hè, Ngăn đồ mùa đông hoặc Ngăn đựng phụ kiện nhỏ.\n• Hoạt động 4 – Thử thách chia đội gấp quần áo theo lệnh của Kem: Chia 2 nhóm đứng ở 2 bàn có rổ quần áo thật; qua 5 lượt hiệu lệnh của nhân vật Kem trên màn hình, Nhóm 1 và Nhóm 2 đổi vai cho nhau, lượt thì Nhóm 1 gấp áo – Nhóm 2 gấp quần, lượt sau đảo lại rồi xếp gọn vào rổ.","co_thuyet_trinh":"Không","de_tai_quen_thuoc":"Kỹ năng tự phục vụ: Dạy trẻ gấp quần áo","noi_dung_novastars":"• Là tiết thứ 3 nâng cao trong chuỗi 3 tiết liên tiếp của khối Lớn: Tiết B22 Phân loại quần áo → Tiết B23 Học cách gấp quần áo → Tiết B24 Học tư duy sắp xếp cả tủ quần áo.\n• Kiến thức: Trẻ nhớ được 3 nguyên tắc thông minh khi sắp xếp tủ quần áo:\n  + Nguyên tắc 1: Phân loại quần, áo rõ ràng.\n  + Nguyên tắc 2: Xếp theo thứ tự ưu tiên – đồ nào hay mặc thường xuyên thì để ở vị trí dễ lấy nhất.\n  + Nguyên tắc 3: Cất riêng những đồ nhỏ như tất, găng tay, mũ, khăn, đồ lót vào 1 ngăn riêng để không bị thất lạc.\n• Kĩ năng: Biết phân loại đồ theo mùa, theo ngăn tủ và phối hợp nhóm gấp quần áo nhanh, gọn.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Hát bài Múa cho mẹ xem, trò chuyện về việc giúp bố mẹ làm việc nhà.\n• Bước 2 – Dạy bài mới: Cô trải cái áo, cái quần lên bàn, chỉ cho trẻ đâu là cổ áo, tay áo, thân áo rồi cô làm mẫu từng bước gấp đôi tay áo, gấp thân áo, vuốt phẳng.\n• Bước 3 – Thực hành: Mỗi trẻ lấy 1 đến 2 bộ quần áo trong rổ tự tập gấp tại chỗ, cô đi sửa cho từng bạn rồi khen bạn nào gấp vuông vắn."},{"stt":"8","khoi":"Mẫu giáo lớn","bai_hoc":"B56 - Bé rèn luyện tư thế ngồi học và kĩ năng cầm bút đúng cách","cong_nghe":"Phần mềm Novastars","diem_an_tien":"• Bí quyết khiến tiết học này cực kỳ hiệu quả: Vì sao ở trường mầm non cô nhắc ngồi thẳng lưng lên nhưng chỉ 1 đến 2 phút sau trẻ lại cúi gập xuống? Vì trẻ 5 tuổi chưa bật được chế độ tập trung chú ý và làm chủ cơ thể. Novastars đưa trò chơi Thỏ con tinh nghịch vào ngay đầu giờ để đánh thức não bộ trẻ tập trung cao độ qua 8 lượt nghe lệnh mà không bị động tác của cô đánh lừa, rồi mới dạy kỹ thuật ngồi và cầm bút.\n• Cụ thể hóa những thứ trừu tượng: Thay vì nói miệng mắt cách vở 30cm khiến trẻ 5 tuổi không thể tưởng tượng 30cm dài bằng nào, giáo án Novastars cho trẻ dùng chính cây thước 30cm đặt đo thử để cảm nhận khoảng cách chuẩn; đồng thời tập luôn văn hóa Lớp trưởng – Lớp phó tự quản giống lớp 1.\n• Điểm chốt với Chủ trường: Cô giáo trường dạy tiết này rất nhàn vì chỉ cần kê 5 bàn ghế mẫu lên đầu lớp, thước 30cm, bút chì và bật phần mềm, nhưng phụ huynh khi biết con được chuẩn bị vào lớp 1 bài bản từ trò chơi rèn tập trung đến cách đo khoảng cách mắt 30cm thì sẽ cực kỳ yên tâm.","cach_trien_khai":"• Hoạt động 1 – Tập nghi thức lớp học Tiểu học: Xem video mở đầu, cô bầu chọn Lớp trưởng – Lớp phó và cho lớp trưởng hô cả lớp đứng nghiêm chào cô giống hệt tiết học ở trường Tiểu học.\n• Hoạt động 2 – Trò chơi rèn sự tập trung Thỏ con tinh nghịch: Trẻ học 4 động tác tay gồm Con thỏ – Ăn cỏ – Uống nước – Vào hang rồi chơi 8 lượt với luật đặc biệt từ nhân vật Su: Chỉ làm theo lời Su nói, KHÔNG làm theo động tác cô làm; 2 lượt đầu cô hô và làm giống nhau, 6 lượt sau cô cố tình hô một đằng nhưng tay làm một nẻo để rèn trẻ tập trung lắng nghe, không bắt chước máy móc.\n• Hoạt động 3 – Xem phim hoạt hình Su và Kem ngồi sai tư thế: Trẻ xem phim thấy bạn Su dí sát mắt vào sách nên mắt nhìn mờ, bạn Kem cúi thấp nên bị đau lưng → trẻ rút ra bài học và hô to câu thần chú tư thế.\n• Hoạt động 4 và 5 – Đo khoảng cách bằng thước 30cm và Luyện cầm bút theo tốp 5 trẻ: Xem video hướng dẫn từng bước → Cô mời lần lượt từng tốp 5 trẻ lên ngồi vào 5 bộ bàn ghế mẫu trước lớp để thực hành đủ 4 bước ngồi, dùng thước 30cm đặt đo thử từ mắt xuống vở và 3 bước cầm bút cho cô kiểm tra kỹ từng bé.\n• Tổng kết: Thưởng 3 sao cho Lớp trưởng, 2 sao cho Lớp phó vì đã giúp cô giữ trật tự lớp và lớp trưởng hô chào cuối giờ.","co_thuyet_trinh":"Không","de_tai_quen_thuoc":"Hướng dẫn trẻ tư thế ngồi học và cách cầm bút","noi_dung_novastars":"• Là tiết học chuyên biệt nằm trong chuỗi 25 tiết Hành trang vào Tiểu học của học kì II lớp Lớn, từ bài B47 đến B71.\n• Kiến thức: Trẻ hiểu rõ vì sao phải ngồi đúng, cầm bút đúng: nếu cúi sát mắt sẽ nhìn mờ và hại mắt, nếu gập lưng sẽ bị đau lưng như bạn Su và bạn Kem trong phim.\n• Kĩ năng được chia thành từng bước rõ ràng, dễ làm theo:\n  + 4 bước ngồi học chuẩn: Bước 1 Ngồi vào ghế, chỉnh ghế ngay ngắn → Bước 2 Hai chân để thẳng, bàn chân chạm đất → Bước 3 Ngồi thẳng lưng → Bước 4 Dùng cây thước 30cm đo đúng khoảng cách từ mắt đến vở.\n  + 3 bước cầm bút chuẩn: Bước 1 Giơ 3 ngón tay cầm bút là cái, trỏ, giữa, 2 ngón còn lại nắm vào lòng bàn tay → Bước 2 Ngón cái và ngón trỏ giữ bút, ngón giữa đỡ bút ở vị trí cách ngòi bút 2 đến 3cm → Bước 3 Hướng đuôi bút về phía vai.","cach_truong_thuong_day":"• Các trường thường không có tiết Kĩ năng sống riêng cho đề tài này mà chỉ nhắc lồng ghép 3 đến 5 phút đầu giờ Tập tô:\n• Cô treo tranh mẫu Tư thế ngồi học đúng, nhắc trẻ ngồi thẳng lưng, ngực không tì vào bàn, mắt cách vở 25 đến 30cm, cầm bút bằng 3 ngón tay. Sau đó cả lớp đọc bài thơ ngắn rồi mở vở tập tô ngồi tô chữ, cô đi quanh lớp chỉnh lưng và tay cho trẻ."},{"stt":"9","khoi":"Mẫu giáo lớn","bai_hoc":"B57 - Bé vui học cùng các chữ cái","cong_nghe":"Phần mềm Novastars","diem_an_tien":"• Giải quyết nỗi đau lớn nhất khi dạy chữ cho trẻ 5 đến 6 tuổi: Hầu hết trẻ 5 tuổi đều bị nhầm giữa chữ b và chữ d nếu cô chỉ giảng lý thuyết nét sổ thẳng bên trái, nét cong bên phải vì trẻ rất dễ quên bên nào là trái, bên nào là phải của con chữ. Novastars dùng mẹo Giơ nút Thích bằng hai bàn tay: tay trái là chữ b, tay phải là chữ d – đôi bàn tay luôn gắn trên người trẻ nên lúc nào quên trẻ chỉ cần giơ 2 tay lên nhìn là biết ngay chữ nào là b, chữ nào là d!\n• Truyền cảm hứng làm trẻ thích học chữ trước khi vào lớp 1: Thay vì bắt trẻ ngồi đọc thẻ chữ khô khan, tiết học cho trẻ khám phá bìa truyện Doraemon, Thần đồng Đất Việt, Rùa và thỏ để trẻ tự thấy học chữ giúp mình tự đọc được bao nhiêu truyện hay.\n• Điểm chốt với Chủ trường: Bài này kết hợp với giờ Làm quen chữ viết của trường thì hiệu quả tăng gấp bội. Cô giáo có sẵn phần mềm 5 lượt thả bóng, 5 lượt đoán sách và video dạy mẹo nút Thích tay trái, tay phải nên tiết học cực kỳ cuốn hút.","cach_trien_khai":"• Hoạt động 1: Nghi thức chào đầu giờ Tiểu học và bầu chọn Lớp trưởng, Lớp phó.\n• Hoạt động 2 – Trò chơi vận động Nghe chữ, thả bóng: Từng nhóm 5 trẻ đứng trước vạch nghe nhân vật Su đọc chữ cái qua 5 lượt gồm a–o, t–a, m–t, b–h, o–x rồi chạy lên thả quả bóng vào đúng chiếc rổ có gắn chữ cái đó.\n• Hoạt động 3 – Xem phim Su và Kem để khơi gợi niềm yêu thích học chữ: Xem phim hai bạn Su, Kem nói về điều thú vị khi biết chữ → Cô hỏi từng trẻ: Khi biết chữ, con thích làm điều gì nhất, vì sao để trẻ hào hứng chia sẻ ước mơ của mình.\n• Hoạt động 4 – Trò chơi Đoán tên sách hay trên màn hình: Trẻ nghe gợi ý của Su hoặc Kem và nhìn hình 3 cuốn sách trên màn hình để giơ tay đoán đúng 5 đầu sách nổi tiếng gồm Thần đồng Đất Việt, Cậu bé chăn cừu, Doraemon, Rùa và thỏ, Trầu cau.\n• Hoạt động 5 – Mẹo dùng 2 bàn tay phân biệt chữ b và d, kết hợp Tập viết nhanh: Xem video hướng dẫn mẹo cực dễ nhớ: Giơ bàn tay bấm nút Thích với ngón cái dựng đứng, 4 ngón nắm tròn – Giơ nút Thích bằng TAY TRÁI sẽ tạo thành đúng hình chữ b; Giơ nút Thích bằng TAY PHẢI sẽ tạo thành đúng hình chữ d → Cô chỉ chữ b, d trên bảng cho trẻ giơ tay trái hoặc tay phải tương ứng và đọc to → Phát giấy A5 và bút màu, qua 5 lượt cô viết cặp từ lên bảng như con bê – con dê, quả bóng – dưa hấu, bánh bao – cái diều..., trẻ nhìn từ rồi tự viết chữ b hoặc d ra giấy giơ lên cho cô kiểm tra.","co_thuyet_trinh":"Có","de_tai_quen_thuoc":"Làm quen chữ cái b, d, đ","noi_dung_novastars":"• Nằm trong chuỗi bài Hành trang vào Tiểu học, bổ trợ trực tiếp cho việc học chữ của trẻ 5 đến 6 tuổi.\n• Kiến thức: Giúp trẻ hiểu và yêu thích việc học chữ vì thấy rõ lợi ích thiết thực: biết chữ để tự đọc tên mình, tự đọc truyện tranh yêu thích, viết thư cho ông bà và bạn bè ở xa.\n• Kĩ năng: Nhận diện nhanh các chữ cái a, b, o, t, x, h, m; đặc biệt nắm được mẹo dùng hai bàn tay để phân biệt chính xác cặp chữ cái trẻ hay viết ngược nhất là chữ b và chữ d.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Hát bài hát chủ đề, xem tranh con bò, con dê, rút các chữ cái đã học.\n• Bước 2 – Dạy bài mới: Cô giơ thẻ chữ b và chữ d cho cả lớp, tổ, cá nhân đọc to; sau đó cô phân tích cấu tạo nét chữ: Chữ b có 1 nét sổ thẳng bên trái và 1 nét cong tròn bên phải; chữ d có 1 nét cong tròn bên trái và 1 nét sổ thẳng bên phải, rồi hỏi trẻ 2 chữ giống và khác nhau ở đâu.\n• Bước 3 – Trò chơi: Tìm chữ theo tiếng sắc xô, bật qua vòng lên bảng gắn chữ b, d hoặc tô chữ chấm mờ."},{"stt":"10","khoi":"Mẫu giáo lớn","bai_hoc":"B70 - Bé thể hiện sự tôn trọng và yêu thương thầy, cô giáo","cong_nghe":"Tự tổ chức theo quy trình chuẩn","diem_an_tien":"• Khác biệt lớn về cách rèn làm việc nhóm: Ở tiết học truyền thống, dù chia trẻ ngồi theo nhóm nhưng mỗi bé vẫn tự tô 1 tấm thiệp nhỏ của riêng mình, ai làm xong của người nấy. Còn ở bài B70 của Novastars, cả lớp cùng hợp sức làm chung 1 tờ Báo tường khổ lớn A1 giống hệt văn hóa trường Tiểu học: nhóm làm trái tim vân tay, nhóm làm hoa nổi, nhóm vẽ chân dung cô, nhóm làm dòng chữ tiêu đề Con yêu cô. Trẻ hiểu rằng mỗi nhóm là một mảnh ghép không thể thiếu để tạo nên tác phẩm lớn của cả lớp.\n• Rèn kỹ năng thuyết trình tập thể: Không chỉ 1 bạn lớp trưởng lên nói, mà cả nhóm cùng bước lên sân khấu, mỗi bạn tự tin nói tiếp nối nhau một đoạn trong bài giới thiệu bức báo tường trước ống kính máy quay.\n• Điểm chốt với Chủ trường: Toàn bộ bộ mẫu in sẵn để ghép vừa khít tờ báo tường A1 gồm chữ CON, CÔ, khung trái tim chấm vân tay, bó hoa có sẵn nét đứt để gấp, tranh chân dung cô đã có sẵn trong thư viện học liệu của Novastars. Cô giáo chuẩn bị rất nhanh mà cuối năm lớp 5 tuổi lại có một bức báo tường tuyệt đẹp treo ở sảnh trường cùng video các con thuyết trình tri ân cô giáo đầy xúc động gửi phụ huynh.","cach_trien_khai":"• Hoạt động 1 – Cả lớp chia 4 nhóm cùng làm 1 tờ Báo tường khổ lớn A1: Cô ôn lại những cách thể hiện tình yêu thương với thầy cô → Cô giới thiệu: Ở trường Tiểu học, hằng năm vào dịp 20/11 các anh chị học sinh đều cùng nhau làm báo tường để tri ân thầy cô. Hôm nay cả lớp mình cùng làm 1 bức báo tường thật to tặng cô nhé! → Cô chia lớp thành 4 nhóm bàn, mỗi nhóm phụ trách 1 phần việc riêng để ghép lên tờ giấy A1 trên giá vẽ:\n  + Nhóm 1: Cắt hình trái tim lớn và dùng hộp mực đỏ chấm dấu vân tay của các bạn trong nhóm phủ kín hình trái tim.\n  + Nhóm 2: Tô màu lên bó hoa, gấp nổi theo đường nét đứt và dán lên báo tường.\n  + Nhóm 3: Vẽ thêm các chi tiết và tô màu bức chân dung cô giáo rồi dán lên giữa báo tường.\n  + Nhóm 4: Cắt và tô màu bộ chữ tiêu đề CON, CÔ cùng các hình bông hoa, trái tim nhỏ để dán trang trí hoàn thiện tờ báo tường Con yêu cô.\n• Hoạt động 2 – Tập thuyết trình nhóm nối tiếp và Quay video: Xếp đội hình vòng cung trước giá vẽ treo tờ báo tường và đặt máy quay phim → Cô hướng dẫn 3 yêu cầu khi đứng thuyết trình gồm Dáng đứng thẳng – Miệng cười tươi – Nói to rõ ràng và đọc mẫu bài giới thiệu hoàn chỉnh của học sinh 6 tuổi → Cho từng nhóm đứng tại chỗ tập phân công nhau, mỗi bạn trong nhóm nói tiếp nối một phần của bài giới thiệu → Mời 1 đến 2 nhóm lên đứng cạnh bức báo tường thuyết trình trước lớp để cô quay phim.","co_thuyet_trinh":"Có","de_tai_quen_thuoc":"Chủ đề Ngày Nhà giáo Việt Nam 20/11","noi_dung_novastars":"• Là tiết tổng kết của cụm 3 tiết liên tiếp ở cuối năm lớp Lớn: B68 Tôn trọng thầy cô → B69 Yêu thương thầy cô → B70 Thể hiện sự tôn trọng và yêu thương thầy cô, ngay trước tiết B71 Sẵn sàng trở thành học sinh Tiểu học.\n• Kiến thức: Trẻ biết truyền thống Làm báo tường tập thể để tri ân thầy cô giáo của các anh chị học sinh Tiểu học.\n• Kĩ năng: Biết phối hợp làm việc nhóm theo sự phân công gồm cắt, dán, tô màu, gấp hoa, chấm vân tay để cùng tạo nên 1 tờ báo tường khổ lớn A1 và rèn kỹ năng đứng thuyết trình theo nhóm trước cả lớp.","cach_truong_thuong_day":"• Bước 1 – Mở đầu: Hát vận động bài Cô giáo miền xuôi hoặc Bông hồng tặng cô.\n• Bước 2 – Dạy bài mới: Xem hình ảnh hoặc video về ngày 20/11, cô hỏi trẻ hàng ngày cô chăm sóc và dạy con những gì, con làm gì để cô vui lòng.\n• Bước 3 – Trải nghiệm: Chia trẻ về các nhóm để mỗi bé trang trí 1 tấm bưu thiếp nhỏ, cắm hoa hoặc tô màu tranh tặng cô; cuối giờ đại diện trẻ lên tặng hoa và chúc cô giáo."}],"structuredType":"sample_10_lessons","durationMinutes":30,"lessonQuickQuizzes":[{"id":"hp03-qq-b06-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong bài B06 (Bé thực hành lời chào với những người xung quanh), trẻ cần phối hợp chính xác 3 cử chỉ nào cùng lúc với câu chào?","options":["Mắt nhìn hướng về phía cô giáo đứng đầu hàng để chờ hiệu lệnh, sau đó giơ hai tay vẫy cao trên đầu và đồng thanh hô chào thật nhanh rồi bước tiếp.","Mắt nhìn thẳng vào người chào, đầu cúi gập góc 45 độ, hai tay buông thẳng xuôi theo thân người để đạt mục tiêu chuẩn 50% trẻ trong lớp làm được.","Miệng nói thật to câu chào chung chung, hai tay khoanh trước ngực bất kể gặp người lớn hay bạn bè cùng tuổi để đồng bộ động tác cả hàng.","Mắt nhìn thẳng vào người chào, miệng cười tươi, tay giơ vẫy khi chào bạn hoặc khoanh tay khi chào người lớn để đạt chuẩn 70% trẻ làm được."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B06 quy định rõ 3 cử chỉ đồng thời: mắt nhìn thẳng – miệng cười tươi – tay vẫy (bạn) hoặc khoanh tay (người lớn), mục tiêu 70% trẻ. | Phân biệt bẫy sai: Dễ nhầm sang khoanh tay với cả bạn bè hoặc tỷ lệ mục tiêu 50% hay cúi gập 45 độ không có trong giáo án.","lessonIndex":0,"lessonCode":"B06"},{"id":"hp03-qq-b06-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"So với cách dạy truyền thống gói gọn chào hỏi trong 1 tiết đóng vai trên lớp, thiết kế tách riêng B05 → B06 của Novastars giải quyết vấn đề gì?","options":["Giảm bớt thời gian kể chuyện mở đầu ở tiết B05 để dành thời lượng cho cô giáo chấm điểm xếp loại thái độ lễ phép của từng trẻ trên bảng thi đua.","Khắc phục việc trẻ trả lời giỏi trong phòng nhưng ra sân gặp khách lạ lại trốn sau lưng mẹ nhờ đưa cả lớp đi thực hành chào người thật quanh trường.","Chuyển toàn bộ hoạt động sang trò chơi chọn thẻ mặt cười – mặt mếu giúp trẻ 3 tuổi nhận diện nhanh hành vi chào hỏi đúng sai ngay trên màn hình.","Rút ngắn thời lượng thực hành chào hỏi xuống còn 10 phút cuối giờ nhằm nhường thời gian cho hoạt động tô màu bức tranh gia đình trong lớp."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): B06 dành trọn thời gian cho trẻ ra sân trường tập chào người thật sau tiết B05 nhận biết trong lớp, phá rào cản sợ người lạ. | Phân biệt bẫy sai: Chọn mặt cười/mếu là bước của giáo án truyền thống; B06 nâng cấp từ đóng vai giả định sang tương tác ngoài phòng học.","lessonIndex":0,"lessonCode":"B06"},{"id":"hp03-qq-b06-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng lo ngại đưa cả lớp 3 tuổi ra sân thực hành chào ở bài B06 sẽ lộn xộn và thiếu người quản lý — Sale nên giải thích dựa trên chi tiết nào?","options":["Nếu sân trường rộng, giáo viên có thể bỏ hẳn hoạt động đi quanh trường mà chỉ cho trẻ đứng thành vòng tròn ngay trước cửa lớp để đảm bảo an toàn.","Nhà trường có thể tách lớp thành từng tốp 3 bé ra sân lần lượt, các bé còn lại ngồi xem video Con chim vành khuyên một mình trong lớp chờ tới lượt.","Bài B06 sẽ bố trí thêm nhân viên bảo vệ và phụ huynh tình nguyện đi dọc hai bên hàng ngũ để nhắc từng bé khoanh tay khi gặp người khác trong sân.","Giáo án vẽ sẵn đội hình 1 hàng dọc (cô chính đi đầu dẫn & chào mẫu phá băng, trẻ ở giữa, cô phụ chốt cuối bao quát) vừa khít đúng 2 cô sẵn có."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): B06 sử dụng đúng 2 cô sẵn có với đội hình cô chính đi đầu chào mẫu – trẻ ở giữa – cô phụ đi cuối bao quát an toàn. | Phân biệt bẫy sai: Không bỏ hoạt động ra sân cốt lõi và không cần huy động bảo vệ hay phụ huynh đi kèm.","lessonIndex":0,"lessonCode":"B06"},{"id":"hp03-qq-b45-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Ở bài B45 (Bé giới thiệu về cách tham gia giao thông an toàn), khung thuyết trình mẫu cho bé 3 tuổi tập trung vào 4 quy tắc thực tế nào?","options":["Bốn quy tắc phòng tai nạn trong lớp: đi nhẹ nói khẽ ở hành lang, không chạy nhảy gần cầu thang, cất đồ chơi vào rổ và lắng nghe hiệu lệnh cô.","Bốn quy tắc đường bộ nâng cao: nhận biết đèn tín hiệu ba màu, đi đúng vạch kẻ sang đường, đội mũ bảo hiểm có quai cài và quan sát hai chiều.","Bốn quy tắc khi đi xe cùng trường và gia đình: xếp hàng, lắng nghe, giữ trật tự và ngồi yên trên ghế (mục tiêu 80% trẻ 3 tuổi tự tin nói rõ).","Bốn quy tắc tự phục vụ khi đi chơi xa: tự soạn quần áo vào ba lô, giữ thẻ tên an toàn, đi theo hàng đôi nắm tay bạn và giữ vệ sinh nơi công cộng."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B45 khối Bé tập trung đúng 4 quy tắc vừa sức trẻ 3 tuổi trên xe ô tô/xe buýt: xếp hàng – lắng nghe – giữ trật tự – ngồi yên trên ghế. | Phân biệt bẫy sai: Đèn tín hiệu hay vạch kẻ sang đường là nội dung giáo án truyền thống trường hay liệt kê, khác với 4 quy tắc thuyết trình trong B45.","lessonIndex":1,"lessonCode":"B45"},{"id":"hp03-qq-b45-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Công cụ nào trong bài B45 giúp trẻ 3 tuổi dù vốn từ ít vẫn nhớ trọn vẹn cả 4 quy tắc khi đứng trước máy quay mà không cần cô đứng cạnh nhắc từng chữ?","options":["Chính 4 bức tranh quy tắc trẻ vừa tự tô ở Hoạt động 3 được dán lên bảng giá vẽ đặt giữa sân khấu để trẻ nhìn hình nhớ ý khi nói theo câu mẫu.","Cô giáo giơ lần lượt 4 tấm thẻ số đếm từ 1 đến 4 ở cuối lớp kết hợp bảng chữ cái in hoa lớn phía sau giá vẽ cho các bé nhìn đánh vần theo.","Phần mềm phát nhạc bài Wheels on the bus chạy chữ phụ đề liên tục trên tivi phía sau lưng để các nhóm học sinh nhìn theo lời bài hát nói lại.","Mỗi nhóm được phát sẵn một kịch bản giấy ghi câu dẫn chi tiết và cử một bạn mạnh dạn nhất đứng cầm tờ giấy đọc mẫu trước cho các bạn đọc theo."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): B45 dùng tranh trẻ tự tô dán lên giá vẽ làm điểm tựa thị giác + câu mẫu 3 câu ngắn + đứng nhóm 4–6 bé. | Phân biệt bẫy sai: Trẻ 3 tuổi chưa biết đọc chữ hay phụ đề; điểm mấu chốt là chính bức tranh trẻ tự tô kích hoạt trí nhớ trực quan.","lessonIndex":1,"lessonCode":"B45"},{"id":"hp03-qq-b45-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Chủ trường hỏi: \"Trẻ lớp 3 tuổi nhà chị còn nói ngọng và nhút nhát lắm, làm sao các con đứng thuyết trình quay video như bài B45 được?\"","options":["Đề xuất dời bài thuyết trình B45 sang cuối học kỳ II của lớp Mẫu giáo Lớn 5 tuổi khi các con đã tròn vành rõ chữ rồi mới quay video gửi bố mẹ.","Đề xuất chỉ chọn khoảng 3 đến 4 bé dạn dĩ và phát âm chuẩn nhất lớp lên quay video mẫu, các bé nhút nhát chỉ ngồi vỗ tay cổ vũ phía dưới.","Trình bày lộ trình đỡ tâm lý B45: hiểu lý do để nhớ ý → nhìn tranh tự tô → cả lớp đồng thanh câu mẫu 3 câu → đứng nhóm 4–6 bé bên giá vẽ cho dạn dĩ.","Khuyên trường cho phụ huynh tự hướng dẫn con học thuộc bài phát biểu tại nhà trước 1 tuần, tới buổi học cô chỉ việc bật máy quay lại từng bé."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Chuỗi 4 bước đồng bộ (hiểu lý do – giá vẽ tranh – đồng thanh – nhóm 4–6 bé) được thiết kế đặc biệt cho trẻ 3 tuổi chưa tự tin. | Phân biệt bẫy sai: Bỏ rơi trẻ nhút nhát hoặc dời sang 5 tuổi là đánh mất USP đạt 80% trẻ 3 tuổi biết thuyết trình.","lessonIndex":1,"lessonCode":"B45"},{"id":"hp03-qq-b69-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong bài B69 khối Bé (Bé học cách phân loại rác bảo vệ môi trường), quy ước màu thùng rác cho 2 nhóm rác được dạy chính xác như thế nào?","options":["Thùng màu Cam đựng rác dễ phân hủy (vỏ chuối, lá cây, thức ăn thừa); thùng màu Xanh lá đựng rác khó phân hủy (vỏ bim bim, lon nước, túi nilon).","Thùng màu Xanh lá đựng rác dễ phân hủy (vỏ chuối, hoa, lá, thức ăn thừa); thùng màu Cam đựng rác khó phân hủy (vỏ hộp sữa, túi bóng, hộp nhựa).","Thùng màu Đỏ đựng toàn bộ rác tái chế bằng nhựa cứng; thùng màu Vàng đựng giấy vụn và rác hữu cơ phát sinh trong bữa ăn bán trú tại lớp.","Thùng màu Xanh dương đựng rác có mùi từ nhà bếp; thùng màu Trắng đựng các loại bao bì bánh kẹo và lá cây khô trẻ nhặt được ngoài sân trường."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B69 quy định chuẩn: Xanh lá = dễ phân hủy (vỏ chuối/cam, hoa, lá, thức ăn thừa); Cam = khó phân hủy (vỏ bim bim, hộp sữa, túi bóng, lon, hộp nhựa). | Phân biệt bẫy sai: Cẩn thận bẫy đảo ngược màu Xanh lá ↔ Cam hoặc bịa thêm màu Đỏ/Vàng/Xanh dương không đúng giáo án B69.","lessonIndex":2,"lessonCode":"B69"},{"id":"hp03-qq-b69-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Cách tổ chức học phân loại rác trong bài B69 của Novastars nâng cấp hơn giáo án truyền thống \"không xả rác bừa bãi\" ở điểm cốt lõi nào?","options":["Yêu cầu mỗi bé tự trang trí và mang theo hai giỏ nhựa nhỏ từ nhà đến lớp để thực hành phân loại đồ chơi gãy và vỏ bánh kẹo trong giờ ra chơi.","Tập trung tổ chức kịch đóng vai chú Cuội giẫm vỏ chuối ngã rồi chia tổ thi nhặt nhanh toàn bộ giấy vụn trên sàn bỏ vào chung một thùng rác lớn.","Hướng dẫn trẻ 3 tuổi phân loại chi tiết thành 4 nhóm rác chuyên sâu gồm rác hữu cơ, rác thủy tinh, pin thải độc hại và đồ nhựa tái chế công nghiệp.","Đưa khái niệm rác dễ/khó phân hủy qua phim Sao Nova và 12 lượt vận động liên tiếp (6 lượt nghiêng người tại chỗ + 6 lượt chạy chạm thẻ màu)."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): B69 kết hợp phim Sao Nova với 12 lượt game phần mềm (6 nghiêng người + 6 chạm thẻ Xanh/Cam), biến kiến thức phân hủy thành phản xạ vận động. | Phân biệt bẫy sai: Chú Cuội bỏ chung 1 thùng là lối dạy cũ; phân 4 nhóm gồm pin/thủy tinh lại quá sức trẻ 3 tuổi.","lessonIndex":2,"lessonCode":"B69"},{"id":"hp03-qq-b69-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng băn khoăn: \"Dạy phân loại rác dễ phân hủy – khó phân hủy cho trẻ 3 tuổi có quá trừu tượng và tốn công chuẩn bị học liệu cho cô không?\"","options":["Giải thích rằng để trẻ 3 tuổi hiểu được bản chất hóa học của sự phân hủy, giáo viên sẽ chuẩn bị hai hố chôn rác thật ngoài vườn để quan sát sau 1 tháng.","Khẳng định phần mềm đã có sẵn phim Sao Nova minh họa trực quan cùng 12 lượt rác nhảy trên tivi; cô chỉ cần đặt đúng 2 tấm thẻ màu lên bàn.","Đề xuất trường bỏ phần phân loại 2 nhóm ở khối Bé, chỉ nhắc trẻ nhặt vỏ kẹo bỏ vào sọt rác chung cho nhẹ nhàng rồi lên khối Lớn mới dạy sau.","Nói với trường rằng giáo viên có thể tự cắt ghép hình ảnh hộp sữa, vỏ chuối trên PowerPoint để tự thiết kế trò chơi 12 lượt tương tự tại lớp."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): B69 dùng phim Sao Nova + game phần mềm sẵn có, đạo cụ thực hành cô chuẩn bị chỉ là 2 tấm thẻ màu Xanh lá và Cam. | Phân biệt bẫy sai: Một giáo viên không tự vẽ hoạt hình/lập trình 12 lượt game được, và không cắt bỏ nội dung phân loại của khối Bé.","lessonIndex":2,"lessonCode":"B69"},{"id":"hp03-qq-b09-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong Hoạt động 3 & 4 của bài B09 khối Nhỡ (Ăn uống đủ chất), giáo án áp dụng mẹo an toàn và kỹ thuật tương tác cặp đôi nào?","options":["Cho trẻ tô màu 5 món trong 3 phút xong mới phát kéo cắt dán vào 4 ô (thịt, rau, quả, ngũ cốc), sau đó 2 bạn ngồi cạnh tự kiểm tra chéo cho nhau.","Phát kéo ngay từ đầu cùng bút sáp màu để trẻ tự cắt rời từng món ăn trước rồi mới tô màu, sau đó cô giáo đi từng bàn chấm điểm từng bảng cá nhân.","Chia lớp làm 4 đội chạy thi bật qua vòng lên bảng gắn thẻ thực phẩm vào 4 ngôi nhà (Đạm, Bột đường, Béo, Vitamin) để cô giáo đếm kết quả.","Yêu cầu mỗi trẻ dán bắt buộc đúng 4 món ăn giống hệt nhau theo mẫu giáo viên chiếu trên tivi để bảng phân loại của cả lớp đồng đều khi trưng bày."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B09 quy định mẹo quản lý kéo (tô 3 phút xong mới phát kéo) + trẻ tự chọn 5 món mình thích + cặp đôi ngồi cạnh kiểm tra chéo 4 nhóm. | Phân biệt bẫy sai: Phát kéo ngay đầu giờ mất an toàn, còn chạy gắn tranh cho cô đếm là cách dạy truyền thống.","lessonIndex":3,"lessonCode":"B09"},{"id":"hp03-qq-b09-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Vì sao việc để trẻ tự chọn 5 món ăn mình thích rồi để bạn ngồi cạnh kiểm tra chéo ở bài B09 lại hiệu quả hơn việc cô giáo kiểm tra bài của cả lớp?","options":["Vì theo cách làm này, những trẻ chưa thuộc tên 4 nhóm thức ăn chỉ cần chép lại món của bạn ngồi cạnh là hoàn thành bảng phân loại không bị thiếu.","Vì cô giáo tiết kiệm được 15 phút chấm bài cuối giờ để dành thời gian dọn dẹp bàn ghế và chuẩn bị đồ dùng cho tiết học tiếp theo trong buổi sáng.","Vì trẻ tự chọn món hay lộ việc kén ăn (chọn toàn thịt bỏ rau), khi được bạn ngồi cạnh nhắc trực tiếp sẽ nhớ sâu gấp đôi và tự hiểu cần ăn đủ chất.","Vì việc chấm chéo giúp chọn ra đúng 3 bạn vẽ đẹp nhất lớp để treo tranh lên bảng tin, tạo động lực thi đua cá nhân mạnh mẽ trong giờ dinh dưỡng."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Để trẻ tự chọn sẽ phản ánh đúng thói quen kén ăn thật, và lời nhắc từ bạn đồng trang lứa tạo ấn tượng tự giác sâu gấp đôi. | Phân biệt bẫy sai: Không phải nhằm tiết kiệm công chấm hay sao chép bài của bạn, mà là cơ chế học ngang hàng (peer-check).","lessonIndex":3,"lessonCode":"B09"},{"id":"hp03-qq-b09-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng lo ngại: \"Lớp Nhỡ 4 tuổi có 18–20 bé mà cùng lúc cắt dán bằng kéo thì rất dễ mất trật tự và nguy hiểm\", Sale phản hồi thế nào cho thuyết phục?","options":["Chỉ ra trong giáo án B09 đã vẽ sẵn sơ đồ 3 bàn (mỗi bàn 6 trẻ), vị trí cô chính – cô phụ và mẹo tô màu 3 phút xong hết rồi mới phát kéo đồng loạt.","Gợi ý cô giáo cắt sẵn toàn bộ các hình món ăn ở nhà trước buổi học, lên lớp trẻ chỉ việc bôi hồ dán vào bảng để loại bỏ hoàn toàn việc dùng kéo.","Đề xuất tách lớp làm 3 nhóm nhỏ, lần lượt mỗi nhóm 6 bé lên bàn giáo viên cắt trong khi các nhóm khác ngồi khoanh tay chờ tại ghế.","Khuyên nhà trường thay thế kéo thủ công bằng việc phát thẻ nhựa có sẵn nam châm để trẻ gắn lên bảng cá nhân thay cho hoạt động làm Bảng phân loại."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): B09 giải quyết bài toán quản lý lớp bằng sơ đồ 3 bàn × 6 trẻ, phân công 2 cô và quy trình phát kéo sau 3 phút tô màu. | Phân biệt bẫy sai: Cắt hết sẵn ở nhà sẽ làm mất mục tiêu rèn vận động tinh; giá trị giáo án là giúp cô tổ chức dùng kéo an toàn ngay trên lớp.","lessonIndex":3,"lessonCode":"B09"},{"id":"hp03-qq-b13-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Sản phẩm và cách ứng dụng thực tế suốt năm học được tạo ra trong bài B13 khối Nhỡ (Cảm xúc của bé) là gì?","options":["Cô giáo phát cho mỗi bàn 1 bộ mặt nạ cảm xúc in sẵn để trẻ đeo khi đóng vai các nhân vật trong câu chuyện ngắn ở Hoạt động 2 rồi thu lại cất tủ.","Mỗi trẻ tô đúng màu quy định cho 4 thẻ cảm xúc (đỏ là giận, xanh là buồn, vàng là vui, tím là sợ) rồi cất vào cặp để mang về cho bố mẹ xem cuối tuần.","Mỗi trẻ dùng đất nặn tạo hình khuôn mặt cười để gắn lên bảng thi đua cuối ngày, trẻ nào giữ được mặt cười cả tuần sẽ được nhận phần thưởng sticker.","Mỗi trẻ tự chọn màu theo cảm nhận riêng cho 4 gương mặt cảm xúc để ghép thành Huy hiệu 4 mặt, dùng lật mặt báo cô khi buồn, sợ hoặc tức giận."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B13 cho trẻ tự chọn màu theo cảm nhận để làm Huy hiệu 4 mặt, dùng lật báo cảm xúc với cô khi chưa nói ra lời được. | Phân biệt bẫy sai: Không quy định màu cứng nhắc và không cất tủ/cất cặp; giá trị nằm ở việc dùng hằng ngày trong lớp.","lessonIndex":4,"lessonCode":"B13"},{"id":"hp03-qq-b13-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Trong Hoạt động 2 bài B13, khi hỏi \"Cảm xúc vui, buồn, sợ hãi, tức giận có màu gì?\", nguyên tắc sư phạm khác biệt của cô giáo Novastars là gì?","options":["Giải thích cho trẻ hiểu khoa học màu sắc quy ước: màu sắc tươi sáng thuộc về cảm xúc tích cực còn màu tối chỉ dành cho cảm xúc buồn hoặc tức giận.","Ghi nhận mọi câu trả lời của trẻ và khẳng định mỗi bạn có cảm nhận riêng nên một cảm xúc có thể mang nhiều màu sắc khác nhau, không áp đặt đúng – sai.","Cho cả lớp giơ tay biểu quyết để chọn ra một màu đại diện duy nhất cho từng cảm xúc trước khi phát bút sáp màu cho các bàn bắt đầu làm huy hiệu.","Nhấn mạnh trẻ ngoan cần giữ mặt vui vẻ cả ngày, hạn chế thể hiện mặt tức giận hay sợ hãi trên chiếc huy hiệu để tránh ảnh hưởng tâm lý bạn xung quanh."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): B13 tôn trọng trải nghiệm chủ quan của từng trẻ 4 tuổi (không ép màu, không cấm cảm xúc tiêu cực) giúp trẻ an toàn giãi bày. | Phân biệt bẫy sai: Cấm cảm xúc giận/buồn hoặc biểu quyết chọn 1 màu duy nhất là đi ngược triết lý tôn trọng cảm xúc của B13.","lessonIndex":4,"lessonCode":"B13"},{"id":"hp03-qq-b13-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Khi Chủ trường hỏi: \"Bài B13 chỉ dùng nhạc không lời và giấy màu cắt huy hiệu, không có phần mềm tương tác thì liệu có đủ tạo dấu ấn với phụ huynh không?\"","options":["Giải thích rằng bài B13 nhằm kiểm tra độ khéo léo cầm kéo của trẻ là chính, phụ huynh sẽ nhận xét được kỹ năng cắt dán qua sản phẩm dán ở góc lớp.","Thừa nhận bài B13 là tiết phụ nhẹ nhàng xen kẽ giữa các tuần dùng phần mềm nên trường có thể linh hoạt gộp chung với giờ tạo hình vẽ tự do cuối chiều.","Đề xuất giáo viên tự tải thêm bộ trò chơi ghép nét mặt trên mạng chiếu kèm để đủ thời lượng 30 phút vì hoạt động cắt dán huy hiệu chỉ tốn 10 phút.","Kể câu chuyện giá trị thật: trẻ 4 tuổi vốn từ ít khi tủi thân hay sợ hãi chỉ cần lật mặt huy hiệu báo cô biết để ôm ấp hỏi han — phụ huynh rất cảm động."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Điểm chốt B13: đạo cụ đơn giản (nhạc không lời, mẫu in sẵn, bút màu, kéo, băng dính) nhưng tạo công cụ giao tiếp tâm lý khiến phụ huynh cảm động. | Phân biệt bẫy sai: Không hạ thấp giá trị B13 xuống thành tiết tạo hình thuần túy hay tiết phụ nhẹ nhàng.","lessonIndex":4,"lessonCode":"B13"},{"id":"hp03-qq-b39-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trình tự 4 hoạt động chính trên phần mềm Novastars trong bài B39 khối Nhỡ (Phòng tránh nguy cơ bỏng, nóng) diễn ra như thế nào?","options":["Nghiêng người chọn thùng màu với 12 lượt đồ dùng → Xem video bạn nhỏ nghịch bếp → Tô màu tranh phích nước → Cả lớp đọc đồng thanh khẩu hiệu tránh nóng.","Xem phim Mẹ Su 10 phút → Chơi thẻ Xanh/Đỏ với 8 đồ vật → Thực hành chườm khăn đá lạnh giả định → Viết cam kết an toàn dán vào góc tuyên truyền lớp.","Giơ thẻ Xanh/Đỏ với 16 đồ vật → Chạy thả bóng vào 4 rổ → Xem phim Mẹ Su dạy 4 nguyên tắc & sơ cứu → Đứng thuyết trình xử lý 4 tình huống của Su.","Gạch chéo tranh gây bỏng trên bảng → Chạy ném bóng vào 2 rổ Xanh/Đỏ → Cô giáo đóng vai Mẹ Su dặn dò → Chọn 2 bạn đại diện kể lại tình huống trong lớp."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B39 gồm đúng 4 chặng: 16 lượt thẻ Xanh/Đỏ → 5 lượt thả bóng 4 rổ → phim Mẹ Su (6 câu hỏi) → thuyết trình 5 cử chỉ cho 4 tình huống của Su. | Phân biệt bẫy sai: B39 không dùng đá lạnh hay gạch chéo tranh trên bảng; nước mát (không đá buốt) và 4 chặng phần mềm là dấu hiệu chuẩn.","lessonIndex":5,"lessonCode":"B39"},{"id":"hp03-qq-b39-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"So với giáo án truyền thống chỉ dạy trẻ \"Nóng là không chạm\", bài B39 của Novastars giải quyết tình huống thực tế hằng ngày cho trẻ 4 tuổi khác biệt ra sao?","options":["Dạy trẻ xử lý khi ăn cháo nóng, tắm bồn, bật máy sưởi (nhờ người lớn thử/làm nguội, ngồi xa) và biết tự xả nước mát ngay lên vết bỏng rồi báo người lớn.","Dạy trẻ cách sử dụng găng tay cách nhiệt và kẹp gắp đồ ăn để các con tự bê bát canh nóng hoặc tự điều chỉnh nhiệt độ bình nóng lạnh trong gia đình.","Tăng cường cho trẻ quan sát hình ảnh vết bỏng phồng rộp thật trên màn hình để tạo tâm lý dè chừng, giúp trẻ tuyệt đối không bước chân vào khu vực bếp.","Hướng dẫn trẻ đọc thuộc lòng số điện thoại cấp cứu 115 và thực hành dùng băng gạc y tế quấn cố định cánh tay bị thương trong khi chờ xe cứu thương đến."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): B39 dạy trẻ cách chung sống an toàn (nhờ người lớn thử nhiệt độ, ngồi xa máy sưởi) kèm phản xạ sơ cứu chuẩn (xả nước mát ngay). | Phân biệt bẫy sai: Không dạy trẻ tự gắp đồ nóng hay dùng hình ảnh rùng rợn gây sợ hãi; số 115 không phải trọng tâm B39.","lessonIndex":5,"lessonCode":"B39"},{"id":"hp03-qq-b39-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Điểm chốt thuyết phục nhất của bài B39 mà Sale nên kể với Chủ trường để chứng minh phụ huynh sẽ nhìn thấy ngay giá trị đồng tiền học phí là gì?","options":["Bài học giúp loại bỏ hoàn toàn trách nhiệm giám sát của giáo viên trong giờ ăn bán trú vì trẻ 4 tuổi đã tự biết phân biệt toàn bộ bát canh nóng nguội.","Cuối bài học, nhà trường sẽ phát cho mỗi gia đình một bộ thẻ Xanh – Đỏ bằng nhựa cứng kèm tờ rơi hướng dẫn sơ cứu bỏng dán ở khu vực bếp gia đình.","Tối hôm học B39, trẻ 4 tuổi về nhà đứng khoanh tay thuyết trình lại cho bố mẹ 4 nguyên tắc phòng và sơ cứu bỏng đúng chuẩn, khiến phụ huynh cực kỳ ấn tượng.","Nhà trường có thể quay video cảnh cô giáo kiểm tra lý thuyết từng bé rồi ghép thành phóng sự dài 15 phút phát trên loa trường vào giờ đón trẻ buổi chiều."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Tổng kết B39 giao nhiệm vụ trẻ tối về thuyết trình lại cho bố mẹ 4 nguyên tắc phòng và sơ cứu bỏng, tạo hiệu ứng truyền thông tự nhiên. | Phân biệt bẫy sai: Trẻ vẫn cần cô giám sát trong giờ ăn bán trú, và giá trị lan tỏa đến từ chính việc con thuyết trình lại cho bố mẹ.","lessonIndex":5,"lessonCode":"B39"},{"id":"hp03-qq-b24-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong bài B24 khối Lớn (Bé tự sắp xếp tủ quần áo), 3 nguyên tắc xếp tủ thông minh được hệ thống hóa chính xác gồm những gì?","options":["(1) Xếp toàn bộ đồ theo màu sắc cầu vồng; (2) Đồ mới mua đặt ở ngăn cao nhất tránh bám bụi; (3) Treo toàn bộ tất và găng tay chung vào móc áo khoác dài.","(1) Phân loại quần và áo rõ ràng; (2) Xếp theo thứ tự ưu tiên — đồ hay mặc để chỗ dễ lấy nhất; (3) Cất riêng đồ nhỏ (tất, mũ, khăn, găng) vào 1 ngăn riêng.","(1) Gấp chung quần và áo thành từng bộ ghép sẵn; (2) Đồ ít dùng đặt ở cửa tủ cho gọn mắt; (3) Để lẫn mũ, khăn len vào cùng ngăn với áo phông mùa hè.","(1) Chia tủ thành 3 ngăn bằng nhau theo ngày trong tuần; (2) Đồ đi ngủ đặt bên trên áo khoác dày; (3) Buộc chặt tất và đồ lót vào trong túi nilon kín."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B24 ghi 3 nguyên tắc: phân loại quần/áo + đồ hay mặc để vị trí dễ lấy nhất + đồ nhỏ (tất, mũ, khăn, găng, đồ lót) gom vào ngăn riêng. | Phân biệt bẫy sai: Xếp theo màu sắc, ghép sẵn cả bộ hay để đồ hay dùng vào sâu bên trong đều sai với 3 nguyên tắc khoa học của B24.","lessonIndex":6,"lessonCode":"B24"},{"id":"hp03-qq-b24-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Bài B24 khối Lớn nâng cấp vượt bậc hơn bài \"dạy trẻ gấp quần áo\" ở trường thông thường nhờ chuỗi bài nào và phương pháp kết hợp gì?","options":["Mời phụ huynh gửi 5 bộ quần áo mặc ở nhà lên lớp để cô giáo kiểm tra xem bé gấp có phẳng hơn tiêu chuẩn chung của nhóm trưởng các tổ hay không.","Tập trung dạy trẻ 5 tuổi thuần thục kỹ năng gấp vuông 5 loại áo sơ mi có cổ bằng bàn nhựa hỗ trợ trong 25 phút rồi phát phiếu bé ngoan thưởng cuối giờ.","Tổ chức cho trẻ ngồi xếp giấy màu thành hình chiếc tủ nhiều ngăn rồi dán các hình vẽ áo quần cắt sẵn từ tạp chí vào từng ô ngăn theo trí tưởng tượng.","Đi theo chuỗi 3 tiết B22 (Phân loại) → B23 (Gấp) → B24 (Quy hoạch cả tủ); kết hợp 8 lượt game nghiêng người xếp tủ trên phần mềm và thi gấp đồ thật."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Chuỗi B22–B23–B24 giúp trẻ sang tiết B24 học tư duy sắp xếp cả tủ đồ thông minh qua 8 lượt game phần mềm + thực hành gấp đồ thật theo đội. | Phân biệt bẫy sai: Dạy mỗi thao tác gấp trên bàn hoặc dán giấy thủ công không đạt đến tư duy tổ chức không gian tủ đồ theo mùa và ưu tiên.","lessonIndex":6,"lessonCode":"B24"},{"id":"hp03-qq-b24-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng nói: \"Kỹ năng tự phục vụ gấp áo quần trẻ lớp 5 tuổi làm quen suốt từ lớp Bé rồi, đưa vào chương trình chính khóa có bị thừa không?\"","options":["Đồng ý rằng nếu lớp 5 tuổi đã gấp áo khéo rồi thì giáo viên có thể bỏ qua toàn bộ cụm B22–B24 để tăng thêm 3 tiết dạy đọc ghép vần chuẩn bị cho lớp 1.","Phân tích rõ: trường thường chỉ dạy gấp 1 chiếc áo, còn B24 dạy tư duy sắp xếp cả tủ như người lớn (theo mùa, tần suất dùng, ngăn phụ kiện) chuẩn bị vào lớp 1.","Giải thích rằng bài B24 thực chất chỉ ôn lại thao tác gấp cho các bé hay quên, giúp giữ nhịp 2 tiết/tuần mà giáo viên không cần chuẩn bị giáo cụ mới.","Đề xuất chuyển bài B24 xuống dạy cho lớp Bé 3 tuổi để làm quen sớm, còn lớp 5 tuổi chỉ nên tập trung vào các bài toán đếm và nghi thức chào cờ."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Khác biệt đẳng cấp của B24 là nâng từ thao tác tay (gấp áo) lên tư duy quy hoạch tủ đồ khoa học cho trẻ chuẩn bị tự lập vào lớp 1. | Phân biệt bẫy sai: Không bỏ qua hay hạ thấp thành bài ôn gấp áo đơn thuần, cũng không dồn xuống lớp 3 tuổi.","lessonIndex":6,"lessonCode":"B24"},{"id":"hp03-qq-b56-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong Hoạt động 4 & 5 bài B56 (Tư thế ngồi học & Cầm bút), trẻ lớp Lớn thực hành chuẩn 4 bước ngồi và 3 bước cầm bút với các thông số nào?","options":["4 bước ngồi đo mắt tới vở đúng bằng thước 30cm (ghế ngay ngắn, chân chạm đất, thẳng lưng); cầm bút bằng 3 ngón (cái–trỏ–giữa) cách ngòi 2–3cm, đuôi hướng về vai.","Ngồi lưng tựa sát thành ghế cách vở 15cm qua thước đo ngắn; cầm bút bằng cả 4 ngón tay tì sát vào đầu ngòi 1cm để nét chữ đậm và không bị run tay.","Hai chân vắt chéo thoải mái dưới gầm bàn, mắt cách vở khoảng 40cm ước lượng bằng một sải tay; cầm bút thẳng đứng vuông góc với mặt giấy khi viết.","Ngồi ép sát ngực vào mép bàn để cố định cột sống, hai khuỷu tay đặt khép gọn trong lòng; giữ bút bằng 2 ngón cái và út, đuôi bút hướng thẳng ra phía trước."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B56 quy định chuẩn: thước 30cm đo từ mắt tới vở + 3 ngón cầm bút (cái, trỏ, giữa; 2 ngón còn lại nắm) cách ngòi 2–3cm, đuôi hướng về vai. | Phân biệt bẫy sai: Cảnh giác bẫy sai khoảng cách (15cm/40cm), ép ngực vào bàn, hoặc số ngón tay/khoảng cách tới ngòi (1cm).","lessonIndex":7,"lessonCode":"B56"},{"id":"hp03-qq-b56-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Điểm đột phá của bài B56 so với việc trường nhắc tư thế 3–5 phút đầu giờ Tập tô nằm ở cách kết hợp công cụ và tâm lý học sinh nào?","options":["Cho cả lớp đọc đồng thanh 4 câu vè tư thế ngồi đúng suốt 10 phút đầu tiết rồi chấm điểm xếp hạng thi đua theo từng dãy bàn vào cuối giờ tập tô.","Phát cho mỗi bé một chiếc đai chống gù đeo cố định suốt 30 phút ngồi học để giữ lưng thẳng tuyệt đối trong khi chép đủ 2 trang nét cong kín vào vở ô li.","Bầu Lớp trưởng–Lớp phó tập nghi thức lớp 1, chơi 8 lượt Thỏ con tinh nghịch bật tập trung não bộ, xem phim Su–Kem cận/đau lưng rồi đo thật bằng thước 30cm.","Chiếu bản vẽ giải phẫu cột sống của bác sĩ chỉnh hình trong 15 phút để giải thích tác hại cong vẹo lưng rồi giao cho từng tổ tự kiểm tra nhau viết chữ."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): B56 tạo quy trình bài bản: nghi thức Lớp trưởng/Lớp phó → 8 lượt game Thỏ con tinh nghịch → phim Su–Kem → đo bằng thước 30cm theo tốp 5 trẻ. | Phân biệt bẫy sai: Không dùng đai chống gù, không đọc vè suông hay chép 2 trang chữ ô li.","lessonIndex":7,"lessonCode":"B56"},{"id":"hp03-qq-b56-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Khi tư vấn trường có nhiều phụ huynh lớp 5 tuổi lo lắng con vào lớp 1 hay bị cận thị, gù lưng và mất tập trung, Sale chốt điểm mạnh nào từ bài B56?","options":["Bài B56 biến con số 30cm trừu tượng thành thước đo thật cho tốp 5 bé thử từng em, kết hợp game rèn não bộ tập trung và tập nếp Lớp trưởng–Lớp phó Tiểu học.","Bài B56 cam kết sau đúng 1 tiết học 30 phút, 100% trẻ 5 tuổi sẽ tự giác giữ thẳng lưng suốt cả năm lớp 1 mà không cần cô giáo hay bố mẹ nhắc nhở thêm.","Bài B56 thay thế hoàn toàn giờ Tập tô của trường bằng việc cho trẻ luyện viết chữ đứng nét thanh nét đậm trên bảng con theo chuẩn sách giáo khoa mới.","Cô giáo chỉ cần chuẩn bị duy nhất 1 màn hình tivi bật chế độ tự chạy video, không cần kê thêm bàn ghế mẫu hay thước đo 30cm khi giảng bài B56."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Giá trị thuyết phục của B56 nằm ở thước 30cm cụ thể hóa khoảng cách, kiểm tra kỹ từng tốp 5 bé, game bật tập trung và nếp tự quản lớp 1. | Phân biệt bẫy sai: Đạo cụ B56 yêu cầu 5 bộ bàn ghế mẫu, thước 30cm, bút chì; và không cam kết tuyệt đối thay thế vai trò nhắc nhở của thầy cô/cha mẹ.","lessonIndex":7,"lessonCode":"B56"},{"id":"hp03-qq-b57-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong bài B57 khối Lớn (Bé vui học cùng các chữ cái), chuỗi trò chơi và hoạt động thực hành chính trên lớp diễn ra qua các bước nào?","options":["Giơ thẻ mặt cười chọn chữ đúng trên màn hình → Đọc thuộc lòng bài thơ về cặp chữ b, d, đ → Cô giáo gọi từng bé lên bảng lớn viết cả bảng chữ cái tiếng Việt.","Đọc đồng thanh bảng 29 chữ cái → Phân tích nét sổ thẳng và nét cong trên thẻ chữ → Thi bật qua vòng gắn chữ b/d → Tô màu vở tập viết chấm mờ 2 trang.","Xem phim hoạt hình suốt 20 phút → Nhảy khởi động theo bài hát chữ cái tiếng Anh → Làm việc nhóm cắt dán bìa truyện Doraemon bằng giấy bìa màu.","Nghe chữ thả bóng (5 lượt) → Phim Su–Kem khơi gợi thích chữ → Đoán 5 tên sách trên màn hình → Mẹo giơ nút Thích hai tay phân biệt b/d & viết nhanh giấy A5."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B57 đi qua: nghi thức đầu giờ → thả bóng 5 lượt (a–o, t–a, m–t, b–h, o–x) → phim Su–Kem → đoán 5 bìa sách → mẹo 2 tay b/d + 5 cặp từ giấy A5. | Phân biệt bẫy sai: Đọc thẻ chữ + bật qua vòng + tô chấm mờ là cách trường thường dạy; B57 truyền cảm hứng đọc sách + mẹo bàn tay.","lessonIndex":8,"lessonCode":"B57"},{"id":"hp03-qq-b57-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Tại sao mẹo giơ nút Thích bằng hai bàn tay ở bài B57 lại giải quyết triệt để hơn hẳn cách giảng lý thuyết \"chữ b nét cong bên phải, chữ d nét cong bên trái\"?","options":["Vì mẹo dùng tay giúp giáo viên không cần chuẩn bị giấy A5, bút màu hay tổ chức phần cho trẻ tập viết nhanh từ khóa lên giấy để kiểm tra vào cuối tiết học.","Vì trẻ 5–6 tuổi hay lẫn khái niệm trái–phải trừu tượng khi nhớ mặt chữ, còn hai bàn tay gắn sẵn trên người nên giơ lên nhìn là phân biệt ngay chữ b (trái) và d (phải).","Vì phương pháp giơ bàn tay giúp trẻ ghi nhớ cùng lúc cả bộ 3 chữ cái dễ nhầm là b, d và đ chỉ bằng một động tác nắm ngón tay cái hướng xuống dưới.","Vì động tác giơ ngón tay cái giúp trẻ rèn lực cổ tay khỏe hơn để chuyển thẳng sang viết bút máy nét thanh nét đậm ngay từ tháng thứ hai của học kỳ II."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Đôi tay luôn đi cùng trẻ (Tay trái = b, Tay phải = d) xóa bỏ sự phụ thuộc vào trí nhớ lý thuyết trái–phải trừu tượng. | Phân biệt bẫy sai: B57 vẫn có bước viết nhanh cặp chữ b/d (con bê–con dê, bóng–dưa hấu...) lên giấy A5 giơ kiểm tra; mẹo áp dụng cho cặp b–d.","lessonIndex":8,"lessonCode":"B57"},{"id":"hp03-qq-b57-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Nếu Hiệu trưởng nói: \"Trường chị dạy Làm quen chữ cái theo chương trình của Bộ đủ hết rồi, thêm bài B57 vào làm gì nữa?\", Sale trả lời thế nào?","options":["Cam kết rằng chỉ sau 1 tiết B57, toàn bộ học sinh lớp Lớn sẽ đọc trôi chảy toàn tập truyện Doraemon và Thần đồng Đất Việt trước khi bế giảng năm học.","Giải thích rằng chương trình Làm quen chữ cái của Bộ dạy sai phương pháp nên trường cần thay thế toàn bộ các tiết tập tô sang sử dụng bài giảng B57.","Đề nghị Hiệu trưởng xếp bài B57 thành buổi phụ đạo riêng vào thứ Bảy dành cho các bé viết chậm, không đưa vào khung 72 tiết chính khóa chung của lớp.","Khẳng định B57 không dạy thay giờ Làm quen chữ cái mà đóng vai trò \"mồi lửa\" tạo động lực tự đọc sách hay và trao mẹo 2 bàn tay để bổ trợ giúp trẻ hết nhầm b–d."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): B57 là mảnh ghép bổ trợ tạo hứng thú đọc truyện (Doraemon, Thần đồng Đất Việt...) và mẹo hết nhầm b–d, nhân đôi hiệu quả giờ chữ của trường. | Phân biệt bẫy sai: Không chê hay đòi thay thế khung Bộ và không thổi phồng kết quả đọc trôi chảy cả tập truyện sau 1 tiết.","lessonIndex":8,"lessonCode":"B57"},{"id":"hp03-qq-b70-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong Hoạt động 1 bài B70 (Bé thể hiện sự tôn trọng và yêu thương thầy, cô giáo), 4 nhóm lớp Lớn được phân công ghép tờ Báo tường A1 ra sao?","options":["Cả 4 nhóm đều cùng tô màu 4 bức tranh chân dung giống nhau trên khổ giấy A4 rồi dán xếp cạnh nhau theo hàng ngang lên tấm bảng nỉ phía cuối phòng học.","Nhóm 1 viết bài thơ tri ân 8 câu; Nhóm 2 cắt dán ảnh chụp hoạt động ngoại khóa; Nhóm 3 vẽ khung viền bằng sáp dầu; Nhóm 4 trang trí thiệp gập cá nhân.","Nhóm 1 chấm vân tay mực đỏ đầy hình trái tim; Nhóm 2 tô gấp bó hoa nổi; Nhóm 3 vẽ tô chân dung cô giáo; Nhóm 4 cắt tô bộ chữ \"CON\", \"CÔ\" & hoa nhỏ.","Nhóm 1 và Nhóm 2 cùng phụ trách gấp 20 bông hoa giấy; Nhóm 3 và Nhóm 4 tự sáng tác khẩu hiệu chúc mừng 20/11 mà không sử dụng mẫu chữ in sẵn."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): B70 chia đúng 4 nhóm chuyên biệt (trái tim vân tay đỏ, hoa nổi nét đứt, chân dung cô, bộ chữ CON–CÔ) để ghép 1 tờ A1. | Phân biệt bẫy sai: Novastars cung cấp sẵn bộ mẫu in vừa khít A1; không có việc tự viết thơ 8 câu hay gấp 4 tấm thiệp rời.","lessonIndex":9,"lessonCode":"B70"},{"id":"hp03-qq-b70-2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Hai nâng cấp sư phạm cốt lõi làm nên giá trị của bài B70 so với việc trường tổ chức làm thiệp 20/11 truyền thống nằm ở đâu?","options":["Chuyển từ mỗi bé làm 1 tấm thiệp lẻ sang dự án hợp tác 4 nhóm ghép 1 Báo tường A1 kiểu Tiểu học, và rèn cả nhóm thuyết trình nối tiếp trước máy quay.","Chuyển từ tô màu bằng sáp dầu sang cắt dán ảnh chụp thật của giáo viên kết hợp giao bài tập về nhà yêu cầu từng bé tự quay clip chúc cô cùng bố mẹ.","Rút gọn toàn bộ phần trò chuyện tình cảm để tập trung 25 phút vào cuộc thi nhóm nào cắt dán hoa giấy nhanh và sạch bàn nhất sẽ giành cúp luân lưu.","Mời ban giám hiệu trực tiếp xuống chấm điểm nghệ thuật cho từng nhóm ngay tại lớp để chọn ra duy nhất 1 bức tranh đẹp nhất tặng đại diện công đoàn."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): B70 nâng cấp cả hợp tác nhóm lớn (4 mảnh ghép tạo 1 tác phẩm A1) lẫn thuyết trình nhóm nối tiếp (mỗi bạn nói tiếp nối một đoạn). | Phân biệt bẫy sai: Làm thiệp lẻ từng cá nhân hay cử 1 lớp trưởng nói đại diện là giới hạn của cách làm cũ.","lessonIndex":9,"lessonCode":"B70"},{"id":"hp03-qq-b70-3","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Chủ trường lo ngại: \"Thiết kế một bức Báo tường khổ A1 hoành tráng với đủ chi tiết như bài B70 chắc giáo viên phải thức đêm tự vẽ khung chuẩn bị mệt lắm?\"","options":["Gợi ý giáo viên rút kích thước báo tường xuống giấy A4 nhỏ hơn và bỏ bớt phần hoa gấp nổi để kịp hoàn thiện trong thời lượng 25 phút trên lớp.","Đề xuất nhà trường thuê họa sĩ thiết kế hoặc nhờ phụ huynh có năng khiếu mỹ thuật đến vẽ sẵn khung bố cục lên giấy A1 vào chiều hôm trước tiết học.","Cho xem bộ học liệu Novastars đã thiết kế in sẵn vừa khít A1 (bộ chữ CON–CÔ, khung trái tim, hoa có sẵn nét đứt, chân dung cô) nên cô chuẩn bị rất nhàn.","Khuyên trường chuyển hoạt động làm báo tường sang kéo dài trong suốt 3 ngày hoạt động góc buổi chiều thay vì gói gọn trong một tiết chính khóa 30 phút."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): B70 ghi rõ toàn bộ bộ mẫu in vừa khít A1 (CON, CÔ, trái tim chấm vân tay, hoa nét đứt, chân dung cô) đã đóng gói sẵn trong kho học liệu. | Phân biệt bẫy sai: Không phải tự vẽ khung tay, không thu nhỏ xuống A4 và hoàn toàn hoàn thành gọn trong tiết chính khóa.","lessonIndex":9,"lessonCode":"B70"}]},{"id":"mod-04-lo-trinh-72-tiet","code":"HP04","title":"Lộ Trình 3 Độ Tuổi & Danh Sách Đủ 72 Tiết × 3 Khối Chính Khóa để Sale Tra cứu","status":"published","category":"Lộ trình & Danh mục 72 Tiết × 3 Khối","subtitle":"Tóm tắt điểm nhấn từng khối tuổi (Bé 3–4 tuổi, Nhỡ 4–5 tuổi, Lớn 5–6 tuổi) và danh mục 72 tiết cả năm (Học kì I & Học kì II)","questions":[{"id":"hp04-std-1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Trong cấu trúc 72 tiết/năm học cho mỗi khối (Bé, Nhỡ, Lớn) ở HP04, Học kì I và Học kì II được phân chia ranh giới tiết học như thế nào?","options":["Học kì I kéo dài 30 tiết đầu năm (Tiết 1 đến Tiết 30), còn Học kì II gồm 42 tiết còn lại (Tiết 31 đến Tiết 72) để bù thêm cho chuỗi Hành trang Tiểu học.","Mỗi năm học chia đều 2 học kì bằng nhau: Học kì I từ Tiết 1 đến Tiết 36 (36 tiết) và Học kì II từ Tiết 37 đến Tiết 72 (36 tiết) cho cả 3 khối.","Học kì I có 40 tiết và Học kì II có 32 tiết, trong đó 2 tuần cuối tháng 5 chỉ dành cho ôn tập chung không đánh số tiết bài học B71 và B72.","Học kì I chỉ áp dụng cho khối Bé và khối Nhỡ (36 tiết/kì), còn khối Lớn gộp cả 72 tiết dạy liền mạch không tách ranh giới học kì I và học kì II."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Tra cứu 72 tiết HP04: cả 3 khối đều chia đúng Tiết 1–36 là Học kì I (36 tiết) và Tiết 37–72 là Học kì II (36 tiết). | Phân biệt bẫy sai: Đừng nhầm ranh giới 36/36 thành 30/42 hay 40/32 dù khối Lớn có cụm 25 tiết Tiểu học ở nửa cuối HK II."},{"id":"hp04-std-2","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Khi tư vấn Điểm nhấn Hiệu trưởng cho Khối Mẫu giáo Bé (3–4 tuổi), dấu mốc chuyển biến thực tế nào giúp Chủ trường thấy trẻ mới 3 tuổi đã hết rụt rè?","options":["Biết sử dụng thành thạo mẹo giơ 2 bàn tay phân biệt chữ b–d (B57), dùng thước 30cm kiểm tra mắt khi ngồi viết (B56) và làm Báo tường khổ lớn A1 (B70).","Biết tự lập thời gian biểu bằng đồng hồ kim (B17), tự buộc dây giày đi học (B38) và tự sắp xếp 3 ngăn tủ quần áo theo mức độ ưu tiên mặc hằng ngày (B24).","Biết đặt mục tiêu gần – mục tiêu xa theo bảng mục tiêu (B04–B06), làm thí nghiệm khoa học (B03) và sáng tạo mô hình robot giới thiệu trước lớp (B22–B24).","Biết chủ động chào người thật tươi tắn đủ mắt–tay–miệng (B06), làm Thẻ an toàn chống đi lạc (B27), phân loại 2 thùng rác (B69) và quay video 4 quy tắc xe (B45)."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Điểm nhấn tư vấn Hiệu trưởng khối Bé (3–4t): B06 chào người thật, B26–B27 chống đi lạc & Thẻ an toàn, B45 thuyết trình 4 quy tắc đi xe, B69 phân loại rác 2 thùng. | Phân biệt bẫy sai: Các dấu mốc đồng hồ/dây giày/tủ quần áo/b–d/30cm thuộc Khối Lớn (5–6t), còn mục tiêu/robot/thí nghiệm thuộc Khối Nhỡ (4–5t)."},{"id":"hp04-std-3","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Lên Khối Mẫu giáo Nhỡ (4–5 tuổi), ngoài kỹ năng giao tiếp và cảm xúc, chuỗi bài \"Khám phá khoa học & Sáng tạo công nghệ\" nổi bật nằm ở những tiết nào trong HK I?","options":["Nằm hoàn toàn ở nửa cuối Học kì II từ B55 đến B65 với các chuyên đề về lắp ghép mô hình máy tính và chế tạo mạch điện tử cơ bản cho trẻ 4 tuổi.","Tập trung ngay trong Học kì I với B03 (Quan sát thí nghiệm diệu kì), B17 (Làm thí nghiệm), B22 & B24 (Sáng tạo & giới thiệu robot) và B23 (Điều thú vị của vũ trụ).","Nằm tại Học kì I của Khối Mẫu giáo Bé (B22 đến B25) kết hợp cùng bài tự chế tạo mô hình cây gia đình và đồ trang trí cây đào đón Tết cổ truyền.","Chỉ xuất hiện duy nhất 1 tiết ôn tập tổng hợp ở cuối năm (B71) dành riêng cho những lớp Nhỡ đăng ký tham gia câu lạc bộ ngoại khóa buổi chiều."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Lộ trình Khối Nhỡ HK I có đủ B03 (Thí nghiệm diệu kì), B17 (Làm thí nghiệm), B22 & B24 (Sáng tạo robot), B23 (Khám phá vũ trụ). | Phân biệt bẫy sai: Cần tra đúng Khối Nhỡ Học kì I (không nhầm sang HK II hay khối Bé làm Cây gia đình)."},{"id":"hp04-std-4","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"So sánh Điểm nhấn tư vấn Hiệu trưởng giữa Khối Bé (3–4 tuổi) và Khối Nhỡ (4–5 tuổi), bước nhảy vọt về năng lực tự chủ của trẻ lên 4 tuổi là gì?","options":["Trẻ không chỉ làm theo lời cô mà bắt đầu tự đặt mục tiêu gần–xa (B04–B06, B25–B26), kiểm tra bài chéo giúp bạn (B09), dùng huy hiệu báo cảm xúc (B13) và sơ cứu bỏng (B39).","Trẻ bắt đầu giảm bớt các hoạt động thực hành tay chân và vận động nhóm để chuyển dần sang làm bài kiểm tra nhận thức cá nhân trên giấy chuẩn bị vào lớp 1.","Trẻ chuyển trọng tâm từ học trong lớp sang đi thực tế dã ngoại ngoài trường 2 tuần/lần thay vì sử dụng bộ trò chơi trên phần mềm Novastars.","Trẻ dừng học các chủ đề về cảm xúc và gia đình vì đã hoàn thành xong ở năm 3 tuổi, dành 100% thời lượng năm 4 tuổi cho an toàn điện và phòng cháy."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Điểm nhấn Hiệu trưởng khối Nhỡ: trẻ chuyển từ làm theo cô sang tự đặt & theo dõi mục tiêu, kiểm tra chéo cho bạn, dùng huy hiệu cảm xúc và sơ cứu bỏng. | Phân biệt bẫy sai: Khối Nhỡ vẫn học phần mềm mạnh mẽ và tiếp tục đào sâu cảm xúc (B12–B13, B18, B56–B65) chứ không bỏ."},{"id":"hp04-std-5","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Nếu Hiệu trưởng quan tâm tới mảng \"An toàn phòng tránh tai nạn nâng cao\" cho trẻ 4 tuổi (Khối Nhỡ), Sale tra cứu được chuỗi tiết trọng tâm nào trong 72 tiết?","options":["Gồm chuỗi B32 đến B39 của Khối Mẫu giáo Bé vì tất cả các kỹ năng về điện giật, đuối nước và thanh tra an toàn đã dạy dứt điểm ngay từ năm 3 tuổi.","Chỉ có đúng 2 tiết là B39 (Phòng tránh bỏng nóng) và B40 (Thuyết trình an toàn) nằm rải rác cuối học kỳ II, ngoài ra không có nội dung điện giật hay đuối nước.","Gồm B32 (Phòng điện giật), B33 (Khu vực an toàn ngoài trời), B34 (Phòng đuối nước), B37 (Vật sắc nhọn), B39 (Phòng & sơ cứu bỏng), B41 (Thanh tra an toàn) & B58–59 (Đi lạc).","Gồm B25–B27 (Chống bắt cóc) và B47–B55 (Nội quy an toàn trường Tiểu học) trong lộ trình Học kì I dành cho các lớp 4 tuổi đi tham quan dã ngoại."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Tra bảng 72 tiết Khối Nhỡ: B31 (nguy hiểm gia đình), B32 (điện giật), B33 (ngoài trời), B34 (đuối nước), B35 (biệt đội), B37 (sắc nhọn), B39 (bỏng), B41 (Thanh tra an toàn), B58–B59 (đi lạc). | Phân biệt bẫy sai: Bắt cóc B25–B27 và Tiểu học B47–B55 nằm ở Khối Lớn; còn hỏa hoạn B39–B40 nằm ở Khối Bé."},{"id":"hp04-std-6","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Kỹ năng \"Xử lý khi đi lạc\" và \"Phòng tránh bị bắt cóc\" được phân bố theo mức độ tăng tiến qua 3 khối tuổi trong bảng 72 tiết như thế nào?","options":["Lớp Bé (B26–B27): cách không bị lạc & làm Thẻ an toàn; Lớp Nhỡ (B55, B58–59): nhận diện nguy cơ & xử lý đi lạc; Lớp Lớn: xử lý đi lạc ngay đầu năm (B02–03) & chống bắt cóc (B25–27).","Chỉ dạy dứt điểm một lần ở 3 tiết đầu năm học của khối Mẫu giáo Lớn (B01 đến B03), hai khối Bé và Nhỡ chưa học kỹ năng này để tránh gây hoang mang cho trẻ.","Gom đồng loạt vào đúng Tiết 26–27 của cả 3 khối với nội dung giống hệt nhau về việc nhận diện người lạ cho quà và làm Thẻ an toàn đeo cổ.","Đưa toàn bộ sang cuối Học kì II của cả 3 khối (Tiết 68–70) để phụ huynh nhắc con ôn lại trước kỳ nghỉ hè đi du lịch cùng gia đình."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Tra đối chiếu 3 khối trong HP04: Bé (B26 không bị lạc, B27 thẻ an toàn), Nhỡ (B55, B58–B59), Lớn (B02–B03 xử lý đi lạc, B25–B27 xử lý nguy cơ bắt cóc). | Phân biệt bẫy sai: Novastars thiết kế đồng tâm nâng bậc theo từng tuổi chứ không lặp y hệt ở cùng một số tiết hay dồn hết vào 1 khối."},{"id":"hp04-std-7","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","bloomLevel":"Hiểu & Phân biệt","question":"Cụm chuyên đề \"Hành trang vào Tiểu học\" của Khối Mẫu giáo Lớn (5–6 tuổi) chiếm trọn bao nhiêu tiết và trải dài từ bài nào đến bài nào?","options":["Chiếm 12 tiết xen kẽ rải rác mỗi tháng 2 tiết trong suốt cả năm học từ B05 đến B70 để tránh gây áp lực tâm lý chuyển cấp cho trẻ 5 tuổi.","Chiếm 10 tiết cuối cùng của năm học, bắt đầu từ B61 (Sắp xếp sách vở) đến B70 (Báo tường 20/11), còn từ B47 đến B60 vẫn dạy kỹ năng sinh hoạt gia đình.","Chiếm 36 tiết trọn vẹn của cả Học kì II (từ B37 đến B72) tập trung hoàn toàn vào rèn viết chữ, làm toán cộng trừ và nghi lễ chào cờ Tiểu học.","Chiếm trọn 25 tiết liên hoàn ở nửa cuối Học kì II, bắt đầu từ B47 (Tìm hiểu nội quy lớp học Tiểu học) cho đến B71 (Sẵn sàng trở thành học sinh Tiểu học)."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Hiểu & Phân biệt): Điểm nhấn Hiệu trưởng & bảng 72 tiết Khối Lớn: đúng 25 tiết cuối HK II từ B47 đến B71 chuyên biệt chuẩn bị Hành trang vào Tiểu học. | Phân biệt bẫy sai: B37–B46 HK II lớp Lớn vẫn dạy trách nhiệm cá nhân/gia đình/buộc dây giày (B38) trước khi bước vào cụm Tiểu học từ B47."},{"id":"hp04-std-8","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Khi phụ huynh lớp 5 tuổi lo lắng con sắp vào lớp 1 chưa biết tự quản lý thời gian và đồ dùng cá nhân, Sale tra cứu những bài học cụ thể nào của Khối Lớn để chứng minh?","options":["Dẫn chứng B13 (Gấp khăn mặt), B24 (Làm cây gia đình), B55 (Sắp xếp giày dép) thuộc danh mục nửa cuối học kỳ II của Khối Mẫu giáo Lớn.","Dẫn chứng B17 (Xem giờ đồng hồ), B18–19 (Đặt & thực hiện mục tiêu gần), B22–24 (Tự xếp tủ quần áo), B38–39 (Tự buộc dây giày), và B61 (Sắp xếp sách vở gọn gàng).","Dẫn chứng B08–B09 (Ăn uống đủ 4 nhóm chất), B11 (Chuẩn bị đồ đi du lịch) và B35 (Tham gia biệt đội an toàn) trong giáo trình chính của Khối Lớn.","Dẫn chứng B47–B50 và B71 vì toàn bộ kỹ năng xem giờ, buộc dây giày, xếp tủ áo đều được gộp chung vào 4 tiết đầu của cụm Hành trang Tiểu học."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Tra 72 tiết Khối Lớn: B17 (xem giờ), B18–B19 (mục tiêu), B22–B24 (tủ quần áo), B38–B39 (buộc dây giày & chuẩn bị giày), B61 (sắp xếp sách vở). | Phân biệt bẫy sai: Gấp khăn/Cây gia đình là bài của Khối Bé; B08–B11 du lịch & Biệt đội B35 là bài của Khối Nhỡ."},{"id":"hp04-std-9","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Hiệu trưởng hỏi: \"Chị tính chỉ mua thử 1 khối Mẫu giáo Lớn (5 tuổi) để dạy chuẩn bị vào lớp 1 thôi, còn khối Bé và khối Nhỡ để năm sau tính tiếp\" — Sale phân tích thế nào?","options":["Gợi ý Hiệu trưởng lấy giáo trình của khối Lớn dạy ghép chung cho cả khối Nhỡ 4 tuổi trong cùng một buổi nhằm tận dụng bản quyền mua cho một khối duy nhất.","Nhận định rằng nếu trẻ không học từ khối Bé 3 tuổi thì khi lên 5 tuổi sẽ hoàn toàn không thể tham gia được bất kỳ trò chơi nào trong cụm 25 tiết Tiểu học.","Đồng ý ngay phương án chỉ ký 1 khối và đề xuất cắt giảm 50% số tiết khối Lớn xuống còn 36 tiết để nhà trường giảm nhẹ chi phí thử nghiệm năm đầu.","Phân tích tính xoắn ốc đồng bộ 3 năm: kỹ năng phức tạp lớp 5t (tự xếp tủ B24, chống bắt cóc B25–27, tập trung Tiểu học) đều kế thừa nền tảng dạn dĩ (3t) và tự chủ mục tiêu (4t)."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Lộ trình 3 độ tuổi xây nền nối tiếp (3t hết rụt rè → 4t biết đặt mục tiêu & tự chủ → 5t bứt phá vào lớp 1), giúp trường có chuỗi tuyển sinh xuyên suốt 3 năm. | Phân biệt bẫy sai: Không nói quá rằng 5 tuổi sẽ không học nổi, cũng không khuyên dạy ghép giáo trình 5 tuổi cho trẻ 4 tuổi."},{"id":"hp04-std-10","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Trong buổi tư vấn trực tiếp, Hiệu trưởng hỏi bất ngờ: \"Ở khối Mẫu giáo Bé 3 tuổi có dạy trẻ cách bảo vệ bản thân khi xảy ra cháy nổ không và vào kì nào?\"","options":["Trả lời rằng hỏa hoạn nằm trong cụm bài Tiết 35–37 của Học kì I khối Bé ngay trước chuyên đề nhận biết ngày Tết cổ truyền.","Trả lời rằng nội dung phòng tránh hỏa hoạn chưa phù hợp với trẻ 3 tuổi nên chỉ được đưa vào Học kì I của khối Nhỡ (B31–B32) và khối Lớn (B35–B36).","Mở/tra nhanh HP04 trả lời chuẩn: Có ngay ở đầu Học kì II của khối Bé với 2 tiết nối tiếp là Tiết 39 (B39) và Tiết 40 (B40): Kĩ năng bảo vệ bản thân khi xảy ra hỏa hoạn.","Ghi nhận câu hỏi của Hiệu trưởng và hứa hẹn sau buổi họp sẽ liên hệ bộ phận soạn giáo án hỏi lại vì danh mục 72 tiết chỉ liệt kê tên chủ đề lớn chung chung."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Tra bảng 72 tiết khối Bé: Tiết 39 & Tiết 40 (Học kì II) chính xác là 'Kĩ năng bảo vệ bản thân khi xảy ra hỏa hoạn (tiết 1 & tiết 2)'. | Phân biệt bẫy sai: Tiết 35–37 khối Bé là bỏng nóng; Tiết 31–32 khối Nhỡ là nguy hiểm gia đình và điện giật. Sale cần tra cứu HP04 trả lời chuẩn ngay."},{"id":"hp04-std-11","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Trong bảng Điểm nhấn tư vấn Hiệu trưởng của HP04, chuỗi kỹ năng \"Điều hòa & làm chủ cảm xúc\" được nâng cấp khác biệt ra sao qua 3 độ tuổi?","options":["Bé (3t): nhận biết vui–buồn & điều hòa sợ hãi (B14–17, B65); Nhỡ (4t): làm Huy hiệu 4 mặt & đồng cảm (B13, B61); Lớn (5t): kiềm chế cơn tức giận & cổ vũ bạn (B10–11, B15–16).","Cả 3 khối đều sử dụng một bộ bài giảng cảm xúc chung dạy vào Tuần 14–16 hằng năm để tạo sự đồng nhất tuyệt đối giữa lớp 3 tuổi, 4 tuổi và 5 tuổi.","Nội dung cảm xúc chỉ tập trung dạy ở Học kì I của khối Bé (3 tuổi), lên khối Nhỡ và khối Lớn chuyển hoàn toàn sang dạy kỹ năng tính toán và chữ cái.","Chỉ tập trung nhận diện cảm xúc buồn của bản thân ở cả 3 khối tuổi nhằm hỗ trợ giáo viên dỗ trẻ mới đi học bớt khóc nhè vào đầu năm học."],"correctIndex":0,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Lộ trình cảm xúc HP04 tăng tiến rõ: Bé (nhận diện cơ bản & giảm sợ B65) → Nhỡ (Huy hiệu 4 mặt B13 & đồng cảm B61) → Lớn (hạ nhiệt tức giận B10–11 & cổ vũ bạn B15–16). | Phân biệt bẫy sai: Không dạy một bài giống nhau cho 3 tuổi và cũng không ngưng dạy cảm xúc ở khối Nhỡ hay Lớn."},{"id":"hp04-std-12","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","bloomLevel":"Vận dụng Dẫn chứng","question":"Khi Hiệu trưởng khối Lớn hỏi: \"Các tiết cuối của cụm Hành trang vào Tiểu học (B58–B70) có những trải nghiệm thực tế nào giúp con hết bỡ ngỡ trước khi rời mầm non?\"","options":["Dành trọn 13 tiết từ B58 đến B70 cho trẻ ngồi xem video giới thiệu cơ sở vật chất của các trường Tiểu học công lập quanh địa bàn quận.","Chỉ có duy nhất các tiết kiểm tra kiến thức viết chữ cái tiếng Việt và phép cộng trong phạm vi 10 để xếp loại năng lực bàn giao sang trường Tiểu học.","Có B58 (Trải nghiệm làm giáo viên Tiểu học), B60 (Đôi tay khéo léo), B61 (Xếp sách vở), B64–67 (Kết bạn mới & hòa đồng), B68–70 (Tôn trọng thầy cô & Báo tường A1).","Tổ chức cho trẻ học thuộc lòng toàn bộ nội quy giao tiếp phòng y tế và cách tự đi xe buýt công cộng một mình từ nhà đến trường cấp 1."],"correctIndex":2,"explanation":"Căn cứ chuẩn (Vận dụng Dẫn chứng): Bảng 72 tiết Khối Lớn (B58–B70): B58 làm giáo viên Tiểu học, B61 xếp sách vở, B64–67 kết bạn mới, B68–70 tôn trọng yêu thương thầy cô (Báo tường A1). | Phân biệt bẫy sai: Novastars chuẩn bị tâm thế – tự phục vụ – kết bạn – tình thầy trò, không biến cuối năm thành lớp luyện thi toán/tiếng Việt cấp tốc."},{"id":"hp04-std-13","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Chủ trường hỏi: \"Chương trình khung Bộ GD&ĐT cũng có rèn nếp lớp, xếp đồ dùng, chào hỏi, vậy tổng thể 72 tiết/khối của Novastars nâng tầm gì hơn cho từng độ tuổi?\"","options":["Novastars lược bỏ hoàn toàn các chủ đề quen thuộc của Bộ để dạy 72 tiết kỹ năng sinh tồn đặc biệt ngoài thiên nhiên như dựng lều, nhóm lửa và đi rừng.","Khối Bé nâng từ giữ vệ sinh/nghe cô sang chào người thật & phân 2 loại rác; Nhỡ từ đếm đến 5 sang đặt mục tiêu, thí nghiệm & sơ cứu; Lớn từ tự phục vụ sang quản lý giờ, b–d & Tiểu học.","Novastars giữ nguyên 100% nội dung mục tiêu của Bộ nhưng tăng thời gian mỗi tiết từ 20 phút lên 45 phút để trẻ có thời gian tô màu tranh đẹp hơn.","Sự khác biệt chỉ nằm ở khâu đặt lại tên gọi bài học cho hiện đại hơn, còn các bước tổ chức đóng vai và trò chơi tại lớp vẫn tuân theo giáo án Bộ."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): Tổng hợp 3 tấm thẻ 'Điểm nhấn Hiệu trưởng' & đối chiếu 'Nội dung Bộ vs Novastars' ở HP04 cho thấy sự nâng tầm cụ thể tại từng khối. | Phân biệt bẫy sai: Không bỏ chủ đề gần gũi, không dạy kỹ năng đi rừng xa rời thực tế và không chỉ đổi tên gọi bề mặt."},{"id":"hp04-std-14","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","bloomLevel":"Phân tích Sư phạm","question":"Nhìn vào danh sách 72 tiết của Khối Nhỡ (Học kì I & II), những kỹ năng \"tư duy logic và quan sát suy luận\" nào được đan xen khéo léo bên cạnh kỹ năng sống?","options":["Chủ yếu thực hiện qua bài tập nối hình giống nhau trên vở in phát cho trẻ làm cá nhân 15 phút đầu mỗi tiết học buổi sáng.","Gồm 10 tiết luyện giải toán tư duy đếm số đến 100 và ghép hình học không gian nâng cao dành riêng cho học kỳ II của khối Mẫu giáo Nhỡ.","Tư duy logic và quan sát chỉ xuất hiện trong cụm hình học B12–B14 và kiểu mẫu B28–B30 của Khối Lớn, không có trong chương trình Khối Nhỡ.","Gồm B36 (Tư duy phân loại, sắp xếp), B66 (Quan sát & sắp xếp theo trình tự), B67 (Quan sát & suy luận), kết hợp B03 & B17 (Quan sát & làm thí nghiệm)."],"correctIndex":3,"explanation":"Căn cứ chuẩn (Phân tích Sư phạm): Bảng 72 tiết Khối Nhỡ có B03, B17 (thí nghiệm), B36 (tư duy phân loại sắp xếp), B66 (xếp trình tự), B67 (quan sát suy luận), B68 (thực hành quan sát). | Phân biệt bẫy sai: Cả Nhỡ và Lớn đều cài cắm tư duy quan sát–phân loại–suy luận thông qua trải nghiệm trực quan, không phải toán đếm đến 100 hay vở nối hình."},{"id":"hp04-std-15","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","bloomLevel":"Vận dụng Tình huống","question":"Khi phụ huynh hay Hiệu trưởng hỏi: \"Làm sao một giáo viên hay Sale mới có thể tra cứu nhanh xem bài X nằm ở khối nào, học kì nào trong tổng số 216 tiết?\"","options":["Phải mở lần lượt từng file Word giáo án của 216 tiết trên máy tính cá nhân và dùng lệnh tìm kiếm thủ công trên từng văn bản riêng lẻ.","Mở tab đối chiếu 3 khối hoặc từng khối riêng trong HP04, dùng ô tìm kiếm theo từ khóa/tên bài và bộ lọc Học kì I (36) / Học kì II (36) để xem ngay số tiết và nội dung chi tiết.","Liên hệ trực tiếp với bộ phận Kỹ thuật Đào tạo qua Zalo để nhờ tra giúp vì hệ thống chỉ hiển thị tóm tắt 10 bài mẫu ở HP03 chứ không lưu đủ 72 tiết.","Tra theo thứ tự bảng chữ cái tên chủ đề ở trang bìa mục lục PDF rồi đối chiếu số trang tương ứng với tuần học trong lịch năm học."],"correctIndex":1,"explanation":"Căn cứ chuẩn (Vận dụng Tình huống): HP04 tích hợp sẵn đủ 72 tiết × 3 khối (216 bài) kèm ô tìm kiếm từ khóa và bộ lọc Cả năm / Học kì I / Học kì II ngay trên giao diện. | Phân biệt bẫy sai: Không cần mở 216 file Word hay hỏi thủ công bộ phận Đào tạo khi đã có công cụ tra cứu trực tiếp tại HP04."}],"updatedAt":"2026-11-26T08:46:39.402Z","authorName":"Phạm Mỹ Linh","sourceFile":{"url":"data/files/So_sanh_Novastars_va_Chuong_trinh_Bo_GDDT_Chinh_khoa.xlsx","name":"So_sanh_Novastars_va_Chuong_trinh_Bo_GDDT_Chinh_khoa.xlsx","type":"xlsx","sheetName":"4_Doi_chieu_3_Do_tuoi_72_Tiet"},"contentHtml":"","passThreshold":80,"summaryPoints":["Mẫu giáo Bé (3–4 tuổi, 2 tiết/tuần): Giúp trẻ mới 3 tuổi hết rụt rè — gặp người thật trong trường biết chủ động chào hỏi tươi tắn (B06), làm Thẻ an toàn chống đi lạc, phân loại rác vào 2 thùng (B69) và bước đầu đứng trước máy quay thuyết trình 4 quy tắc đi xe an toàn (B45).","Mẫu giáo Nhỡ (4–5 tuổi, 2 tiết/tuần): Trẻ không chỉ làm theo lời cô mà bắt đầu biết đặt mục tiêu gần – xa (B04–B06), ăn uống đủ 4 nhóm chất & kiểm tra bài chéo giúp bạn (B09), dùng Huy hiệu cảm xúc 4 mặt (B13), làm thí nghiệm khoa học/robot/vũ trụ và biết sơ cứu ban đầu khi bị bỏng (B39).","Mẫu giáo Lớn (5–6 tuổi, 2 tiết/tuần): Giải quyết trọn vẹn nỗi lo lớn nhất của phụ huynh có con sắp vào lớp 1 — kỹ năng bình tĩnh khi đi lạc & phòng bắt cóc, xem giờ & tự lập thời gian biểu, 3 nguyên tắc xếp tủ quần áo (B24), và dành trọn 25 tiết cuối Học kì II (B47–B71) chuẩn bị Hành trang vào Tiểu học."],"structuredData":{"ageSummaries":[{"stt":"1","do_tuoi":"Mẫu giáo bé\n3–4 tuổi\n2 tiết/tuần","noi_dung_bo":"• Làm quen nếp lớp, nói tên và tuổi.\n• Nhận biết mặt vui – buồn – sợ.\n• Chào hỏi và cất đồ chơi khi cô nhắc.\n• Giữ vệ sinh, bỏ rác vào thùng.","diem_nhan_sale":"Trẻ mới 3 tuổi đã hết rụt rè: gặp người thật trong trường biết chủ động chào hỏi tươi tắn, biết phân loại rác vào 2 thùng và bước đầu đứng trước máy quay nói trọn câu giới thiệu.","noi_dung_novastars":"• Nhớ 4 quy tắc lớp học, làm quen bạn, đi quanh trường thực hành chào hỏi đủ mắt – tay – miệng ở bài B06.\n• Tự dọn đồ chơi, gấp khăn.\n• Yêu thương gia đình qua bài Cây gia đình, biết cách không bị đi lạc và làm Thẻ an toàn.\n• Phòng tránh vật sắc nhọn, bỏng, cháy nổ; đứng thuyết trình 4 quy tắc đi xe an toàn ở bài B45.\n• Chọn quần áo theo thời tiết, đeo khẩu trang, phân loại rác dễ phân hủy và khó phân hủy ở bài B69."},{"stt":"2","do_tuoi":"Mẫu giáo nhỡ\n4–5 tuổi\n2 tiết/tuần","noi_dung_bo":"• Phân loại đồ vật đơn giản, đếm đến 5.\n• Nói câu trọn vẹn, biết chia sẻ đồ chơi.\n• Phân biệt hành vi đúng – sai, tiết kiệm nước.","diem_nhan_sale":"Lên 4 tuổi, trẻ không chỉ làm theo lời cô mà bắt đầu biết đặt mục tiêu, biết kiểm tra bài giúp bạn, biết dùng huy hiệu báo cảm xúc và biết cả cách sơ cứu ban đầu khi bị bỏng.","noi_dung_novastars":"• Tự tin thuyết trình bản thân, làm thí nghiệm khám phá khoa học, sáng tạo mô hình robot và tìm hiểu vũ trụ.\n• Biết đặt mục tiêu gần, mục tiêu xa và theo dõi bảng mục tiêu.\n• Ăn uống đủ 4 nhóm chất và biết kiểm tra bài chéo cùng bạn ở bài B09.\n• Làm Huy hiệu cảm xúc 4 mặt theo màu sắc riêng ở bài B13, biết đồng cảm khi bạn buồn và làm dịu cơn sợ hãi.\n• An toàn nâng cao: phòng điện giật, đuối nước, an toàn sân chơi, phòng và sơ cứu khi bị bỏng nóng ở bài B39, tập làm Thanh tra an toàn."},{"stt":"3","do_tuoi":"Mẫu giáo lớn\n5–6 tuổi\n2 tiết/tuần","noi_dung_bo":"• Tự phục vụ cá nhân, chơi theo nhóm.\n• Kiềm chế cảm xúc, đếm đến 10, làm quen chữ cái.\n• Chuẩn bị tâm thế vào lớp 1.","diem_nhan_sale":"Năm cuối mầm non 5 tuổi, chương trình giải quyết trọn vẹn nỗi lo lớn nhất của phụ huynh có con sắp vào lớp 1: con tự giác quản lý thời gian, tự soạn đồ dùng, ngồi học đúng chuẩn và cực kỳ háo hức bước vào trường Tiểu học.","noi_dung_novastars":"• Bình tĩnh xử lý khi đi lạc và kỹ năng phòng tránh bị bắt cóc.\n• Nhận diện và hạ nhiệt cơn tức giận, biết cổ vũ động viên bạn.\n• Biết xem giờ đồng hồ, tự lập thời gian biểu trong ngày, nhớ 3 nguyên tắc sắp xếp tủ quần áo ở bài B24, tự buộc dây giày.\n• Dành trọn nửa cuối học kì II từ bài B47 đến B71 chuẩn bị Hành trang vào Tiểu học: nội quy, nghi lễ chào cờ, trò chơi rèn tập trung và đo khoảng cách mắt 30cm khi ngồi viết ở bài B56, mẹo dùng 2 bàn tay phân biệt chữ b và d ở bài B57, tự soạn sách vở và làm dự án Báo tường A1 tri ân thầy cô ở bài B70."}],"curriculum72":[{"tiet":"1","hoc_ki":"Học kì I","mg_be":"B01 - Bé tìm hiểu về nội quy lớp học","mg_be_nd":"1. Trẻ nhắc lại bốn quy tắc lớp học: lắng nghe, xếp hàng, giơ tay khi có ý kiến, nói to và rõ ràng.\n2. Trẻ thực hành nhìn và nghe cô nói; xếp hàng không chen lấn, xô đẩy; giơ tay cao và trả lời to, rõ ràng.","mg_nho":"B01 - Bé thuyết trình giới thiệu bản thân","mg_nho_nd":"1. Trẻ biết cách giới thiệu tên, tuổi và cuốn sách yêu thích của mình.\n2. Trẻ thuyết trình to, rõ ràng, kết hợp đứng thẳng, cười tươi, nhìn người nghe và dùng tay chào, giới thiệu bản thân, thể hiện số tuổi.","mg_lon":"B01 - Bé tự tin làm quen kết bạn","mg_lon_nd":"1. Trẻ biết các câu nói làm quen bạn mới và cách thể hiện nét mặt, cử chỉ thân thiện.\n2. Trẻ thực hành các bước làm quen, kết bạn với những người bạn mới.","ghi_chu":""},{"tiet":"2","hoc_ki":"Học kì I","mg_be":"B02 - Bé cam kết thực hiện các quy tắc lớp học","mg_be_nd":"1. Trẻ nhắc lại bốn quy tắc lớp học: lắng nghe, xếp hàng chờ tới lượt, nói to và rõ ràng, giơ tay khi có ý kiến.\n2. Trẻ nói to, rõ ràng lời cam kết thực hiện các quy tắc trong lớp học.","mg_nho":"B02 - Bé yêu thích khám phá thế giới","mg_nho_nd":"1. Trẻ nhắc lại tên môn học, các bạn trong chương trình và biết khoa học vũ trụ nghiên cứu các hành tinh, ngôi sao.\n2. Trẻ nhận biết, thể hiện cảm xúc ngạc nhiên và sự hào hứng khi quan sát vũ trụ.","mg_lon":"B02 - Bé bình tĩnh xử lý tình huống khi đi lạc","mg_lon_nd":"1. Trẻ nhận biết những nguy cơ khi đi lạc: đói, bị bắt nạt, bị bắt cóc hoặc gặp nguy hiểm đến tính mạng.\n2. Trẻ học cách dừng lại, giữ bình tĩnh, gọi người thân và nhờ người lớn đáng tin giúp đỡ khi đi lạc.","ghi_chu":""},{"tiet":"3","hoc_ki":"Học kì I","mg_be":"B03 - Bé vui học kĩ năng sống","mg_be_nd":"1. Trẻ gọi tên bốn quy tắc lớp học: lắng nghe, xếp hàng, giơ tay khi có ý kiến, nói to và rõ ràng.\n2. Trẻ luyện tập thực hiện bốn quy tắc lớp học.","mg_nho":"B03 - Bé quan sát thí nghiệm diệu kì","mg_nho_nd":"1. Trẻ nhận diện kính thiên văn, nhắc lại nguyên liệu và thứ tự thực hiện thí nghiệm galaxy sữa.\n2. Trẻ thực hành cho sữa vào đĩa, nhỏ màu, chấm tăm bông vào nước rửa bát rồi chấm vào màu theo hướng dẫn.","mg_lon":"B03 - Bé luyện tập xử lý tình huống khi đi lạc","mg_lon_nd":"1. Trẻ ôn tập cách xử lý tình huống khi đi lạc và nhận diện người lớn đáng tin để nhờ giúp đỡ.\n2. Trẻ luyện tập hít thở sâu để bình tĩnh, gọi to báo hiệu cho người thân và nhờ sự giúp đỡ.","ghi_chu":""},{"tiet":"4","hoc_ki":"Học kì I","mg_be":"B04 - Bé học cách làm quen bạn mới","mg_be_nd":"1. Trẻ nhắc lại câu chào hỏi, giới thiệu tên khi làm quen với bạn mới.\n2. Trẻ thể hiện sự thân thiện qua nụ cười, vẫy tay chào và đặt tay lên ngực khi giới thiệu tên.","mg_nho":"B04 - Bé tìm hiểu về mục tiêu","mg_nho_nd":"1. Trẻ kể tên công việc hằng ngày và ghi nhớ từ “mục tiêu”.\n2. Trẻ thực hành đặt mục tiêu cho việc đánh răng, ăn cơm, đi học đúng giờ.","mg_lon":"B04 - Bé thử tài so sánh số lượng","mg_lon_nd":"1. Trẻ biết so sánh số lượng bằng cách đếm ít nhất hai nhóm đồ vật.\n2. Trẻ nhận diện các chữ số trong phạm vi 10 và thực hành so sánh số lượng.","ghi_chu":""},{"tiet":"5","hoc_ki":"Học kì I","mg_be":"B05 - Lời chào dễ mến","mg_be_nd":"1. Trẻ biết ý nghĩa của việc nói lời chào với mọi người.\n2. Trẻ thực hành nói lời chào dễ mến với người lớn và bạn bè.","mg_nho":"B05 - Bé luyện tập đặt mục tiêu và thực hiện mục tiêu","mg_nho_nd":"1. Trẻ nhắc lại những yêu cầu để trở thành phi hành gia: khỏe mạnh, nhanh nhẹn, khéo léo.\n2. Trẻ luyện tập đặt mục tiêu trước khi thực hiện công việc.","mg_lon":"B05 - Bé học kĩ năng sắp xếp bàn ăn khoa học","mg_lon_nd":"1. Trẻ gọi tên các đồ dùng cần thiết để sắp xếp bàn ăn.\n2. Trẻ kiểm tra số lượng bát, đũa, ghế và sắp xếp ghế phù hợp với số người ăn.","ghi_chu":""},{"tiet":"6","hoc_ki":"Học kì I","mg_be":"B06 - Bé thực hành lời chào với những người xung quanh","mg_be_nd":"1. Trẻ ghi nhớ lời chào phù hợp với người lớn và bạn bè.\n2. Trẻ thực hành nhìn người được chào, mỉm cười, vẫy tay chào bạn hoặc khoanh tay chào người lớn.","mg_nho":"B06 - Bé theo dõi việc thực hiện mục tiêu","mg_nho_nd":"1. Trẻ nhắc lại cụm từ “mục tiêu gần”.\n2. Trẻ đặt mục tiêu cho các việc hằng ngày như đánh răng, ăn cơm, đi học đúng giờ, uống nước, cất đồ chơi, uống sữa, gấp quần áo.","mg_lon":"B06 - Bé học cách dọn dẹp bàn ăn","mg_lon_nd":"1. Trẻ nêu được các bước dọn dẹp bàn ăn.\n2. Trẻ thực hành dọn dẹp bàn ăn theo các bước đã học.","ghi_chu":""},{"tiet":"7","hoc_ki":"Học kì I","mg_be":"B07 - Bé tự tin giới thiệu bản thân","mg_be_nd":"1. Trẻ ghi nhớ lời chào, giới thiệu tên, tuổi và lời cảm ơn người nghe.\n2. Trẻ giới thiệu bản thân to, rõ ràng, kết hợp đứng thẳng, cười tươi, vẫy tay, đặt tay lên ngực và giơ ngón tay chỉ số tuổi.","mg_nho":"B07 - Bé học cách quan sát và tìm điểm khác biệt","mg_nho_nd":"1. Trẻ biết từ ngữ so sánh dáng cao, thấp; tóc dài, ngắn; màu tóc và quần áo.\n2. Trẻ quan sát, mô tả ít nhất một điểm khác biệt giữa mình với bạn cùng cặp bằng giọng nói to, rõ ràng.","mg_lon":"B07 - Bé luyện tập sắp xếp và dọn dẹp bàn ăn","mg_lon_nd":"1. Trẻ biết cách chuẩn bị bàn trước bữa ăn và dọn bàn sau bữa ăn.\n2. Trẻ thực hành dọn đồ, lau bàn; gom thức ăn thừa, bỏ rác đúng nơi, chuyển bát đĩa đến bồn rửa và lau sạch bàn.\n3. Trẻ phối hợp với các bạn khi sắp xếp và dọn dẹp bàn ăn.","ghi_chu":""},{"tiet":"8","hoc_ki":"Học kì I","mg_be":"B08 - Bé là công dân nhí gương mẫu","mg_be_nd":"1. Trẻ gọi tên đội hình hai hàng dọc và nêu được ít nhất một trách nhiệm của công dân nhí gương mẫu.\n2. Trẻ thực hành bốn quy tắc lớp học.","mg_nho":"B08 - Bé học cách ăn uống đủ chất dinh dưỡng","mg_nho_nd":"1. Trẻ kể tên bốn nhóm thức ăn: thịt, rau, trái cây, ngũ cốc và biết lợi ích của ăn đủ chất.\n2. Trẻ phân loại thức ăn vào bốn nhóm và cam kết ăn uống đủ chất dinh dưỡng.","mg_lon":"B08 - Bé ứng xử lịch sự khi đến chơi nhà bạn","mg_lon_nd":"1. Trẻ biết cách ứng xử lịch sự khi đến chơi nhà bạn: bấm chuông hoặc gõ cửa, chào hỏi, xếp giày dép gọn gàng, chào và cảm ơn khi ra về.\n2. Trẻ thực hành lời nói, hành động lịch sự và đặt giày dép đúng chiều, đúng vị trí.","ghi_chu":""},{"tiet":"9","hoc_ki":"Học kì I","mg_be":"B09 - Kĩ năng làm việc nhóm","mg_be_nd":"1. Trẻ nhắc lại tên đội hình vòng tròn.\n2. Trẻ thực hành xếp đội hình hai hàng dọc trong thời gian quy định và xếp đội hình vòng tròn.","mg_nho":"B09 - Bé ôn tập cách ăn uống đủ chất dinh dưỡng","mg_nho_nd":"1. Trẻ ôn tập tên bốn nhóm thức ăn: thịt, rau, hoa quả, ngũ cốc.\n2. Trẻ thực hành phân loại thức ăn vào đúng nhóm.","mg_lon":"B09 - Bé thực hành ứng xử lịch sự khi đến chơi nhà bạn","mg_lon_nd":"1. Trẻ nhắc lại các cách ứng xử lịch sự khi đến chơi nhà bạn.\n2. Trẻ thực hành chào hỏi, xếp giày dép, nói lời cảm ơn và xử lý tình huống giao tiếp khi đến chơi nhà bạn.","ghi_chu":""},{"tiet":"10","hoc_ki":"Học kì I","mg_be":"B10 - Bé giới thiệu về sở thích của mình","mg_be_nd":"1. Trẻ gọi tên đồ chơi, màu sắc và nói được sở thích của bản thân.\n2. Trẻ thực hành giới thiệu đồ chơi yêu thích và màu sắc yêu thích bằng câu nói phù hợp.","mg_nho":"B10 - Bé rèn luyện kĩ năng thuyết trình","mg_nho_nd":"1. Trẻ nhắc lại các việc cần làm để trở thành phi hành gia: tập thể dục, rèn quan sát, ăn đủ chất.\n2. Trẻ tự tin giơ tay thuyết trình, nói to, rõ ràng và dùng tay vẫy chào, đặt lên ngực khi giới thiệu bản thân.","mg_lon":"B10 - Bé học cách nhận diện cảm xúc tức giận của bản thân","mg_lon_nd":"1. Trẻ nhận diện và gọi tên cảm xúc tức giận của bản thân.\n2. Trẻ nhận biết những biểu hiện khi tức giận như muốn hét, giậm chân, khóc hoặc nắm chặt tay.","ghi_chu":""},{"tiet":"11","hoc_ki":"Học kì I","mg_be":"B11 - Bé tìm hiểu trách nhiệm của bản thân","mg_be_nd":"1. Trẻ kể tên các trách nhiệm cá nhân như dọn đồ chơi, tự xúc ăn, rửa tay, đánh răng.\n2. Trẻ nhận diện trách nhiệm theo yêu cầu và nói to, rõ ràng tên các việc thuộc trách nhiệm của mình.","mg_nho":"B11 - Bé học cách chuẩn bị đồ dùng khi đi du lịch","mg_nho_nd":"1. Trẻ nhận biết bốn nhóm đồ dùng khi du lịch: đồ cá nhân, đồ bảo vệ, đồ ăn nước uống, đồ chơi.\n2. Trẻ ghi nhớ tiêu chí ngắn, nhỏ, gọn và lựa chọn đồ dùng cần thiết cho chuyến đi.","mg_lon":"B11 - Bé làm sản phẩm thể hiện cảm xúc của mình","mg_lon_nd":"1. Trẻ nhận biết các cảm xúc vui, buồn, tức giận, sợ hãi và ngạc nhiên.\n2. Trẻ rèn luyện kĩ năng tô màu, vận động tinh để làm sản phẩm thể hiện cảm xúc.","ghi_chu":""},{"tiet":"12","hoc_ki":"Học kì I","mg_be":"B12 - Bé học cách dọn đồ chơi khoa học","mg_be_nd":"1. Trẻ nhắc lại ba cách cất gọn đồ chơi theo kích cỡ, loại và màu sắc.\n2. Trẻ tập sắp xếp đồ chơi ngăn nắp, bước đầu tự giác dọn đồ chơi sau khi chơi.","mg_nho":"B12 - Bé học cách nhận biết cảm xúc sợ hãi của bản thân","mg_nho_nd":"1. Trẻ gọi tên cảm xúc sợ hãi và các biểu hiện bên trong: muốn che mắt, muốn co người, muốn trốn.\n2. Trẻ nhận diện ba biểu hiện của cảm xúc sợ hãi qua hình ảnh gợi ý.","mg_lon":"B12 - Bé học về ứng dụng của hình học trong cuộc sống (tiết 1)","mg_lon_nd":"1. Trẻ gọi tên các hình tròn, vuông, chữ nhật, tam giác và nhận biết ứng dụng của hình tròn làm bánh xe.\n2. Trẻ quan sát, mô tả để nhận diện các hình cơ bản và thuyết trình về giải pháp bánh xe hình tròn.","ghi_chu":""},{"tiet":"13","hoc_ki":"Học kì I","mg_be":"B13 - Bé học cách gấp khăn thật gọn gàng","mg_be_nd":"1. Trẻ nhắc lại trách nhiệm gấp khăn lau bàn của mình.\n2. Trẻ rèn luyện vận động tinh qua việc gấp khăn và bước đầu tự giác thực hiện trách nhiệm cá nhân.","mg_nho":"B13 - Cảm xúc của bé","mg_nho_nd":"1. Trẻ nhắc lại các cảm xúc vui, buồn, sợ hãi, tức giận.\n2. Trẻ luyện tập kĩ năng vận động tinh.","mg_lon":"B13 - Bé học về ứng dụng của hình học trong cuộc sống (tiết 2)","mg_lon_nd":"1. Trẻ gọi tên, nhận diện các hình khối cơ bản và đồ vật có hình khối trong cuộc sống.\n2. Trẻ đề xuất cách xây nhà theo hình khối, nhà cao tầng và chung cư.","ghi_chu":""},{"tiet":"14","hoc_ki":"Học kì I","mg_be":"B14 - Bé học cách nhận diện cảm xúc vui vẻ của bản thân","mg_be_nd":"1. Trẻ nhận biết hai biểu hiện bên trong của cảm xúc vui: muốn cười, muốn nhảy nhót.\n2. Trẻ chỉ ra các biểu hiện qua hình ảnh và luyện tập thể hiện niềm vui bằng những nụ cười khác nhau.","mg_nho":"B14 - Bé đã sẵn sàng khám phá thế giới","mg_nho_nd":"1. Trẻ ôn tập các thức ăn thuộc bốn nhóm chất dinh dưỡng.\n2. Trẻ rèn luyện quan sát, tìm điểm khác biệt và thuyết trình.","mg_lon":"B14 - Bé khám phá ứng dụng của hình học xung quanh mình","mg_lon_nd":"1. Trẻ gọi tên và nhận diện các hình khối xung quanh mình.\n2. Trẻ phối hợp làm mô hình bằng que kem, đất nặn và thực hành cổ vũ, động viên các bạn.","ghi_chu":""},{"tiet":"15","hoc_ki":"Học kì I","mg_be":"B15 - Bé học cách nhận biết cảm xúc buồn của bản thân","mg_be_nd":"1. Trẻ gọi tên cảm xúc buồn và hai biểu hiện bên trong: muốn khóc, muốn ngồi một mình.\n2. Trẻ nhận diện các biểu hiện của cảm xúc buồn qua hình ảnh gợi ý.","mg_nho":"B15 - Bé học cách tham gia giao thông an toàn","mg_nho_nd":"1. Trẻ nêu bốn quy tắc khi đi phương tiện giao thông công cộng: xếp hàng, giữ trật tự, lắng nghe, thắt dây an toàn.\n2. Trẻ biết lý do cần thắt dây an toàn và thực hành động tác thắt dây, ôm đầu cúi thấp.","mg_lon":"B15 - Bé học cách cổ vũ, động viên","mg_lon_nd":"1. Trẻ nhận biết các cảm xúc vui, buồn, lo lắng, tự hào khi tham gia cổ vũ.\n2. Trẻ thực hành giơ tay, vỗ tay và hô lời cổ vũ, động viên.","ghi_chu":""},{"tiet":"16","hoc_ki":"Học kì I","mg_be":"B16 - Bé học cách nhận biết cảm xúc buồn của người khác","mg_be_nd":"1. Trẻ gọi tên cảm xúc buồn của người khác qua biểu hiện mắt khóc, miệng mếu.\n2. Trẻ quan sát khuôn mặt và nhận diện hai biểu hiện của cảm xúc buồn.","mg_nho":"B16 - Bé tham gia giao thông an toàn","mg_nho_nd":"1. Trẻ nhắc lại bốn quy tắc khi đi phương tiện giao thông công cộng: xếp hàng, giữ trật tự, lắng nghe, thắt dây an toàn.\n2. Trẻ thực hành động tác ôm đầu cúi thấp.","mg_lon":"B16 - Bé tham gia cổ vũ, động viên bạn bè","mg_lon_nd":"1. Trẻ nhận biết các động tác và dụng cụ cổ vũ như bông cổ vũ, bảng, băng đô, trống, kèn.\n2. Trẻ cắt, dán làm dụng cụ và thực hành cổ vũ, động viên bạn bằng giọng nói to, rõ ràng.","ghi_chu":""},{"tiet":"17","hoc_ki":"Học kì I","mg_be":"B17 - Bé thực hành nhận diện cảm xúc buồn, vui","mg_be_nd":"1. Trẻ nhắc lại biểu hiện buồn như mắt khóc, miệng mếu và biểu hiện vui như cười tươi, nhảy nhót.\n2. Trẻ chia sẻ các biểu hiện của bản thân khi vui vẻ hoặc buồn bã.","mg_nho":"B17 - Bé làm thí nghiệm và quan sát thí nghiệm","mg_nho_nd":"1. Trẻ biết bề mặt Mặt Trăng có nhiều hố sâu do thiên thạch va vào.\n2. Trẻ thực hiện thí nghiệm về sự hình thành hố sâu, quan sát và mô tả bề mặt Mặt Trăng.","mg_lon":"B17 - Bé học cách xem giờ","mg_lon_nd":"1. Trẻ nhận biết đồng hồ kim và đồng hồ điện tử.\n2. Trẻ luyện tập xem giờ trên đồng hồ kim và đồng hồ điện tử.","ghi_chu":""},{"tiet":"18","hoc_ki":"Học kì I","mg_be":"B18 - Bé học cách chơi với bạn thật vui","mg_be_nd":"1. Trẻ biết hỏi ý kiến bạn trước khi chơi cùng bằng câu “Bạn ơi! Cho tớ chơi cùng nhé!”.\n2. Trẻ thực hành làm quen, hỏi để được chơi cùng với ánh mắt nhìn bạn, nụ cười và giọng nói to, rõ ràng.","mg_nho":"B18 - Bé học cách nhận biết cảm xúc sợ hãi của người khác","mg_nho_nd":"1. Trẻ gọi tên các biểu hiện sợ hãi của người khác: mắt mở to, cơ thể run rẩy, co người.\n2. Trẻ quan sát và nhận diện cảm xúc sợ hãi qua các biểu hiện đó.","mg_lon":"B18 - Bé luyện tập đặt mục tiêu gần trong các công việc hằng ngày","mg_lon_nd":"1. Trẻ hiểu mục tiêu là kết quả mong muốn đạt được trong một khoảng thời gian.\n2. Trẻ xác định công việc, kết quả và thời gian thực hiện để đặt, trình bày mục tiêu gần trong sinh hoạt hằng ngày.","ghi_chu":""},{"tiet":"19","hoc_ki":"Học kì I","mg_be":"B19 - Gia đình là nơi yêu thương nhất","mg_be_nd":"1. Trẻ ghi nhớ câu nói thể hiện tình yêu thương với bố mẹ.\n2. Trẻ thực hành nói lời yêu thương, nhìn bố mẹ, cười tươi và dùng cử chỉ như tạo hình trái tim, bông hoa hoặc gửi nụ hôn gió.","mg_nho":"B19 - Bé tự tin chia sẻ về điều mình được khám phá","mg_nho_nd":"1. Trẻ nhắc lại đặc điểm của sao chổi Halley: đuôi dài, phát sáng, bay rất nhanh.\n2. Trẻ tự tin giơ tay thuyết trình, nói to, rõ ràng và sử dụng tay mô tả nội dung.","mg_lon":"B19 - Bé quyết tâm thực hiện mục tiêu của mình","mg_lon_nd":"1. Trẻ biết mục tiêu là kết quả mong muốn đạt được trong một khoảng thời gian; xác định công việc, kết quả và thời gian khi đặt mục tiêu.\n2. Trẻ thực hành đặt mục tiêu gần và chia sẻ mục tiêu của mình.","ghi_chu":""},{"tiet":"20","hoc_ki":"Học kì I","mg_be":"B20 - Bé làm thiệp tặng bố mẹ","mg_be_nd":"1. Trẻ nhắc lại câu nói thể hiện tình yêu thương với bố mẹ.\n2. Trẻ rèn luyện vận động tinh khi làm thiệp và nói to, rõ ràng lời yêu thương dành cho bố mẹ.","mg_nho":"B20 - Bé học cách quan sát và so sánh","mg_nho_nd":"1. Trẻ mô tả hình dạng, màu sắc của Sao Hỏa qua hình ảnh và biết màu đỏ đến từ bụi, đất trên Sao Hỏa.\n2. Trẻ quan sát, so sánh điểm giống và khác nhau giữa Sao Hỏa với Trái Đất về hình dạng, kích thước, màu sắc.","mg_lon":"B20 - Bé học cách sắp xếp thời gian biểu hợp lý","mg_lon_nd":"1. Trẻ nhận biết bốn buổi trong ngày: sáng, trưa, chiều, tối.\n2. Trẻ biết các bước sắp xếp thời gian biểu: xác định các buổi, chọn công việc và xếp công việc vào từng buổi phù hợp.","ghi_chu":""},{"tiet":"21","hoc_ki":"Học kì I","mg_be":"B21 - Bé học cách quan tâm, chăm sóc người thân","mg_be_nd":"1. Trẻ kể tên những hành động quan tâm, chăm sóc người thân: đưa nước, đưa đồ ăn, đấm lưng, đắp chăn, ôm.\n2. Trẻ thực hành thể hiện tình cảm với bố mẹ bằng các hành động chăm sóc phù hợp.","mg_nho":"B21 - Bé thực hành quan sát và so sánh","mg_nho_nd":"1. Trẻ ôn tập cách quan sát, so sánh theo hình dạng, màu sắc và kích thước.\n2. Trẻ thực hành quan sát, so sánh và thuyết trình.","mg_lon":"B21 - Bé tự sắp xếp lịch trình trong ngày","mg_lon_nd":"1. Trẻ nhắc lại các bước sắp xếp thời gian biểu trong ngày.\n2. Trẻ thực hành lựa chọn, sắp xếp các công việc vào lịch trình phù hợp.","ghi_chu":""},{"tiet":"22","hoc_ki":"Học kì I","mg_be":"B22 - Bé học cách giới thiệu về gia đình mình","mg_be_nd":"1. Trẻ nhớ và gọi tên các thành viên trong gia đình.\n2. Trẻ thuyết trình giới thiệu gia đình to, rõ ràng, kết hợp đứng thẳng, nhìn người nghe, cười tươi và dùng tay minh họa.","mg_nho":"B22 - Bé học cách sáng tạo robot","mg_nho_nd":"1. Trẻ biết vai trò thám hiểm Sao Hỏa của robot và kể tên một số công việc robot giúp con người.\n2. Trẻ lựa chọn, kết hợp các bộ phận để cùng tạo nên robot.","mg_lon":"B22 - Bé học cách sắp xếp và phân loại quần áo","mg_lon_nd":"1. Trẻ biết cách phân loại quần áo theo loại, độ dài và mùa.\n2. Trẻ nhận diện các nhóm quần áo và lựa chọn quần áo phù hợp với mùa hè, mùa đông.","ghi_chu":""},{"tiet":"23","hoc_ki":"Học kì I","mg_be":"B23 - Bé thể hiện tình yêu với gia đình mình","mg_be_nd":"1. Trẻ ôn tập cách thể hiện tình cảm với bố mẹ bằng lời nói và hành động.\n2. Trẻ thực hành lời nói, hành động yêu thương và rèn luyện kĩ năng thuyết trình.","mg_nho":"B23 - Những điều thú vị của vũ trụ","mg_nho_nd":"1. Trẻ ôn tập tên kính thiên văn, tàu vũ trụ, Mặt Trăng, sao chổi Halley, robot, Sao Hỏa.\n2. Trẻ rèn luyện kĩ năng quan sát và thuyết trình về những điều đã khám phá.","mg_lon":"B23 - Bé học cách gấp quần áo","mg_lon_nd":"1. Trẻ biết lý do cần gấp quần áo gọn gàng.\n2. Trẻ thực hành gấp quần áo theo hướng dẫn.","ghi_chu":""},{"tiet":"24","hoc_ki":"Học kì I","mg_be":"B24 - Bé làm sản phẩm cây gia đình","mg_be_nd":"1. Trẻ kể tên và nhận diện hình ảnh các thành viên trong gia đình.\n2. Trẻ luyện tập dán tranh, tô màu để làm sản phẩm cây gia đình.","mg_nho":"B24 - Bé sáng tạo và giới thiệu robot của mình","mg_nho_nd":"1. Trẻ kể tên một số vai trò của robot trong cuộc sống qua hình ảnh.\n2. Trẻ thuyết trình to, rõ ràng và chỉ vào từng bộ phận của robot để minh họa nội dung giới thiệu.","mg_lon":"B24 - Bé tự sắp xếp tủ quần áo","mg_lon_nd":"1. Trẻ nhắc lại ba nguyên tắc sắp xếp tủ quần áo.\n2. Trẻ thực hành phân loại và gấp quần áo để sắp xếp tủ gọn gàng.","ghi_chu":""},{"tiet":"25","hoc_ki":"Học kì I","mg_be":"B25 - Bé tự tin giới thiệu về gia đình thân yêu","mg_be_nd":"1. Trẻ ghi nhớ câu giới thiệu các thành viên trong gia đình và thể hiện tình yêu với gia đình.\n2. Trẻ nói to, rõ ràng khi giới thiệu về những người thân của mình.","mg_nho":"B25 - Bé tìm hiểu mục tiêu xa","mg_nho_nd":"1. Trẻ ghi nhớ khái niệm mục tiêu xa, các từ “phi hành gia”, “nhà môi trường học” và biểu hiện vui vẻ.\n2. Trẻ chọn một mục tiêu xa trong hai mục tiêu của bài, thuyết trình to, rõ ràng, dùng tay minh họa và thể hiện cảm xúc vui.","mg_lon":"B25 - Bé học cách xử lý nguy cơ bị bắt cóc (tiết 1)","mg_lon_nd":"1. Trẻ biết người bắt cóc có thể là bất cứ ai và nhận diện nguy cơ, hậu quả của việc bị bắt cóc.\n2. Trẻ biết từ chối nhận quà, đi theo người lạ; thực hành kêu cứu và động tác bám dính khi có nguy cơ bị bắt cóc.","ghi_chu":""},{"tiet":"26","hoc_ki":"Học kì I","mg_be":"B26 - Bé làm gì để không bị lạc","mg_be_nd":"1. Trẻ biết nguy hiểm khi bị lạc và nhắc lại hai nguyên tắc phòng tránh: đeo vòng tay an toàn, xin phép bố mẹ trước khi đi chơi.\n2. Trẻ thực hành quay về nhiều hướng và gọi to, rõ ràng tên người thân đi cùng để báo hiệu khi bị lạc.","mg_nho":"B26 - Bé tự tin thuyết trình về mục tiêu xa của mình","mg_nho_nd":"1. Trẻ gọi tên các nghề nghiệp qua hình ảnh.\n2. Trẻ tự tin thuyết trình to, rõ ràng về mục tiêu nghề nghiệp của mình trước lớp.","mg_lon":"B26 - Bé học cách xử lý nguy cơ bị bắt cóc (tiết 2)","mg_lon_nd":"1. Trẻ nhắc lại cách kêu cứu khi có nguy cơ bị bắt cóc.\n2. Trẻ luyện tập các động tác quay tay cánh quạt, đập và đạp theo hướng dẫn.","ghi_chu":""},{"tiet":"27","hoc_ki":"Học kì I","mg_be":"B27 - Bé làm thẻ an toàn","mg_be_nd":"1. Trẻ nhắc lại việc đeo vòng tay an toàn, xin phép bố mẹ trước khi đi chơi và cách báo hiệu khi bị lạc.\n2. Trẻ rèn luyện vận động tinh khi làm thẻ an toàn; quay về nhiều hướng, gọi to và rõ tên bố mẹ.","mg_nho":"B27 - Bé học cách nhận lì xì thật lịch sự","mg_nho_nd":"1. Trẻ biết ý nghĩa của lì xì ngày Tết và cách nhận lì xì lịch sự.\n2. Trẻ thực hành nhận bằng hai tay, cười tươi và nói lời cảm ơn to, rõ ràng, lễ phép.","mg_lon":"B27 - Bé luyện tập cách xử lý nguy cơ bị bắt cóc","mg_lon_nd":"1. Trẻ nhắc lại việc người bắt cóc có thể là bất cứ ai và các cách ứng phó đã học.\n2. Trẻ thực hành kêu cứu, bám dính và xử lý tình huống có nguy cơ bị bắt cóc.","ghi_chu":""},{"tiet":"28","hoc_ki":"Học kì I","mg_be":"B28 - Bé học cách nhận lì xì thật lịch sự","mg_be_nd":"1. Trẻ biết cách nhận lì xì đúng và lịch sự.\n2. Trẻ thực hành nhận lì xì lịch sự theo hướng dẫn.","mg_nho":"B28 - Bé làm đồ dùng trang trí Tết","mg_nho_nd":"1. Trẻ nhắc lại tên sản phẩm “Khánh trang trí ngày Tết”.\n2. Trẻ luyện tập vận động thô phối hợp theo cặp.","mg_lon":"B28 - Bé học cách quan sát và mô tả các kiểu mẫu trong cuộc sống","mg_lon_nd":"1. Trẻ biết cách chế biến đồ ăn, đồ uống theo kiểu mẫu đơn giản; đếm số lượng nguyên liệu và tìm quy luật sắp xếp.\n2. Trẻ thực hành sắp xếp theo kiểu mẫu 2–2.","ghi_chu":""},{"tiet":"29","hoc_ki":"Học kì I","mg_be":"B29 - Bé trang trí cây đào đón Tết","mg_be_nd":"1. Trẻ nhắc lại một số loại cây, hoa trang trí ngày Tết.\n2. Trẻ rèn luyện vận động tinh khi trang trí cây đào và nói to, rõ ràng lời chúc năm mới vui vẻ, hạnh phúc.","mg_nho":"B29 - Bé vui vẻ nói lời chúc Tết họ hàng","mg_nho_nd":"1. Trẻ biết cách nói lời chúc Tết phù hợp với mọi người.\n2. Trẻ thực hành lời chúc dành cho ông bà, cô chú, anh chị và em nhỏ.","mg_lon":"B29 - Bé học cách ứng dụng các kiểu mẫu trong trang trí nhà cửa","mg_lon_nd":"1. Trẻ nhắc lại các bước sao chép kiểu mẫu.\n2. Trẻ thực hành sắp xếp các kiểu mẫu 2–1 và 1–2–1 để ứng dụng trong trang trí.","ghi_chu":""},{"tiet":"30","hoc_ki":"Học kì I","mg_be":"B30 - Bé tự tin nói lời chúc Tết ông bà, cha mẹ","mg_be_nd":"1. Trẻ biết cách nói lời chúc Tết.\n2. Trẻ thực hành nói lời chúc Tết.","mg_nho":"B30 - Bé tự tin chinh phục các thử thách","mg_nho_nd":"1. Trẻ kể tên mục tiêu gần, mục tiêu xa của mình và bốn nhóm thức ăn: ngũ cốc, thịt, rau, hoa quả.\n2. Trẻ quan sát, tìm điểm khác biệt qua tranh và thuyết trình về điều mình tự hào trong năm học, kết hợp giọng nói, nét mặt, cử chỉ.","mg_lon":"B30 - Bé trang trí lớp học theo kiểu mẫu","mg_lon_nd":"1. Trẻ biết cách làm dây cờ trang trí lớp học theo kiểu mẫu.\n2. Trẻ rèn luyện tô màu, phối màu đơn giản, quan sát sự khác biệt và sáng tạo sản phẩm.\n3. Trẻ thuyết trình về sản phẩm trang trí của mình.","ghi_chu":""},{"tiet":"31","hoc_ki":"Học kì I","mg_be":"B31 - Bé tự tin chinh phục thử thách","mg_be_nd":"1. Trẻ kể tên các trách nhiệm cá nhân và những việc có thể làm để chăm sóc người thân.\n2. Trẻ thuyết trình về điều mình tự hào đã làm được trong năm học, kết hợp tư thế, nét mặt, cử chỉ và giọng nói to, rõ ràng.","mg_nho":"B31 - Bé rèn luyện kĩ năng quan sát, phát hiện nguy hiểm trong gia đình","mg_nho_nd":"1. Trẻ kể tên đồ dùng điện trong gia đình và nhắc lại cách phòng tránh điện giật: không chơi với đồ điện, nhờ người lớn giúp khi cần sử dụng.\n2. Trẻ nhận diện đồ dùng đang cắm điện có nguy cơ gây điện giật và lựa chọn đồ chơi an toàn.","mg_lon":"B31 - Bé chia sẻ về đồ trang trí trong gia đình","mg_lon_nd":"1. Trẻ nhận biết các hoạt động có trong lớp học và tạo được nhiều hình trang trí theo kiểu mẫu.\n2. Trẻ thực hành thuyết trình to, rõ ràng kết hợp nét mặt, cử chỉ theo hướng dẫn.","ghi_chu":""},{"tiet":"32","hoc_ki":"Học kì I","mg_be":"B32 - Bé học cách phòng tránh tai nạn thương tích do đồ vật sắc, nhọn (tiết 1)","mg_be_nd":"1. Trẻ nhận diện đồ vật sắc, nhọn trong đồ dùng gia đình, dụng cụ học tập và đồ chơi.\n2. Trẻ ghi nhớ bốn nguyên tắc: quan sát phát hiện, tránh xa đồ vật sắc nhọn, cất gọn đồ sau khi dùng, không cầm đồ khi chạy nhảy.\n3. Trẻ phân biệt đồ vật sắc, nhọn và hành động an toàn hoặc không an toàn.","mg_nho":"B32 - Bé phòng tránh nguy cơ điện giật","mg_nho_nd":"1. Trẻ nhận biết dấu hiệu đồ dùng có nguy cơ điện giật là phích cắm đang cắm vào ổ điện.\n2. Trẻ nhắc lại hai nguyên tắc: không chơi với đồ điện, nhờ người lớn giúp khi cần dùng; nhận diện đồ điện đang cắm và biển cảnh báo điện giật.","mg_lon":"B32 - Bé ứng xử lịch sự khi nhận lì xì Tết","mg_lon_nd":"1. Trẻ biết cách ứng xử lịch sự và nói lời cảm ơn khi nhận lì xì Tết.\n2. Trẻ thực hành nhận lì xì và thể hiện lời cảm ơn phù hợp.","ghi_chu":""},{"tiet":"33","hoc_ki":"Học kì I","mg_be":"B33 - Kĩ năng phòng, tránh tai nạn thương tích do đồ vật sắc nhọn (tiết 2)","mg_be_nd":"1. Trẻ ôn tập bốn nguyên tắc phòng tránh thương tích do đồ vật sắc, nhọn và gọi tên hình dạng của đồ vật.\n2. Trẻ thực hành kĩ năng phòng tránh thương tích và rèn luyện thuyết trình.","mg_nho":"B33 - Bé rèn luyện quan sát, nhận diện khu vực an toàn khi vui chơi ngoài trời","mg_nho_nd":"1. Trẻ kể tên các khu vực có nguy cơ đuối nước và bốn nguyên tắc an toàn với nước.\n2. Trẻ lựa chọn giải pháp an toàn khi chơi gần nước và thuyết trình về các nguyên tắc an toàn.","mg_lon":"B33 - Bé làm lì xì Tết","mg_lon_nd":"1. Trẻ biết ý nghĩa cầu chúc may mắn của phong bao lì xì Tết.\n2. Trẻ thực hành gấp, dán, vẽ và trang trí phong bao lì xì.","ghi_chu":""},{"tiet":"34","hoc_ki":"Học kì I","mg_be":"B34 - Bé quan sát và phát hiện nguy hiểm từ đồ vật sắc nhọn","mg_be_nd":"1. Trẻ nhắc lại bốn nguyên tắc phòng tránh thương tích do đồ vật sắc, nhọn.\n2. Trẻ phát hiện đồ vật sắc, nhọn ở nhà, ở trường và thuyết trình to, rõ ràng về các nguyên tắc an toàn.","mg_nho":"B34 - Bé phòng tránh nguy cơ bị đuối nước","mg_nho_nd":"1. Trẻ biết ba bước khi thấy người đuối nước: không nhảy xuống cứu và lùi lại; bình tĩnh kêu cứu; tìm người lớn giúp, vừa đi vừa hô.\n2. Trẻ luyện tập kêu cứu to, rõ ràng và chọn hành động đảm bảo an toàn với nước.","mg_lon":"B34 - Bé chủ động nói lời chúc Tết với mọi người xung quanh","mg_lon_nd":"1. Trẻ biết một số lời chúc Tết dành cho mọi người xung quanh.\n2. Trẻ thực hành nói lời chúc Tết phù hợp.","ghi_chu":""},{"tiet":"35","hoc_ki":"Học kì I","mg_be":"B35 - Bé học cách phòng tránh nguy cơ bỏng, nóng (tiết 1)","mg_be_nd":"1. Trẻ nhận diện dấu hiệu có nguy cơ gây bỏng từ đồ ăn, đồ uống, nước và thiết bị điện.\n2. Trẻ nhắc lại bốn nguyên tắc: phát hiện nguy cơ; không chạm vào đồ vật có nguy cơ; nhờ người lớn kiểm tra; làm mát vết bỏng bằng nước và báo người lớn.\n3. Trẻ phân biệt đồ dùng, đồ vật an toàn và không an toàn.","mg_nho":"B35 - Bé tham gia biệt đội an toàn","mg_nho_nd":"1. Trẻ ôn tập hai nguyên tắc an toàn điện và bốn nguyên tắc an toàn với nước qua các tình huống.\n2. Trẻ nhận diện nguy cơ, chọn hành động an toàn và thực hành lùi lại, hô kêu cứu, tìm người lớn giúp khi thấy người đuối nước.","mg_lon":"B35 - Bé tự tin chinh phục thử thách","mg_lon_nd":"1. Trẻ nhận biết hình học xung quanh và sắp xếp công việc phù hợp với bốn buổi trong ngày.\n2. Trẻ nhận diện cảm xúc tức giận, nói được cảm xúc và lý do tức giận của mình.\n3. Trẻ thuyết trình về điều mình tự hào đã làm được, kết hợp tư thế, nét mặt, cử chỉ và giọng nói to, rõ ràng.","ghi_chu":""},{"tiet":"36","hoc_ki":"Học kì I","mg_be":"B36 - Kĩ năng phòng, tránh nguy cơ bỏng, nóng (tiết 2)","mg_be_nd":"1. Trẻ kể tên hai nguyên tắc mới để phòng tránh nguy cơ bỏng, nóng.\n2. Trẻ thực hành kĩ năng phòng tránh bỏng, nóng và rèn luyện thuyết trình.","mg_nho":"B36 - Bé rèn luyện kĩ năng tư duy phân loại, sắp xếp","mg_nho_nd":"1. Trẻ nhận biết đồ vật có hình dạng và kích cỡ khác nhau.\n2. Trẻ thực hành phân loại đồ vật theo hình dạng, kích cỡ.","mg_lon":"B36 - Bé đảm bảo an toàn cho bản thân","mg_lon_nd":"1. Trẻ ôn tập cách xử lý khi đi lạc và kể tên những người lớn đáng tin để nhờ giúp đỡ.\n2. Trẻ luyện tập hít thở sâu, báo hiệu cho người thân và nhờ người lớn đáng tin giúp đỡ.\n3. Trẻ lựa chọn điểm hẹn an toàn để gặp lại người lớn đi cùng nếu bị lạc.","ghi_chu":""},{"tiet":"37","hoc_ki":"Học kì II","mg_be":"B37 - Bé quan sát và phát hiện nguy cơ bỏng nóng","mg_be_nd":"1. Trẻ nhắc lại hai nguyên tắc: nhờ người lớn kiểm tra an toàn; làm mát vết bỏng bằng nước và báo hiệu cho người lớn.\n2. Trẻ quan sát, phát hiện các nguy cơ gây bỏng, nóng trong nhà.","mg_nho":"B37 - Kĩ năng phòng, tránh tai nạn thương tích do đồ vật sắc nhọn","mg_nho_nd":"1. Trẻ kể tên các nguyên tắc phòng tránh thương tích do đồ vật sắc, nhọn.\n2. Trẻ lựa chọn hành động đảm bảo an toàn để không bị thương bởi đồ vật sắc, nhọn.","mg_lon":"B37 - Trách nhiệm cá nhân của bé khi đi du lịch","mg_lon_nd":"1. Trẻ kể tên các công việc thuộc trách nhiệm cá nhân khi đi du lịch.\n2. Trẻ lựa chọn đồ dùng cần thiết và thuyết trình to, rõ ràng về trách nhiệm của mình.","ghi_chu":""},{"tiet":"38","hoc_ki":"Học kì II","mg_be":"B38 - Kĩ năng nhận diện nguy hiểm bằng các giác quan","mg_be_nd":"1. Trẻ kể tên bốn dấu hiệu khi có cháy: mùi khét, khói, lửa, tiếng chuông báo cháy.\n2. Trẻ luyện tập hô to lời kêu cứu “Cháy! Cháy! Cứu!”.","mg_nho":"B38 - Bé rèn luyện kĩ năng nhận diện nguy hiểm bằng các giác quan","mg_nho_nd":"1. Trẻ kể tên dấu hiệu có nguy cơ gây bỏng từ đồ ăn, đồ uống, thiết bị điện và các nguyên tắc phòng tránh.\n2. Trẻ lựa chọn hành động an toàn để phòng tránh bỏng, nóng.","mg_lon":"B38 - Bé học cách tự buộc dây giày","mg_lon_nd":"1. Trẻ biết các bước tự buộc dây giày.\n2. Trẻ thực hành buộc dây giày theo hướng dẫn.","ghi_chu":""},{"tiet":"39","hoc_ki":"Học kì II","mg_be":"B39 - Kĩ năng bảo vệ bản thân khi xảy ra hỏa hoạn (tiết 1)","mg_be_nd":"1. Trẻ ôn tập cách hô kêu cứu và biết cách phòng tránh khói độc khi có cháy.\n2. Trẻ thực hành dùng khăn ướt che mũi, miệng, cúi thấp người và bò để thoát khỏi đám cháy theo hướng dẫn.","mg_nho":"B39 - Kĩ năng phòng, tránh nguy cơ bỏng nóng","mg_nho_nd":"1. Trẻ kể tên bốn nguyên tắc an toàn phòng tránh bỏng, nóng.\n2. Trẻ chọn hành động an toàn với đồ ăn, đồ uống, thiết bị điện và biết cách xử lý khi bị bỏng theo nội dung đã học.","mg_lon":"B39 - Bé tự chuẩn bị giày dép khi đi học","mg_lon_nd":"1. Trẻ biết cách chuẩn bị tất và giày khi đi học.\n2. Trẻ thực hành chuẩn bị tất, đi giày và buộc dây giày.","ghi_chu":""},{"tiet":"40","hoc_ki":"Học kì II","mg_be":"B40 - Kĩ năng bảo vệ bản thân khi xảy ra hỏa hoạn (tiết 2)","mg_be_nd":"1. Trẻ kể tên hai nguồn nước có thể dùng làm ướt khăn che mũi, miệng khi có cháy và nêu cách phòng tránh ngạt khói.\n2. Trẻ thực hành kĩ năng bảo vệ bản thân khi xảy ra hỏa hoạn.","mg_nho":"B40 - Bé thuyết trình về các giải pháp an toàn","mg_nho_nd":"1. Trẻ nêu dấu hiệu của nguy cơ điện giật, bỏng nóng, thương tích do vật sắc nhọn, đuối nước.\n2. Trẻ quan sát, phát hiện nguy cơ và thuyết trình to, rõ ràng về giải pháp an toàn.","mg_lon":"B40 - Bé tìm hiểu về trách nhiệm gia đình","mg_lon_nd":"1. Trẻ hiểu ý nghĩa của trách nhiệm gia đình và kể tên những việc phù hợp với khả năng của mình.\n2. Trẻ thực hành cách quan tâm, chăm sóc bố mẹ.","ghi_chu":""},{"tiet":"41","hoc_ki":"Học kì II","mg_be":"B41 - Bé đảm bảo an toàn khi vui chơi ở nhà","mg_be_nd":"1. Trẻ nêu cách thoát hiểm an toàn khi có cháy.\n2. Trẻ thực hành thoát hiểm và lựa chọn đồ vật an toàn trong những đồ vật có nguy cơ gây bỏng hoặc thương tích do sắc, nhọn.","mg_nho":"B41 - Bé làm thanh tra an toàn","mg_nho_nd":"1. Trẻ phát hiện, nêu nguy cơ mất an toàn trong tranh tình huống.\n2. Trẻ nhận diện nguy cơ điện giật, bỏng nóng, thương tích do vật sắc nhọn và thuyết trình to, rõ ràng.","mg_lon":"B41 - Bé ghi nhớ và phân loại trách nhiệm của mình","mg_lon_nd":"1. Trẻ kể tên các trách nhiệm cá nhân và trách nhiệm gia đình phù hợp với sức mình.\n2. Trẻ thực hành phân loại trách nhiệm cá nhân và trách nhiệm gia đình.","ghi_chu":""},{"tiet":"42","hoc_ki":"Học kì II","mg_be":"B42 - Bé rèn luyện kĩ năng thuyết trình","mg_be_nd":"1. Trẻ nhắc lại bốn quy tắc lớp học và một số trách nhiệm cá nhân.\n2. Trẻ thực hành nói lời làm quen to, rõ ràng, kết hợp đứng thẳng, cười tươi và dùng tay minh họa khi giới thiệu tên, tuổi.","mg_nho":"B42 - Bé đảm bảo an toàn trong lớp học","mg_nho_nd":"1. Trẻ nêu nguy cơ trong lớp và nhắc lại hai nguyên tắc: quan sát khu vực trước khi chơi, tránh xa nơi có biển cảnh báo.\n2. Trẻ phát hiện nguy cơ điện giật, bỏng nóng, thương tích do vật sắc nhọn và đuối nước.","mg_lon":"B42 - Bé thuyết trình về trách nhiệm của mình","mg_lon_nd":"1. Trẻ kể tên những công việc thuộc trách nhiệm cá nhân và trách nhiệm gia đình.\n2. Trẻ rèn luyện tô màu và thuyết trình to, rõ ràng về những trách nhiệm mình đã thực hiện.","ghi_chu":""},{"tiet":"43","hoc_ki":"Học kì II","mg_be":"B43 - Bé tự tin làm quen, kết bạn bốn phương","mg_be_nd":"1. Trẻ nhắc lại tên mô hình thu nhỏ của Trái Đất là quả địa cầu.\n2. Trẻ thực hành chào hỏi, giới thiệu tên, tuổi, hỏi tên bạn và kết hợp cử chỉ thân thiện khi làm quen.","mg_nho":"B43 - Bé tìm hiểu về nhân vật mình yêu thích","mg_nho_nd":"1. Trẻ làm quen với văn học và biết nhân vật có thể là người, con vật, đồ vật hoặc cây cối có hành động, cảm xúc trong câu chuyện.\n2. Trẻ nhắc lại khái niệm nhân vật và chỉ ra các nhân vật trong bài.","mg_lon":"B43 - Các bạn đã thực hiện trách nhiệm của mình như thế nào","mg_lon_nd":"1. Trẻ kể tên những trách nhiệm phù hợp với bản thân.\n2. Trẻ phối hợp thuyết trình theo nhóm và thể hiện cam kết thực hiện trách nhiệm của mình.","ghi_chu":""},{"tiet":"44","hoc_ki":"Học kì II","mg_be":"B44 - Bé học cách tham gia giao thông an toàn","mg_be_nd":"1. Trẻ nhận biết tên địa hình đồng bằng và nhắc lại các quy tắc khi đi phương tiện giao thông công cộng: xếp hàng, ngồi yên, giữ trật tự, lắng nghe hướng dẫn.\n2. Trẻ thực hành các quy tắc tham gia giao thông an toàn.","mg_nho":"B44 - Bé sáng tạo nhân vật yêu thích","mg_nho_nd":"1. Trẻ nhắc lại nhân vật có thể là người, con vật, đồ vật hoặc cây cối trong câu chuyện.\n2. Trẻ sáng tạo nhân vật yêu thích thể hiện được cảm xúc và đặc điểm ngoại hình.","mg_lon":"B44 - Bé thực hiện các trách nhiệm của mình","mg_lon_nd":"1. Trẻ ôn tập cách xem giờ, lựa chọn quần áo theo thời tiết và các trách nhiệm của mình.\n2. Trẻ thực hành xem đồng hồ kim, đồng hồ điện tử; chọn quần áo mùa hè, mùa đông.\n3. Trẻ thuyết trình về việc chuẩn bị giày dép khi đi học.","ghi_chu":""},{"tiet":"45","hoc_ki":"Học kì II","mg_be":"B45 - Bé giới thiệu về cách tham gia giao thông an toàn","mg_be_nd":"1. Trẻ nhắc lại bốn quy tắc khi đi phương tiện giao thông công cộng: xếp hàng, giữ trật tự, lắng nghe hướng dẫn, ngồi yên tại chỗ.\n2. Trẻ thuyết trình to, rõ ràng về các quy tắc an toàn.","mg_nho":"B45 - Bé học cách miêu tả đặc điểm của nhân vật","mg_nho_nd":"1. Trẻ biết các từ mô tả thân hình: nhỏ nhắn, cao lớn, mảnh mai, mũm mĩm và biết mô tả màu sắc nổi bật của nhân vật.\n2. Trẻ nhận diện nhân vật theo đặc điểm, mô tả màu quần áo, da, tóc hoặc lông và thuyết trình về nhân vật yêu thích.","mg_lon":"B45 - Ấn tượng đầu tiên của bé","mg_lon_nd":"1. Trẻ biết cách chào hỏi thân thiện với bạn bè và lễ phép với người lớn.\n2. Trẻ thực hành chào hỏi kết hợp nét mặt, cử chỉ phù hợp và giọng nói vui vẻ, rõ ràng.","ghi_chu":""},{"tiet":"46","hoc_ki":"Học kì II","mg_be":"B46 - Bé học cách giới thiệu về con vật yêu thích","mg_be_nd":"1. Trẻ nhắc lại trách nhiệm bảo vệ rừng và kể tên một số động vật sống trong rừng.\n2. Trẻ thuyết trình về tên và đặc điểm con vật yêu thích, kết hợp giọng nói to, rõ ràng với tư thế, nét mặt và cử chỉ tay phù hợp.","mg_nho":"B46 - Bé luyện tập miêu tả nhân vật yêu thích của mình","mg_nho_nd":"1. Trẻ nhắc lại từ ngữ mô tả thân hình: nhỏ nhắn, cao lớn, mảnh mai, mũm mĩm.\n2. Trẻ thuyết trình về nhân vật yêu thích bằng từ ngữ chỉ thân hình, màu sắc; nói to, rõ ràng và dùng tay minh họa.","mg_lon":"B46 - Bé thể hiện ấn tượng đầu tiên của mình","mg_lon_nd":"1. Trẻ ôn tập cách tạo ấn tượng đầu tiên qua lời chào thân thiện, lễ phép.\n2. Trẻ luyện tập chào bạn bè, người lớn bằng lời nói và nét mặt, cử chỉ phù hợp.","ghi_chu":""},{"tiet":"47","hoc_ki":"Học kì II","mg_be":"B47 - Bé luyện tập thuyết trình về con vật yêu thích","mg_be_nd":"1. Trẻ ghi nhớ lời giới thiệu con vật yêu thích qua tên, màu lông và thức ăn.\n2. Trẻ luyện tập thuyết trình to, rõ ràng về con vật yêu thích.","mg_nho":"B47 - Bé giới thiệu về đặc điểm riêng của bản thân","mg_nho_nd":"1. Trẻ biết miêu tả màu sắc bằng cách so sánh với sự vật có màu tương ứng xung quanh.\n2. Trẻ đặt câu so sánh màu sắc theo hình ảnh gợi ý và thuyết trình to, rõ ràng về đặc điểm bản thân.","mg_lon":"B47 - Bé tìm hiểu nội quy lớp học Tiểu học","mg_lon_nd":"1. Trẻ ghi nhớ ba nội quy lớp Tiểu học: đi học đúng giờ, lắng nghe và làm bài tập đầy đủ.\n2. Trẻ nhận diện nội quy qua hình ảnh, lắng nghe và trả lời câu hỏi.\n3. Trẻ thực hành đứng nghiêm, hô hiệu lệnh và chào đầu giờ.","ghi_chu":""},{"tiet":"48","hoc_ki":"Học kì II","mg_be":"B48 - Bé tự tin nhờ sự giúp đỡ khi cần","mg_be_nd":"1. Trẻ kể tên ba loài sinh vật ở biển và đại dương.\n2. Trẻ thực hành nhờ giúp đỡ khi gặp khó khăn, đứng thẳng, nhìn người được nhờ và nói to, rõ ràng.","mg_nho":"B48 - Bé mô tả thế giới sắc màu","mg_nho_nd":"1. Trẻ biết cách miêu tả màu sắc bằng sự so sánh với những sự vật xung quanh.\n2. Trẻ luyện tập đặt câu so sánh theo hình ảnh và thuyết trình to, rõ ràng về đặc điểm bản thân.","mg_lon":"B48 - Bé tự tin thuyết trình về lớp học","mg_lon_nd":"1. Trẻ nhắc lại ba nội quy lớp học Tiểu học.\n2. Trẻ thuyết trình về lớp học với tư thế đứng thẳng, nét mặt tươi vui, cử chỉ tay phù hợp và giọng nói to, rõ ràng.\n3. Trẻ thực hành hô hiệu lệnh, đứng nghiêm và chào giáo viên đầu giờ.","ghi_chu":""},{"tiet":"49","hoc_ki":"Học kì II","mg_be":"B49 - Bé nhờ sự giúp đỡ trong trường học","mg_be_nd":"1. Trẻ nhắc lại câu nói nhờ cô, bác hoặc bạn giúp đỡ khi gặp khó khăn.\n2. Trẻ tự tin nói to, rõ ràng lời nhờ giúp đỡ trong trường học.","mg_nho":"B49 - Bé học cách sáng tạo từ những đồ vật xung quanh mình","mg_nho_nd":"1. Trẻ biết sáng tạo nhân vật bằng cách kết hợp những thứ xung quanh, nhận biết các yếu tố tạo nên nhân vật hoạt hình quen thuộc.\n2. Trẻ lựa chọn, kết hợp các bộ phận để cùng sáng tạo nhân vật mới.","mg_lon":"B49 - Bé tham gia cuộc thi thuyết trình tài ba","mg_lon_nd":"1. Trẻ biết cách thuyết trình ở không gian rộng: đứng ở vị trí trung tâm, nói to, mở rộng cử chỉ tay và nhìn bao quát người nghe.\n2. Trẻ thực hành thuyết trình với tư thế, giọng nói, ánh mắt và cử chỉ phù hợp.","ghi_chu":""},{"tiet":"50","hoc_ki":"Học kì II","mg_be":"B50 - Bé thể hiện sự tự tin của mình","mg_be_nd":"1. Trẻ ôn tập kĩ năng làm quen, kết bạn và nói to, rõ ràng khi thực hành.\n2. Trẻ thuyết trình giới thiệu hồng hạc với giọng nói to, rõ ràng và sử dụng cử chỉ tay minh họa.","mg_nho":"B50 - Bé học cách quan sát và mô tả thế giới xung quanh","mg_nho_nd":"1. Trẻ gọi tên các không gian quen thuộc: rừng, đại dương, thành phố, nông trại.\n2. Trẻ chọn nhân vật phù hợp với bối cảnh và mô tả theo hai câu hỏi “Nhân vật sống ở đâu?”, “Ở đó có gì?”.","mg_lon":"B50 - Những điều thú vị ở trường Tiểu học","mg_lon_nd":"1. Trẻ nhận biết các hoạt động ở trường Tiểu học như học tập, vui chơi, câu lạc bộ và chào cờ.\n2. Trẻ chia sẻ hoạt động yêu thích, trải nghiệm làm thí nghiệm theo hướng dẫn của giáo viên.\n3. Trẻ thực hành đứng nghiêm và chào đầu giờ.","ghi_chu":""},{"tiet":"51","hoc_ki":"Học kì II","mg_be":"B51 - Bé nhận diện các loại hình thời tiết","mg_be_nd":"1. Trẻ gọi tên, nhận diện ba loại thời tiết: nắng, mưa, giông bão.\n2. Trẻ lựa chọn một số trang phục phù hợp với trời nắng hoặc mưa.","mg_nho":"B51 - Bé sáng tạo câu chuyện","mg_nho_nd":"1. Trẻ gọi tên các bối cảnh như Mặt Trăng, rừng, lâu đài, bãi biển, nông trại, thành phố.\n2. Trẻ mô tả nhân vật và nơi nhân vật đi chơi, đề xuất cách giải quyết các vấn đề nhân vật gặp phải.","mg_lon":"B51 - Bé muốn tham gia đội nghi lễ","mg_lon_nd":"1. Trẻ biết về đội nghi lễ và ý nghĩa của bài Quốc ca.\n2. Trẻ rèn luyện quan sát, vận động tinh và hát Quốc ca to, rõ ràng.","ghi_chu":""},{"tiet":"52","hoc_ki":"Học kì II","mg_be":"B52 - Bé giới thiệu về các loại thời tiết","mg_be_nd":"1. Trẻ gọi tên ba loại thời tiết nắng, mưa, giông bão và ghi nhớ câu giới thiệu biểu tượng thời tiết.\n2. Trẻ thuyết trình to, rõ ràng, dùng tay chỉ vào tranh khi giới thiệu thời tiết.","mg_nho":"B52 - Bé học cách mô tả không gian qua các mùa","mg_nho_nd":"1. Trẻ nhắc lại đặc điểm thời tiết và hoạt động đặc trưng của mùa xuân, hạ, thu, đông.\n2. Trẻ phân biệt các mùa qua trang phục và hoạt động.","mg_lon":"B52 - Bé trải nghiệm hoạt động thú vị ở trường Tiểu học","mg_lon_nd":"1. Trẻ gọi tên lễ Chào cờ và biết cần đứng nghiêm, hát Quốc ca khi tham dự.\n2. Trẻ thực hành tư thế đứng nghiêm trong lễ Chào cờ.","ghi_chu":""},{"tiet":"53","hoc_ki":"Học kì II","mg_be":"B53 - Bé lựa chọn trang phục phù hợp với thời tiết","mg_be_nd":"1. Trẻ kể tên hai loại trang phục, phụ kiện phù hợp với thời tiết nóng, lạnh, mưa, nắng.\n2. Trẻ thực hành lựa chọn trang phục, phụ kiện phù hợp với từng loại thời tiết.","mg_nho":"B53 - Bé học cách sáng tạo phù hợp với các tình huống quen thuộc","mg_nho_nd":"1. Trẻ xác định mùa dựa trên đặc điểm thời tiết.\n2. Trẻ chọn trang phục, hoạt động phù hợp với nhân vật và kể câu chuyện gồm nhân vật, bối cảnh, hoạt động.","mg_lon":"B53 - Bé thực hiện các nghi lễ ở trường Tiểu học","mg_lon_nd":"1. Trẻ nhận diện một số hiệu lệnh quen thuộc, biết các động tác thể dục đơn giản và cách giậm chân tại chỗ.\n2. Trẻ quan sát, thực hiện động tác thể dục và giậm chân tại chỗ theo hiệu lệnh của giáo viên.","ghi_chu":""},{"tiet":"54","hoc_ki":"Học kì II","mg_be":"B54 - Bé luyện tập cách lựa chọn trang phục phù hợp với thời tiết","mg_be_nd":"1. Trẻ nhận biết trang phục, đồ dùng phù hợp với thời tiết và biết cần ở trong nhà khi giông bão để đảm bảo an toàn.\n2. Trẻ lựa chọn và giới thiệu to, rõ ràng các trang phục, đồ dùng phù hợp.","mg_nho":"B54 - Bé học cách thuyết trình về các ý tưởng sáng tạo của mình","mg_nho_nd":"1. Trẻ kể tên những chi tiết cần có trong câu chuyện: màu sắc nổi bật của nhân vật, nơi ở, thời tiết, hoạt động.\n2. Trẻ kể chuyện với tư thế đứng thẳng, nụ cười, giọng nói to, rõ ràng và cử chỉ tay minh họa.","mg_lon":"B54 - Bé giữ gìn vệ sinh thật tốt","mg_lon_nd":"1. Trẻ biết lý do cần tự lau chùi sau khi đi vệ sinh và các bước thực hiện.\n2. Trẻ thực hành lau chùi sau khi đi vệ sinh theo hướng dẫn.","ghi_chu":""},{"tiet":"55","hoc_ki":"Học kì II","mg_be":"B55 - Bé học cách sắp xếp giày, dép gọn gàng","mg_be_nd":"1. Trẻ nhắc lại ba tiêu chí xếp giày dép: đúng đôi, đúng chiều, mũi giày dép quay vào trong.\n2. Trẻ thực hành sắp xếp giày dép gọn gàng theo các tiêu chí đã học.","mg_nho":"B55 - Bé tìm hiểu nguy cơ khi đi lạc","mg_nho_nd":"1. Trẻ nhận diện, gọi tên những nguy cơ khi đi lạc.\n2. Trẻ mô tả nhân vật bị lạc theo tranh, nhận diện và thể hiện cảm xúc sợ hãi, vui vẻ, ngạc nhiên.","mg_lon":"B55 - Bé làm quen thích ứng với môi trường mới","mg_lon_nd":"1. Trẻ kể tên ba nội quy lớp Tiểu học và các bước lau chùi sau khi đi vệ sinh.\n2. Trẻ lắng nghe, trả lời câu hỏi và sắp xếp đúng thứ tự các bước lau chùi.\n3. Trẻ thực hành đứng nghiêm khi tham dự lễ Chào cờ.","ghi_chu":""},{"tiet":"56","hoc_ki":"Học kì II","mg_be":"B56 - Bé học cách vui chơi an toàn dưới nắng","mg_be_nd":"1. Trẻ gọi tên tia UV và nhắc lại tác hại của tia UV trong ánh nắng.\n2. Trẻ nhận diện bóng râm, các vị trí cần bôi kem chống nắng và lựa chọn trang phục, phụ kiện phù hợp với trời nắng.","mg_nho":"B56 - Bé học cách điều hòa cảm xúc sợ hãi","mg_nho_nd":"1. Trẻ nhắc lại cách hít thở “Ngửi hoa – Thổi nến”: hít vào bằng mũi, thở ra bằng miệng, mỗi nhịp đếm nhẩm từ một đến năm.\n2. Trẻ thực hành hít thở sâu theo hướng dẫn để điều hòa cảm xúc sợ hãi.","mg_lon":"B56 - Bé rèn luyện tư thế ngồi học và kĩ năng cầm bút đúng cách","mg_lon_nd":"1. Trẻ biết các bước ngồi học đúng tư thế, lợi ích của việc cầm bút đúng và tác hại của tư thế sai.\n2. Trẻ luyện tập tư thế ngồi học và cách cầm bút đúng.","ghi_chu":""},{"tiet":"57","hoc_ki":"Học kì II","mg_be":"B57 - Bé học cách quan sát và mô tả tầm quan trọng của nước","mg_be_nd":"1. Trẻ kể tên hai hoạt động cần sử dụng nước và nhắc lại các từ cằn cỗi, màu mỡ, khô héo, tươi tốt, ốm yếu, khỏe mạnh.\n2. Trẻ thuyết trình về sự thay đổi của sự vật khi thiếu nước hoặc đủ nước, kết hợp giọng nói, tư thế và cử chỉ minh họa.","mg_nho":"B57 - Bé luyện tập điều hòa cảm xúc","mg_nho_nd":"1. Trẻ ghi nhớ cách hít vào bằng mũi, thở ra bằng miệng.\n2. Trẻ luyện tập hít thở sâu và sử dụng sản phẩm “Hơi thở của rồng” để lấy lại bình tĩnh, điều hòa cảm xúc.","mg_lon":"B57 - Bé vui học cùng các chữ cái","mg_lon_nd":"1. Trẻ biết lợi ích của việc học bảng chữ cái.\n2. Trẻ nhận diện các chữ a, b, o, t, x, h, m và phân biệt chữ b với chữ d.","ghi_chu":""},{"tiet":"58","hoc_ki":"Học kì II","mg_be":"B58 - Bé học cách tiết kiệm nước","mg_be_nd":"1. Trẻ kể tên các hành động lãng phí nước và ít nhất hai cách tiết kiệm nước trong gia đình.\n2. Trẻ thuyết trình về cách tiết kiệm nước với giọng nói to, rõ ràng và cử chỉ tay minh họa.","mg_nho":"B58 - Bé học cách xử lý khi đi lạc","mg_nho_nd":"1. Trẻ kể tên những người đáng tin để nhờ giúp đỡ khi đi lạc.\n2. Trẻ luyện tập gọi to, rõ tên người lớn đi cùng và kể lại câu chuyện cô bé đi lạc theo tranh.","mg_lon":"B58 - Bé trải nghiệm làm giáo viên Tiểu học","mg_lon_nd":"1. Trẻ biết cách phân biệt chữ b và chữ d bằng bàn tay trái, bàn tay phải.\n2. Trẻ thực hành phân biệt và chia sẻ cách nhận diện hai chữ cái.","ghi_chu":""},{"tiet":"59","hoc_ki":"Học kì II","mg_be":"B59 - Bé học cách uống nước khoa học","mg_be_nd":"1. Trẻ kể tên một số thời điểm uống nước có lợi cho sức khỏe và cách uống: ngồi xuống, uống từng ngụm nhỏ.\n2. Trẻ thuyết trình về các thời điểm uống nước, kết hợp tư thế, nét mặt, cử chỉ và giọng nói to, rõ ràng.","mg_nho":"B59 - Bé luyện tập xử lí khi đi lạc","mg_nho_nd":"1. Trẻ nhắc lại cách báo hiệu khi bị lạc: gọi to tên người lớn đi cùng về nhiều phía.\n2. Trẻ luyện tập gọi to, rõ ràng và điều chỉnh giọng nói theo bốn mức âm thanh.","mg_lon":"B59 - 1 2 3 Nào ta cùng đếm","mg_lon_nd":"1. Trẻ biết chiều viết đúng của các chữ số 2, 5, 6, 9.\n2. Trẻ thực hành viết các chữ số 2, 5, 6, 9 theo đúng chiều.","ghi_chu":""},{"tiet":"60","hoc_ki":"Học kì II","mg_be":"B60 - Bé học cách quan sát và mô tả lợi ích của không khí","mg_be_nd":"1. Trẻ kể tên một số đặc điểm của không khí: có ở xung quanh, không màu, rất nhẹ.\n2. Trẻ quan sát thí nghiệm và mô tả đặc điểm của không khí.","mg_nho":"B60 - Thể hiện cảm xúc buồn của bản thân","mg_nho_nd":"1. Trẻ biết cách nhận diện và thể hiện cảm xúc buồn của bản thân.\n2. Trẻ thực hành nét mặt buồn và nói “Tớ buồn lắm!” bằng giọng nhỏ, chậm.","mg_lon":"B60 - Bé rèn luyện đôi tay khoẻ mạnh, khéo léo","mg_lon_nd":"1. Trẻ ghi nhớ các bài tập cho tay để giảm mỏi khi viết.\n2. Trẻ thực hành ba bài tập ngón tay và hai bài tập cánh tay theo hướng dẫn.","ghi_chu":""},{"tiet":"61","hoc_ki":"Học kì II","mg_be":"B61 - Bé học cách đeo khẩu trang đúng cách","mg_be_nd":"1. Trẻ kể tên các tác nhân gây hại trong không khí như khói bụi, vi khuẩn, vi rút.\n2. Trẻ biết khẩu trang cần vừa mặt, che kín mũi và miệng, không bị ướt hoặc quá rộng; nhận diện cách đeo sai qua hình ảnh.","mg_nho":"B61 - Thể hiện sự đồng cảm với cảm xúc buồn của người khác","mg_nho_nd":"1. Trẻ biết hỏi thăm để thể hiện sự đồng cảm với người đang buồn.\n2. Trẻ thực hành nhìn, nắm tay người được hỏi thăm và nhẹ nhàng, chậm rãi nói “Cậu đang không vui à?”.","mg_lon":"B61 - Bé học cách sắp xếp sách vở","mg_lon_nd":"1. Trẻ gọi tên các đồ dùng học tập và biết các bước sắp xếp sách vở vào ba lô.\n2. Trẻ thực hành đặt sách vở đúng mặt, đúng chiều, sắp xếp từ lớn đến nhỏ và cho vào ba lô.","ghi_chu":""},{"tiet":"62","hoc_ki":"Học kì II","mg_be":"B62 - Bé tạo thói quen tốt cho sức khỏe","mg_be_nd":"1. Trẻ ôn tập cách chọn trang phục theo thời tiết, đeo khẩu trang và uống nước khoa học.\n2. Trẻ chọn quần áo phù hợp với thời tiết hôm sau, nhận diện cách đeo khẩu trang đúng, lựa chọn thời điểm và cách uống nước phù hợp.","mg_nho":"B62 - Bé thực hành thể hiện sự đồng cảm","mg_nho_nd":"1. Trẻ nhắc lại cách hỏi thăm khi người khác buồn.\n2. Trẻ thực hành nói “Cậu đang không vui à?” bằng giọng nhẹ nhàng, chậm, mắt nhìn người được hỏi thăm.","mg_lon":"B62 - Bé học cách chuẩn bị đồ dùng học tập trước khi đi học","mg_lon_nd":"1. Trẻ gọi tên các đồ dùng trong hộp bút và ghi nhớ ba tiêu chí bảo quản: đầy đủ, sẵn sàng, sạch sẽ.\n2. Trẻ thực hành chuẩn bị, sắp xếp và giữ gìn đồ dùng học tập.","ghi_chu":""},{"tiet":"63","hoc_ki":"Học kì II","mg_be":"B63 - Bé thuyết trình các cách bảo vệ sức khỏe","mg_be_nd":"1. Trẻ nhắc lại ba cách bảo vệ sức khỏe: chọn trang phục theo thời tiết, uống đủ nước, đeo khẩu trang ở nơi đông người.\n2. Trẻ thuyết trình to, rõ ràng và dùng cử chỉ minh họa các cách bảo vệ sức khỏe.","mg_nho":"B63 - Sự thay đổi cảm xúc","mg_nho_nd":"1. Trẻ nhận diện, gọi tên cảm xúc và sự thay đổi cảm xúc của nhân vật.\n2. Trẻ trình bày cảm xúc của nhân vật thay đổi như thế nào, vì sao và thể hiện nét mặt phù hợp với cảm xúc vui, buồn.","mg_lon":"B63 - Học tập ở trường Tiểu học thật vui","mg_lon_nd":"1. Trẻ ôn tập cách sắp xếp sách vở và giữ đồ dùng học tập đầy đủ, sẵn sàng, sạch sẽ.\n2. Trẻ thực hành phân biệt chữ b, chữ d và viết đúng chiều các chữ số 2, 5, 6, 9.","ghi_chu":""},{"tiet":"64","hoc_ki":"Học kì II","mg_be":"B64 - Bé học cách nhận diện cảm xúc vui vẻ của mọi người xung quanh","mg_be_nd":"1. Trẻ kể tên biểu hiện vui vẻ của người khác: mắt cười, miệng cười, nhảy nhót.\n2. Trẻ quan sát và nhận diện cảm xúc vui qua các biểu hiện đó.","mg_nho":"B64 - Bé luyện tập cảm nhận sự thay đổi cảm xúc","mg_nho_nd":"1. Trẻ nhắc lại các cảm xúc vui, buồn, tức giận, sợ hãi.\n2. Trẻ nhận diện cảm xúc qua ảnh người thật và kể câu chuyện đơn giản về sự thay đổi cảm xúc cùng lý do thay đổi.","mg_lon":"B64 - Bé làm quen thật nhiều bạn mới","mg_lon_nd":"1. Trẻ ghi nhớ cách làm quen với bạn mới.\n2. Trẻ thực hành giới thiệu tên, sở thích của bản thân khi làm quen, kết bạn.","ghi_chu":""},{"tiet":"65","hoc_ki":"Học kì II","mg_be":"B65 - Bé học cách điều hòa cảm xúc khi sợ hãi","mg_be_nd":"1. Trẻ ghi nhớ cách hít thở sâu kiểu “Ngửi hoa – Thổi nến”: hít vào bằng mũi, thở ra bằng miệng.\n2. Trẻ thực hành hít vào như ngửi hoa, thở ra như thổi nến theo hướng dẫn.","mg_nho":"B65 - Bé chủ động tìm cách điều hòa cảm xúc","mg_nho_nd":"1. Trẻ biết cách chuyển cảm xúc từ buồn sang vui và chọn một việc làm giúp mình vui hơn.\n2. Trẻ thuyết trình về lựa chọn của mình với tư thế đứng thẳng, nụ cười, giọng nói to, rõ ràng và cử chỉ tay minh họa.","mg_lon":"B65 - Bé tìm hiểu sở thích của bạn","mg_lon_nd":"1. Trẻ nhận biết các hoạt động thể hiện sở thích của bản thân, của bạn và ôn tập cách làm quen, kết bạn.\n2. Trẻ vẽ, chia sẻ sở thích của mình và hỏi để tìm hiểu sở thích của bạn.","ghi_chu":""},{"tiet":"66","hoc_ki":"Học kì II","mg_be":"B66 - Bé thể hiện cảm xúc vui vẻ của bản thân","mg_be_nd":"1. Trẻ biết cách thể hiện niềm vui: nhìn người đem đến niềm vui, mỉm cười và nói “Tớ rất vui! Cảm ơn cậu!”.\n2. Trẻ thực hành thể hiện cảm xúc vui bằng lời nói, ánh mắt và nụ cười.","mg_nho":"B66 - Bé thử tài quan sát và sắp xếp theo trình tự","mg_nho_nd":"1. Trẻ gọi tên bốn buổi theo thứ tự sáng, trưa, chiều, tối và sắp xếp công việc theo buổi.\n2. Trẻ sắp xếp tranh, đóng vai và diễn câu chuyện “Hai con dê qua cầu” theo đúng trình tự.","mg_lon":"B66 - Bé hòa đồng, vui chơi cùng bạn","mg_lon_nd":"1. Trẻ biết các cách duy trì tình bạn: cùng làm việc, giúp đỡ, chia sẻ và lắng nghe.\n2. Trẻ thực hành hợp tác với bạn để cùng vẽ con vật.","ghi_chu":""},{"tiet":"67","hoc_ki":"Học kì II","mg_be":"B67 - Bé chia sẻ cảm xúc của mình","mg_be_nd":"1. Trẻ nhắc lại những biểu hiện vui vẻ như nhảy nhót, cười, vỗ tay và ghi nhớ câu nói chia sẻ niềm vui.\n2. Trẻ nhận diện cảm xúc vui của người khác và nói to, rõ ràng khi chia sẻ cảm xúc của mình.","mg_nho":"B67 - Bé rèn luyện khả năng quan sát và suy luận","mg_nho_nd":"1. Trẻ biết quá trình trứng nở và quá trình cây lớn.\n2. Trẻ rèn luyện lắng nghe, quan sát, suy luận và sắp xếp tranh theo trình tự hợp lý.","mg_lon":"B67 - Bé tự tin kết bạn và chơi cùng bạn","mg_lon_nd":"1. Trẻ nhắc lại các bước làm quen, kết bạn và cách duy trì tình bạn.\n2. Trẻ thực hành làm quen với bạn ở lớp khác, trao đổi tên và sở thích, kết hợp ánh mắt, nụ cười, giọng nói và cử chỉ tay.","ghi_chu":""},{"tiet":"68","hoc_ki":"Học kì II","mg_be":"B68 - Bé làm chủ cảm xúc của mình","mg_be_nd":"1. Trẻ ôn tập kĩ thuật “Ngửi hoa – Thổi nến” và tìm hiểu thêm cách giúp bản thân bình tĩnh.\n2. Trẻ chia sẻ điều khiến mình vui, lựa chọn hành động phù hợp và thực hành hít thở để điều hòa cảm xúc buồn, sợ hãi, lo lắng.","mg_nho":"B68 - Bé thực hành kĩ năng quan sát","mg_nho_nd":"1. Trẻ nhận diện, gọi tên các buổi trong ngày.\n2. Trẻ luyện tập quan sát, tìm điểm khác biệt và thuyết trình với giọng nói to, rõ ràng.","mg_lon":"B68 - Bé tôn trọng thầy, cô giáo","mg_lon_nd":"1. Trẻ biết cách thể hiện sự tôn trọng thầy cô: chào hỏi, làm bài đầy đủ, chuẩn bị đồ dùng và giữ lớp sạch sẽ.\n2. Trẻ thực hành chào thầy cô lễ phép: hướng mặt về thầy cô, mỉm cười, khoanh tay và nói to, rõ ràng.","ghi_chu":""},{"tiet":"69","hoc_ki":"Học kì II","mg_be":"B69 - Bé học cách phân loại rác bảo vệ môi trường","mg_be_nd":"1. Trẻ kể tên một số loại rác dễ phân hủy và khó phân hủy.\n2. Trẻ thực hành phân loại rác vào đúng thùng dựa trên nhãn dán.","mg_nho":"B69 - Bé học cách sáng tác câu chuyện của mình","mg_nho_nd":"1. Trẻ nhắc lại những việc xảy ra trong chuyến hành trình dựa vào tranh.\n2. Trẻ sắp xếp tranh đúng thứ tự và kể lại câu chuyện với giọng to, rõ ràng, tư thế, nét mặt, cử chỉ phù hợp.","mg_lon":"B69 - Bé yêu thương thầy, cô giáo","mg_lon_nd":"1. Trẻ biết thể hiện tình yêu thương thầy cô bằng lời nói và những việc giúp đỡ phù hợp.\n2. Trẻ thực hành nói lời yêu thương, đề nghị giúp đỡ và làm các việc như lau bảng, chuyển đồ, phát bài.","ghi_chu":""},{"tiet":"70","hoc_ki":"Học kì II","mg_be":"B70 - Bé chung tay bảo vệ môi trường","mg_be_nd":"1. Trẻ kể tên nguyên liệu, đồ dùng có thể tái sử dụng làm đồ trang trí như lá cây, vỏ hộp sữa chua, nắp chai, chai lọ.\n2. Trẻ rèn luyện vận động tinh và nói to, rõ ràng khẩu hiệu kêu gọi bảo vệ môi trường.","mg_nho":"B70 - Bé tự tin chia sẻ câu chuyện của mình","mg_nho_nd":"1. Trẻ ôn tập khái niệm nhân vật và chỉ ra các nhân vật trong câu chuyện.\n2. Trẻ chọn một điều yêu thích trong chuyến hành trình và thuyết trình to, rõ ràng về điều đó.","mg_lon":"B70 - Bé thể hiện sự tôn trọng và yêu thương thầy, cô giáo","mg_lon_nd":"1. Trẻ biết cách làm báo tường thể hiện lòng biết ơn, sự tôn trọng và yêu thương thầy cô.\n2. Trẻ thực hành cắt, dán, tô màu và thuyết trình về sản phẩm.","ghi_chu":""},{"tiet":"71","hoc_ki":"Học kì II","mg_be":"B71 - Bé chia sẻ cách bảo vệ môi trường","mg_be_nd":"1. Trẻ kể tên hành động bảo vệ môi trường như bỏ rác đúng nơi, nhắc bạn không xả rác, quét rác, trồng và tưới cây, tiết kiệm nước.\n2. Trẻ thuyết trình chia sẻ hành động mình muốn làm để bảo vệ môi trường.","mg_nho":"B71 - Bé khám phá bản thân mình","mg_nho_nd":"1. Trẻ nêu các đặc điểm ngoại hình và màu sắc yêu thích của bản thân.\n2. Trẻ dùng câu so sánh màu sắc với những sự vật có màu tương ứng xung quanh để mô tả bản thân.","mg_lon":"B71 - Bé sẵn sàng trở thành học sinh Tiểu học","mg_lon_nd":"1. Trẻ nêu được một điều mình thích nhất khi học lớp Hành trang vào Tiểu học.\n2. Trẻ chia sẻ về điều mình yêu thích trong lớp Hành trang vào Tiểu học.","ghi_chu":""},{"tiet":"72","hoc_ki":"Học kì II","mg_be":"B72 - Tổng kết năm học","mg_be_nd":"1. Trẻ ôn tập trách nhiệm cá nhân, gia đình, xã hội và cách thể hiện tình yêu thương với bố mẹ.\n2. Trẻ lựa chọn trách nhiệm phù hợp, thực hành hành động yêu thương bố mẹ và chọn cách tiết kiệm nước, bỏ rác đúng nơi.","mg_nho":"B72 - Tổng kết năm học","mg_nho_nd":"1. Trẻ ôn tập lựa chọn thức ăn theo bốn nhóm: thịt, rau, hoa quả, ngũ cốc.\n2. Trẻ luyện tập tham gia giao thông an toàn, chọn thức ăn đủ chất, lắng nghe, quan sát, sắp xếp tranh và kể chuyện theo trình tự.","mg_lon":"B72 - Tổng kết năm học","mg_lon_nd":"1. Trẻ ôn tập cách phòng tránh nguy cơ bỏng nóng, điện giật, đuối nước, bị thương do vật sắc nhọn và bị bắt cóc.\n2. Trẻ nhận diện nguy cơ trong tình huống, nêu cách phòng tránh và lựa chọn dây cờ theo kiểu mẫu.\n3. Trẻ thuyết trình to, rõ ràng về mục tiêu của mình khi trở thành học sinh Tiểu học.","ghi_chu":""}]},"structuredType":"roadmap_72_lessons","durationMinutes":20},{"id":"mod-05-ptbaihay-kb","code":"HP05","category":"Phân tích Bài học Tiêu biểu","title":"Phân tích nội dung hay các khối: Kĩ năng phòng tránh ngạt khói & Vui chơi an toàn dưới nắng","subtitle":"Khung chương trình 72 tiết - Khối Mẫu giáo Bé (3 - 4 tuổi) | Phân tích chuyên môn & Mục đích kĩ năng","durationMinutes":25,"passThreshold":80,"status":"published","authorId":"up-huongdt","authorName":"Đinh Thị Hương","updatedAt":"2026-11-26T06:35:00.000Z","sourceFile":{"name":"Sale-ptbaihay-KB.xlsx","type":"xlsx"},"summaryPoints":["Bài 1 (Tiết 38 & 39 - Khối Bé 3-4 tuổi): Cặp bài liên hoàn Nhận diện nguy hiểm cháy nổ qua giác quan, làm loa tay hô 'CHÁY! CHÁY! CỨU!', nhớ số 114, dùng đồ vải ướt che kín mũi miệng và cúi thấp/bò sát sàn men chân tường ra cửa Exit.","Bài 2 (Tiết 56 - Khối Bé 3-4 tuổi - Bài Demo tiêu biểu): Nhân hóa tia cực tím vô hình thành 'Quái vật UV' (4 tác hại: cháy da, chóng mặt, ốm sốt, ngất xỉu), nghiêng người tìm bóng râm, nhảy vũ đạo bôi kem chống nắng và trang bị 'Chiếc khiên chống nắng'."],"structuredType":"","contentText":"=== CHUYÊN ĐỀ: KĨ NĂNG PHÒNG TRÁNH NGẠT KHÓI ===\nBÀI 1: KĨ NĂNG PHÒNG TRÁNH VÀ BẢO VỆ BẢN THÂN KHI XẢY RA HOẢ HOẠN (TIẾT 38 & 39)\nKhung chương trình 72 tiết - Khối Mẫu giáo Bé (3 - 4 tuổi) | Kĩ năng an toàn, bảo vệ bản thân & Thoát hiểm khẩn cấp\nPHẦN I: HỒ SƠ CHUYÊN MÔN CHI TIẾT (CỘT: STT | HẠNG MỤC | NỘI DUNG TRIỂN KHAI | PHÂN TÍCH CHUYÊN MÔN & MỤC ĐÍCH KĨ NĂNG)\n\n[1. Thông tin chung]\n• Tên bài học liên hoàn: Kĩ năng nhận diện nguy hiểm bằng các giác quan & Phòng tránh ngạt khói khi có hoả hoạn\n• Mã tiết chuẩn khung 72 tiết: Tiết 38 (Lý thuyết nhận diện & Kêu cứu) và Tiết 39 (Thực hành chống ngạt khói & Thoát hiểm an toàn)\n• Khối lớp: Mẫu giáo Bé (3 - 4 tuổi)\n• Nhóm kĩ năng: Kĩ năng an toàn, bảo vệ bản thân & Thoát hiểm sinh tồn khẩn cấp\n• Thời lượng chuẩn: 2 tiết (30 - 35 phút/tiết)\n1. Phân tích sư phạm chuyên sâu:\n• Thiết kế cặp bài liên hoàn kế thừa và bổ trợ hoàn hảo: Tiết 38 đặt nền tảng nhận thức giác quan (nhìn, nghe, ngửi), hiểu rõ nguyên nhân - hậu quả và rèn phản xạ ngôn ngữ báo động (hô cứu); Tiết 39 nâng cấp lên hành động sinh tồn thực tế (chống ngạt khói bằng đồ vải ướt và di chuyển thoát hiểm cúi thấp sát sàn).\n• Chia nhỏ tiến trình thành 2 tiết độc lập giúp trẻ 3 tuổi không bị quá tải tâm lý, biến kiến thức an toàn cháy nổ thành chuỗi phản xạ tự nhiên ăn sâu vào tiềm thức.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Trang bị Kĩ năng sinh tồn cơ bản nhất (Survival Skills), giúp trẻ 3 tuổi không hoảng loạn khóc lóc, biết cách báo động cho người lớn và tự che chắn đường hô hấp khi có sự cố cháy nổ.\n\n[2. Kiến thức kĩ năng cốt lõi]\n1. Kiến thức trọng tâm:\n• Hậu quả nghiêm trọng của hỏa hoạn: Cháy rụi nhà cửa, hư hỏng đồ đạc, tạo ra khói độc cay mắt khó thở và gây nguy hiểm trực tiếp đến tính mạng con người.\n• 4 Nguyên nhân phổ biến gây cháy: Bạn nhỏ nghịch bật lửa, người lớn đốt vàng mã, cắm quá nhiều thiết bị vào một ổ điện, vứt tàn thuốc lá vào bãi cỏ khô.\n• 4 Dấu hiệu nhận biết cháy bằng giác quan: Ngửi thấy mùi khét nồng (Khứu giác); Nhìn thấy khói đen bốc lên và ngọn lửa đỏ (Thị giác); Nghe thấy tiếng chuông/còi báo cháy reo inh ỏi (Thính giác).\n• Số điện thoại khẩn cấp: Nhớ số cứu hỏa 114.\n• Kĩ năng kêu cứu chuẩn: Giơ 2 tay lên miệng làm loa và hô thật to, rõ ràng: 'CHÁY! CHÁY! CỨU!'.\n• Bản chất nguy hiểm của khói độc: Trong đám cháy, KHÓI ĐỘC NGUY HIỂM HƠN LỬA đối với tính mạng (gây ngạt thở, ngất xỉu); khói bốc lên cao, tầng khí sạch dễ thở nằm ở SÁT MẶT SÀN NHÀ.\n• Nguyên tắc ngăn khói tại chỗ: Tìm nhanh đồ dùng bằng vải (khăn, quần áo, mũ vải, giẻ lau...), làm ướt bằng nguồn nước gần nhất (bình nước, chai nước, hộp sữa tươi, vòi nước) và gấp che kín cả MŨI lẫn MIỆNG.\n• Nguyên tắc thoát hiểm an toàn: Cúi gập người / bò sát sàn men theo chân tường ra cửa Exit; tuyệt đối KHÔNG dùng thang máy, KHÔNG trốn vào gầm giường/tủ quần áo/nhà vệ sinh, KHÔNG quay lại lấy đồ chơi.\n\n2. Kĩ năng đạt chuẩn:\n• 90% trẻ nhắc lại được 4 dấu hiệu nhận biết cháy qua các giác quan và số 114.\n• 85% trẻ thực hiện đúng động tác loa tay và hô to dõng dạc câu: 'Cháy! Cháy! Cứu!'.\n• 85% trẻ biết tìm đồ vải, làm ướt và gấp che kín hoàn toàn cả mũi và miệng.\n• 80% trẻ thực hành đúng tư thế cúi thấp người / bò men theo chân tường thoát ra ngoài.\n1. Phân tích sư phạm chuyên sâu:\n• Bài học đi thẳng vào bản chất khoa học của sự cố: Triệt tiêu thói quen nghịch lửa nguy hiểm ở lứa tuổi mầm non và phá vỡ bản năng sai lầm (sợ hãi chui rúc vào góc tối). Thay vào đó, trẻ được trao quyền năng hành động: biết dùng giác quan để phát hiện sớm, biết mở miệng hô cứu và biết hạ thấp trọng tâm để tự bảo vệ lá phổi.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng quan sát & nhận thức giác quan: Nhạy bén phát hiện các biến đổi bất thường của môi trường (mùi lạ, âm thanh còi, cột khói).\n• Kĩ năng ngôn ngữ & phát tín hiệu khẩn cấp: Hô khẩu lệnh ngắn, to, dứt khoát trong hoàn cảnh hoảng loạn.\n• Kĩ năng tự bảo vệ & thích ứng sinh tồn: Bảo toàn oxy, che chắn đường hô hấp và định hướng không gian.\n\n[3. Khái quát nội dung bài]\nBài học liên hoàn (Tiết 38 & 39): Kĩ năng nhận diện nguy hiểm bằng các giác quan & Phòng tránh ngạt khói khi có hoả hoạn (Khối Bé 3–4 tuổi, 2 tiết, 30–35 phút/tiết) là nội dung đào tạo sinh tồn khẩn cấp tối quan trọng giúp trẻ hình thành kĩ năng tự bảo vệ bản thân và ứng phó sự cố cháy nổ. Trọng tâm bài học giải quyết triệt để rào cản tâm lý hoảng loạn và bản năng trốn tránh nguy hiểm của trẻ mầm non bằng cách kích hoạt đa giác quan nhận diện sớm dấu hiệu cháy (ngửi mùi khét, thấy khói lửa, nghe chuông báo), ghi nhớ số khẩn cấp 114 và rèn phản xạ ngôn ngữ làm loa tay hô to: “CHÁY! CHÁY! CỨU!”. Từ đó, trẻ nắm vững nguyên lý khoa học sống còn: “Khói độc nguy hiểm hơn lửa và tầng khí sạch nằm sát sàn nhà”, nhanh chóng tìm đồ vải làm ướt che kín cả mũi lẫn miệng và thực hiện đúng tư thế cúi thấp người/bò men theo chân tường hướng ra cửa thoát hiểm Exit.\n\nĐặc biệt, thấu hiểu tâm sinh lý trẻ 3 tuổi rất dễ hoảng sợ trước lửa khói nhưng lại nhanh quên nếu chỉ học lý thuyết suông, Novastars đã tách biệt thành chuỗi bài liên hoàn 2 tiết kế thừa khoa học: Tiết 38 đặt nền tảng nhận thức và phản xạ báo động qua phóng sự thực tế, thảo luận và game số tương tác “Rồng phun lửa”; Tiết 39 nâng cấp lên hành động thực chiến thông qua thử thách tìm đồ vải, làm ướt khăn bịt kín mũi miệng và diễn tập thoát hiểm trong không gian thực tế. Sự luân chuyển trạng thái liên tục này giúp trẻ tiếp thu bài học tự nhiên, không bị áp lực tâm lý và biến kĩ năng sinh tồn thành chuỗi phản xạ có điều kiện ăn sâu vào tiềm thức.\n1. Phân tích sư phạm chuyên sâu:\n• Thiết kế chuỗi bài liên hoàn 2 bậc thang 'Nhận thức giác quan ➔ Hành động sinh tồn': Giúp trẻ 3-4 tuổi không bị quá tải tâm lý; chuyển hóa kiến thức an toàn cháy nổ thành phản xạ tự nhiên.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng sinh tồn khẩn cấp (Survival Skills): Biết tự bảo vệ đường hô hấp bằng đồ vải ướt và di chuyển an toàn men chân tường ra cửa Exit.\n• Kĩ năng giao tiếp & Cầu cứu: Hô to dõng dạc câu báo động, chủ động tìm sự trợ giúp của người lớn khi gặp nguy hiểm.\n\n[4. Hoạt động cụ thể 1 (Tiết 38):\nPhóng sự hỏa hoạn (Hậu quả & Nguyên nhân)]\n• Tên hoạt động: Khởi động – Xem phóng sự hỏa hoạn cùng Su và Kem\n• Hình thức tổ chức: Tương tác qua video phóng sự kết hợp đàm thoại phản biện\n• Tiến trình chi tiết:\n  - Giáo viên ổn định lớp, chào hỏi, nhắc tên môn học Kĩ năng sống Novastars.\n  - Cho trẻ xem đoạn video phóng sự thời sự: Su và Kem đang theo dõi bản tin về một vụ cháy lớn.\n  - Đàm thoại về HẬU QUẢ CỦA ĐÁM CHÁY: Giáo viên hỏi: 'Khi có hỏa hoạn, chuyện gì có thể xảy ra?' -> Trẻ trả lời theo quan sát và kinh nghiệm (nhà bị cháy sập, khói cay mắt, đồ dùng bị thiêu rụi, người bị nạn...); cô ghi nhận và giải thích sự nguy hiểm.\n  - Đàm thoại về 4 NGUYÊN NHÂN GÂY CHÁY: Giáo viên hỏi: 'Có những nguyên nhân nào dẫn tới hỏa hoạn?' -> Cùng trẻ mổ xẻ 4 tình huống thực tế: (1) Bạn nhỏ nghịch bật lửa; (2) Người lớn đốt vàng mã không trông coi; (3) Cắm quá nhiều thiết bị vào một ổ cắm điện gây chập điện; (4) Vứt tàn thuốc lá đang cháy vào bãi cỏ khô.\n  - Giáo viên mở video tổng kết bài học về nguyên nhân và hậu quả.\n1. Phân tích sư phạm chuyên sâu:\n• Hoạt động ở đầu sử dụng chất liệu phóng sự thực tế mang tính thời sự giúp thu hút sự chú ý tối đa của trẻ 3 tuổi. Bằng cách chỉ ra 4 nguyên nhân đời thường (đặc biệt là hành vi nghịch bật lửa của trẻ nhỏ), bài học đánh thức ý thức cảnh giác phòng ngừa tai nạn từ sớm.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tư duy nguyên nhân - kết quả: Nhận thức rõ hành vi nghịch lửa/điện sẽ dẫn tới hậu quả khôn lường là đám cháy phá hủy tài sản và đe dọa mạng sống.\n• Kĩ năng tập trung chú ý & phân tích thông tin: Lắng nghe, quan sát video phóng sự và diễn đạt suy nghĩ bằng lời nói.\n\n[5. Hoạt động cụ thể 2 (Tiết 38):\nThảo luận dấu hiệu cảnh báo bằng giác quan]\n• Tên hoạt động: Hoạt động 2 – Thảo luận: Dấu hiệu cảnh báo khi có cháy & Số cứu hỏa 114\n• Hình thức tổ chức: Xem video tương tác kết hợp thảo luận giác quan\n• Tiến trình chi tiết:\n  - Giáo viên cho trẻ xem video các tình huống cháy và đặt câu hỏi kích thích tư duy giác quan: 'Khi có cháy, chúng mình sẽ ngửi thấy gì, nghe thấy gì và nhìn thấy gì?'.\n  - Hướng dẫn trẻ liên kết từng giác quan với dấu hiệu cảnh báo:\n  * Khứu giác (Mũi ngửi): Ngửi thấy mùi khét lẹt, cay nồng.\n  * Thị giác (Mắt nhìn): Nhìn thấy khói đen cuồn cuộn bốc lên, nhìn thấy ngọn lửa đỏ rực.\n  * Thính giác (Tai nghe): Nghe thấy tiếng chuông/còi báo cháy reo vang inh ỏi khắp tòa nhà.\n  - Giới thiệu số điện thoại khẩn cấp của Đội Cứu hỏa: Số 114.\n  - Cho trẻ xem video hoạt hình tổng kết 4 dấu hiệu và nhắc lại đồng thanh.\n1. Phân tích sư phạm chuyên sâu:\n• Thay vì định nghĩa trừu tượng, bài học gắn liền dấu hiệu nguy hiểm với các bộ phận cơ thể quen thuộc của trẻ (mũi ngửi mùi khét, mắt nhìn khói lửa, tai nghe còi). Đây là phương pháp dạy học giác quan trực quan kinh điển, giúp trẻ 3 tuổi ghi nhớ sâu sắc và phản xạ ngay lập tức khi xuất hiện mùi khét hay tiếng còi.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng nhận biết thế giới qua các giác quan: Tăng cường độ nhạy bén của khứu giác, thính giác và thị giác trong việc phát hiện nguy cơ mất an toàn.\n• Kĩ năng ghi nhớ thông tin khẩn cấp: Ghi nhớ số điện thoại 114 để nhờ người lớn bấm gọi cứu trợ.\n\n[6. Hoạt động cụ thể 3 (Tiết 38):\nGiới thiệu & Luyện tập kĩ năng loa tay kêu cứu]\n• Tên hoạt động: Hoạt động 3 – Huấn luyện phản xạ kêu cứu 'Cháy! Cháy! Cứu!'\n• Hình thức tổ chức: Thực hành kĩ năng cá nhân và nhóm nhỏ kết hợp khích lệ bằng Sao thưởng\n• Tiến trình chi tiết:\n  - Giáo viên mở video hướng dẫn thao tác kêu cứu khi phát hiện cháy: Đặt câu hỏi: 'Khi thấy đám cháy, việc đầu tiên chúng mình cần làm là gì?' -> Nhanh chóng báo hiệu cho người lớn xung quanh.\n  - Hướng dẫn kĩ thuật phát âm thanh khẩn cấp: Giơ 2 bàn tay cong khum áp sát vào khóe miệng để tạo thành chiếc LOA PHÓNG THANH, giúp âm thanh vang xa và rõ nhất.\n  - Dạy khẩu lệnh kêu cứu ngắn gọn, dứt khoát: 'CHÁY! CHÁY! CỨU!' (hoặc 'Cháy! Cháy! Cứu với!').\n  - Tổ chức luyện tập đa cấp độ:\n  * Cấp độ 1: Cả lớp cùng đứng dậy, làm động tác loa tay và hô đồng thanh nhiều hướng.\n  * Cấp độ 2: Giáo viên mời từng nhóm 02 – 03 trẻ/lượt lên trước lớp thực hành hô to dõng dạc.\n  - Khen ngợi và trao tặng Sao thưởng Novastars dũng cảm cho các bé thực hành đúng.\n  - Xem video tổng kết kĩ năng kêu cứu và củng cố toàn bộ Tiết 38.\n1. Phân tích sư phạm chuyên sâu:\n•  Hiệu lệnh thông báo khi xảy ra đám cháy được rút gọn chỉ gồm 3 từ đanh thép 'Cháy! Cháy! Cứu!' giúp trẻ không bị ngọng hay hụt hơi trong trạng thái hoảng loạn, đảm bảo tín hiệu kêu cứu đến tai người lớn nhanh nhất.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng vận động thô & phối hợp tay - miệng: Đưa tay lên tạo vòm loa chuẩn xác và lấy hơi từ bụng để phát âm lượng lớn.\n• Kĩ năng cảm xúc xã hội (SEL) & Bản lĩnh cá nhân: Vượt qua sự rụt rè nhút nhát, tự tin đứng trước đám đông hô to khẩu lệnh khẩn cấp.\n\n[7. Hoạt động cụ thể 4 (Tiết 39):\nGame 'Rồng phun lửa' & Thảo luận nguy cơ khói độc]\n• Tên hoạt động: Hoạt động 1 (Tiết 39) – Game tương tác 'Rồng phun lửa' & Cú sốc nhận thức về khói độc\n• Hình thức tổ chức: Game tương tác số trên phần mềm Novastars kết hợp đàm thoại phản biện\n• Tiến trình chi tiết:\n  - Giáo viên giới thiệu căn phòng mô phỏng và thử thách số 1 của Biệt đội cứu hỏa nhí: Trò chơi 'Rồng phun lửa'.\n  - Nhiệm vụ: Điều khiển nhân vật né tránh các ngọn lửa do rồng phun ra. Cả lớp cùng đứng dậy nghiêng người sang phải, nghiêng sang trái theo chuyển động trên màn hình.\n  - Đàm thoại tạo cú sốc nhận thức sau game: 'Chúng mình đã giúp nhân vật né tránh được hết lửa rồi, tại sao bạn ấy vẫn gặp nguy hiểm và ngất xỉu trong đám cháy?'.\n  - Cho trẻ xem video khoa học 'Sự nguy hiểm của khói trong đám cháy': Phân tích chuyện gì xảy ra nếu hít phải quá nhiều khói độc (khói làm cay xè mắt không nhìn thấy đường, khói độc tràn vào phổi gây ho sặc sụa, ngạt thở và ngất xỉu).\n  - Đúc kết thông điệp sinh tử: Trong đám cháy, chúng ta không chỉ cần tránh lửa mà BẮT BUỘC PHẢI TRÁNH CẢ KHÓI ĐỘC.\n1. Phân tích sư phạm chuyên sâu:\n•  Tình huống 'né hết lửa mà vẫn bị nạn' là một cú sốc nhận thức (Cognitive Dissonance) sư phạm đắt giá, đánh đổ quan niệm ngây thơ của trẻ con rằng 'cháy chỉ nguy hiểm vì lửa'. Qua đó trẻ tự giác nhận ra: Khói độc mới chính là kẻ thù số 1 cần phòng chống hàng đầu.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tư duy phản biện & Bản chất vấn đề: Nhận thức rõ ràng khói độc nguy hiểm hơn ngọn lửa đối với đường hô hấp.\n• Kĩ năng vận động thô phản xạ: Luyện khả năng nghiêng thân mình né tránh chướng ngại vật theo nhịp độ hình ảnh.\n\n[8. Hoạt động cụ thể 5 (Tiết 39):\nGame tương tác 'Truy tìm đồ dùng vải trong phòng']\n• Tên hoạt động: Hoạt động 2 (Tiết 39) – Thử thách 'Truy tìm đồ dùng vải để ngăn khói'\n• Hình thức tổ chức: Game tương tác chạm/chọn trên màn hình cảm ứng kết hợp nhận diện vật thật\n• Tiến trình chi tiết:\n  - Giáo viên mở video thử thách số 2: Tìm kiếm các đồ vật bằng vải có trong căn phòng mô phỏng để làm 'mặt nạ lọc khói'.\n  - Mời từng trẻ lên chạm/chọn các đồ vật bằng vải xuất hiện trong phòng: Khăn mặt, khăn tay, quần áo, mũ vải, rèm cửa, giẻ lau...\n  - Đàm thoại củng cố: Kể tên các đồ vải xung quanh mình có thể dùng để che mũi miệng khi có cháy.\n  - Chốt nguyên tắc sinh tồn: Khi có hỏa hoạn, phải thật nhanh chóng tìm bất kỳ đồ vật nào bằng vải ở gần mình nhất, kể cả vạt áo hay tay áo đang mặc trên người đều dùng để ngăn khói độc được.\n1. Phân tích sư phạm chuyên sâu:\n• Ứng dụng trò chơi hóa vào rèn luyện kĩ năng phân loại chất liệu. Giáo trình mở rộng tư duy của trẻ vượt ra ngoài khuôn khổ sách vở: Không cứng nhắc đi tìm chiếc 'khăn mặt', mà linh hoạt biến mọi vật liệu vải có sẵn xung quanh (quần áo đang mặc, mũ, giẻ lau) thành 'lá chắn lọc khí cứu sinh'.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng quan sát & phân loại chất liệu: Nhận biết đặc tính thấm hút và lọc khí của chất liệu vải so với các đồ vật nhựa, gỗ, kim loại.\n• Kĩ năng giải quyết vấn đề linh hoạt (Resourcefulness): Biết tận dụng tài nguyên có sẵn trên người trong tình huống cấp bách.\n\n[9. Hoạt động cụ thể 6 (Tiết 39):\nTrò chơi 'Nguồn nước ở đâu?' & Thực hành làm ướt khăn]\n• Tên hoạt động: Hoạt động 3 & 4 (Tiết 39) – Tìm nguồn nước & Thực hành làm ướt đồ vải che kín mũi miệng\n• Hình thức tổ chức: Trò chơi vận động tìm thẻ tranh trong lớp kết hợp thao tác trực tiếp với vật thật\n• Tiến trình chi tiết:\n  - Xem video thử thách số 3: Đi tìm nguồn nước để làm ướt đồ vải khi không có vòi nước bồn rửa.\n  - Trẻ vận động tìm các thẻ tranh nguồn nước giấu quanh lớp học (bình nước lọc, chai nước khoáng, hộp sữa giấy, vòi nước) gắn lên bảng kết quả.\n  - Thực hành làm ướt vật thật: Giáo viên mời học sinh lên thao tác trực tiếp làm ướt khăn bằng nước trong bình, nước đóng chai và nước từ hộp sữa tươi.\n  - Hướng dẫn kĩ thuật che mũi miệng: Vắt nhẹ khăn, gấp lại và áp chặt che kín hoàn toàn cả MŨI và MIỆNG, thở chậm rãi qua lớp vải ướt.\n  - Trải nghiệm mở rộng: Cho trẻ quan sát chiếc mặt nạ chống khói chuyên dụng để nhận biết trang bị cứu hộ hiện đại.\n1. Phân tích sư phạm chuyên sâu:\n• Đưa tình huống thực tế 'khan hiếm tài nguyên' vào giảng dạy. Việc cho trẻ trực tiếp rót nước từ bình, chai và hộp sữa thật vào khăn giúp hình thành kinh nghiệm cảm giác chân thực (Hands-on Experience). Trẻ hiểu rằng trong tình huống sinh tử, bất kỳ chất lỏng an toàn nào (kể cả sữa tươi) đều là cứu tinh để làm ướt khăn ngăn khói độc xâm nhập vào phổi.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng vận động tinh & thao tác phối hợp: Thao tác rót nước, nhúng khăn, vắt khăn vừa phải và áp chặt kín khít sống mũi và khóe miệng.\n• Kĩ năng ứng biến hoàn cảnh khẩn cấp: Tự tin xử lý tình huống khi không có vòi nước máy bên cạnh.\n\n[10. Hoạt động cụ thể 7 (Tiết 39):\nLuyện tập di chuyển cúi thấp người men chân tường & Diễn tập còi báo cháy]\n• Tên hoạt động: Hoạt động 5 & Tổng kết (Tiết 39) – Huấn luyện di chuyển thoát hiểm cúi thấp men chân tường & Diễn tập còi báo cháy thực tế\n• Hình thức tổ chức: Luyện tập vận động thực địa kết hợp kích hoạt phản xạ còi báo cháy thật\n• Tiến trình chi tiết:\n  - Huấn luyện tư thế thoát hiểm chuẩn xác: Giáo viên làm mẫu và chỉnh sửa tư thế cho học sinh: Một tay giữ chặt khăn ướt áp kín mũi miệng; Toàn bộ cơ thể cúi gập thật thấp (hoặc bò bằng đầu gối và một bàn tay sát mặt sàn) để hít thở tầng không khí sạch.\n  - Kĩ thuật dò đường men chân tường: Một bàn tay còn lại luôn đặt chạm men theo mép tường để định hướng phương hướng di chuyển trong làn khói dày, dẫn thẳng ra cửa có biển báo Exit màu xanh lá cây.\n  - Cả lớp xếp thành hàng nối đuôi nhau thực hành di chuyển cúi thấp men tường quanh phòng học ra cửa thoát hiểm.\n  - Tình huống thực chiến bất ngờ: Giáo viên bật âm thanh còi báo cháy thật của trường mầm non. Trẻ lập tức phối hợp chuỗi kĩ năng hoàn chỉnh: Giữ khăn ướt che kín mũi miệng -> Hạ thấp người bò men tường -> Nhanh chóng theo cô giáo di chuyển an toàn ra sân trường.\n  - Giáo viên tổng kết, khen ngợi và trao huy hiệu lính cứu hỏa nhí dũng cảm cho cả lớp.\n1. Phân tích sư phạm chuyên sâu:\n• Luyện tập phản xạ hành vi & Thử nghiệm tích cực: Việc loại bỏ đạo cụ ống chui cồng kềnh giúp tiết học tập trung hoàn toàn vào kĩ năng cốt lõi thực tế: Cúi thấp người hạ thấp trọng tâm và sờ tay men theo chân tường để không bị lạc lối trong bóng tối. Âm thanh còi báo cháy thật chuyển hóa kiến thức trên lớp thành bản năng sinh tồn trọn đời.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng vận động thô thích ứng không gian: Duy trì tư thế bò, trườn hoặc đi khom lưng giữ thăng bằng trong khi một tay luôn phải giữ chặt khăn che mặt.\n• Kĩ năng định hướng không gian: Rèn thói quen dùng xúc giác sờ men theo bờ tường để tìm lối thoát hiểm Exit.\n• Kĩ năng quản lý cảm xúc (SEL): Giữ được sự bình tĩnh, không khóc lóc giẫm đạp lên nhau, tuân thủ kỷ luật thoát hiểm an toàn.\n=== CHUYÊN ĐỀ: VUI CHƠI AN TOÀN DƯỚI NẮNG ===\nBÀI 2: BÉ HỌC CÁCH VUI CHƠI AN TOÀN DƯỚI NẮNG (TIẾT 56)\nKhung chương trình 72 tiết - Khối Mẫu giáo Bé (3 - 4 tuổi) | Bài Demo tiêu biểu chuyển giao mầm non\nPHẦN I: HỒ SƠ CHUYÊN MÔN CHI TIẾT (CỘT: STT | HẠNG MỤC | NỘI DUNG TRIỂN KHAI | PHÂN TÍCH CHUYÊN MÔN & MỤC ĐÍCH KĨ NĂNG)\n\n[1. Thông tin chung]\n• Tên bài học: Bé học cách vui chơi an toàn dưới nắng\n• Mã tiết: Tiết 56 (Khung 72 tiết mầm non CG)\n• Khối lớp: Mẫu giáo Bé (3 - 4 tuổi)\n• Nhóm kĩ năng: Kĩ năng an toàn, bảo vệ bản thân\n• Thời lượng chuẩn: 30 - 35 phút/tiết\n• Học liệu nền tảng: Phần mềm KNS Novastars\n1. Phân tích sư phạm chuyên sâu:\n• Đây là BÀI DẠY DEMO TIÊU BIỂU được tuyển chọn kỹ lưỡng trong gói chuyển giao công nghệ mầm non Novastars. Bài học giải quyết trực diện vấn đề sinh hoạt thực tế của trẻ mầm non khi tham gia các hoạt động ngoài trời, dã ngoại.\n• Thiết kế chuẩn mực theo Mô hình tiết học 5 bước, kết hợp công nghệ tương tác số với âm nhạc vận động và sản phẩm học liệu mang về.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Đặt nền móng xây dựng ý thức tự chăm sóc và bảo vệ cơ thể (Self-care), giúp trẻ 3 tuổi bước đầu hình thành phản xạ tự bảo vệ trước các điều kiện thời tiết khắc nghiệt.\n\n[2. Kiến thức kĩ năng cốt lõi]\n1. Kiến thức trọng tâm:\n• Trẻ ghi nhớ và gọi tên được tia có hại cho sức khỏe ẩn nấp trong ánh nắng mặt trời: Tia UV (nhân hóa thành 'Quái vật UV').\n• Trẻ nhắc lại được 4 tác hại chính của tia UV: Cháy rát da, chóng mặt đau đầu, bị ốm (sốt cao), ngất xỉu (say nắng).\n• Trẻ nhận biết các vị trí có bóng râm an toàn: dưới bóng cây to, sân chơi có mái che, nơi có ô/bạt che lớn.\n• Trẻ nhận biết các vị trí cơ thể cần thoa kem chống nắng: mặt, tai, cổ, cánh tay, cẳng chân, bụng/lưng (khi mặc đồ bơi).\n• Trẻ nhận biết trang phục, phụ kiện bảo hộ trời nắng: mũ rộng vành, áo chống nắng, kính râm, ô che, bình nước.\n\n2. Kĩ năng đạt chuẩn:\n• trẻ nhận diện đúng vị trí bóng râm an toàn.\n• trẻ nhận diện và chỉ đúng các vị trí cần bôi kem chống nắng trên cơ thể.\n•  trẻ chọn lựa đúng trang phục, phụ kiện phù hợp với thời tiết nắng.\n• trẻ thực hiện đúng động tác vũ đạo bôi kem chống nắng theo nhạc.\n1. Phân tích sư phạm chuyên sâu:\n• Tư duy của trẻ 3 - 4 tuổi là tư duy trực quan hình tượng. Khái niệm vật lý 'tia cực tím/bức xạ UV' hoàn toàn vô hình và khó hiểu với trẻ. Việc nhân hóa tia UV thành 'Quái vật UV' là sáng tạo sư phạm đắt giá giúp cụ thể hóa mối nguy thành hình tượng nhìn thấy được, trẻ hiểu ngay lý do phải phòng vệ.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tư duy nhân quả: Liên kết hành vi và hậu quả (Đi nắng không đội mũ -> Quái vật UV tấn công -> Cháy da, ốm sốt).\n• Kĩ năng quan sát & định hướng không gian: Rèn luyện mắt quan sát để tự tìm đến khu vực râm mát an toàn.\n• Kĩ năng tự bảo vệ (Self-protection): Trẻ hình thành tâm thế chủ động chuẩn bị đồ dùng hoặc nhời người lớn chuẩn bị đồ cho mình trước khi ra trời nắng.\n\n[3. Khái quát nội dung bài]\nBài 56: Bé học cách vui chơi an toàn dưới nắng (Khối Bé 3–4 tuổi, 30–35 phút) là tiết dạy demo tiêu biểu giúp trẻ hình thành kỹ năng tự bảo vệ và chăm sóc cơ thể (Self-care & Self-protection) khi tham gia hoạt động ngoài trời. Trọng tâm bài học giải quyết xuất sắc rào cản nhận thức của lứa tuổi mầm non bằng cách nhân hóa tia cực tím vô hình thành “Quái vật UV”, giúp trẻ ghi nhớ 4 tác hại cốt lõi: cháy da, chóng mặt, ốm sốt và ngất xỉu; từ đó chủ động tìm đến bóng râm an toàn (tán cây, mái che, bạt lớn) và tự giác trang bị “Chiếc khiên chống nắng” (mũ, áo chống nắng, kính râm, ô, và kem chống nắng).\n\nĐặc biệt, thấu hiểu tâm sinh lý trẻ 3 tuổi có khoảng thời gian tập trung rất ngắn, Novastars đã đa dạng hóa các loại hình hoạt động và liên tục thay đổi trạng thái học tập (từ xem video, đàm thoại sang đứng lên vận động, nhảy múa, kéo thả chạm màn hình), giúp trẻ luôn duy trì năng lượng hứng khởi, tập trung cao độ và tiếp thu bài học một cách tự nhiên nhất.\n1. Phân tích sư phạm chuyên sâu:\n• Phương pháp Nhân cách hóa & Gamification: Chuyển hóa khái niệm trừu tượng (tia cực tím UV) thành hình tượng 'Quái vật UV' và 'Hiệp sĩ mang khiên', giúp trẻ 3-4 tuổi tiếp thu tự nhiên, biến sự gò bó khi mặc đồ chống nắng thành niềm tự hào tự trang bị vũ khí bảo vệ bản thân.\n• Đa dạng hóa hình thức hoạt động theo tâm sinh lý lứa tuổi: Luân chuyển liên tục các trạng thái học tập (xem video, đàm thoại, vận động, nhảy múa, kéo thả màn hình cảm ứng) giúp trẻ duy trì năng lượng hứng khởi suốt 30-35 phút.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tự chăm sóc & Tự bảo vệ (Self-care & Self-protection): Khắc sâu 4 tác hại cốt lõi (cháy da, chóng mặt, ốm sốt, ngất xỉu), chủ động tìm bóng râm và tự giác trang bị đủ đồ dùng che chắn khi ra ngoài nắng.\n• Kĩ năng tư duy phân loại & Bảo vệ sức khỏe: Biết tự chọn không gian chơi an toàn và nhận diện các dấu hiệu mệt mỏi của cơ thể để dừng chơi kịp thời.\n\n[4. Hoạt động cụ thể 1:\nKhởi động & Dẫn dắt]\n• Tên hoạt động: Khởi động – Gặp gỡ Sao Nova & Thử thách Quái vật UV\n• Hình thức tổ chức: Video hoạt hình dẫn dắt\n• Tiến trình chi tiết:\n  - Giáo viên mở đoạn phim ngắn nhân vật đồng hành Sao Nova.\n  - Trẻ theo dõi bối cảnh sa mạc nắng gắt và câu chuyện người dân chạy trốn Quái vật UV ẩn nấp trong ánh nắng mặt trời.\n  - Giáo viên tạo không khí hào hứng và cho cả lớp đồng thanh hô to khẩu lệnh 'SẴN SÀNG' để chính thức bước vào bài học.\n1. Phân tích sư phạm chuyên sâu:\n• Hoạt động khởi động và dẫn dắt (Chuyển giao trạng thái & Dẫn dắt cốt truyện). Nhân vật Sao Nova đóng vai trò 'cầu nối tâm lý', biến bài học kĩ năng thành một chuyến phiêu lưu giải cứu, giúp trẻ chuyển từ trạng thái tự do sang tập trung có chủ đích.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng lắng nghe có chủ đích: Luyện khả năng tập trung chú ý vào màn hình và tiếp nhận thông tin từ câu chuyện dẫn dắt.\n• Kĩ năng cảm xúc xã hội (SEL): Tạo tâm thế tự tin, hứng khởi, sẵn sàng đối mặt thử thách và tinh thần đồng đội qua khẩu lệnh 'Sẵn sàng'.\n\n[5. Hoạt động cụ thể 2:\nGame 'Truy tìm bóng râm']\n• Tên hoạt động: Hoạt động 1 – Game tương tác 'Truy tìm bóng râm'\n• Hình thức tổ chức: Game tương tác số kết hợp vận động cơ thể\n• Tiến trình chi tiết:\n  - Giáo viên giới thiệu tên hoạt động, trẻ đồng thanh nhắc lại: 'Truy tìm bóng râm'.\n  - Hướng dẫn luật chơi: Bước 1: Quan sát 2 hình ảnh trên bảng; Bước 2: Nghiêng cơ thể về phía hình ảnh có bóng râm an toàn.\n  - Cả lớp hô 'Sẵn sàng' và tham gia chơi qua các màn hình bối cảnh thực tế (sân chơi có ô che, dưới tán cây to, khu vui chơi có mái che).\n  - Giáo viên mở video tổng kết, cùng trẻ nhắc lại các khu vực an toàn có bóng râm.\n1. Phân tích sư phạm chuyên sâu:\n• Ứng dụng Thuyết Đa trí tuệ của Howard Gardner (kết hợp Thị giác Visual và Vận động Kinesthetic). Trẻ không chỉ nhìn thụ động mà dùng chính chuyển động nghiêng thân người (trái/phải) để lựa chọn đáp án. Đây là vũ khí bẻ gãy hiểu lầm 'slide thụ động': Màn hình kích hoạt toàn bộ học sinh đứng lên vận động thực tế!\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng nhận diện không gian an toàn: Nhận diện chính xác đâu là nơi có bóng râm râm mát ngoài đời thực để vui chơi.\n• Kĩ năng vận động thô & Thăng bằng cơ thể: Rèn luyện khả năng điều khiển thân người nghiêng trái, nghiêng phải linh hoạt, nhanh nhẹn theo hiệu lệnh thị giác.\n\n[6. Hoạt động cụ thể 3:\nThảo luận Quái vật UV]\n• Tên hoạt động: Hoạt động 2 – Thảo luận 'Nguy cơ khu vui chơi dưới nắng'\n• Hình thức tổ chức: Xem video phân tích & Đàm thoại gợi mở\n• Tiến trình chi tiết:\n  - Giáo viên mở đoạn phim giới thiệu về tác hại của Quái vật UV.\n  - Hệ thống 3 câu hỏi đàm thoại:\n  1. Sao Nova vừa nhắc đến con quái vật gì? -> Quái vật UV.\n  2. Quái vật UV ẩn nấp ở đâu? -> Trong ánh nắng mặt trời.\n  3. Quái vật UV có thể khiến chúng mình bị làm sao? -> Cháy da, chóng mặt, bị ốm, ngất xỉu.\n  - Giáo viên và học sinh đồng thanh nhắc lại thông điệp trọng tâm để khắc sâu ghi nhớ.\n1. Phân tích sư phạm chuyên sâu:\n• Phương pháp đàm thoại đa tầng giúp học sinh tự tư duy và nói ra kiến thức thay vì nghe cô giáo giảng giải một chiều.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng giao tiếp & Ngôn ngữ mạch lạc: Rèn luyện phản xạ nói to, rõ ràng, tự tin diễn đạt câu trả lời trước tập thể lớp học.\n• Kĩ năng nhận thức rủi ro: Khắc sâu 4 tác hại nguy hiểm vào tiềm thức, tạo rào cản nhận thức giúp trẻ tự biết sợ và tránh nắng gắt.\n\n[7. Hoạt động cụ thể 4:\nVận động theo nhạc Bôi kem]\n• Tên hoạt động: Hoạt động 3 – Luyện tập vận động theo nhạc 'Bôi kem chống nắng'\n• Hình thức tổ chức: Âm nhạc & Vũ đạo mô phỏng thao tác\n• Tiến trình chi tiết:\n  - Giáo viên mời toàn bộ trẻ đứng dậy, bật bài hát sôi động 'Bôi kem chống nắng'.\n  - Giáo viên làm mẫu và trẻ nhảy múa theo nhạc, thực hiện các động tác vũ đạo mô phỏng thoa kem: xoa mặt, vuốt cổ, xoa dọc hai cánh tay, hai cẳng chân và xoa bụng.\n  - Xem video tổng kết, trẻ nhắc lại danh sách các vị trí cơ thể bắt buộc phải thoa kem trước khi ra ngoài nắng.\n1. Phân tích sư phạm chuyên sâu:\n• Đột phá phương pháp qua Âm nhạc & Trí nhớ vận động cơ thể. Thao tác bôi kem khô khan được chuyển thể thành vũ điệu bắt tai. Âm nhạc kích thích não bộ, giúp trẻ 3 tuổi nhớ các vị trí cần bảo vệ mà không cần học vẹt.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tự phục vụ cơ thể (Self-help): Nắm vững thao tác và các vị trí da hở cần bôi kem chống nắng để bảo vệ cơ thể.\n• Kĩ năng vận động thô & Cảm thụ nhịp điệu: Giải phóng năng lượng thể chất, rèn sự dẻo dai và khả năng phối hợp vận động tay - chân - thân người theo nhịp nhạc.\n\n[8. Hoạt động cụ thể 5:\nGame 'Làm khiên chống nắng']\n• Tên hoạt động: Hoạt động 4 – Game tương tác kéo thả 'Làm khiên chống nắng'\n• Hình thức tổ chức: Game tương tác số trên bảng cảm ứng\n• Tiến trình chi tiết:\n  - Giáo viên mở video hướng dẫn: quan sát đồ vật trên màn hình, gọi to tên các đồ dùng bảo vệ sử dụng khi trời nắng\n   - Hệ thống tự động hoàn thiện các đồ dùng trong khiên\n1. Phân tích sư phạm chuyên sâu:\n• Ứng dụng Gamification và biểu tượng 'Chiếc khiên hiệp sĩ'. Tạo cho trẻ cảm giác mình là những hiệp sĩ nhí tự trang bị khiên giáp bảo vệ sức khỏe, loại bỏ hoàn toàn cảm giác bị người lớn ép mặc đồ chống nắng cồng kềnh.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tư duy phân loại đồ dùng (Cognitive Sorting): Phân biệt chính xác đồ dùng cần thiết khi trời nắng và loại bỏ các đồ dùng không phù hợp.\n• Rèn luyện sự tự tin mạnh dạn nói ra ý kiến của bản thân bằng cách gọi to tên đồ dùng có thể chống nắng, đồng thời tạo không khí vui nhộn cho lớp học\n\n[9. Hoạt động cụ thể 6:\nGame 'Chiến đấu Quái vật UV']\n• Tên hoạt động: Hoạt động 5 – Game vận động phản xạ 'Chiến đấu với quái vật UV'\n• Hình thức tổ chức: Game vận động phản xạ tương tác không gian\n• Tiến trình chi tiết:\n  - Giáo viên mở video hướng dẫn nhiệm vụ: Đứng ở vạch chính giữa bảng nhìn lên màn hình; Quái vật UV xuất hiện tấn công từ hướng nào thì giơ tay có ngôi sao về hướng đó để đẩy lùi.\n  - Giáo viên mời từng nhóm trẻ lên đứng tại vạch và tham gia thử thách phản xạ đánh đuổi quái vật.\n  - Kết thúc trò chơi trong âm thanh chúc mừng chiến thắng rộn rã.\n1. Phân tích sư phạm chuyên sâu:\n• Trẻ được Nhập vai & Thực hành phản xạ: Trò chơi đẩy tiết học lên cao trào cảm xúc, giúp củng cố niềm tin vào năng lực tự bảo vệ của bản thân sau khi đã trang bị đầy đủ 'khiên chống nắng'.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng phản xạ nhanh & Định hướng không gian đa chiều: Luyện khả năng phản xạ mắt nhìn - tay giơ theo các hướng (trái, phải, trên) kịp thời khi mối nguy xuất hiện.\n• Kĩ năng xây dựng lòng tự tin và tính chủ động: Trẻ không sợ hãi mà tự tin làm chủ tình huống, biết rằng mình hoàn toàn có thể tự bảo vệ an toàn.","uploadedTables":[{"rows":[["BÀI 1: KĨ NĂNG PHÒNG TRÁNH VÀ BẢO VỆ BẢN THÂN KHI XẢY RA HOẢ HOẠN (TIẾT 38 & 39)","","",""],["Khung chương trình 72 tiết - Khối Mẫu giáo Bé (3 - 4 tuổi) | Kĩ năng an toàn, bảo vệ bản thân & Thoát hiểm khẩn cấp","","",""],["PHẦN I: HỒ SƠ CHUYÊN MÔN CHI TIẾT (CỘT: STT | HẠNG MỤC | NỘI DUNG TRIỂN KHAI | PHÂN TÍCH CHUYÊN MÔN & MỤC ĐÍCH KĨ NĂNG)","","",""],["STT","Hạng mục chuyên môn","Nội dung triển khai thực tế","Phân tích chuyên môn (Kẹp Mục đích phát triển kĩ năng cho trẻ)"],["1","Thông tin chung","• Tên bài học liên hoàn: Kĩ năng nhận diện nguy hiểm bằng các giác quan & Phòng tránh ngạt khói khi có hoả hoạn\n• Mã tiết chuẩn khung 72 tiết: Tiết 38 (Lý thuyết nhận diện & Kêu cứu) và Tiết 39 (Thực hành chống ngạt khói & Thoát hiểm an toàn)\n• Khối lớp: Mẫu giáo Bé (3 - 4 tuổi)\n• Nhóm kĩ năng: Kĩ năng an toàn, bảo vệ bản thân & Thoát hiểm sinh tồn khẩn cấp\n• Thời lượng chuẩn: 2 tiết (30 - 35 phút/tiết)","1. Phân tích sư phạm chuyên sâu:\n• Thiết kế cặp bài liên hoàn kế thừa và bổ trợ hoàn hảo: Tiết 38 đặt nền tảng nhận thức giác quan (nhìn, nghe, ngửi), hiểu rõ nguyên nhân - hậu quả và rèn phản xạ ngôn ngữ báo động (hô cứu); Tiết 39 nâng cấp lên hành động sinh tồn thực tế (chống ngạt khói bằng đồ vải ướt và di chuyển thoát hiểm cúi thấp sát sàn).\n• Chia nhỏ tiến trình thành 2 tiết độc lập giúp trẻ 3 tuổi không bị quá tải tâm lý, biến kiến thức an toàn cháy nổ thành chuỗi phản xạ tự nhiên ăn sâu vào tiềm thức.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Trang bị Kĩ năng sinh tồn cơ bản nhất (Survival Skills), giúp trẻ 3 tuổi không hoảng loạn khóc lóc, biết cách báo động cho người lớn và tự che chắn đường hô hấp khi có sự cố cháy nổ."],["2","Kiến thức kĩ năng cốt lõi","1. Kiến thức trọng tâm:\n• Hậu quả nghiêm trọng của hỏa hoạn: Cháy rụi nhà cửa, hư hỏng đồ đạc, tạo ra khói độc cay mắt khó thở và gây nguy hiểm trực tiếp đến tính mạng con người.\n• 4 Nguyên nhân phổ biến gây cháy: Bạn nhỏ nghịch bật lửa, người lớn đốt vàng mã, cắm quá nhiều thiết bị vào một ổ điện, vứt tàn thuốc lá vào bãi cỏ khô.\n• 4 Dấu hiệu nhận biết cháy bằng giác quan: Ngửi thấy mùi khét nồng (Khứu giác); Nhìn thấy khói đen bốc lên và ngọn lửa đỏ (Thị giác); Nghe thấy tiếng chuông/còi báo cháy reo inh ỏi (Thính giác).\n• Số điện thoại khẩn cấp: Nhớ số cứu hỏa 114.\n• Kĩ năng kêu cứu chuẩn: Giơ 2 tay lên miệng làm loa và hô thật to, rõ ràng: 'CHÁY! CHÁY! CỨU!'.\n• Bản chất nguy hiểm của khói độc: Trong đám cháy, KHÓI ĐỘC NGUY HIỂM HƠN LỬA đối với tính mạng (gây ngạt thở, ngất xỉu); khói bốc lên cao, tầng khí sạch dễ thở nằm ở SÁT MẶT SÀN NHÀ.\n• Nguyên tắc ngăn khói tại chỗ: Tìm nhanh đồ dùng bằng vải (khăn, quần áo, mũ vải, giẻ lau...), làm ướt bằng nguồn nước gần nhất (bình nước, chai nước, hộp sữa tươi, vòi nước) và gấp che kín cả MŨI lẫn MIỆNG.\n• Nguyên tắc thoát hiểm an toàn: Cúi gập người / bò sát sàn men theo chân tường ra cửa Exit; tuyệt đối KHÔNG dùng thang máy, KHÔNG trốn vào gầm giường/tủ quần áo/nhà vệ sinh, KHÔNG quay lại lấy đồ chơi.\n\n2. Kĩ năng đạt chuẩn:\n• 90% trẻ nhắc lại được 4 dấu hiệu nhận biết cháy qua các giác quan và số 114.\n• 85% trẻ thực hiện đúng động tác loa tay và hô to dõng dạc câu: 'Cháy! Cháy! Cứu!'.\n• 85% trẻ biết tìm đồ vải, làm ướt và gấp che kín hoàn toàn cả mũi và miệng.\n• 80% trẻ thực hành đúng tư thế cúi thấp người / bò men theo chân tường thoát ra ngoài.","1. Phân tích sư phạm chuyên sâu:\n• Bài học đi thẳng vào bản chất khoa học của sự cố: Triệt tiêu thói quen nghịch lửa nguy hiểm ở lứa tuổi mầm non và phá vỡ bản năng sai lầm (sợ hãi chui rúc vào góc tối). Thay vào đó, trẻ được trao quyền năng hành động: biết dùng giác quan để phát hiện sớm, biết mở miệng hô cứu và biết hạ thấp trọng tâm để tự bảo vệ lá phổi.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng quan sát & nhận thức giác quan: Nhạy bén phát hiện các biến đổi bất thường của môi trường (mùi lạ, âm thanh còi, cột khói).\n• Kĩ năng ngôn ngữ & phát tín hiệu khẩn cấp: Hô khẩu lệnh ngắn, to, dứt khoát trong hoàn cảnh hoảng loạn.\n• Kĩ năng tự bảo vệ & thích ứng sinh tồn: Bảo toàn oxy, che chắn đường hô hấp và định hướng không gian."],["3","Khái quát nội dung bài","Bài học liên hoàn (Tiết 38 & 39): Kĩ năng nhận diện nguy hiểm bằng các giác quan & Phòng tránh ngạt khói khi có hoả hoạn (Khối Bé 3–4 tuổi, 2 tiết, 30–35 phút/tiết) là nội dung đào tạo sinh tồn khẩn cấp tối quan trọng giúp trẻ hình thành kĩ năng tự bảo vệ bản thân và ứng phó sự cố cháy nổ. Trọng tâm bài học giải quyết triệt để rào cản tâm lý hoảng loạn và bản năng trốn tránh nguy hiểm của trẻ mầm non bằng cách kích hoạt đa giác quan nhận diện sớm dấu hiệu cháy (ngửi mùi khét, thấy khói lửa, nghe chuông báo), ghi nhớ số khẩn cấp 114 và rèn phản xạ ngôn ngữ làm loa tay hô to: “CHÁY! CHÁY! CỨU!”. Từ đó, trẻ nắm vững nguyên lý khoa học sống còn: “Khói độc nguy hiểm hơn lửa và tầng khí sạch nằm sát sàn nhà”, nhanh chóng tìm đồ vải làm ướt che kín cả mũi lẫn miệng và thực hiện đúng tư thế cúi thấp người/bò men theo chân tường hướng ra cửa thoát hiểm Exit.\n\nĐặc biệt, thấu hiểu tâm sinh lý trẻ 3 tuổi rất dễ hoảng sợ trước lửa khói nhưng lại nhanh quên nếu chỉ học lý thuyết suông, Novastars đã tách biệt thành chuỗi bài liên hoàn 2 tiết kế thừa khoa học: Tiết 38 đặt nền tảng nhận thức và phản xạ báo động qua phóng sự thực tế, thảo luận và game số tương tác “Rồng phun lửa”; Tiết 39 nâng cấp lên hành động thực chiến thông qua thử thách tìm đồ vải, làm ướt khăn bịt kín mũi miệng và diễn tập thoát hiểm trong không gian thực tế. Sự luân chuyển trạng thái liên tục này giúp trẻ tiếp thu bài học tự nhiên, không bị áp lực tâm lý và biến kĩ năng sinh tồn thành chuỗi phản xạ có điều kiện ăn sâu vào tiềm thức.","1. Phân tích sư phạm chuyên sâu:\n• Thiết kế chuỗi bài liên hoàn 2 bậc thang 'Nhận thức giác quan ➔ Hành động sinh tồn': Giúp trẻ 3-4 tuổi không bị quá tải tâm lý; chuyển hóa kiến thức an toàn cháy nổ thành phản xạ tự nhiên.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng sinh tồn khẩn cấp (Survival Skills): Biết tự bảo vệ đường hô hấp bằng đồ vải ướt và di chuyển an toàn men chân tường ra cửa Exit.\n• Kĩ năng giao tiếp & Cầu cứu: Hô to dõng dạc câu báo động, chủ động tìm sự trợ giúp của người lớn khi gặp nguy hiểm."],["4","Hoạt động cụ thể 1 (Tiết 38):\nPhóng sự hỏa hoạn (Hậu quả & Nguyên nhân)","• Tên hoạt động: Khởi động – Xem phóng sự hỏa hoạn cùng Su và Kem\n• Hình thức tổ chức: Tương tác qua video phóng sự kết hợp đàm thoại phản biện\n• Tiến trình chi tiết:\n  - Giáo viên ổn định lớp, chào hỏi, nhắc tên môn học Kĩ năng sống Novastars.\n  - Cho trẻ xem đoạn video phóng sự thời sự: Su và Kem đang theo dõi bản tin về một vụ cháy lớn.\n  - Đàm thoại về HẬU QUẢ CỦA ĐÁM CHÁY: Giáo viên hỏi: 'Khi có hỏa hoạn, chuyện gì có thể xảy ra?' -> Trẻ trả lời theo quan sát và kinh nghiệm (nhà bị cháy sập, khói cay mắt, đồ dùng bị thiêu rụi, người bị nạn...); cô ghi nhận và giải thích sự nguy hiểm.\n  - Đàm thoại về 4 NGUYÊN NHÂN GÂY CHÁY: Giáo viên hỏi: 'Có những nguyên nhân nào dẫn tới hỏa hoạn?' -> Cùng trẻ mổ xẻ 4 tình huống thực tế: (1) Bạn nhỏ nghịch bật lửa; (2) Người lớn đốt vàng mã không trông coi; (3) Cắm quá nhiều thiết bị vào một ổ cắm điện gây chập điện; (4) Vứt tàn thuốc lá đang cháy vào bãi cỏ khô.\n  - Giáo viên mở video tổng kết bài học về nguyên nhân và hậu quả.","1. Phân tích sư phạm chuyên sâu:\n• Hoạt động ở đầu sử dụng chất liệu phóng sự thực tế mang tính thời sự giúp thu hút sự chú ý tối đa của trẻ 3 tuổi. Bằng cách chỉ ra 4 nguyên nhân đời thường (đặc biệt là hành vi nghịch bật lửa của trẻ nhỏ), bài học đánh thức ý thức cảnh giác phòng ngừa tai nạn từ sớm.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tư duy nguyên nhân - kết quả: Nhận thức rõ hành vi nghịch lửa/điện sẽ dẫn tới hậu quả khôn lường là đám cháy phá hủy tài sản và đe dọa mạng sống.\n• Kĩ năng tập trung chú ý & phân tích thông tin: Lắng nghe, quan sát video phóng sự và diễn đạt suy nghĩ bằng lời nói."],["5","Hoạt động cụ thể 2 (Tiết 38):\nThảo luận dấu hiệu cảnh báo bằng giác quan","• Tên hoạt động: Hoạt động 2 – Thảo luận: Dấu hiệu cảnh báo khi có cháy & Số cứu hỏa 114\n• Hình thức tổ chức: Xem video tương tác kết hợp thảo luận giác quan\n• Tiến trình chi tiết:\n  - Giáo viên cho trẻ xem video các tình huống cháy và đặt câu hỏi kích thích tư duy giác quan: 'Khi có cháy, chúng mình sẽ ngửi thấy gì, nghe thấy gì và nhìn thấy gì?'.\n  - Hướng dẫn trẻ liên kết từng giác quan với dấu hiệu cảnh báo:\n  * Khứu giác (Mũi ngửi): Ngửi thấy mùi khét lẹt, cay nồng.\n  * Thị giác (Mắt nhìn): Nhìn thấy khói đen cuồn cuộn bốc lên, nhìn thấy ngọn lửa đỏ rực.\n  * Thính giác (Tai nghe): Nghe thấy tiếng chuông/còi báo cháy reo vang inh ỏi khắp tòa nhà.\n  - Giới thiệu số điện thoại khẩn cấp của Đội Cứu hỏa: Số 114.\n  - Cho trẻ xem video hoạt hình tổng kết 4 dấu hiệu và nhắc lại đồng thanh.","1. Phân tích sư phạm chuyên sâu:\n• Thay vì định nghĩa trừu tượng, bài học gắn liền dấu hiệu nguy hiểm với các bộ phận cơ thể quen thuộc của trẻ (mũi ngửi mùi khét, mắt nhìn khói lửa, tai nghe còi). Đây là phương pháp dạy học giác quan trực quan kinh điển, giúp trẻ 3 tuổi ghi nhớ sâu sắc và phản xạ ngay lập tức khi xuất hiện mùi khét hay tiếng còi.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng nhận biết thế giới qua các giác quan: Tăng cường độ nhạy bén của khứu giác, thính giác và thị giác trong việc phát hiện nguy cơ mất an toàn.\n• Kĩ năng ghi nhớ thông tin khẩn cấp: Ghi nhớ số điện thoại 114 để nhờ người lớn bấm gọi cứu trợ."],["6","Hoạt động cụ thể 3 (Tiết 38):\nGiới thiệu & Luyện tập kĩ năng loa tay kêu cứu","• Tên hoạt động: Hoạt động 3 – Huấn luyện phản xạ kêu cứu 'Cháy! Cháy! Cứu!'\n• Hình thức tổ chức: Thực hành kĩ năng cá nhân và nhóm nhỏ kết hợp khích lệ bằng Sao thưởng\n• Tiến trình chi tiết:\n  - Giáo viên mở video hướng dẫn thao tác kêu cứu khi phát hiện cháy: Đặt câu hỏi: 'Khi thấy đám cháy, việc đầu tiên chúng mình cần làm là gì?' -> Nhanh chóng báo hiệu cho người lớn xung quanh.\n  - Hướng dẫn kĩ thuật phát âm thanh khẩn cấp: Giơ 2 bàn tay cong khum áp sát vào khóe miệng để tạo thành chiếc LOA PHÓNG THANH, giúp âm thanh vang xa và rõ nhất.\n  - Dạy khẩu lệnh kêu cứu ngắn gọn, dứt khoát: 'CHÁY! CHÁY! CỨU!' (hoặc 'Cháy! Cháy! Cứu với!').\n  - Tổ chức luyện tập đa cấp độ:\n  * Cấp độ 1: Cả lớp cùng đứng dậy, làm động tác loa tay và hô đồng thanh nhiều hướng.\n  * Cấp độ 2: Giáo viên mời từng nhóm 02 – 03 trẻ/lượt lên trước lớp thực hành hô to dõng dạc.\n  - Khen ngợi và trao tặng Sao thưởng Novastars dũng cảm cho các bé thực hành đúng.\n  - Xem video tổng kết kĩ năng kêu cứu và củng cố toàn bộ Tiết 38.","1. Phân tích sư phạm chuyên sâu:\n•  Hiệu lệnh thông báo khi xảy ra đám cháy được rút gọn chỉ gồm 3 từ đanh thép 'Cháy! Cháy! Cứu!' giúp trẻ không bị ngọng hay hụt hơi trong trạng thái hoảng loạn, đảm bảo tín hiệu kêu cứu đến tai người lớn nhanh nhất.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng vận động thô & phối hợp tay - miệng: Đưa tay lên tạo vòm loa chuẩn xác và lấy hơi từ bụng để phát âm lượng lớn.\n• Kĩ năng cảm xúc xã hội (SEL) & Bản lĩnh cá nhân: Vượt qua sự rụt rè nhút nhát, tự tin đứng trước đám đông hô to khẩu lệnh khẩn cấp."],["7","Hoạt động cụ thể 4 (Tiết 39):\nGame 'Rồng phun lửa' & Thảo luận nguy cơ khói độc","• Tên hoạt động: Hoạt động 1 (Tiết 39) – Game tương tác 'Rồng phun lửa' & Cú sốc nhận thức về khói độc\n• Hình thức tổ chức: Game tương tác số trên phần mềm Novastars kết hợp đàm thoại phản biện\n• Tiến trình chi tiết:\n  - Giáo viên giới thiệu căn phòng mô phỏng và thử thách số 1 của Biệt đội cứu hỏa nhí: Trò chơi 'Rồng phun lửa'.\n  - Nhiệm vụ: Điều khiển nhân vật né tránh các ngọn lửa do rồng phun ra. Cả lớp cùng đứng dậy nghiêng người sang phải, nghiêng sang trái theo chuyển động trên màn hình.\n  - Đàm thoại tạo cú sốc nhận thức sau game: 'Chúng mình đã giúp nhân vật né tránh được hết lửa rồi, tại sao bạn ấy vẫn gặp nguy hiểm và ngất xỉu trong đám cháy?'.\n  - Cho trẻ xem video khoa học 'Sự nguy hiểm của khói trong đám cháy': Phân tích chuyện gì xảy ra nếu hít phải quá nhiều khói độc (khói làm cay xè mắt không nhìn thấy đường, khói độc tràn vào phổi gây ho sặc sụa, ngạt thở và ngất xỉu).\n  - Đúc kết thông điệp sinh tử: Trong đám cháy, chúng ta không chỉ cần tránh lửa mà BẮT BUỘC PHẢI TRÁNH CẢ KHÓI ĐỘC.","1. Phân tích sư phạm chuyên sâu:\n•  Tình huống 'né hết lửa mà vẫn bị nạn' là một cú sốc nhận thức (Cognitive Dissonance) sư phạm đắt giá, đánh đổ quan niệm ngây thơ của trẻ con rằng 'cháy chỉ nguy hiểm vì lửa'. Qua đó trẻ tự giác nhận ra: Khói độc mới chính là kẻ thù số 1 cần phòng chống hàng đầu.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tư duy phản biện & Bản chất vấn đề: Nhận thức rõ ràng khói độc nguy hiểm hơn ngọn lửa đối với đường hô hấp.\n• Kĩ năng vận động thô phản xạ: Luyện khả năng nghiêng thân mình né tránh chướng ngại vật theo nhịp độ hình ảnh."],["8","Hoạt động cụ thể 5 (Tiết 39):\nGame tương tác 'Truy tìm đồ dùng vải trong phòng'","• Tên hoạt động: Hoạt động 2 (Tiết 39) – Thử thách 'Truy tìm đồ dùng vải để ngăn khói'\n• Hình thức tổ chức: Game tương tác chạm/chọn trên màn hình cảm ứng kết hợp nhận diện vật thật\n• Tiến trình chi tiết:\n  - Giáo viên mở video thử thách số 2: Tìm kiếm các đồ vật bằng vải có trong căn phòng mô phỏng để làm 'mặt nạ lọc khói'.\n  - Mời từng trẻ lên chạm/chọn các đồ vật bằng vải xuất hiện trong phòng: Khăn mặt, khăn tay, quần áo, mũ vải, rèm cửa, giẻ lau...\n  - Đàm thoại củng cố: Kể tên các đồ vải xung quanh mình có thể dùng để che mũi miệng khi có cháy.\n  - Chốt nguyên tắc sinh tồn: Khi có hỏa hoạn, phải thật nhanh chóng tìm bất kỳ đồ vật nào bằng vải ở gần mình nhất, kể cả vạt áo hay tay áo đang mặc trên người đều dùng để ngăn khói độc được.","1. Phân tích sư phạm chuyên sâu:\n• Ứng dụng trò chơi hóa vào rèn luyện kĩ năng phân loại chất liệu. Giáo trình mở rộng tư duy của trẻ vượt ra ngoài khuôn khổ sách vở: Không cứng nhắc đi tìm chiếc 'khăn mặt', mà linh hoạt biến mọi vật liệu vải có sẵn xung quanh (quần áo đang mặc, mũ, giẻ lau) thành 'lá chắn lọc khí cứu sinh'.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng quan sát & phân loại chất liệu: Nhận biết đặc tính thấm hút và lọc khí của chất liệu vải so với các đồ vật nhựa, gỗ, kim loại.\n• Kĩ năng giải quyết vấn đề linh hoạt (Resourcefulness): Biết tận dụng tài nguyên có sẵn trên người trong tình huống cấp bách."],["9","Hoạt động cụ thể 6 (Tiết 39):\nTrò chơi 'Nguồn nước ở đâu?' & Thực hành làm ướt khăn","• Tên hoạt động: Hoạt động 3 & 4 (Tiết 39) – Tìm nguồn nước & Thực hành làm ướt đồ vải che kín mũi miệng\n• Hình thức tổ chức: Trò chơi vận động tìm thẻ tranh trong lớp kết hợp thao tác trực tiếp với vật thật\n• Tiến trình chi tiết:\n  - Xem video thử thách số 3: Đi tìm nguồn nước để làm ướt đồ vải khi không có vòi nước bồn rửa.\n  - Trẻ vận động tìm các thẻ tranh nguồn nước giấu quanh lớp học (bình nước lọc, chai nước khoáng, hộp sữa giấy, vòi nước) gắn lên bảng kết quả.\n  - Thực hành làm ướt vật thật: Giáo viên mời học sinh lên thao tác trực tiếp làm ướt khăn bằng nước trong bình, nước đóng chai và nước từ hộp sữa tươi.\n  - Hướng dẫn kĩ thuật che mũi miệng: Vắt nhẹ khăn, gấp lại và áp chặt che kín hoàn toàn cả MŨI và MIỆNG, thở chậm rãi qua lớp vải ướt.\n  - Trải nghiệm mở rộng: Cho trẻ quan sát chiếc mặt nạ chống khói chuyên dụng để nhận biết trang bị cứu hộ hiện đại.","1. Phân tích sư phạm chuyên sâu:\n• Đưa tình huống thực tế 'khan hiếm tài nguyên' vào giảng dạy. Việc cho trẻ trực tiếp rót nước từ bình, chai và hộp sữa thật vào khăn giúp hình thành kinh nghiệm cảm giác chân thực (Hands-on Experience). Trẻ hiểu rằng trong tình huống sinh tử, bất kỳ chất lỏng an toàn nào (kể cả sữa tươi) đều là cứu tinh để làm ướt khăn ngăn khói độc xâm nhập vào phổi.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng vận động tinh & thao tác phối hợp: Thao tác rót nước, nhúng khăn, vắt khăn vừa phải và áp chặt kín khít sống mũi và khóe miệng.\n• Kĩ năng ứng biến hoàn cảnh khẩn cấp: Tự tin xử lý tình huống khi không có vòi nước máy bên cạnh."],["10","Hoạt động cụ thể 7 (Tiết 39):\nLuyện tập di chuyển cúi thấp người men chân tường & Diễn tập còi báo cháy","• Tên hoạt động: Hoạt động 5 & Tổng kết (Tiết 39) – Huấn luyện di chuyển thoát hiểm cúi thấp men chân tường & Diễn tập còi báo cháy thực tế\n• Hình thức tổ chức: Luyện tập vận động thực địa kết hợp kích hoạt phản xạ còi báo cháy thật\n• Tiến trình chi tiết:\n  - Huấn luyện tư thế thoát hiểm chuẩn xác: Giáo viên làm mẫu và chỉnh sửa tư thế cho học sinh: Một tay giữ chặt khăn ướt áp kín mũi miệng; Toàn bộ cơ thể cúi gập thật thấp (hoặc bò bằng đầu gối và một bàn tay sát mặt sàn) để hít thở tầng không khí sạch.\n  - Kĩ thuật dò đường men chân tường: Một bàn tay còn lại luôn đặt chạm men theo mép tường để định hướng phương hướng di chuyển trong làn khói dày, dẫn thẳng ra cửa có biển báo Exit màu xanh lá cây.\n  - Cả lớp xếp thành hàng nối đuôi nhau thực hành di chuyển cúi thấp men tường quanh phòng học ra cửa thoát hiểm.\n  - Tình huống thực chiến bất ngờ: Giáo viên bật âm thanh còi báo cháy thật của trường mầm non. Trẻ lập tức phối hợp chuỗi kĩ năng hoàn chỉnh: Giữ khăn ướt che kín mũi miệng -> Hạ thấp người bò men tường -> Nhanh chóng theo cô giáo di chuyển an toàn ra sân trường.\n  - Giáo viên tổng kết, khen ngợi và trao huy hiệu lính cứu hỏa nhí dũng cảm cho cả lớp.","1. Phân tích sư phạm chuyên sâu:\n• Luyện tập phản xạ hành vi & Thử nghiệm tích cực: Việc loại bỏ đạo cụ ống chui cồng kềnh giúp tiết học tập trung hoàn toàn vào kĩ năng cốt lõi thực tế: Cúi thấp người hạ thấp trọng tâm và sờ tay men theo chân tường để không bị lạc lối trong bóng tối. Âm thanh còi báo cháy thật chuyển hóa kiến thức trên lớp thành bản năng sinh tồn trọn đời.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng vận động thô thích ứng không gian: Duy trì tư thế bò, trườn hoặc đi khom lưng giữ thăng bằng trong khi một tay luôn phải giữ chặt khăn che mặt.\n• Kĩ năng định hướng không gian: Rèn thói quen dùng xúc giác sờ men theo bờ tường để tìm lối thoát hiểm Exit.\n• Kĩ năng quản lý cảm xúc (SEL): Giữ được sự bình tĩnh, không khóc lóc giẫm đạp lên nhau, tuân thủ kỷ luật thoát hiểm an toàn."]],"sheet":"Kĩ năng phòng tránh ngạt khói"},{"rows":[["BÀI 2: BÉ HỌC CÁCH VUI CHƠI AN TOÀN DƯỚI NẮNG (TIẾT 56)","","",""],["Khung chương trình 72 tiết - Khối Mẫu giáo Bé (3 - 4 tuổi) | Bài Demo tiêu biểu chuyển giao mầm non","","",""],["PHẦN I: HỒ SƠ CHUYÊN MÔN CHI TIẾT (CỘT: STT | HẠNG MỤC | NỘI DUNG TRIỂN KHAI | PHÂN TÍCH CHUYÊN MÔN & MỤC ĐÍCH KĨ NĂNG)","","",""],["STT","Hạng mục chuyên môn","Nội dung triển khai thực tế","Phân tích chuyên môn (Kẹp Mục đích phát triển kĩ năng cho trẻ)"],["1","Thông tin chung","• Tên bài học: Bé học cách vui chơi an toàn dưới nắng\n• Mã tiết: Tiết 56 (Khung 72 tiết mầm non CG)\n• Khối lớp: Mẫu giáo Bé (3 - 4 tuổi)\n• Nhóm kĩ năng: Kĩ năng an toàn, bảo vệ bản thân\n• Thời lượng chuẩn: 30 - 35 phút/tiết\n• Học liệu nền tảng: Phần mềm KNS Novastars","1. Phân tích sư phạm chuyên sâu:\n• Đây là BÀI DẠY DEMO TIÊU BIỂU được tuyển chọn kỹ lưỡng trong gói chuyển giao công nghệ mầm non Novastars. Bài học giải quyết trực diện vấn đề sinh hoạt thực tế của trẻ mầm non khi tham gia các hoạt động ngoài trời, dã ngoại.\n• Thiết kế chuẩn mực theo Mô hình tiết học 5 bước, kết hợp công nghệ tương tác số với âm nhạc vận động và sản phẩm học liệu mang về.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Đặt nền móng xây dựng ý thức tự chăm sóc và bảo vệ cơ thể (Self-care), giúp trẻ 3 tuổi bước đầu hình thành phản xạ tự bảo vệ trước các điều kiện thời tiết khắc nghiệt."],["2","Kiến thức kĩ năng cốt lõi","1. Kiến thức trọng tâm:\n• Trẻ ghi nhớ và gọi tên được tia có hại cho sức khỏe ẩn nấp trong ánh nắng mặt trời: Tia UV (nhân hóa thành 'Quái vật UV').\n• Trẻ nhắc lại được 4 tác hại chính của tia UV: Cháy rát da, chóng mặt đau đầu, bị ốm (sốt cao), ngất xỉu (say nắng).\n• Trẻ nhận biết các vị trí có bóng râm an toàn: dưới bóng cây to, sân chơi có mái che, nơi có ô/bạt che lớn.\n• Trẻ nhận biết các vị trí cơ thể cần thoa kem chống nắng: mặt, tai, cổ, cánh tay, cẳng chân, bụng/lưng (khi mặc đồ bơi).\n• Trẻ nhận biết trang phục, phụ kiện bảo hộ trời nắng: mũ rộng vành, áo chống nắng, kính râm, ô che, bình nước.\n\n2. Kĩ năng đạt chuẩn:\n• trẻ nhận diện đúng vị trí bóng râm an toàn.\n• trẻ nhận diện và chỉ đúng các vị trí cần bôi kem chống nắng trên cơ thể.\n•  trẻ chọn lựa đúng trang phục, phụ kiện phù hợp với thời tiết nắng.\n• trẻ thực hiện đúng động tác vũ đạo bôi kem chống nắng theo nhạc.","1. Phân tích sư phạm chuyên sâu:\n• Tư duy của trẻ 3 - 4 tuổi là tư duy trực quan hình tượng. Khái niệm vật lý 'tia cực tím/bức xạ UV' hoàn toàn vô hình và khó hiểu với trẻ. Việc nhân hóa tia UV thành 'Quái vật UV' là sáng tạo sư phạm đắt giá giúp cụ thể hóa mối nguy thành hình tượng nhìn thấy được, trẻ hiểu ngay lý do phải phòng vệ.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tư duy nhân quả: Liên kết hành vi và hậu quả (Đi nắng không đội mũ -> Quái vật UV tấn công -> Cháy da, ốm sốt).\n• Kĩ năng quan sát & định hướng không gian: Rèn luyện mắt quan sát để tự tìm đến khu vực râm mát an toàn.\n• Kĩ năng tự bảo vệ (Self-protection): Trẻ hình thành tâm thế chủ động chuẩn bị đồ dùng hoặc nhời người lớn chuẩn bị đồ cho mình trước khi ra trời nắng."],["3","Khái quát nội dung bài","Bài 56: Bé học cách vui chơi an toàn dưới nắng (Khối Bé 3–4 tuổi, 30–35 phút) là tiết dạy demo tiêu biểu giúp trẻ hình thành kỹ năng tự bảo vệ và chăm sóc cơ thể (Self-care & Self-protection) khi tham gia hoạt động ngoài trời. Trọng tâm bài học giải quyết xuất sắc rào cản nhận thức của lứa tuổi mầm non bằng cách nhân hóa tia cực tím vô hình thành “Quái vật UV”, giúp trẻ ghi nhớ 4 tác hại cốt lõi: cháy da, chóng mặt, ốm sốt và ngất xỉu; từ đó chủ động tìm đến bóng râm an toàn (tán cây, mái che, bạt lớn) và tự giác trang bị “Chiếc khiên chống nắng” (mũ, áo chống nắng, kính râm, ô, và kem chống nắng).\n\nĐặc biệt, thấu hiểu tâm sinh lý trẻ 3 tuổi có khoảng thời gian tập trung rất ngắn, Novastars đã đa dạng hóa các loại hình hoạt động và liên tục thay đổi trạng thái học tập (từ xem video, đàm thoại sang đứng lên vận động, nhảy múa, kéo thả chạm màn hình), giúp trẻ luôn duy trì năng lượng hứng khởi, tập trung cao độ và tiếp thu bài học một cách tự nhiên nhất.","1. Phân tích sư phạm chuyên sâu:\n• Phương pháp Nhân cách hóa & Gamification: Chuyển hóa khái niệm trừu tượng (tia cực tím UV) thành hình tượng 'Quái vật UV' và 'Hiệp sĩ mang khiên', giúp trẻ 3-4 tuổi tiếp thu tự nhiên, biến sự gò bó khi mặc đồ chống nắng thành niềm tự hào tự trang bị vũ khí bảo vệ bản thân.\n• Đa dạng hóa hình thức hoạt động theo tâm sinh lý lứa tuổi: Luân chuyển liên tục các trạng thái học tập (xem video, đàm thoại, vận động, nhảy múa, kéo thả màn hình cảm ứng) giúp trẻ duy trì năng lượng hứng khởi suốt 30-35 phút.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tự chăm sóc & Tự bảo vệ (Self-care & Self-protection): Khắc sâu 4 tác hại cốt lõi (cháy da, chóng mặt, ốm sốt, ngất xỉu), chủ động tìm bóng râm và tự giác trang bị đủ đồ dùng che chắn khi ra ngoài nắng.\n• Kĩ năng tư duy phân loại & Bảo vệ sức khỏe: Biết tự chọn không gian chơi an toàn và nhận diện các dấu hiệu mệt mỏi của cơ thể để dừng chơi kịp thời."],["4","Hoạt động cụ thể 1:\nKhởi động & Dẫn dắt","• Tên hoạt động: Khởi động – Gặp gỡ Sao Nova & Thử thách Quái vật UV\n• Hình thức tổ chức: Video hoạt hình dẫn dắt\n• Tiến trình chi tiết:\n  - Giáo viên mở đoạn phim ngắn nhân vật đồng hành Sao Nova.\n  - Trẻ theo dõi bối cảnh sa mạc nắng gắt và câu chuyện người dân chạy trốn Quái vật UV ẩn nấp trong ánh nắng mặt trời.\n  - Giáo viên tạo không khí hào hứng và cho cả lớp đồng thanh hô to khẩu lệnh 'SẴN SÀNG' để chính thức bước vào bài học.","1. Phân tích sư phạm chuyên sâu:\n• Hoạt động khởi động và dẫn dắt (Chuyển giao trạng thái & Dẫn dắt cốt truyện). Nhân vật Sao Nova đóng vai trò 'cầu nối tâm lý', biến bài học kĩ năng thành một chuyến phiêu lưu giải cứu, giúp trẻ chuyển từ trạng thái tự do sang tập trung có chủ đích.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng lắng nghe có chủ đích: Luyện khả năng tập trung chú ý vào màn hình và tiếp nhận thông tin từ câu chuyện dẫn dắt.\n• Kĩ năng cảm xúc xã hội (SEL): Tạo tâm thế tự tin, hứng khởi, sẵn sàng đối mặt thử thách và tinh thần đồng đội qua khẩu lệnh 'Sẵn sàng'."],["5","Hoạt động cụ thể 2:\nGame 'Truy tìm bóng râm'","• Tên hoạt động: Hoạt động 1 – Game tương tác 'Truy tìm bóng râm'\n• Hình thức tổ chức: Game tương tác số kết hợp vận động cơ thể\n• Tiến trình chi tiết:\n  - Giáo viên giới thiệu tên hoạt động, trẻ đồng thanh nhắc lại: 'Truy tìm bóng râm'.\n  - Hướng dẫn luật chơi: Bước 1: Quan sát 2 hình ảnh trên bảng; Bước 2: Nghiêng cơ thể về phía hình ảnh có bóng râm an toàn.\n  - Cả lớp hô 'Sẵn sàng' và tham gia chơi qua các màn hình bối cảnh thực tế (sân chơi có ô che, dưới tán cây to, khu vui chơi có mái che).\n  - Giáo viên mở video tổng kết, cùng trẻ nhắc lại các khu vực an toàn có bóng râm.","1. Phân tích sư phạm chuyên sâu:\n• Ứng dụng Thuyết Đa trí tuệ của Howard Gardner (kết hợp Thị giác Visual và Vận động Kinesthetic). Trẻ không chỉ nhìn thụ động mà dùng chính chuyển động nghiêng thân người (trái/phải) để lựa chọn đáp án. Đây là vũ khí bẻ gãy hiểu lầm 'slide thụ động': Màn hình kích hoạt toàn bộ học sinh đứng lên vận động thực tế!\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng nhận diện không gian an toàn: Nhận diện chính xác đâu là nơi có bóng râm râm mát ngoài đời thực để vui chơi.\n• Kĩ năng vận động thô & Thăng bằng cơ thể: Rèn luyện khả năng điều khiển thân người nghiêng trái, nghiêng phải linh hoạt, nhanh nhẹn theo hiệu lệnh thị giác."],["6","Hoạt động cụ thể 3:\nThảo luận Quái vật UV","• Tên hoạt động: Hoạt động 2 – Thảo luận 'Nguy cơ khu vui chơi dưới nắng'\n• Hình thức tổ chức: Xem video phân tích & Đàm thoại gợi mở\n• Tiến trình chi tiết:\n  - Giáo viên mở đoạn phim giới thiệu về tác hại của Quái vật UV.\n  - Hệ thống 3 câu hỏi đàm thoại:\n  1. Sao Nova vừa nhắc đến con quái vật gì? -> Quái vật UV.\n  2. Quái vật UV ẩn nấp ở đâu? -> Trong ánh nắng mặt trời.\n  3. Quái vật UV có thể khiến chúng mình bị làm sao? -> Cháy da, chóng mặt, bị ốm, ngất xỉu.\n  - Giáo viên và học sinh đồng thanh nhắc lại thông điệp trọng tâm để khắc sâu ghi nhớ.","1. Phân tích sư phạm chuyên sâu:\n• Phương pháp đàm thoại đa tầng giúp học sinh tự tư duy và nói ra kiến thức thay vì nghe cô giáo giảng giải một chiều.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng giao tiếp & Ngôn ngữ mạch lạc: Rèn luyện phản xạ nói to, rõ ràng, tự tin diễn đạt câu trả lời trước tập thể lớp học.\n• Kĩ năng nhận thức rủi ro: Khắc sâu 4 tác hại nguy hiểm vào tiềm thức, tạo rào cản nhận thức giúp trẻ tự biết sợ và tránh nắng gắt."],["7","Hoạt động cụ thể 4:\nVận động theo nhạc Bôi kem","• Tên hoạt động: Hoạt động 3 – Luyện tập vận động theo nhạc 'Bôi kem chống nắng'\n• Hình thức tổ chức: Âm nhạc & Vũ đạo mô phỏng thao tác\n• Tiến trình chi tiết:\n  - Giáo viên mời toàn bộ trẻ đứng dậy, bật bài hát sôi động 'Bôi kem chống nắng'.\n  - Giáo viên làm mẫu và trẻ nhảy múa theo nhạc, thực hiện các động tác vũ đạo mô phỏng thoa kem: xoa mặt, vuốt cổ, xoa dọc hai cánh tay, hai cẳng chân và xoa bụng.\n  - Xem video tổng kết, trẻ nhắc lại danh sách các vị trí cơ thể bắt buộc phải thoa kem trước khi ra ngoài nắng.","1. Phân tích sư phạm chuyên sâu:\n• Đột phá phương pháp qua Âm nhạc & Trí nhớ vận động cơ thể. Thao tác bôi kem khô khan được chuyển thể thành vũ điệu bắt tai. Âm nhạc kích thích não bộ, giúp trẻ 3 tuổi nhớ các vị trí cần bảo vệ mà không cần học vẹt.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tự phục vụ cơ thể (Self-help): Nắm vững thao tác và các vị trí da hở cần bôi kem chống nắng để bảo vệ cơ thể.\n• Kĩ năng vận động thô & Cảm thụ nhịp điệu: Giải phóng năng lượng thể chất, rèn sự dẻo dai và khả năng phối hợp vận động tay - chân - thân người theo nhịp nhạc."],["8","Hoạt động cụ thể 5:\nGame 'Làm khiên chống nắng'","• Tên hoạt động: Hoạt động 4 – Game tương tác kéo thả 'Làm khiên chống nắng'\n• Hình thức tổ chức: Game tương tác số trên bảng cảm ứng\n• Tiến trình chi tiết:\n  - Giáo viên mở video hướng dẫn: quan sát đồ vật trên màn hình, gọi to tên các đồ dùng bảo vệ sử dụng khi trời nắng\n   - Hệ thống tự động hoàn thiện các đồ dùng trong khiên","1. Phân tích sư phạm chuyên sâu:\n• Ứng dụng Gamification và biểu tượng 'Chiếc khiên hiệp sĩ'. Tạo cho trẻ cảm giác mình là những hiệp sĩ nhí tự trang bị khiên giáp bảo vệ sức khỏe, loại bỏ hoàn toàn cảm giác bị người lớn ép mặc đồ chống nắng cồng kềnh.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng tư duy phân loại đồ dùng (Cognitive Sorting): Phân biệt chính xác đồ dùng cần thiết khi trời nắng và loại bỏ các đồ dùng không phù hợp.\n• Rèn luyện sự tự tin mạnh dạn nói ra ý kiến của bản thân bằng cách gọi to tên đồ dùng có thể chống nắng, đồng thời tạo không khí vui nhộn cho lớp học"],["9","Hoạt động cụ thể 6:\nGame 'Chiến đấu Quái vật UV'","• Tên hoạt động: Hoạt động 5 – Game vận động phản xạ 'Chiến đấu với quái vật UV'\n• Hình thức tổ chức: Game vận động phản xạ tương tác không gian\n• Tiến trình chi tiết:\n  - Giáo viên mở video hướng dẫn nhiệm vụ: Đứng ở vạch chính giữa bảng nhìn lên màn hình; Quái vật UV xuất hiện tấn công từ hướng nào thì giơ tay có ngôi sao về hướng đó để đẩy lùi.\n  - Giáo viên mời từng nhóm trẻ lên đứng tại vạch và tham gia thử thách phản xạ đánh đuổi quái vật.\n  - Kết thúc trò chơi trong âm thanh chúc mừng chiến thắng rộn rã.","1. Phân tích sư phạm chuyên sâu:\n• Trẻ được Nhập vai & Thực hành phản xạ: Trò chơi đẩy tiết học lên cao trào cảm xúc, giúp củng cố niềm tin vào năng lực tự bảo vệ của bản thân sau khi đã trang bị đầy đủ 'khiên chống nắng'.\n\n2. Mục đích phát triển kĩ năng cho trẻ:\n• Kĩ năng phản xạ nhanh & Định hướng không gian đa chiều: Luyện khả năng phản xạ mắt nhìn - tay giơ theo các hướng (trái, phải, trên) kịp thời khi mối nguy xuất hiện.\n• Kĩ năng xây dựng lòng tự tin và tính chủ động: Trẻ không sợ hãi mà tự tin làm chủ tình huống, biết rằng mình hoàn toàn có thể tự bảo vệ an toàn."]],"sheet":"Vui chơi an toàn dưới nắng"}],"questions":[{"id":"hp05-q1","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","question":"Cặp bài học liên hoàn 'Kĩ năng nhận diện nguy hiểm bằng các giác quan & Phòng tránh ngạt khói khi có hoả hoạn' thuộc khối lớp nào và tương ứng với mã tiết nào trong khung 72 tiết Novastars?","options":["Khối Mẫu giáo Bé (3 - 4 tuổi) — Tiết 38 (Lý thuyết nhận diện & Kêu cứu) và Tiết 39 (Thực hành chống ngạt khói & Thoát hiểm an toàn).","Khối Mẫu giáo Nhỡ (4 - 5 tuổi) — Tiết 12 và Tiết 13.","Khối Mẫu giáo Lớn (5 - 6 tuổi) — Tiết 70 và Tiết 71.","Chỉ dạy ngoại khóa 1 tiết duy nhất cho toàn trường."],"correctIndex":0,"explanation":"Theo Hồ sơ chuyên môn Bài 1: Cặp bài học liên hoàn được thiết kế ở Tiết 38 và Tiết 39 cho Khối Mẫu giáo Bé (3 - 4 tuổi), mỗi tiết 30 - 35 phút."},{"id":"hp05-q2","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","question":"Vì sao Novastars tách nội dung phòng cháy và thoát hiểm của trẻ 3 - 4 tuổi thành chuỗi 2 tiết liên hoàn (Tiết 38 & Tiết 39) thay vì dồn vào 1 tiết?","options":["Vì giáo viên không kịp chuẩn bị video trong 1 tiết học.","Thiết kế 2 bậc thang 'Nhận thức giác quan & báo động (Tiết 38) ➔ Hành động sinh tồn chống ngạt khói & thoát hiểm (Tiết 39)' giúp trẻ 3 tuổi không bị quá tải tâm lý, biến kiến thức thành phản xạ tự nhiên.","Để dành toàn bộ Tiết 38 cho trẻ ngồi tô màu xe cứu hỏa.","Vì quy định bắt buộc mọi bài học mầm non đều phải kéo dài đúng 60 phút."],"correctIndex":1,"explanation":"Trẻ 3 tuổi dễ hoảng sợ trước lửa khói nhưng nhanh quên nếu chỉ học lý thuyết suông. Chia thành 2 tiết liên hoàn giúp trẻ đi từ Nhận thức giác quan & Hô cứu sang Hành động thực chiến."},{"id":"hp05-q3","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","question":"Trong Hoạt động 1 của Tiết 38 (Xem phóng sự hỏa hoạn cùng Su và Kem), giáo viên cùng trẻ mổ xẻ 4 nguyên nhân phổ biến nào dẫn tới hỏa hoạn?","options":["Trời mưa to, bật quạt điện, mở cửa sổ và tưới cây.","Bạn nhỏ nghịch bật lửa; người lớn đốt vàng mã không trông coi; cắm quá nhiều thiết bị vào một ổ điện; vứt tàn thuốc lá đang cháy vào bãi cỏ khô.","Chỉ có một nguyên nhân duy nhất là do sét đánh vào mùa hè.","Do trẻ chạy nhảy mạnh trên sàn lớp học."],"correctIndex":1,"explanation":"Bài học chỉ rõ 4 nguyên nhân đời thường (nghịch bật lửa, đốt vàng mã, cắm quá tải ổ điện, vứt tàn thuốc vào cỏ khô) để đánh thức ý thức phòng ngừa tai nạn từ sớm."},{"id":"hp05-q4","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","question":"Bài học Tiết 38 hướng dẫn trẻ 3 - 4 tuổi sử dụng những giác quan nào trên cơ thể để nhận biết sớm dấu hiệu hỏa hoạn và ghi nhớ số điện thoại khẩn cấp nào?","options":["Khứu giác (mũi ngửi mùi khét nồng), Thị giác (mắt nhìn khói đen & lửa đỏ), Thính giác (tai nghe chuông/còi báo cháy) và nhớ số cứu hỏa 114.","Chỉ dùng vị giác để nếm thử nước và gọi số 115.","Chỉ nhìn qua cửa sổ và gọi số 113.","Đợi người lớn thông báo chứ trẻ 3 tuổi không thể nhận biết dấu hiệu cháy."],"correctIndex":0,"explanation":"Phương pháp dạy học đa giác quan gắn dấu hiệu nguy hiểm với bộ phận cơ thể quen thuộc (Mũi - Mắt - Tai) kết hợp ghi nhớ số cứu hỏa 114."},{"id":"hp05-q5","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","question":"Kĩ thuật kêu cứu chuẩn khi phát hiện đám cháy được huấn luyện cho trẻ ở Hoạt động 3 (Tiết 38) như thế nào?","options":["Trốn vào góc tủ và khóc thật to.","Đứng im tại chỗ nói thì thầm với bạn bên cạnh.","Giơ 2 bàn tay cong khum áp sát vào khóe miệng tạo thành chiếc LOA PHÓNG THANH và hô ngắn gọn, dứt khoát 3 từ: 'CHÁY! CHÁY! CỨU!'.","Học thuộc một đoạn văn dài 20 từ để đọc khi có cháy."],"correctIndex":2,"explanation":"Hiệu lệnh rút gọn còn 3 từ đanh thép 'CHÁY! CHÁY! CỨU!' kết hợp động tác loa tay giúp trẻ 3 tuổi không bị ngọng hay hụt hơi khi hoảng loạn, giúp âm thanh vang xa nhất."},{"id":"hp05-q6","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","question":"Trong Tiết 39, trò chơi tương tác 'Rồng phun lửa' tạo ra 'cú sốc nhận thức' (Cognitive Dissonance) đắt giá nào cho học sinh?","options":["Trẻ giúp nhân vật nghiêng người né tránh được hết ngọn lửa nhưng nhân vật vẫn bị ngất xỉu vì hít phải KHÓI ĐỘC — giúp trẻ nhận ra trong đám cháy, khói độc còn nguy hiểm hơn lửa.","Trẻ nhận ra rồng trong phim hoạt hình có thể bay lên trời.","Trẻ biết cách dùng kiếm đồ chơi để đánh nhau với rồng lửa.","Trẻ hiểu rằng chỉ cần đứng yên là lửa tự tắt."],"correctIndex":0,"explanation":"Tình huống 'né hết lửa mà vẫn bị nạn' đánh đổ quan niệm ngây thơ rằng cháy chỉ nguy hiểm vì lửa, giúp trẻ tự giác hiểu rằng khói độc mới là kẻ thù số 1 gây ngạt thở."},{"id":"hp05-q7","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","question":"Trong thử thách 'Truy tìm đồ dùng vải để ngăn khói' và 'Nguồn nước ở đâu?' (Tiết 39), Novastars rèn cho trẻ tư duy linh hoạt xử lý tình huống khan hiếm tài nguyên như thế nào?","options":["Bắt buộc trẻ chỉ được dùng khăn mặt mới tinh và nước từ vòi bồn rửa tay.","Khi cấp bách, trẻ biết tận dụng bất kỳ đồ vải nào gần nhất (khăn, quần áo, mũ vải, giẻ lau, vạt áo đang mặc) và làm ướt bằng bất kỳ nguồn chất lỏng an toàn nào sẵn có (bình nước, chai nước, hộp sữa tươi) để gấp che kín cả MŨI lẫn MIỆNG.","Hướng dẫn trẻ dùng túi nilon bọc kín đầu.","Dặn trẻ chạy đi mua mặt nạ chống độc ngoài cửa hàng."],"correctIndex":1,"explanation":"Trẻ được thực hành rót nước từ bình, chai nước và cả hộp sữa tươi thật vào khăn để hiểu rằng mọi chất lỏng an toàn và đồ vải quanh mình đều là cứu tinh lọc khói độc."},{"id":"hp05-q8","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","question":"Vì sao khi thoát hiểm trong đám cháy có khói, trẻ được huấn luyện tư thế cúi gập người thật thấp hoặc bò sát mặt sàn men theo chân tường ra cửa Exit?","options":["Vì bò dưới sàn giúp trẻ tìm lại đồ chơi bị rơi.","Vì khói độc bốc lên cao còn tầng khí sạch dễ thở nằm ở SÁT MẶT SÀN NHÀ; đồng thời một tay giữ khăn ướt che kín mũi miệng, tay kia sờ men theo mép tường giúp định hướng thẳng ra cửa Exit mà không bị lạc trong khói dày.","Để đi vào thang máy cho nhanh.","Để trốn vào gầm giường, tủ quần áo hoặc nhà vệ sinh."],"correctIndex":1,"explanation":"Bài học giải thích rõ nguyên lý khoa học: khói độc bay lên cao, tầng khí sạch nằm sát sàn nhà; tuyệt đối không dùng thang máy, không trốn vào tủ/gầm giường/nhà vệ sinh."},{"id":"hp05-q9","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","question":"Vì sao trong Hoạt động 5 (Tiết 39), giáo án Novastars loại bỏ đạo cụ ống chui cồng kềnh mà sử dụng âm thanh còi báo cháy thật của trường và cho trẻ men theo chân tường thật?","options":["Để tiết kiệm chi phí mua ống chui bằng nhựa.","Để tập trung 100% vào kĩ năng thực tế (cúi thấp hạ trọng tâm + dùng xúc giác sờ men bờ tường tìm cửa Exit) và dùng còi báo cháy thật nhằm chuyển hóa kiến thức trên lớp thành bản năng sinh tồn ngoài đời thực.","Vì phòng học không đủ chỗ đặt ống chui.","Để trẻ thi chạy nhanh xem ai về đích trước."],"correctIndex":1,"explanation":"Loại bỏ đạo cụ ống chui giả định giúp trẻ rèn đúng kĩ năng thực địa: một tay giữ chặt khăn ướt che mũi miệng, một tay sờ men tường định hướng khi nghe tiếng còi báo cháy thật."},{"id":"hp05-q10","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","question":"Theo bộ tiêu chuẩn đầu ra của cặp bài Phòng tránh ngạt khói (Tiết 38 & 39), tỷ lệ trẻ đạt chuẩn ở các kĩ năng nhận biết dấu hiệu cháy, hô loa tay kêu cứu, làm ướt khăn che mũi miệng và bò thoát hiểm là bao nhiêu?","options":["Chỉ khoảng 20% - 30% trẻ trong lớp làm được.","90% trẻ nhắc được 4 dấu hiệu cháy & số 114; 85% trẻ làm đúng loa tay hô 'Cháy! Cháy! Cứu!'; 85% trẻ biết làm ướt đồ vải che kín mũi miệng; 80% trẻ thực hành đúng tư thế cúi thấp/bò men chân tường thoát ra ngoài.","Chỉ yêu cầu trẻ ngồi nghe cô giảng chứ không đo lường tỷ lệ thực hành.","100% trẻ phải tự dập tắt đám cháy bằng bình cứu hỏa."],"correctIndex":1,"explanation":"Mục tiêu định lượng rõ ràng (80% – 90% trẻ thực hành đạt chuẩn từng thao tác) là minh chứng cam kết chất lượng đầu ra của chương trình Novastars khi tư vấn Chủ trường."},{"id":"hp05-q11","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","question":"Bài học 'Bé học cách vui chơi an toàn dưới nắng' có mã tiết bao nhiêu trong khung 72 tiết Khối Mẫu giáo Bé (3 - 4 tuổi) và giữ vai trò gì đặc biệt khi triển khai cho trường mầm non?","options":["Tiết 56 — Là BÀI DẠY DEMO TIÊU BIỂU trong gói chuyển giao công nghệ mầm non Novastars, thiết kế chuẩn theo mô hình 5 bước kết hợp tương tác số, âm nhạc vận động và học liệu.","Tiết 01 — Bài học lý thuyết thuần túy không có trò chơi.","Tiết 72 — Bài kiểm tra viết cuối năm của khối Lớn.","Bài đọc thêm chỉ gửi bản chữ cho phụ huynh tự đọc."],"correctIndex":0,"explanation":"Theo Hồ sơ chuyên môn Bài 2: Tiết 56 (Khối Bé 3-4 tuổi) là Bài dạy Demo tiêu biểu được tuyển chọn kỹ lưỡng trong gói chuyển giao mầm non Novastars."},{"id":"hp05-q12","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","question":"Để giúp trẻ 3 - 4 tuổi (vốn có tư duy trực quan hình tượng) hiểu được khái niệm vật lý vô hình 'tia cực tím / bức xạ UV', Novastars đã sử dụng thủ pháp sư phạm sáng tạo nào?","options":["Giảng giải công thức vật lý về bước sóng ánh sáng mặt trời.","Nhân hóa tia UV vô hình thành hình tượng 'Quái vật UV' ẩn nấp trong ánh nắng mặt trời và biến các đồ dùng chống nắng thành 'Chiếc khiên hiệp sĩ'.","Cấm trẻ không được bước ra sân trường suốt mùa hè.","Cho trẻ học thuộc lòng định nghĩa tia cực tím trong từ điển."],"correctIndex":1,"explanation":"Nhân cách hóa tia UV thành 'Quái vật UV' và đồ bảo hộ thành 'Chiếc khiên hiệp sĩ' giúp cụ thể hóa mối nguy vô hình thành hình tượng nhìn thấy được, trẻ tự hào trang bị đồ chống nắng."},{"id":"hp05-q13","category":"kien_thuc","categoryLabel":"1. Cấu trúc chương trình","question":"Trong bài 'Bé học cách vui chơi an toàn dưới nắng' (Tiết 56), trẻ ghi nhớ 4 tác hại chính nào do 'Quái vật UV' (tia UV) gây ra cho cơ thể?","options":["Đau răng, sún răng, mỏi tay và buồn ngủ.","Cháy rát da, chóng mặt đau đầu, bị ốm (sốt cao) và ngất xỉu (say nắng).","Chỉ làm bẩn quần áo chứ không ảnh hưởng sức khỏe.","Làm trẻ cao lên quá nhanh."],"correctIndex":1,"explanation":"Qua video phân tích và hệ thống 3 câu hỏi đàm thoại cùng Sao Nova, trẻ khắc sâu 4 tác hại cốt lõi của Quái vật UV: cháy rát da, chóng mặt đau đầu, bị ốm sốt cao, ngất xỉu."},{"id":"hp05-q14","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","question":"Ở Hoạt động khởi động của Tiết 56, nhân vật đồng hành nào dẫn dắt trẻ qua bối cảnh sa mạc nắng gắt và cùng cả lớp hô to khẩu lệnh gì để bước vào bài học?","options":["Nhân vật Sao Nova dẫn dắt câu chuyện người dân chạy trốn Quái vật UV và cả lớp đồng thanh hô to khẩu lệnh 'SẴN SÀNG'.","Nhân vật Mèo máy đọc truyện cổ tích cho trẻ đi ngủ.","Cô giáo kiểm tra bài cũ bằng phiếu điểm.","Trẻ ngồi im lặng tuyệt đối trong 10 phút đầu giờ."],"correctIndex":0,"explanation":"Nhân vật Sao Nova đóng vai trò cầu nối tâm lý, biến bài học kĩ năng thành chuyến phiêu lưu giải cứu và kích hoạt tâm thế hứng khởi qua khẩu lệnh 'SẴN SÀNG'."},{"id":"hp05-q15","category":"usp_khac_biet","categoryLabel":"2. Điểm khác biệt USP","question":"Trò chơi tương tác 'Truy tìm bóng râm' (Hoạt động 1 - Tiết 56) ứng dụng Thuyết Đa trí tuệ của Howard Gardner như thế nào để đập tan định kiến 'dạy bằng slide là thụ động'?","options":["Trẻ chỉ ngồi khoanh tay nhìn cô giáo bấm slide.","Kết hợp Thị giác (Visual) và Vận động (Kinesthetic): Trẻ quan sát 2 hình ảnh trên màn hình và dùng chính chuyển động NGHIÊNG THÂN NGƯỜI (sang trái / sang phải) về phía hình ảnh có bóng râm an toàn (dưới tán cây to, sân chơi có mái che, ô che lớn).","Chỉ gọi 1 học sinh lên bảng cầm chuột máy tính suốt tiết học.","Cho trẻ vẽ tranh bóng cây trên giấy trắng."],"correctIndex":1,"explanation":"Màn hình tương tác kích hoạt toàn bộ học sinh cả lớp đứng lên vận động nghiêng thân người trái/phải để chọn khu vực có bóng râm an toàn."},{"id":"hp05-q16","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","question":"Trong Hoạt động 3 (Vận động theo nhạc 'Bôi kem chống nắng'), thao tác thoa kem bảo vệ da được chuyển thể thành vũ đạo mô phỏng những vị trí cơ thể nào?","options":["Chỉ thoa kem lên tóc và giày dép.","Trẻ nhảy múa theo bài hát sôi động 'Bôi kem chống nắng', thực hiện động tác mô phỏng thoa kem lên các vùng da hở: xoa mặt, vuốt cổ (và tai), xoa dọc hai cánh tay, hai cẳng chân và xoa bụng.","Chỉ bôi kem vào lòng bàn tay.","Cô giáo bôi kem cho búp bê trên bàn giáo viên."],"correctIndex":1,"explanation":"Ứng dụng Âm nhạc & Trí nhớ vận động cơ thể (Muscle Memory) giúp trẻ 3 tuổi nhớ chính xác các vị trí da hở cần thoa kem chống nắng mà không cần học vẹt."},{"id":"hp05-q17","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","question":"Ở Hoạt động 4 — Game tương tác số 'Làm khiên chống nắng', trẻ thực hiện nhiệm vụ gì để hoàn thiện chiếc khiên bảo vệ sức khỏe?","options":["Quan sát các đồ vật trên màn hình, phân loại và gọi to tên các đồ dùng bảo hộ cần thiết khi trời nắng (mũ rộng vành, áo chống nắng, kính râm, ô che, kem chống nắng, bình nước) để hệ thống đưa vào hoàn thiện Khiên chống nắng.","Chọn áo mưa, ủng đi mưa và khăn len mùa đông.","Cắt giấy bìa cứng bằng kéo sắc nhọn.","Ngồi nghe cô đọc danh sách quần áo."],"correctIndex":0,"explanation":"Biểu tượng 'Chiếc khiên hiệp sĩ' kết hợp tư duy phân loại (Cognitive Sorting) giúp trẻ tự giác chọn đúng trang phục chống nắng và loại bỏ cảm giác bị người lớn ép mặc đồ bảo hộ."},{"id":"hp05-q18","category":"dan_chung_bai_mau","categoryLabel":"3. Dẫn chứng bài mẫu","question":"Hoạt động cao trào cuối bài Tiết 56 — Game vận động phản xạ 'Chiến đấu với quái vật UV' được tổ chức như thế nào?","options":["Trẻ đứng ở vạch chính giữa bảng nhìn lên màn hình; Quái vật UV xuất hiện tấn công từ hướng nào (trái, phải, trên) thì trẻ phản xạ giơ nhanh tay có ngôi sao về đúng hướng đó để đẩy lùi quái vật.","Trẻ ném phấn vào màn hình tivi.","Trẻ ngồi tại chỗ xem phim hoạt hình dài 15 phút.","Cô giáo tắt màn hình và cho trẻ đi ngủ trưa."],"correctIndex":0,"explanation":"Game vận động phản xạ đa chiều đẩy tiết học lên cao trào cảm xúc, rèn phản xạ mắt nhìn - tay giơ theo hướng mối nguy và củng cố niềm tin vào năng lực tự bảo vệ bản thân."},{"id":"hp05-q19","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","question":"Khi tư vấn Chủ trường muốn chọn một tiết dạy mẫu (Demo) cho khối Mẫu giáo Bé (3 - 4 tuổi) vừa sôi động, vừa chứng minh học sinh cả lớp được vận động liên tục cùng phần mềm, Sale nên giới thiệu cấu trúc 5 bước của Tiết 56 như thế nào?","options":["Giới thiệu chuỗi luân chuyển trạng thái liên tục trong 30-35 phút: (1) Video Sao Nova & hô khẩu lệnh Sẵn sàng ➔ (2) Nghiêng người 'Truy tìm bóng râm' ➔ (3) Đàm thoại 3 câu hỏi về Quái vật UV ➔ (4) Nhảy vũ đạo 'Bôi kem chống nắng' ➔ (5) Gọi tên đồ bảo hộ 'Làm khiên chống nắng' & phản xạ giơ tay ngôi sao 'Chiến đấu Quái vật UV'.","Báo với Chủ trường rằng tiết Demo chỉ có cô giáo đứng thuyết trình bằng slide PowerPoint tĩnh.","Đề xuất cho trẻ 3 tuổi làm bài kiểm tra trắc nghiệm trên giấy 30 phút.","Nói rằng chương trình chỉ có video ca nhạc cho trẻ xem tự do."],"correctIndex":0,"explanation":"Cấu trúc 5 hoạt động liên hoàn thay đổi trạng thái liên tục (Xem phim - Nghiêng người - Đàm thoại - Nhảy vũ đạo - Phản xạ không gian) giải quyết triệt để đặc điểm thời gian tập trung ngắn của trẻ 3 tuổi."},{"id":"hp05-q20","category":"xu_ly_tinh_huong","categoryLabel":"4. Xử lý tình huống","question":"Điểm chung nổi bật về giá trị sư phạm giữa cặp bài 'Phòng tránh ngạt khói' (Tiết 38-39) và bài 'Vui chơi an toàn dưới nắng' (Tiết 56) để Sale thuyết phục Hiệu trưởng là gì?","options":["Cả hai bài đều chuyển hóa các nguy cơ trừu tượng/đáng sợ (khói độc, tia UV) thành trải nghiệm trực quan, trò chơi tương tác số và thao tác thực hành cơ thể (loa tay hô cứu, làm ướt khăn bò sát sàn, vũ đạo bôi kem, làm khiên chống nắng), giúp trẻ 3-4 tuổi hình thành phản xạ tự bảo vệ thực chất mà không bị áp lực tâm lý.","Cả hai bài đều cắt bỏ hoàn toàn vai trò hướng dẫn của giáo viên trên lớp.","Cả hai bài đều chỉ dành cho học sinh lớp 1 Tiểu học.","Cả hai bài đều yêu cầu trường phải xây dựng phòng thí nghiệm hóa học riêng."],"correctIndex":0,"explanation":"Đây là luận điểm cốt lõi kết nối cả 2 chuyên đề: tôn trọng tâm sinh lý trẻ 3-4 tuổi, dùng công nghệ tương tác số + thực hành cơ thể để biến kiến thức an toàn sinh tồn thành phản xạ tự nhiên."}]}],"progress":[{"id":"prog__mod-01-tong-quan__sale-tientt","userId":"sale-tientt","userName":"Triệu Thị Tiên","moduleId":"mod-01-tong-quan","docViewed":true,"docViewedAt":"2026-11-25T08:25:34.126Z","bestScore":0,"passed":false,"attempts":[],"updatedAt":"2026-11-25T08:24:58.080Z"}]};
